-- Phase 14 native app compatibility preflight and Cortex AI explanation assist
-- Co-authored with CoCo
-- ============================================================
-- KMAT COST MODEL
-- PHASE 14A — NATIVE APP COMPATIBILITY PREFLIGHT
--
-- Purpose:
--   Read-only confirmation that the current governed KMAT baseline
--   exists before compatibility refactoring starts.
--
-- Safety:
--   No cost procedure is called.
--   No policy, runtime authority, switch, model, or cost output is changed.
-- ============================================================

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

SELECT
    CURRENT_ROLE() AS CURRENT_ROLE,
    CURRENT_WAREHOUSE() AS CURRENT_WAREHOUSE,
    CURRENT_DATABASE() AS CURRENT_DATABASE,
    CURRENT_SCHEMA() AS CURRENT_SCHEMA;

-- Required object inventory. Expected: zero rows.
WITH REQUIRED_OBJECTS AS (
    SELECT * FROM VALUES
        ('CORE_OUTPUT', 'KMAT_CONFIGURED_COST_SUMMARY'),
        ('CORE_ML', 'VW_KMAT_PHASE10B_HIERARCHY_V1'),
        ('CORE_ML', 'VW_ML_DECISION_POLICY_CURRENT_V1'),
        ('CORE_ML', 'ML_RUNTIME_AUTHORITY_REGISTRY_V1'),
        ('CORE_ML', 'ML_RUNTIME_AUTHORITY_DECISION_V1'),
        ('CORE_ML', 'ML_RUNTIME_SAFETY_MONITOR_RUN_V1')
    AS required(SCHEMA_NAME, OBJECT_NAME)
),
FOUND_OBJECTS AS (
    SELECT TABLE_SCHEMA AS SCHEMA_NAME, TABLE_NAME AS OBJECT_NAME
    FROM KMAT_COST_MODEL_DB.INFORMATION_SCHEMA.TABLES
)
SELECT required.SCHEMA_NAME, required.OBJECT_NAME
FROM REQUIRED_OBJECTS required
LEFT JOIN FOUND_OBJECTS found
    ON required.SCHEMA_NAME = found.SCHEMA_NAME
   AND required.OBJECT_NAME = found.OBJECT_NAME
WHERE found.OBJECT_NAME IS NULL
ORDER BY required.SCHEMA_NAME, required.OBJECT_NAME;

-- Required baseline row. Expected: one row.
SELECT
    COUNT(*) AS SIM_001_SUMMARY_ROW_COUNT,
    COUNT_IF(TOTAL_CONFIGURED_COST_USD IS NULL) AS NULL_TOTAL_COST_ROW_COUNT,
    COUNT_IF(RISK_ADJUSTED_TOTAL_COST_USD IS NULL) AS NULL_RISK_COST_ROW_COUNT
FROM KMAT_COST_MODEL_DB.CORE_OUTPUT.KMAT_CONFIGURED_COST_SUMMARY
WHERE SIMULATION_ID = 'SIM_001';

-- Current policy posture. Expected: 4 active, 4 shadow, 0 authority enabled.
SELECT
    COUNT(*) AS ACTIVE_POLICY_COUNT,
    COUNT_IF(DEPLOYMENT_MODE = 'SHADOW') AS SHADOW_POLICY_COUNT,
    COALESCE(
        COUNT_IF(
            AUTO_USE_ALLOWED_FLAG = TRUE
            OR OFFICIAL_COST_IMPACT_ALLOWED_FLAG = TRUE
            OR BUSINESS_DECISION_ALLOWED_FLAG = TRUE
        ),
        0
    ) AS AUTHORITY_ENABLED_COUNT
FROM KMAT_COST_MODEL_DB.CORE_ML.VW_ML_DECISION_POLICY_CURRENT_V1;

-- Current runtime posture. Expected: all zero.
SELECT
    (SELECT COUNT(*)
     FROM KMAT_COST_MODEL_DB.CORE_ML.ML_RUNTIME_AUTHORITY_REGISTRY_V1)
        AS RUNTIME_AUTHORITY_ROW_COUNT,
    (SELECT COUNT(*)
     FROM KMAT_COST_MODEL_DB.CORE_ML.ML_RUNTIME_AUTHORITY_REGISTRY_V1
     WHERE UPPER(AUTHORITY_STATUS) = 'ENABLED')
        AS ENABLED_RUNTIME_AUTHORITY_COUNT,
    (SELECT COUNT(*)
     FROM KMAT_COST_MODEL_DB.CORE_ML.ML_RUNTIME_AUTHORITY_DECISION_V1)
        AS RUNTIME_DECISION_COUNT,
    (SELECT COUNT(*)
     FROM KMAT_COST_MODEL_DB.CORE_ML.ML_RUNTIME_SAFETY_MONITOR_RUN_V1)
        AS RUNTIME_MONITOR_RUN_COUNT;

-- Governed baseline hierarchy. Expected: one safe row for SIM_001.
SELECT
    SIMULATION_ID,
    CSS_RULE_VALUE,
    CSS_ML_VALUE,
    CSS_OVERRIDE_VALUE,
    CSS_SAFE_DEFAULT_VALUE,
    RESOLVED_SCRAP_RATE,
    CSS_RESOLVED_SOURCE,
    FMIS_RULE_VALUE,
    FMIS_ML_VALUE,
    FMIS_OVERRIDE_VALUE,
    FMIS_SAFE_DEFAULT_VALUE,
    RESOLVED_FMIS_MULTIPLIER,
    FMIS_RESOLVED_SOURCE,
    TDS_RULE_VALUE,
    TDS_ML_VALUE,
    TDS_OVERRIDE_VALUE,
    TDS_SAFE_DEFAULT_VALUE,
    RESOLVED_TDS_FACTOR,
    TDS_RESOLVED_SOURCE,
    RESOLVED_BMCS_STATUS,
    SAFETY_GATE_PASS_FLAG,
    COST_ENGINE_CONSUMPTION_ALLOWED_FLAG,
    OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG
FROM KMAT_COST_MODEL_DB.CORE_ML.VW_KMAT_PHASE10B_HIERARCHY_V1
WHERE SIMULATION_ID = 'SIM_001';

-- ============================================================
-- KMAT COST MODEL
-- PHASE 14A — IMMUTABLE COMPATIBILITY BASELINE CAPTURE
--
-- Purpose:
--   Capture one immutable regression row for SIM_001 before any
--   Native App compatibility refactoring is applied.
--
-- Safety:
--   Creates/writes only CORE_ML.NATIVE_COMPAT_BASELINE_V1.
--   Does not call or update the cost engine or governance controls.
-- ============================================================

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

CREATE TABLE IF NOT EXISTS
    KMAT_COST_MODEL_DB.CORE_ML.NATIVE_COMPAT_BASELINE_V1 (
        BASELINE_ID VARCHAR NOT NULL,
        BASELINE_VERSION VARCHAR NOT NULL,
        SIMULATION_ID VARCHAR NOT NULL,
        CAPTURED_AT TIMESTAMP_NTZ NOT NULL,
        CAPTURED_BY VARCHAR NOT NULL,

        MATERIAL_COST_USD FLOAT,
        LABOR_COST_USD FLOAT,
        MACHINE_COST_USD FLOAT,
        OVERHEAD_COST_USD FLOAT,
        TOTAL_CONFIGURED_COST_USD FLOAT,
        FLOOR_PRICE_USD FLOAT,
        TARGET_PRICE_USD FLOAT,
        CEILING_PRICE_USD FLOAT,

        BASELINE_TOTAL_COST_USD FLOAT,
        RISK_ADJUSTED_TOTAL_COST_USD FLOAT,
        TOTAL_RISK_UPLIFT_USD FLOAT,
        TOTAL_RISK_UPLIFT_PCT FLOAT,

        CSS_SCORE FLOAT,
        SCRAP_RATE_APPLIED FLOAT,
        AVG_WEIGHTED_FMIS FLOAT,
        MAX_TDS_FACTOR FLOAT,

        BOM_MATCH_CONFIDENCE_SCORE FLOAT,
        BMCS_REVIEW_STATUS VARCHAR,
        FINAL_TRUSTED_COST_ALLOWED_FLAG BOOLEAN,
        QUOTE_TRUST_STATUS VARCHAR,

        RESOLVED_SCRAP_RATE FLOAT,
        CSS_RESOLVED_SOURCE VARCHAR,
        RESOLVED_FMIS_MULTIPLIER FLOAT,
        FMIS_RESOLVED_SOURCE VARCHAR,
        RESOLVED_TDS_FACTOR FLOAT,
        TDS_RESOLVED_SOURCE VARCHAR,
        RESOLVED_BMCS_STATUS VARCHAR,

        SAFETY_GATE_PASS_FLAG BOOLEAN,
        COST_ENGINE_CONSUMPTION_ALLOWED_FLAG BOOLEAN,
        OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG BOOLEAN,

        ACTIVE_POLICY_COUNT NUMBER,
        SHADOW_POLICY_COUNT NUMBER,
        POLICY_AUTHORITY_ENABLED_COUNT NUMBER,
        RUNTIME_AUTHORITY_ROW_COUNT NUMBER,
        ENABLED_RUNTIME_AUTHORITY_COUNT NUMBER,
        RUNTIME_DECISION_COUNT NUMBER,
        RUNTIME_MONITOR_RUN_COUNT NUMBER,

        SNAPSHOT_HASH NUMBER,
        COMMENTS VARCHAR
    );

MERGE INTO KMAT_COST_MODEL_DB.CORE_ML.NATIVE_COMPAT_BASELINE_V1 target
USING (
    SELECT
        'PHASE14A_SIM_001_BASELINE_V1' AS BASELINE_ID,
        'V1' AS BASELINE_VERSION,
        s.SIMULATION_ID,
        CURRENT_TIMESTAMP() AS CAPTURED_AT,
        CURRENT_USER() AS CAPTURED_BY,

        s.MATERIAL_COST_USD::FLOAT AS MATERIAL_COST_USD,
        s.LABOR_COST_USD::FLOAT AS LABOR_COST_USD,
        s.MACHINE_COST_USD::FLOAT AS MACHINE_COST_USD,
        s.OVERHEAD_COST_USD::FLOAT AS OVERHEAD_COST_USD,
        s.TOTAL_CONFIGURED_COST_USD::FLOAT AS TOTAL_CONFIGURED_COST_USD,
        s.FLOOR_PRICE_USD::FLOAT AS FLOOR_PRICE_USD,
        s.TARGET_PRICE_USD::FLOAT AS TARGET_PRICE_USD,
        s.CEILING_PRICE_USD::FLOAT AS CEILING_PRICE_USD,

        s.BASELINE_TOTAL_COST_USD::FLOAT AS BASELINE_TOTAL_COST_USD,
        s.RISK_ADJUSTED_TOTAL_COST_USD::FLOAT AS RISK_ADJUSTED_TOTAL_COST_USD,
        s.TOTAL_RISK_UPLIFT_USD::FLOAT AS TOTAL_RISK_UPLIFT_USD,
        s.TOTAL_RISK_UPLIFT_PCT::FLOAT AS TOTAL_RISK_UPLIFT_PCT,

        s.CSS_SCORE::FLOAT AS CSS_SCORE,
        s.SCRAP_RATE_APPLIED::FLOAT AS SCRAP_RATE_APPLIED,
        s.AVG_WEIGHTED_FMIS::FLOAT AS AVG_WEIGHTED_FMIS,
        s.MAX_TDS_FACTOR::FLOAT AS MAX_TDS_FACTOR,

        s.BOM_MATCH_CONFIDENCE_SCORE::FLOAT AS BOM_MATCH_CONFIDENCE_SCORE,
        s.BMCS_REVIEW_STATUS,
        s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
        s.QUOTE_TRUST_STATUS,

        h.RESOLVED_SCRAP_RATE::FLOAT AS RESOLVED_SCRAP_RATE,
        h.CSS_RESOLVED_SOURCE,
        h.RESOLVED_FMIS_MULTIPLIER::FLOAT AS RESOLVED_FMIS_MULTIPLIER,
        h.FMIS_RESOLVED_SOURCE,
        h.RESOLVED_TDS_FACTOR::FLOAT AS RESOLVED_TDS_FACTOR,
        h.TDS_RESOLVED_SOURCE,
        h.RESOLVED_BMCS_STATUS,

        h.SAFETY_GATE_PASS_FLAG,
        h.COST_ENGINE_CONSUMPTION_ALLOWED_FLAG,
        h.OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG,

        (SELECT COUNT(*)
         FROM KMAT_COST_MODEL_DB.CORE_ML.VW_ML_DECISION_POLICY_CURRENT_V1)
            AS ACTIVE_POLICY_COUNT,
        (SELECT COUNT_IF(DEPLOYMENT_MODE = 'SHADOW')
         FROM KMAT_COST_MODEL_DB.CORE_ML.VW_ML_DECISION_POLICY_CURRENT_V1)
            AS SHADOW_POLICY_COUNT,
        (SELECT COALESCE(COUNT_IF(
                    AUTO_USE_ALLOWED_FLAG = TRUE
                    OR OFFICIAL_COST_IMPACT_ALLOWED_FLAG = TRUE
                    OR BUSINESS_DECISION_ALLOWED_FLAG = TRUE
                ), 0)
         FROM KMAT_COST_MODEL_DB.CORE_ML.VW_ML_DECISION_POLICY_CURRENT_V1)
            AS POLICY_AUTHORITY_ENABLED_COUNT,
        (SELECT COUNT(*)
         FROM KMAT_COST_MODEL_DB.CORE_ML.ML_RUNTIME_AUTHORITY_REGISTRY_V1)
            AS RUNTIME_AUTHORITY_ROW_COUNT,
        (SELECT COUNT(*)
         FROM KMAT_COST_MODEL_DB.CORE_ML.ML_RUNTIME_AUTHORITY_REGISTRY_V1
         WHERE UPPER(AUTHORITY_STATUS) = 'ENABLED')
            AS ENABLED_RUNTIME_AUTHORITY_COUNT,
        (SELECT COUNT(*)
         FROM KMAT_COST_MODEL_DB.CORE_ML.ML_RUNTIME_AUTHORITY_DECISION_V1)
            AS RUNTIME_DECISION_COUNT,
        (SELECT COUNT(*)
         FROM KMAT_COST_MODEL_DB.CORE_ML.ML_RUNTIME_SAFETY_MONITOR_RUN_V1)
            AS RUNTIME_MONITOR_RUN_COUNT,

        HASH(
            s.MATERIAL_COST_USD,
            s.LABOR_COST_USD,
            s.MACHINE_COST_USD,
            s.OVERHEAD_COST_USD,
            s.TOTAL_CONFIGURED_COST_USD,
            s.FLOOR_PRICE_USD,
            s.TARGET_PRICE_USD,
            s.CEILING_PRICE_USD,
            s.BASELINE_TOTAL_COST_USD,
            s.RISK_ADJUSTED_TOTAL_COST_USD,
            s.TOTAL_RISK_UPLIFT_USD,
            s.TOTAL_RISK_UPLIFT_PCT,
            s.CSS_SCORE,
            s.SCRAP_RATE_APPLIED,
            s.AVG_WEIGHTED_FMIS,
            s.MAX_TDS_FACTOR,
            s.BOM_MATCH_CONFIDENCE_SCORE,
            s.BMCS_REVIEW_STATUS,
            s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
            s.QUOTE_TRUST_STATUS,
            h.RESOLVED_SCRAP_RATE,
            h.CSS_RESOLVED_SOURCE,
            h.RESOLVED_FMIS_MULTIPLIER,
            h.FMIS_RESOLVED_SOURCE,
            h.RESOLVED_TDS_FACTOR,
            h.TDS_RESOLVED_SOURCE,
            h.RESOLVED_BMCS_STATUS,
            h.SAFETY_GATE_PASS_FLAG,
            h.COST_ENGINE_CONSUMPTION_ALLOWED_FLAG,
            h.OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG
        ) AS SNAPSHOT_HASH,

        'Immutable regression baseline captured before Native App compatibility refactoring.'
            AS COMMENTS
    FROM KMAT_COST_MODEL_DB.CORE_OUTPUT.KMAT_CONFIGURED_COST_SUMMARY s
    LEFT JOIN KMAT_COST_MODEL_DB.CORE_ML.VW_KMAT_PHASE10B_HIERARCHY_V1 h
        ON s.SIMULATION_ID = h.SIMULATION_ID
    WHERE s.SIMULATION_ID = 'SIM_001'
    QUALIFY ROW_NUMBER() OVER (
        PARTITION BY s.SIMULATION_ID
        ORDER BY s.CALCULATED_AT DESC
    ) = 1
) source
ON target.BASELINE_ID = source.BASELINE_ID
WHEN NOT MATCHED THEN INSERT (
    BASELINE_ID,
    BASELINE_VERSION,
    SIMULATION_ID,
    CAPTURED_AT,
    CAPTURED_BY,
    MATERIAL_COST_USD,
    LABOR_COST_USD,
    MACHINE_COST_USD,
    OVERHEAD_COST_USD,
    TOTAL_CONFIGURED_COST_USD,
    FLOOR_PRICE_USD,
    TARGET_PRICE_USD,
    CEILING_PRICE_USD,
    BASELINE_TOTAL_COST_USD,
    RISK_ADJUSTED_TOTAL_COST_USD,
    TOTAL_RISK_UPLIFT_USD,
    TOTAL_RISK_UPLIFT_PCT,
    CSS_SCORE,
    SCRAP_RATE_APPLIED,
    AVG_WEIGHTED_FMIS,
    MAX_TDS_FACTOR,
    BOM_MATCH_CONFIDENCE_SCORE,
    BMCS_REVIEW_STATUS,
    FINAL_TRUSTED_COST_ALLOWED_FLAG,
    QUOTE_TRUST_STATUS,
    RESOLVED_SCRAP_RATE,
    CSS_RESOLVED_SOURCE,
    RESOLVED_FMIS_MULTIPLIER,
    FMIS_RESOLVED_SOURCE,
    RESOLVED_TDS_FACTOR,
    TDS_RESOLVED_SOURCE,
    RESOLVED_BMCS_STATUS,
    SAFETY_GATE_PASS_FLAG,
    COST_ENGINE_CONSUMPTION_ALLOWED_FLAG,
    OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG,
    ACTIVE_POLICY_COUNT,
    SHADOW_POLICY_COUNT,
    POLICY_AUTHORITY_ENABLED_COUNT,
    RUNTIME_AUTHORITY_ROW_COUNT,
    ENABLED_RUNTIME_AUTHORITY_COUNT,
    RUNTIME_DECISION_COUNT,
    RUNTIME_MONITOR_RUN_COUNT,
    SNAPSHOT_HASH,
    COMMENTS
)
VALUES (
    source.BASELINE_ID,
    source.BASELINE_VERSION,
    source.SIMULATION_ID,
    source.CAPTURED_AT,
    source.CAPTURED_BY,
    source.MATERIAL_COST_USD,
    source.LABOR_COST_USD,
    source.MACHINE_COST_USD,
    source.OVERHEAD_COST_USD,
    source.TOTAL_CONFIGURED_COST_USD,
    source.FLOOR_PRICE_USD,
    source.TARGET_PRICE_USD,
    source.CEILING_PRICE_USD,
    source.BASELINE_TOTAL_COST_USD,
    source.RISK_ADJUSTED_TOTAL_COST_USD,
    source.TOTAL_RISK_UPLIFT_USD,
    source.TOTAL_RISK_UPLIFT_PCT,
    source.CSS_SCORE,
    source.SCRAP_RATE_APPLIED,
    source.AVG_WEIGHTED_FMIS,
    source.MAX_TDS_FACTOR,
    source.BOM_MATCH_CONFIDENCE_SCORE,
    source.BMCS_REVIEW_STATUS,
    source.FINAL_TRUSTED_COST_ALLOWED_FLAG,
    source.QUOTE_TRUST_STATUS,
    source.RESOLVED_SCRAP_RATE,
    source.CSS_RESOLVED_SOURCE,
    source.RESOLVED_FMIS_MULTIPLIER,
    source.FMIS_RESOLVED_SOURCE,
    source.RESOLVED_TDS_FACTOR,
    source.TDS_RESOLVED_SOURCE,
    source.RESOLVED_BMCS_STATUS,
    source.SAFETY_GATE_PASS_FLAG,
    source.COST_ENGINE_CONSUMPTION_ALLOWED_FLAG,
    source.OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG,
    source.ACTIVE_POLICY_COUNT,
    source.SHADOW_POLICY_COUNT,
    source.POLICY_AUTHORITY_ENABLED_COUNT,
    source.RUNTIME_AUTHORITY_ROW_COUNT,
    source.ENABLED_RUNTIME_AUTHORITY_COUNT,
    source.RUNTIME_DECISION_COUNT,
    source.RUNTIME_MONITOR_RUN_COUNT,
    source.SNAPSHOT_HASH,
    source.COMMENTS
);

SELECT *
FROM KMAT_COST_MODEL_DB.CORE_ML.NATIVE_COMPAT_BASELINE_V1
WHERE BASELINE_ID = 'PHASE14A_SIM_001_BASELINE_V1';

-- ============================================================
-- KMAT COST MODEL
-- PHASE 14A — BASELINE VERIFICATION
--
-- Read-only comparison of the current SIM_001 governed output
-- against the immutable compatibility baseline.
-- ============================================================


WITH baseline AS (
    SELECT *
    FROM KMAT_COST_MODEL_DB.CORE_ML.NATIVE_COMPAT_BASELINE_V1
    WHERE BASELINE_ID = 'PHASE14A_SIM_001_BASELINE_V1'
),
current_state AS (
    SELECT
        s.SIMULATION_ID,
        HASH(
            s.MATERIAL_COST_USD,
            s.LABOR_COST_USD,
            s.MACHINE_COST_USD,
            s.OVERHEAD_COST_USD,
            s.TOTAL_CONFIGURED_COST_USD,
            s.FLOOR_PRICE_USD,
            s.TARGET_PRICE_USD,
            s.CEILING_PRICE_USD,
            s.BASELINE_TOTAL_COST_USD,
            s.RISK_ADJUSTED_TOTAL_COST_USD,
            s.TOTAL_RISK_UPLIFT_USD,
            s.TOTAL_RISK_UPLIFT_PCT,
            s.CSS_SCORE,
            s.SCRAP_RATE_APPLIED,
            s.AVG_WEIGHTED_FMIS,
            s.MAX_TDS_FACTOR,
            s.BOM_MATCH_CONFIDENCE_SCORE,
            s.BMCS_REVIEW_STATUS,
            s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
            s.QUOTE_TRUST_STATUS,
            h.RESOLVED_SCRAP_RATE,
            h.CSS_RESOLVED_SOURCE,
            h.RESOLVED_FMIS_MULTIPLIER,
            h.FMIS_RESOLVED_SOURCE,
            h.RESOLVED_TDS_FACTOR,
            h.TDS_RESOLVED_SOURCE,
            h.RESOLVED_BMCS_STATUS,
            h.SAFETY_GATE_PASS_FLAG,
            h.COST_ENGINE_CONSUMPTION_ALLOWED_FLAG,
            h.OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG
        ) AS SNAPSHOT_HASH,
        (SELECT COUNT(*)
         FROM KMAT_COST_MODEL_DB.CORE_ML.VW_ML_DECISION_POLICY_CURRENT_V1)
            AS ACTIVE_POLICY_COUNT,
        (SELECT COUNT_IF(DEPLOYMENT_MODE = 'SHADOW')
         FROM KMAT_COST_MODEL_DB.CORE_ML.VW_ML_DECISION_POLICY_CURRENT_V1)
            AS SHADOW_POLICY_COUNT,
        (SELECT COALESCE(COUNT_IF(
                    AUTO_USE_ALLOWED_FLAG = TRUE
                    OR OFFICIAL_COST_IMPACT_ALLOWED_FLAG = TRUE
                    OR BUSINESS_DECISION_ALLOWED_FLAG = TRUE
                ), 0)
         FROM KMAT_COST_MODEL_DB.CORE_ML.VW_ML_DECISION_POLICY_CURRENT_V1)
            AS POLICY_AUTHORITY_ENABLED_COUNT,
        (SELECT COUNT(*)
         FROM KMAT_COST_MODEL_DB.CORE_ML.ML_RUNTIME_AUTHORITY_REGISTRY_V1)
            AS RUNTIME_AUTHORITY_ROW_COUNT,
        (SELECT COUNT(*)
         FROM KMAT_COST_MODEL_DB.CORE_ML.ML_RUNTIME_AUTHORITY_REGISTRY_V1
         WHERE UPPER(AUTHORITY_STATUS) = 'ENABLED')
            AS ENABLED_RUNTIME_AUTHORITY_COUNT,
        (SELECT COUNT(*)
         FROM KMAT_COST_MODEL_DB.CORE_ML.ML_RUNTIME_AUTHORITY_DECISION_V1)
            AS RUNTIME_DECISION_COUNT,
        (SELECT COUNT(*)
         FROM KMAT_COST_MODEL_DB.CORE_ML.ML_RUNTIME_SAFETY_MONITOR_RUN_V1)
            AS RUNTIME_MONITOR_RUN_COUNT
    FROM KMAT_COST_MODEL_DB.CORE_OUTPUT.KMAT_CONFIGURED_COST_SUMMARY s
    LEFT JOIN KMAT_COST_MODEL_DB.CORE_ML.VW_KMAT_PHASE10B_HIERARCHY_V1 h
        ON s.SIMULATION_ID = h.SIMULATION_ID
    WHERE s.SIMULATION_ID = 'SIM_001'
    QUALIFY ROW_NUMBER() OVER (
        PARTITION BY s.SIMULATION_ID
        ORDER BY s.CALCULATED_AT DESC
    ) = 1
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            b.SNAPSHOT_HASH = c.SNAPSHOT_HASH
            AND b.ACTIVE_POLICY_COUNT = c.ACTIVE_POLICY_COUNT
            AND b.SHADOW_POLICY_COUNT = c.SHADOW_POLICY_COUNT
            AND c.POLICY_AUTHORITY_ENABLED_COUNT = 0
            AND c.ENABLED_RUNTIME_AUTHORITY_COUNT = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),
    'phase', 'PHASE_14A',
    'baseline_id', b.BASELINE_ID,
    'simulation_id', b.SIMULATION_ID,
    'cost_and_governance_snapshot_match', b.SNAPSHOT_HASH = c.SNAPSHOT_HASH,
    'baseline_snapshot_hash', b.SNAPSHOT_HASH,
    'current_snapshot_hash', c.SNAPSHOT_HASH,
    'active_policy_count', c.ACTIVE_POLICY_COUNT,
    'shadow_policy_count', c.SHADOW_POLICY_COUNT,
    'policy_authority_enabled_count', c.POLICY_AUTHORITY_ENABLED_COUNT,
    'runtime_authority_row_count', c.RUNTIME_AUTHORITY_ROW_COUNT,
    'enabled_runtime_authority_count', c.ENABLED_RUNTIME_AUTHORITY_COUNT,
    'runtime_decision_count', c.RUNTIME_DECISION_COUNT,
    'runtime_monitor_run_count', c.RUNTIME_MONITOR_RUN_COUNT,
    'official_cost_changed', b.SNAPSHOT_HASH <> c.SNAPSHOT_HASH
) AS PHASE14A_BASELINE_VERIFICATION
FROM baseline b
CROSS JOIN current_state c;

-- ============================================================
-- KMAT COST MODEL
-- PHASE 14A — PROCEDURE RIGHTS AND IDENTITY INVENTORY
--
-- Read-only metadata review. No procedure is replaced.
-- Run each DESCRIBE statement and record the "execute as" row.
-- ============================================================

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_INTERNAL;

-- Core deterministic procedure candidate.
DESCRIBE PROCEDURE
    KMAT_COST_MODEL_DB.CORE_INTERNAL.RUN_KMAT_COST_SIMULATION(STRING);

-- Cortex/RFQ procedure candidates observed in project source.
DESCRIBE PROCEDURE
    KMAT_COST_MODEL_DB.CORE_INTERNAL.RUN_CORTEX_COST_EXPLANATION(STRING);

DESCRIBE PROCEDURE
    KMAT_COST_MODEL_DB.CORE_INTERNAL.RUN_CORTEX_RFQ_QUOTE_PIPELINE(STRING);

DESCRIBE PROCEDURE
    KMAT_COST_MODEL_DB.CORE_INTERNAL.RUN_CORTEX_BMCS_ASSESSMENT(STRING);

DESCRIBE PROCEDURE
    KMAT_COST_MODEL_DB.CORE_INTERNAL.RUN_CORTEX_CSS_EXPLANATION_ASSIST(STRING);

-- Database-wide procedure inventory and identity-sensitive source scan.
SELECT
    PROCEDURE_SCHEMA,
    PROCEDURE_NAME,
    ARGUMENT_SIGNATURE,
    PROCEDURE_LANGUAGE,
    PROCEDURE_OWNER,
    IFF(
        REGEXP_LIKE(COALESCE(PROCEDURE_DEFINITION, ''),
                    'CURRENT_USER\\s*\\(', 'i'),
        TRUE,
        FALSE
    ) AS USES_CURRENT_USER_FLAG,
    IFF(
        REGEXP_LIKE(COALESCE(PROCEDURE_DEFINITION, ''),
                    'CURRENT_ROLE\\s*\\(', 'i'),
        TRUE,
        FALSE
    ) AS USES_CURRENT_ROLE_FLAG,
    IFF(
        REGEXP_LIKE(COALESCE(PROCEDURE_DEFINITION, ''),
                    'CURRENT_WAREHOUSE\\s*\\(', 'i'),
        TRUE,
        FALSE
    ) AS USES_CURRENT_WAREHOUSE_FLAG,
    IFF(
        REGEXP_LIKE(COALESCE(PROCEDURE_DEFINITION, ''),
                    'CREATE\\s+(OR\\s+REPLACE\\s+)?TEMP(ORARY)?', 'i'),
        TRUE,
        FALSE
    ) AS CREATES_TEMP_OBJECT_FLAG
FROM KMAT_COST_MODEL_DB.INFORMATION_SCHEMA.PROCEDURES
WHERE PROCEDURE_SCHEMA IN ('CORE_INTERNAL', 'CORE_ML')
ORDER BY PROCEDURE_SCHEMA, PROCEDURE_NAME, ARGUMENT_SIGNATURE;

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

-- ============================================================
-- PHASE 14C.1 — PROCEDURE RIGHTS PREFLIGHT
--
-- Purpose:
--   1. Confirm the 12 CORE_INTERNAL procedures exist.
--   2. Read each deployed DDL.
--   3. Verify the current execution mode and context dependencies.
--
-- This script is read-only.
-- Expected:
--   * missing-procedure query = zero rows
--   * 12 procedure rows returned
--   * current mode normally CALLER before conversion
-- ============================================================

WITH REQUIRED_PROCEDURES AS (
    SELECT * FROM VALUES
        ('PREPARE_RFQ_SIMULATION_INPUTS', '(VARCHAR)'),
        ('RUN_CORTEX_BMCS_ASSESSMENT', '(VARCHAR)'),
        ('RUN_CORTEX_COST_EXPLANATION', '(VARCHAR)'),
        ('RUN_CORTEX_CSS_EXPLANATION_ASSIST', '(VARCHAR)'),
        ('RUN_CORTEX_FMIS_SIGNAL_ASSIST', '(VARCHAR)'),
        ('RUN_CORTEX_RFQ_INTAKE_PIPELINE', '(VARCHAR)'),
        ('RUN_CORTEX_RFQ_QUOTE_PIPELINE', '(VARCHAR)'),
        ('RUN_CORTEX_TDS_EXPLANATION_ASSIST', '(VARCHAR, VARCHAR)'),
        ('RUN_KMAT_COST_SIMULATION', '(VARCHAR)'),
        ('RUN_KMAT_COST_SIMULATION_GOVERNED_V2', '(VARCHAR)'),
        ('RUN_KMAT_COST_SIMULATION_GOVERNED_V3', '(VARCHAR)'),
        ('RUN_RULE_BASED_BMCS_SCORING', '(VARCHAR)')
    AS required(
        PROCEDURE_NAME,
        TYPE_SIGNATURE
    )
),
DEPLOYED_PROCEDURES AS (
    SELECT
        PROCEDURE_NAME,
        ARGUMENT_SIGNATURE,
        PROCEDURE_LANGUAGE,
        PROCEDURE_OWNER
    FROM
        KMAT_COST_MODEL_DB.INFORMATION_SCHEMA.PROCEDURES
    WHERE PROCEDURE_SCHEMA = 'CORE_INTERNAL'
)
SELECT
    required.PROCEDURE_NAME,
    required.TYPE_SIGNATURE
FROM REQUIRED_PROCEDURES required
LEFT JOIN DEPLOYED_PROCEDURES deployed
    ON required.PROCEDURE_NAME =
       deployed.PROCEDURE_NAME
WHERE deployed.PROCEDURE_NAME IS NULL
ORDER BY required.PROCEDURE_NAME;


WITH PROCEDURE_TARGETS AS (
    SELECT * FROM VALUES
        ('PREPARE_RFQ_SIMULATION_INPUTS', '(VARCHAR)'),
        ('RUN_CORTEX_BMCS_ASSESSMENT', '(VARCHAR)'),
        ('RUN_CORTEX_COST_EXPLANATION', '(VARCHAR)'),
        ('RUN_CORTEX_CSS_EXPLANATION_ASSIST', '(VARCHAR)'),
        ('RUN_CORTEX_FMIS_SIGNAL_ASSIST', '(VARCHAR)'),
        ('RUN_CORTEX_RFQ_INTAKE_PIPELINE', '(VARCHAR)'),
        ('RUN_CORTEX_RFQ_QUOTE_PIPELINE', '(VARCHAR)'),
        ('RUN_CORTEX_TDS_EXPLANATION_ASSIST', '(VARCHAR, VARCHAR)'),
        ('RUN_KMAT_COST_SIMULATION', '(VARCHAR)'),
        ('RUN_KMAT_COST_SIMULATION_GOVERNED_V2', '(VARCHAR)'),
        ('RUN_KMAT_COST_SIMULATION_GOVERNED_V3', '(VARCHAR)'),
        ('RUN_RULE_BASED_BMCS_SCORING', '(VARCHAR)')
    AS target(
        PROCEDURE_NAME,
        TYPE_SIGNATURE
    )
),
DEPLOYED_DDL AS (
    SELECT
        target.PROCEDURE_NAME,
        target.TYPE_SIGNATURE,
        COALESCE(proc.PROCEDURE_DEFINITION, '') AS PROCEDURE_DDL
    FROM PROCEDURE_TARGETS target
    LEFT JOIN KMAT_COST_MODEL_DB.INFORMATION_SCHEMA.PROCEDURES proc
        ON proc.PROCEDURE_SCHEMA = 'CORE_INTERNAL'
       AND proc.PROCEDURE_NAME = target.PROCEDURE_NAME
)
SELECT
    PROCEDURE_NAME,
    TYPE_SIGNATURE,

    CASE
        WHEN REGEXP_LIKE(
            UPPER(PROCEDURE_DDL),
            'EXECUTE[[:space:]]+AS[[:space:]]+RESTRICTED[[:space:]]+CALLER'
        )
        THEN 'RESTRICTED_CALLER'

        WHEN REGEXP_LIKE(
            UPPER(PROCEDURE_DDL),
            'EXECUTE[[:space:]]+AS[[:space:]]+CALLER'
        )
        THEN 'CALLER'

        WHEN REGEXP_LIKE(
            UPPER(PROCEDURE_DDL),
            'EXECUTE[[:space:]]+AS[[:space:]]+OWNER'
        )
        THEN 'OWNER'

        ELSE 'OWNER_DEFAULT'
    END AS EXECUTION_MODE,

    REGEXP_LIKE(
        UPPER(PROCEDURE_DDL),
        'CURRENT_USER[[:space:]]*\\('
    ) AS USES_CURRENT_USER_FLAG,

    REGEXP_LIKE(
        UPPER(PROCEDURE_DDL),
        'CURRENT_ROLE[[:space:]]*\\('
    ) AS USES_CURRENT_ROLE_FLAG,

    REGEXP_LIKE(
        UPPER(PROCEDURE_DDL),
        'CURRENT_WAREHOUSE[[:space:]]*\\('
    ) AS USES_CURRENT_WAREHOUSE_FLAG,

    REGEXP_LIKE(
        UPPER(PROCEDURE_DDL),
        'CURRENT_SESSION[[:space:]]*\\('
    ) AS USES_CURRENT_SESSION_FLAG,

    REGEXP_LIKE(
        UPPER(PROCEDURE_DDL),
        '.*CREATE[[:space:]]+(OR[[:space:]]+REPLACE[[:space:]]+)?TEMP'
    ) AS CREATES_TEMP_OBJECT_FLAG,

    REGEXP_LIKE(
        UPPER(PROCEDURE_DDL),
        '(^|[[:space:];])LIST[[:space:]]+@.*'
    ) AS USES_LIST_COMMAND_FLAG

FROM DEPLOYED_DDL
ORDER BY PROCEDURE_NAME;

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

-- ============================================================
-- PHASE 14C.1 — CONVERT VERIFIED CORE_INTERNAL PROCEDURES
--                  TO OWNER RIGHTS
--
-- No procedure body, signature, business formula, table, model,
-- policy, runtime switch or Streamlit source is changed.
-- ============================================================

CREATE TABLE IF NOT EXISTS
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PROCEDURE_RIGHTS_CHANGE_V1 (
            CHANGE_BATCH_ID VARCHAR NOT NULL,
            PROCEDURE_SCHEMA VARCHAR NOT NULL,
            PROCEDURE_NAME VARCHAR NOT NULL,
            TYPE_SIGNATURE VARCHAR NOT NULL,
            PREVIOUS_EXECUTION_MODE VARCHAR NOT NULL,
            TARGET_EXECUTION_MODE VARCHAR NOT NULL,
            CHANGE_STATUS VARCHAR NOT NULL,
            CHANGED_BY VARCHAR NOT NULL,
            CHANGED_AT TIMESTAMP_NTZ NOT NULL,
            COMMENTS VARCHAR
        );

MERGE INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PROCEDURE_RIGHTS_CHANGE_V1 target
USING (
    SELECT * FROM VALUES

        ('PHASE14C1_OWNER_RIGHTS_V1', 'CORE_INTERNAL', 'PREPARE_RFQ_SIMULATION_INPUTS', '(VARCHAR)', 'CALLER', 'OWNER', 'PLANNED'),
        ('PHASE14C1_OWNER_RIGHTS_V1', 'CORE_INTERNAL', 'RUN_CORTEX_BMCS_ASSESSMENT', '(VARCHAR)', 'CALLER', 'OWNER', 'PLANNED'),
        ('PHASE14C1_OWNER_RIGHTS_V1', 'CORE_INTERNAL', 'RUN_CORTEX_COST_EXPLANATION', '(VARCHAR)', 'CALLER', 'OWNER', 'PLANNED'),
        ('PHASE14C1_OWNER_RIGHTS_V1', 'CORE_INTERNAL', 'RUN_CORTEX_CSS_EXPLANATION_ASSIST', '(VARCHAR)', 'CALLER', 'OWNER', 'PLANNED'),
        ('PHASE14C1_OWNER_RIGHTS_V1', 'CORE_INTERNAL', 'RUN_CORTEX_FMIS_SIGNAL_ASSIST', '(VARCHAR)', 'CALLER', 'OWNER', 'PLANNED'),
        ('PHASE14C1_OWNER_RIGHTS_V1', 'CORE_INTERNAL', 'RUN_CORTEX_RFQ_INTAKE_PIPELINE', '(VARCHAR)', 'CALLER', 'OWNER', 'PLANNED'),
        ('PHASE14C1_OWNER_RIGHTS_V1', 'CORE_INTERNAL', 'RUN_CORTEX_RFQ_QUOTE_PIPELINE', '(VARCHAR)', 'CALLER', 'OWNER', 'PLANNED'),
        ('PHASE14C1_OWNER_RIGHTS_V1', 'CORE_INTERNAL', 'RUN_CORTEX_TDS_EXPLANATION_ASSIST', '(VARCHAR, VARCHAR)', 'CALLER', 'OWNER', 'PLANNED'),
        ('PHASE14C1_OWNER_RIGHTS_V1', 'CORE_INTERNAL', 'RUN_KMAT_COST_SIMULATION', '(VARCHAR)', 'CALLER', 'OWNER', 'PLANNED'),
        ('PHASE14C1_OWNER_RIGHTS_V1', 'CORE_INTERNAL', 'RUN_KMAT_COST_SIMULATION_GOVERNED_V2', '(VARCHAR)', 'CALLER', 'OWNER', 'PLANNED'),
        ('PHASE14C1_OWNER_RIGHTS_V1', 'CORE_INTERNAL', 'RUN_KMAT_COST_SIMULATION_GOVERNED_V3', '(VARCHAR)', 'CALLER', 'OWNER', 'PLANNED'),
        ('PHASE14C1_OWNER_RIGHTS_V1', 'CORE_INTERNAL', 'RUN_RULE_BASED_BMCS_SCORING', '(VARCHAR)', 'CALLER', 'OWNER', 'PLANNED')
    AS seed(
        CHANGE_BATCH_ID,
        PROCEDURE_SCHEMA,
        PROCEDURE_NAME,
        TYPE_SIGNATURE,
        PREVIOUS_EXECUTION_MODE,
        TARGET_EXECUTION_MODE,
        CHANGE_STATUS
    )
) source
ON target.CHANGE_BATCH_ID = source.CHANGE_BATCH_ID
AND target.PROCEDURE_SCHEMA = source.PROCEDURE_SCHEMA
AND target.PROCEDURE_NAME = source.PROCEDURE_NAME
AND target.TYPE_SIGNATURE = source.TYPE_SIGNATURE
WHEN NOT MATCHED THEN INSERT (
    CHANGE_BATCH_ID,
    PROCEDURE_SCHEMA,
    PROCEDURE_NAME,
    TYPE_SIGNATURE,
    PREVIOUS_EXECUTION_MODE,
    TARGET_EXECUTION_MODE,
    CHANGE_STATUS,
    CHANGED_BY,
    CHANGED_AT,
    COMMENTS
)
VALUES (
    source.CHANGE_BATCH_ID,
    source.PROCEDURE_SCHEMA,
    source.PROCEDURE_NAME,
    source.TYPE_SIGNATURE,
    source.PREVIOUS_EXECUTION_MODE,
    source.TARGET_EXECUTION_MODE,
    source.CHANGE_STATUS,
    CURRENT_USER(),
    CURRENT_TIMESTAMP(),
    'Phase 14C.1 Native App compatibility conversion.'
);


ALTER PROCEDURE IF EXISTS
    KMAT_COST_MODEL_DB.CORE_INTERNAL.PREPARE_RFQ_SIMULATION_INPUTS(VARCHAR)
    EXECUTE AS OWNER;

ALTER PROCEDURE IF EXISTS
    KMAT_COST_MODEL_DB.CORE_INTERNAL.RUN_CORTEX_BMCS_ASSESSMENT(VARCHAR)
    EXECUTE AS OWNER;

ALTER PROCEDURE IF EXISTS
    KMAT_COST_MODEL_DB.CORE_INTERNAL.RUN_CORTEX_COST_EXPLANATION(VARCHAR)
    EXECUTE AS OWNER;

ALTER PROCEDURE IF EXISTS
    KMAT_COST_MODEL_DB.CORE_INTERNAL.RUN_CORTEX_CSS_EXPLANATION_ASSIST(VARCHAR)
    EXECUTE AS OWNER;

ALTER PROCEDURE IF EXISTS
    KMAT_COST_MODEL_DB.CORE_INTERNAL.RUN_CORTEX_FMIS_SIGNAL_ASSIST(VARCHAR)
    EXECUTE AS OWNER;

ALTER PROCEDURE IF EXISTS
    KMAT_COST_MODEL_DB.CORE_INTERNAL.RUN_CORTEX_RFQ_INTAKE_PIPELINE(VARCHAR)
    EXECUTE AS OWNER;

ALTER PROCEDURE IF EXISTS
    KMAT_COST_MODEL_DB.CORE_INTERNAL.RUN_CORTEX_RFQ_QUOTE_PIPELINE(VARCHAR)
    EXECUTE AS OWNER;

ALTER PROCEDURE IF EXISTS
    KMAT_COST_MODEL_DB.CORE_INTERNAL.RUN_CORTEX_TDS_EXPLANATION_ASSIST(VARCHAR, VARCHAR)
    EXECUTE AS OWNER;

ALTER PROCEDURE IF EXISTS
    KMAT_COST_MODEL_DB.CORE_INTERNAL.RUN_KMAT_COST_SIMULATION(VARCHAR)
    EXECUTE AS OWNER;

ALTER PROCEDURE IF EXISTS
    KMAT_COST_MODEL_DB.CORE_INTERNAL.RUN_KMAT_COST_SIMULATION_GOVERNED_V2(VARCHAR)
    EXECUTE AS OWNER;

ALTER PROCEDURE IF EXISTS
    KMAT_COST_MODEL_DB.CORE_INTERNAL.RUN_KMAT_COST_SIMULATION_GOVERNED_V3(VARCHAR)
    EXECUTE AS OWNER;

ALTER PROCEDURE IF EXISTS
    KMAT_COST_MODEL_DB.CORE_INTERNAL.RUN_RULE_BASED_BMCS_SCORING(VARCHAR)
    EXECUTE AS OWNER;


UPDATE
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PROCEDURE_RIGHTS_CHANGE_V1
SET
    CHANGE_STATUS = 'APPLIED',
    CHANGED_BY = CURRENT_USER(),
    CHANGED_AT = CURRENT_TIMESTAMP(),
    COMMENTS =
        'Execution mode changed only; procedure body and signature preserved.'
WHERE CHANGE_BATCH_ID = 'PHASE14C1_OWNER_RIGHTS_V1';

SELECT
    CHANGE_BATCH_ID,
    PROCEDURE_SCHEMA,
    PROCEDURE_NAME,
    TYPE_SIGNATURE,
    PREVIOUS_EXECUTION_MODE,
    TARGET_EXECUTION_MODE,
    CHANGE_STATUS,
    CHANGED_BY,
    CHANGED_AT
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PROCEDURE_RIGHTS_CHANGE_V1
WHERE CHANGE_BATCH_ID = 'PHASE14C1_OWNER_RIGHTS_V1'
ORDER BY PROCEDURE_NAME;

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

-- ============================================================
-- PHASE 14C.1 — RIGHTS CONVERSION VERIFICATION
--
-- Read-only.
-- Expected:
--   total procedure count          = 12
--   owner-rights procedure count   = 12
--   caller-rights procedure count  = 0
--   context-sensitive count        = 0
--   status                         = SUCCESS
-- ============================================================

WITH PROCEDURE_TARGETS AS (
    SELECT * FROM VALUES
        ('PREPARE_RFQ_SIMULATION_INPUTS', '(VARCHAR)'),
        ('RUN_CORTEX_BMCS_ASSESSMENT', '(VARCHAR)'),
        ('RUN_CORTEX_COST_EXPLANATION', '(VARCHAR)'),
        ('RUN_CORTEX_CSS_EXPLANATION_ASSIST', '(VARCHAR)'),
        ('RUN_CORTEX_FMIS_SIGNAL_ASSIST', '(VARCHAR)'),
        ('RUN_CORTEX_RFQ_INTAKE_PIPELINE', '(VARCHAR)'),
        ('RUN_CORTEX_RFQ_QUOTE_PIPELINE', '(VARCHAR)'),
        ('RUN_CORTEX_TDS_EXPLANATION_ASSIST', '(VARCHAR, VARCHAR)'),
        ('RUN_KMAT_COST_SIMULATION', '(VARCHAR)'),
        ('RUN_KMAT_COST_SIMULATION_GOVERNED_V2', '(VARCHAR)'),
        ('RUN_KMAT_COST_SIMULATION_GOVERNED_V3', '(VARCHAR)'),
        ('RUN_RULE_BASED_BMCS_SCORING', '(VARCHAR)')
    AS target(
        PROCEDURE_NAME,
        TYPE_SIGNATURE
    )
),
DEPLOYED_DDL AS (
    SELECT
        target.PROCEDURE_NAME,
        target.TYPE_SIGNATURE,
        COALESCE(proc.PROCEDURE_DEFINITION, '') AS PROCEDURE_DDL
    FROM PROCEDURE_TARGETS target
    LEFT JOIN KMAT_COST_MODEL_DB.INFORMATION_SCHEMA.PROCEDURES proc
        ON proc.PROCEDURE_SCHEMA = 'CORE_INTERNAL'
       AND proc.PROCEDURE_NAME = target.PROCEDURE_NAME
),
CLASSIFIED AS (
    SELECT
        PROCEDURE_NAME,
        TYPE_SIGNATURE,

        CASE
            WHEN REGEXP_LIKE(
                UPPER(PROCEDURE_DDL),
                'EXECUTE[[:space:]]+AS[[:space:]]+RESTRICTED[[:space:]]+CALLER'
            )
            THEN 'RESTRICTED_CALLER'

            WHEN REGEXP_LIKE(
                UPPER(PROCEDURE_DDL),
                'EXECUTE[[:space:]]+AS[[:space:]]+CALLER'
            )
            THEN 'CALLER'

            WHEN REGEXP_LIKE(
                UPPER(PROCEDURE_DDL),
                'EXECUTE[[:space:]]+AS[[:space:]]+OWNER'
            )
            THEN 'OWNER'

            ELSE 'OWNER_DEFAULT'
        END AS EXECUTION_MODE,

        (
            REGEXP_LIKE(
                UPPER(PROCEDURE_DDL),
                'CURRENT_USER[[:space:]]*\\('
            )
            OR REGEXP_LIKE(
                UPPER(PROCEDURE_DDL),
                'CURRENT_ROLE[[:space:]]*\\('
            )
            OR REGEXP_LIKE(
                UPPER(PROCEDURE_DDL),
                'CURRENT_WAREHOUSE[[:space:]]*\\('
            )
            OR REGEXP_LIKE(
                UPPER(PROCEDURE_DDL),
                'CURRENT_SESSION[[:space:]]*\\('
            )
        ) AS CONTEXT_SENSITIVE_FLAG

    FROM DEPLOYED_DDL
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COUNT(*) = 12
            AND COUNT_IF(
                EXECUTION_MODE IN (
                    'OWNER',
                    'OWNER_DEFAULT'
                )
            ) = 12
            AND COUNT_IF(
                EXECUTION_MODE = 'CALLER'
            ) = 0
            AND COUNT_IF(
                CONTEXT_SENSITIVE_FLAG = TRUE
            ) = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase', 'PHASE_14C_1',

    'total_procedure_count',
        COUNT(*),

    'owner_rights_procedure_count',
        COUNT_IF(
            EXECUTION_MODE IN (
                'OWNER',
                'OWNER_DEFAULT'
            )
        ),

    'unrestricted_caller_rights_count',
        COUNT_IF(
            EXECUTION_MODE = 'CALLER'
        ),

    'restricted_caller_rights_count',
        COUNT_IF(
            EXECUTION_MODE = 'RESTRICTED_CALLER'
        ),

    'context_sensitive_procedure_count',
        COUNT_IF(
            CONTEXT_SENSITIVE_FLAG = TRUE
        ),

    'procedure_body_changed', FALSE,
    'procedure_signature_changed', FALSE,
    'official_cost_changed', FALSE,
    'ml_authority_changed', FALSE
) AS PHASE14C1_RIGHTS_VERIFICATION
FROM CLASSIFIED;


WITH PROCEDURE_TARGETS AS (
    SELECT * FROM VALUES
        ('PREPARE_RFQ_SIMULATION_INPUTS', '(VARCHAR)'),
        ('RUN_CORTEX_BMCS_ASSESSMENT', '(VARCHAR)'),
        ('RUN_CORTEX_COST_EXPLANATION', '(VARCHAR)'),
        ('RUN_CORTEX_CSS_EXPLANATION_ASSIST', '(VARCHAR)'),
        ('RUN_CORTEX_FMIS_SIGNAL_ASSIST', '(VARCHAR)'),
        ('RUN_CORTEX_RFQ_INTAKE_PIPELINE', '(VARCHAR)'),
        ('RUN_CORTEX_RFQ_QUOTE_PIPELINE', '(VARCHAR)'),
        ('RUN_CORTEX_TDS_EXPLANATION_ASSIST', '(VARCHAR, VARCHAR)'),
        ('RUN_KMAT_COST_SIMULATION', '(VARCHAR)'),
        ('RUN_KMAT_COST_SIMULATION_GOVERNED_V2', '(VARCHAR)'),
        ('RUN_KMAT_COST_SIMULATION_GOVERNED_V3', '(VARCHAR)'),
        ('RUN_RULE_BASED_BMCS_SCORING', '(VARCHAR)')
    AS target(
        PROCEDURE_NAME,
        TYPE_SIGNATURE
    )
)
SELECT
    target.PROCEDURE_NAME,
    target.TYPE_SIGNATURE,
    COALESCE(proc.PROCEDURE_DEFINITION, '') AS PROCEDURE_DDL
FROM PROCEDURE_TARGETS target
LEFT JOIN KMAT_COST_MODEL_DB.INFORMATION_SCHEMA.PROCEDURES proc
    ON proc.PROCEDURE_SCHEMA = 'CORE_INTERNAL'
   AND proc.PROCEDURE_NAME = target.PROCEDURE_NAME
ORDER BY target.PROCEDURE_NAME;

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

UPDATE
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PROCEDURE_RIGHTS_CHANGE_V1
SET
    PREVIOUS_EXECUTION_MODE = 'OWNER_DEFAULT',
    TARGET_EXECUTION_MODE = 'OWNER',
    CHANGE_STATUS = 'VALIDATED_ALREADY_COMPATIBLE',
    CHANGED_BY = CURRENT_USER(),
    CHANGED_AT = CURRENT_TIMESTAMP(),
    COMMENTS =
        'Preflight confirmed the procedure already used default owner rights. '
        || 'ALTER PROCEDURE EXECUTE AS OWNER was idempotent; no procedure body '
        || 'or effective execution model changed.'
WHERE CHANGE_BATCH_ID = 'PHASE14C1_OWNER_RIGHTS_V1';

SELECT
    PROCEDURE_NAME,
    TYPE_SIGNATURE,
    PREVIOUS_EXECUTION_MODE,
    TARGET_EXECUTION_MODE,
    CHANGE_STATUS,
    COMMENTS
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PROCEDURE_RIGHTS_CHANGE_V1
WHERE CHANGE_BATCH_ID = 'PHASE14C1_OWNER_RIGHTS_V1'
ORDER BY PROCEDURE_NAME;

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_INTERNAL;

-- ============================================================
-- PHASE 14C.1 — CONTROLLED FUNCTIONAL SMOKE TEST
--
-- This intentionally reruns only the deterministic governed
-- simulation for the existing golden scenario SIM_001.
-- It does not activate ML or enable runtime authority.
-- ============================================================

CALL
    KMAT_COST_MODEL_DB.CORE_INTERNAL
        .RUN_KMAT_COST_SIMULATION_GOVERNED_V3(
            'SIM_001'
        );

SELECT
    SIMULATION_ID,
    BASELINE_TOTAL_COST_USD,
    RISK_ADJUSTED_TOTAL_COST_USD,
    TOTAL_RISK_UPLIFT_USD,
    TOTAL_RISK_UPLIFT_PCT,
    BOM_MATCH_CONFIDENCE_SCORE,
    BMCS_REVIEW_STATUS,
    FINAL_TRUSTED_COST_ALLOWED_FLAG,
    QUOTE_TRUST_STATUS,
    CALCULATED_AT
FROM
    KMAT_COST_MODEL_DB.CORE_OUTPUT
        .KMAT_CONFIGURED_COST_SUMMARY
WHERE SIMULATION_ID = 'SIM_001'
QUALIFY ROW_NUMBER() OVER (
    PARTITION BY SIMULATION_ID
    ORDER BY CALCULATED_AT DESC
) = 1;

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

-- ============================================================
-- PHASE 14C.1 — GOLDEN BASELINE VERIFICATION
-- ============================================================

WITH baseline AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_BASELINE_V1
    WHERE BASELINE_ID =
          'PHASE14A_SIM_001_BASELINE_V1'
),
current_state AS (
    SELECT
        s.SIMULATION_ID,

        HASH(
            s.MATERIAL_COST_USD,
            s.LABOR_COST_USD,
            s.MACHINE_COST_USD,
            s.OVERHEAD_COST_USD,
            s.TOTAL_CONFIGURED_COST_USD,
            s.FLOOR_PRICE_USD,
            s.TARGET_PRICE_USD,
            s.CEILING_PRICE_USD,
            s.BASELINE_TOTAL_COST_USD,
            s.RISK_ADJUSTED_TOTAL_COST_USD,
            s.TOTAL_RISK_UPLIFT_USD,
            s.TOTAL_RISK_UPLIFT_PCT,
            s.CSS_SCORE,
            s.SCRAP_RATE_APPLIED,
            s.AVG_WEIGHTED_FMIS,
            s.MAX_TDS_FACTOR,
            s.BOM_MATCH_CONFIDENCE_SCORE,
            s.BMCS_REVIEW_STATUS,
            s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
            s.QUOTE_TRUST_STATUS,
            h.RESOLVED_SCRAP_RATE,
            h.CSS_RESOLVED_SOURCE,
            h.RESOLVED_FMIS_MULTIPLIER,
            h.FMIS_RESOLVED_SOURCE,
            h.RESOLVED_TDS_FACTOR,
            h.TDS_RESOLVED_SOURCE,
            h.RESOLVED_BMCS_STATUS,
            h.SAFETY_GATE_PASS_FLAG,
            h.COST_ENGINE_CONSUMPTION_ALLOWED_FLAG,
            h.OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG
        ) AS SNAPSHOT_HASH,

        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS ACTIVE_POLICY_COUNT,

        (
            SELECT COUNT_IF(
                DEPLOYMENT_MODE = 'SHADOW'
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS SHADOW_POLICY_COUNT,

        (
            SELECT COALESCE(
                COUNT_IF(
                    AUTO_USE_ALLOWED_FLAG = TRUE
                    OR OFFICIAL_COST_IMPACT_ALLOWED_FLAG = TRUE
                    OR BUSINESS_DECISION_ALLOWED_FLAG = TRUE
                ),
                0
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS POLICY_AUTHORITY_ENABLED_COUNT,

        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .ML_RUNTIME_AUTHORITY_REGISTRY_V1
            WHERE UPPER(AUTHORITY_STATUS) = 'ENABLED'
        ) AS ENABLED_RUNTIME_AUTHORITY_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_OUTPUT
            .KMAT_CONFIGURED_COST_SUMMARY s

    LEFT JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .VW_KMAT_PHASE10B_HIERARCHY_V1 h
        ON s.SIMULATION_ID = h.SIMULATION_ID

    WHERE s.SIMULATION_ID = 'SIM_001'

    QUALIFY ROW_NUMBER() OVER (
        PARTITION BY s.SIMULATION_ID
        ORDER BY s.CALCULATED_AT DESC
    ) = 1
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            baseline.SNAPSHOT_HASH =
                current_state.SNAPSHOT_HASH
            AND baseline.ACTIVE_POLICY_COUNT =
                current_state.ACTIVE_POLICY_COUNT
            AND baseline.SHADOW_POLICY_COUNT =
                current_state.SHADOW_POLICY_COUNT
            AND current_state
                .POLICY_AUTHORITY_ENABLED_COUNT = 0
            AND current_state
                .ENABLED_RUNTIME_AUTHORITY_COUNT = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase', 'PHASE_14C_1',

    'baseline_id',
        baseline.BASELINE_ID,

    'simulation_id',
        baseline.SIMULATION_ID,

    'cost_and_governance_snapshot_match',
        baseline.SNAPSHOT_HASH =
        current_state.SNAPSHOT_HASH,

    'baseline_snapshot_hash',
        baseline.SNAPSHOT_HASH,

    'current_snapshot_hash',
        current_state.SNAPSHOT_HASH,

    'active_policy_count',
        current_state.ACTIVE_POLICY_COUNT,

    'shadow_policy_count',
        current_state.SHADOW_POLICY_COUNT,

    'policy_authority_enabled_count',
        current_state
            .POLICY_AUTHORITY_ENABLED_COUNT,

    'enabled_runtime_authority_count',
        current_state
            .ENABLED_RUNTIME_AUTHORITY_COUNT,

    'official_cost_changed',
        baseline.SNAPSHOT_HASH <>
        current_state.SNAPSHOT_HASH,

    'procedure_body_changed', FALSE,
    'ml_authority_changed', FALSE
) AS PHASE14C1_BASELINE_VERIFICATION

FROM baseline
CROSS JOIN current_state;

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

-- ============================================================
-- PHASE 14C.2 PREPARATION — SECURE IDENTITY AUDIT
--
-- Read-only. No secure wrapper is changed in Phase 14C.1.
--
-- This scan is important because CURRENT_USER and CURRENT_SESSION
-- may behave differently in a future Native App context.
-- ============================================================

SELECT
    PROCEDURE_SCHEMA,
    PROCEDURE_NAME,
    ARGUMENT_SIGNATURE,
    PROCEDURE_LANGUAGE,
    PROCEDURE_OWNER,

    REGEXP_LIKE(
        UPPER(PROCEDURE_DEFINITION),
        'CURRENT_USER[[:space:]]*\\('
    ) AS USES_CURRENT_USER_FLAG,

    REGEXP_LIKE(
        UPPER(PROCEDURE_DEFINITION),
        'CURRENT_SESSION[[:space:]]*\\('
    ) AS USES_CURRENT_SESSION_FLAG,

    REGEXP_LIKE(
        UPPER(PROCEDURE_DEFINITION),
        'CURRENT_ROLE[[:space:]]*\\('
    ) AS USES_CURRENT_ROLE_FLAG,

    REGEXP_LIKE(
        UPPER(PROCEDURE_DEFINITION),
        'CURRENT_WAREHOUSE[[:space:]]*\\('
    ) AS USES_CURRENT_WAREHOUSE_FLAG,

    CASE
        WHEN REGEXP_LIKE(
            UPPER(PROCEDURE_DEFINITION),
            'CURRENT_USER[[:space:]]*\\('
        )
        OR REGEXP_LIKE(
            UPPER(PROCEDURE_DEFINITION),
            'CURRENT_SESSION[[:space:]]*\\('
        )
        THEN 'PHASE_14C_2_IDENTITY_CONTRACT_REVIEW'
        ELSE 'NO_SESSION_IDENTITY_DEPENDENCY_DETECTED'
    END AS NEXT_ACTION

FROM
    KMAT_COST_MODEL_DB.INFORMATION_SCHEMA.PROCEDURES

WHERE PROCEDURE_SCHEMA = 'CORE_ML'
  AND (
        UPPER(PROCEDURE_NAME) LIKE '%SECURE%'
        OR PROCEDURE_NAME IN (
            'SUBMIT_ML_DECISION_OVERRIDE_V2',
            'REVIEW_ML_DECISION_OVERRIDE_V2'
        )
      )

ORDER BY
    PROCEDURE_SCHEMA,
    PROCEDURE_NAME,
    ARGUMENT_SIGNATURE;

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

-- ============================================================
-- PHASE 14D.1 — RUNTIME NAMESPACE AND PORTABILITY INVENTORY
--
-- Read-only. This inventories deployed procedure and view text.
-- It does not change any object or business logic.
-- ============================================================

WITH PROCEDURE_SCAN AS (
    SELECT
        'PROCEDURE' AS OBJECT_TYPE,
        PROCEDURE_SCHEMA AS OBJECT_SCHEMA,
        PROCEDURE_NAME AS OBJECT_NAME,
        ARGUMENT_SIGNATURE AS OBJECT_SIGNATURE,
        PROCEDURE_LANGUAGE AS OBJECT_LANGUAGE,
        PROCEDURE_DEFINITION AS OBJECT_DEFINITION
    FROM KMAT_COST_MODEL_DB.INFORMATION_SCHEMA.PROCEDURES
    WHERE PROCEDURE_SCHEMA IN (
        'CORE_INTERNAL',
        'CORE_ML'
    )
),
VIEW_SCAN AS (
    SELECT
        'VIEW' AS OBJECT_TYPE,
        TABLE_SCHEMA AS OBJECT_SCHEMA,
        TABLE_NAME AS OBJECT_NAME,
        NULL::VARCHAR AS OBJECT_SIGNATURE,
        'SQL' AS OBJECT_LANGUAGE,
        VIEW_DEFINITION AS OBJECT_DEFINITION
    FROM KMAT_COST_MODEL_DB.INFORMATION_SCHEMA.VIEWS
    WHERE TABLE_SCHEMA IN (
        'CORE_INPUT',
        'CORE_OUTPUT',
        'CORE_INTERNAL',
        'CORE_ML'
    )
),
ALL_OBJECTS AS (
    SELECT * FROM PROCEDURE_SCAN
    UNION ALL
    SELECT * FROM VIEW_SCAN
),
CLASSIFIED AS (
    SELECT
        OBJECT_TYPE,
        OBJECT_SCHEMA,
        OBJECT_NAME,
        OBJECT_SIGNATURE,
        OBJECT_LANGUAGE,

        REGEXP_COUNT(
            UPPER(COALESCE(OBJECT_DEFINITION, '')),
            'KMAT_COST_MODEL_DB'
        ) AS FIXED_DATABASE_REFERENCE_COUNT,

        REGEXP_COUNT(
            UPPER(COALESCE(OBJECT_DEFINITION, '')),
            'KMAT_WH'
        ) AS FIXED_WAREHOUSE_REFERENCE_COUNT,

        REGEXP_COUNT(
            UPPER(COALESCE(OBJECT_DEFINITION, '')),
            'CORE_INPUT'
        ) AS CORE_INPUT_REFERENCE_COUNT,

        REGEXP_COUNT(
            UPPER(COALESCE(OBJECT_DEFINITION, '')),
            'CORE_OUTPUT'
        ) AS CORE_OUTPUT_REFERENCE_COUNT,

        REGEXP_COUNT(
            UPPER(COALESCE(OBJECT_DEFINITION, '')),
            'CORE_INTERNAL'
        ) AS CORE_INTERNAL_REFERENCE_COUNT,

        REGEXP_COUNT(
            UPPER(COALESCE(OBJECT_DEFINITION, '')),
            'CORE_ML'
        ) AS CORE_ML_REFERENCE_COUNT,

        REGEXP_LIKE(
            UPPER(COALESCE(OBJECT_DEFINITION, '')),
            '.*CREATE[[:space:]]+(OR[[:space:]]+REPLACE[[:space:]]+)?TEMP(ORARY)?[[:space:]]+(TABLE|STAGE).*'
        ) AS CREATES_TEMP_TABLE_OR_STAGE_FLAG,

        REGEXP_LIKE(
            UPPER(COALESCE(OBJECT_DEFINITION, '')),
            '(^|[[:space:];])LIST[[:space:]]+@.*'
        ) AS USES_STAGE_LIST_COMMAND_FLAG,

        REGEXP_LIKE(
            UPPER(COALESCE(OBJECT_DEFINITION, '')),
            'RFQ_DOC_STAGE'
        ) AS USES_RFQ_STAGE_FLAG,

        REGEXP_LIKE(
            UPPER(COALESCE(OBJECT_DEFINITION, '')),
            'TDS_XGB_REGRESSOR|BMCS_CALIBRATED_CLASSIFIER|CSS_CLASSIFIER|FMIS_FORECAST_MODEL'
        ) AS USES_MODEL_OBJECT_OR_NAME_FLAG

    FROM ALL_OBJECTS
)
SELECT OBJECT_CONSTRUCT(
    'phase', 'PHASE_14D_1',
    'status', 'INVENTORY_COMPLETE',
    'object_count', COUNT(*),
    'objects_with_fixed_database_reference',
        COUNT_IF(FIXED_DATABASE_REFERENCE_COUNT > 0),
    'total_fixed_database_references',
        COALESCE(SUM(FIXED_DATABASE_REFERENCE_COUNT), 0),
    'objects_with_fixed_warehouse_reference',
        COUNT_IF(FIXED_WAREHOUSE_REFERENCE_COUNT > 0),
    'temporary_table_or_stage_object_count',
        COUNT_IF(CREATES_TEMP_TABLE_OR_STAGE_FLAG = TRUE),
    'stage_list_object_count',
        COUNT_IF(USES_STAGE_LIST_COMMAND_FLAG = TRUE),
    'rfq_stage_object_count',
        COUNT_IF(USES_RFQ_STAGE_FLAG = TRUE),
    'model_object_or_name_count',
        COUNT_IF(USES_MODEL_OBJECT_OR_NAME_FLAG = TRUE),
    'official_cost_changed', FALSE,
    'ml_authority_changed', FALSE
) AS PHASE14D1_NAMESPACE_INVENTORY
FROM CLASSIFIED;


WITH PROCEDURE_SCAN AS (
    SELECT
        'PROCEDURE' AS OBJECT_TYPE,
        PROCEDURE_SCHEMA AS OBJECT_SCHEMA,
        PROCEDURE_NAME AS OBJECT_NAME,
        ARGUMENT_SIGNATURE AS OBJECT_SIGNATURE,
        PROCEDURE_LANGUAGE AS OBJECT_LANGUAGE,
        PROCEDURE_DEFINITION AS OBJECT_DEFINITION
    FROM KMAT_COST_MODEL_DB.INFORMATION_SCHEMA.PROCEDURES
    WHERE PROCEDURE_SCHEMA IN (
        'CORE_INTERNAL',
        'CORE_ML'
    )
),
VIEW_SCAN AS (
    SELECT
        'VIEW' AS OBJECT_TYPE,
        TABLE_SCHEMA AS OBJECT_SCHEMA,
        TABLE_NAME AS OBJECT_NAME,
        NULL::VARCHAR AS OBJECT_SIGNATURE,
        'SQL' AS OBJECT_LANGUAGE,
        VIEW_DEFINITION AS OBJECT_DEFINITION
    FROM KMAT_COST_MODEL_DB.INFORMATION_SCHEMA.VIEWS
    WHERE TABLE_SCHEMA IN (
        'CORE_INPUT',
        'CORE_OUTPUT',
        'CORE_INTERNAL',
        'CORE_ML'
    )
),
ALL_OBJECTS AS (
    SELECT * FROM PROCEDURE_SCAN
    UNION ALL
    SELECT * FROM VIEW_SCAN
)
SELECT
    OBJECT_TYPE,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE,
    OBJECT_LANGUAGE,

    REGEXP_COUNT(
        UPPER(COALESCE(OBJECT_DEFINITION, '')),
        'KMAT_COST_MODEL_DB'
    ) AS FIXED_DATABASE_REFERENCE_COUNT,

    REGEXP_COUNT(
        UPPER(COALESCE(OBJECT_DEFINITION, '')),
        'KMAT_WH'
    ) AS FIXED_WAREHOUSE_REFERENCE_COUNT,

    REGEXP_LIKE(
        UPPER(COALESCE(OBJECT_DEFINITION, '')),
        '.*CREATE[[:space:]]+(OR[[:space:]]+REPLACE[[:space:]]+)?TEMP(ORARY)?[[:space:]]+(TABLE|STAGE).*'
    ) AS CREATES_TEMP_TABLE_OR_STAGE_FLAG,

    REGEXP_LIKE(
        UPPER(COALESCE(OBJECT_DEFINITION, '')),
        '(^|[[:space:];])LIST[[:space:]]+@.*'
    ) AS USES_STAGE_LIST_COMMAND_FLAG,

    REGEXP_LIKE(
        UPPER(COALESCE(OBJECT_DEFINITION, '')),
        'RFQ_DOC_STAGE'
    ) AS USES_RFQ_STAGE_FLAG,

    CASE
        WHEN REGEXP_LIKE(
            UPPER(COALESCE(OBJECT_DEFINITION, '')),
            '.*CREATE[[:space:]]+(OR[[:space:]]+REPLACE[[:space:]]+)?TEMP(ORARY)?[[:space:]]+(TABLE|STAGE).*'
        )
        THEN 'BLOCKER_TEMP_OBJECT_REDESIGN'

        WHEN REGEXP_COUNT(
            UPPER(COALESCE(OBJECT_DEFINITION, '')),
            'KMAT_COST_MODEL_DB'
        ) > 0
        THEN 'PHASE_14D_2_NAMESPACE_REFACTOR'

        ELSE 'NO_FIXED_DATABASE_REFERENCE_DETECTED'
    END AS NEXT_ACTION

FROM ALL_OBJECTS
WHERE
    REGEXP_COUNT(
        UPPER(COALESCE(OBJECT_DEFINITION, '')),
        'KMAT_COST_MODEL_DB'
    ) > 0
    OR REGEXP_COUNT(
        UPPER(COALESCE(OBJECT_DEFINITION, '')),
        'KMAT_WH'
    ) > 0
    OR REGEXP_LIKE(
        UPPER(COALESCE(OBJECT_DEFINITION, '')),
        '.*CREATE[[:space:]]+(OR[[:space:]]+REPLACE[[:space:]]+)?TEMP(ORARY)?[[:space:]]+(TABLE|STAGE).*'
    )
    OR REGEXP_LIKE(
        UPPER(COALESCE(OBJECT_DEFINITION, '')),
        'RFQ_DOC_STAGE'
    )
ORDER BY
    OBJECT_TYPE,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE;

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

-- ============================================================
-- PHASE 14D.1 — CENTRAL RUNTIME NAMESPACE AND DATA CONTRACT
--
-- Adds configuration/contract metadata only.
-- Existing schemas, tables, procedures, models and formulas are
-- not renamed, moved or recreated.
-- ============================================================

CREATE TABLE IF NOT EXISTS
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_RUNTIME_NAMESPACE_V1 (
            CONFIG_KEY VARCHAR NOT NULL,
            CONFIG_VALUE VARCHAR NOT NULL,
            VALUE_CLASS VARCHAR NOT NULL,
            CONFIG_SOURCE VARCHAR NOT NULL,
            ACTIVE_FLAG BOOLEAN NOT NULL,
            UPDATED_BY VARCHAR NOT NULL,
            UPDATED_AT TIMESTAMP_NTZ NOT NULL,
            COMMENTS VARCHAR
        );

MERGE INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_RUNTIME_NAMESPACE_V1 target
USING (
    SELECT * FROM VALUES
        (
            'DATABASE_RESOLUTION_MODE',
            'CURRENT_DATABASE',
            'RESOLUTION_MODE',
            'PHASE_14D_1',
            TRUE,
            'Resolve the active runtime database first; use the development fallback only when context is unavailable.'
        ),
        (
            'DEVELOPMENT_DATABASE_FALLBACK',
            'KMAT_COST_MODEL_DB',
            'DEVELOPMENT_DEFAULT',
            'PHASE_14D_1',
            TRUE,
            'Current standalone-development fallback; not a future consumer requirement.'
        ),
        (
            'INPUT_SCHEMA',
            'CORE_INPUT',
            'SCHEMA_NAME',
            'PHASE_14D_1',
            TRUE,
            'Current input/configuration schema.'
        ),
        (
            'OUTPUT_SCHEMA',
            'CORE_OUTPUT',
            'SCHEMA_NAME',
            'PHASE_14D_1',
            TRUE,
            'Current deterministic and governed output schema.'
        ),
        (
            'INTERNAL_SCHEMA',
            'CORE_INTERNAL',
            'SCHEMA_NAME',
            'PHASE_14D_1',
            TRUE,
            'Current deterministic and Cortex procedure schema.'
        ),
        (
            'ML_SCHEMA',
            'CORE_ML',
            'SCHEMA_NAME',
            'PHASE_14D_1',
            TRUE,
            'Current ML governance, monitoring and runtime schema.'
        ),
        (
            'RFQ_STAGE_NAME',
            'RFQ_DOC_STAGE',
            'STAGE_OBJECT_NAME',
            'PHASE_14D_1',
            TRUE,
            'Current governed RFQ stage object within INPUT_SCHEMA.'
        ),
        (
            'DEFAULT_KMAT_ID',
            'KMAT_TRUCK_01',
            'BUSINESS_DEFAULT',
            'PHASE_14D_1',
            TRUE,
            'Current KMAT Cost model identifier.'
        )
    AS seed(
        CONFIG_KEY,
        CONFIG_VALUE,
        VALUE_CLASS,
        CONFIG_SOURCE,
        ACTIVE_FLAG,
        COMMENTS
    )
) source
ON target.CONFIG_KEY = source.CONFIG_KEY
WHEN MATCHED THEN UPDATE SET
    target.CONFIG_VALUE = source.CONFIG_VALUE,
    target.VALUE_CLASS = source.VALUE_CLASS,
    target.CONFIG_SOURCE = source.CONFIG_SOURCE,
    target.ACTIVE_FLAG = source.ACTIVE_FLAG,
    target.UPDATED_BY = CURRENT_USER(),
    target.UPDATED_AT = CURRENT_TIMESTAMP(),
    target.COMMENTS = source.COMMENTS
WHEN NOT MATCHED THEN INSERT (
    CONFIG_KEY,
    CONFIG_VALUE,
    VALUE_CLASS,
    CONFIG_SOURCE,
    ACTIVE_FLAG,
    UPDATED_BY,
    UPDATED_AT,
    COMMENTS
)
VALUES (
    source.CONFIG_KEY,
    source.CONFIG_VALUE,
    source.VALUE_CLASS,
    source.CONFIG_SOURCE,
    source.ACTIVE_FLAG,
    CURRENT_USER(),
    CURRENT_TIMESTAMP(),
    source.COMMENTS
);


CREATE TABLE IF NOT EXISTS
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_DATA_CONTRACT_V1 (
            CONTRACT_ID VARCHAR NOT NULL,
            FEATURE_AREA VARCHAR NOT NULL,
            LOGICAL_RESOURCE_NAME VARCHAR NOT NULL,
            CURRENT_OBJECT_PATTERN VARCHAR NOT NULL,
            DATA_CLASS VARCHAR NOT NULL,
            CURRENT_ACCESS_MODE VARCHAR NOT NULL,
            FUTURE_NATIVE_ACCESS_MODE VARCHAR NOT NULL,
            REQUIRED_PRIVILEGES VARCHAR,
            WRITE_AUTHORITY VARCHAR NOT NULL,
            COMPATIBILITY_STATUS VARCHAR NOT NULL,
            TARGET_PHASE VARCHAR NOT NULL,
            ACTIVE_FLAG BOOLEAN NOT NULL,
            UPDATED_BY VARCHAR NOT NULL,
            UPDATED_AT TIMESTAMP_NTZ NOT NULL,
            COMMENTS VARCHAR
        );

MERGE INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_DATA_CONTRACT_V1 target
USING (
    SELECT * FROM VALUES
        ('DC001','Configuration','Characteristic Master','CORE_INPUT.CHARACTERISTIC_MASTER','APPLICATION_CONFIGURATION','DIRECT_PROJECT_TABLE','APP_OWNED_CONFIGURATION_OR_CONSUMER_REFERENCE','SELECT','GOVERNED_PROCEDURE_ONLY','CLASSIFIED','14D',TRUE,'Retain validation semantics.'),
        ('DC002','Configuration','Dependency Rules','CORE_INPUT.*DEPENDENCY*','APPLICATION_CONFIGURATION','DIRECT_PROJECT_TABLE','APP_OWNED_CONFIGURATION','SELECT','GOVERNED_PROCEDURE_ONLY','CLASSIFIED','14D',TRUE,'Retain JSON/dependency evaluation logic.'),
        ('DC003','BOM','Super BOM','CORE_INPUT.SUPER_BOM*','CONSUMER_INPUT_CANDIDATE','DIRECT_PROJECT_TABLE','CONSUMER_TABLE_OR_VIEW_REFERENCE','SELECT','READ_ONLY','CLASSIFIED','14D',TRUE,'Component selection input; do not change formulas.'),
        ('DC004','Routing','Super Routing','CORE_INPUT.SUPER_ROUTING*','CONSUMER_INPUT_CANDIDATE','DIRECT_PROJECT_TABLE','CONSUMER_TABLE_OR_VIEW_REFERENCE','SELECT','READ_ONLY','CLASSIFIED','14D',TRUE,'Operation selection input.'),
        ('DC005','Rates','Material/Labour/Machine/Overhead Rates','CORE_INPUT.*RATE* / *COST*','CONSUMER_INPUT_CANDIDATE','DIRECT_PROJECT_TABLE','CONSUMER_TABLE_OR_VIEW_REFERENCE_OR_APP_CONFIG','SELECT','READ_ONLY','CLASSIFIED','14D',TRUE,'Financial source data must be explicitly governed.'),
        ('DC006','RFQ','RFQ Header and Configuration','CORE_INPUT.RFQ_HEADER / RFQ_CONFIGURATION','MIXED_INPUT_AND_APP_STATE','DIRECT_PROJECT_TABLE','APP_STATE_OR_CONSUMER_REFERENCE','SELECT,INSERT,UPDATE','GOVERNED_PROCEDURE_ONLY','CLASSIFIED','14D',TRUE,'Preserve document lineage and validated KMAT extraction.'),
        ('DC007','RFQ','RFQ Document Stage','CORE_INPUT.RFQ_DOC_STAGE','CONSUMER_INPUT_CANDIDATE','FIXED_NAMED_STAGE','APP_OWNED_STAGE_OR_APPROVED_REFERENCE','READ,WRITE','GOVERNED_INGESTION_ONLY','CLASSIFIED','14D',TRUE,'Streamlit selects governed documents; it does not upload bytes.'),
        ('DC008','Production','Simulation Production Context','CORE_INPUT.SIMULATION_PRODUCTION_CONTEXT','CONSUMER_INPUT_CANDIDATE','DIRECT_PROJECT_TABLE','CONSUMER_TABLE_OR_VIEW_REFERENCE_OR_APP_STATE','SELECT,INSERT,UPDATE','GOVERNED_PROCEDURE_ONLY','CLASSIFIED','14D',TRUE,'Used by FMIS and costing context.'),
        ('DC009','Quality','Quality/Scrap History','CORE_INPUT.*QUALITY* / *SCRAP*','CONSUMER_INPUT_CANDIDATE','DIRECT_PROJECT_TABLE','CONSUMER_TABLE_OR_VIEW_REFERENCE','SELECT','READ_ONLY','CLASSIFIED','14E',TRUE,'CSS historical evidence.'),
        ('DC010','Market','Commodity Notes and Forecasts','CORE_INPUT.COMMODITY_MARKET_NOTES / MATERIAL_INDEX_FORECASTS','CONSUMER_INPUT_CANDIDATE','DIRECT_PROJECT_TABLE','CONSUMER_TABLE_OR_VIEW_REFERENCE_OR_APP_CONFIG','SELECT','READ_ONLY','CLASSIFIED','14E',TRUE,'FMIS evidence and official table remain separate from advisory Cortex text.'),
        ('DC011','Maintenance','Maintenance and Tooling Signals','CORE_INPUT.*MAINTENANCE* / *TOOL*','CONSUMER_INPUT_CANDIDATE','DIRECT_PROJECT_TABLE','CONSUMER_TABLE_OR_VIEW_REFERENCE','SELECT','READ_ONLY','CLASSIFIED','14E',TRUE,'TDS evidence.'),
        ('DC012','Cost Output','Configured Cost Summary','CORE_OUTPUT.KMAT_CONFIGURED_COST_SUMMARY','APPLICATION_OUTPUT','DIRECT_PROJECT_TABLE','APP_OWNED_DURABLE_STATE','SELECT,INSERT,UPDATE','GOVERNED_PROCEDURE_ONLY','CLASSIFIED','14D',TRUE,'Official deterministic and governed result.'),
        ('DC013','Cost Output','Component and Operation Cost Detail','CORE_OUTPUT.KMAT_CONFIGURED_COMPONENT_COSTS / KMAT_CONFIGURED_OPERATION_COSTS','APPLICATION_OUTPUT','DIRECT_PROJECT_TABLE','APP_OWNED_DURABLE_STATE','SELECT,INSERT,UPDATE','GOVERNED_PROCEDURE_ONLY','CLASSIFIED','14D',TRUE,'Preserve cost bridge and lineage.'),
        ('DC014','Governance','Policies, Decisions and Overrides','CORE_ML.ML_*POLICY* / ML_*DECISION* / ML_*OVERRIDE*','GOVERNANCE_STATE','DIRECT_PROJECT_TABLE','APP_OWNED_DURABLE_STATE','SELECT,INSERT,UPDATE','SECURE_PROCEDURES_ONLY','CLASSIFIED','14D',TRUE,'No direct UI DML.'),
        ('DC015','Runtime','Runtime Authority and Kill Switches','CORE_ML.ML_RUNTIME_*','GOVERNANCE_STATE','DIRECT_PROJECT_TABLE','APP_OWNED_DURABLE_STATE','SELECT,INSERT,UPDATE','SECURE_PROCEDURES_ONLY','CLASSIFIED','14D',TRUE,'Remain blocked unless separately promoted.'),
        ('DC016','Monitoring','Actual Outcomes and Monitoring','CORE_ML.*ACTUAL_OUTCOME* / *MONITOR*','MIXED_CONSUMER_INPUT_AND_APP_STATE','DIRECT_PROJECT_TABLE','CONSUMER_REFERENCE_PLUS_APP_STATE','SELECT,INSERT,UPDATE','GOVERNED_PROCEDURE_ONLY','CLASSIFIED','14D',TRUE,'Consumer outcomes feed app-owned monitoring evidence.'),
        ('DC017','ML','CSS Model','CSS_CLASSIFIER / registry version','MODEL_ARTIFACT','ACCOUNT_LOCAL_MODEL','WAREHOUSE_MODEL_REGISTRY_IN_APP_WORKFLOW','USAGE','SHADOW_ONLY','DEFERRED_TO_14E','14E',TRUE,'No authority change.'),
        ('DC018','ML','FMIS Model','FMIS_FORECAST_MODEL / registry version','MODEL_ARTIFACT','ACCOUNT_LOCAL_MODEL','WAREHOUSE_MODEL_REGISTRY_IN_APP_WORKFLOW','USAGE','SHADOW_ONLY','DEFERRED_TO_14E','14E',TRUE,'No authority change.'),
        ('DC019','ML','TDS Model','TDS_XGB_REGRESSOR / V2_SHADOW_1','MODEL_ARTIFACT','ACCOUNT_LOCAL_MODEL','WAREHOUSE_MODEL_REGISTRY_IN_APP_WORKFLOW','USAGE','SHADOW_ONLY','DEFERRED_TO_14E','14E',TRUE,'No authority change.'),
        ('DC020','ML','BMCS Model','BMCS_CALIBRATED_CLASSIFIER / V2_SHADOW_2','MODEL_ARTIFACT','ACCOUNT_LOCAL_MODEL','WAREHOUSE_MODEL_REGISTRY_IN_APP_WORKFLOW','USAGE','TRUST_ADVISORY_ONLY','DEFERRED_TO_14E','14E',TRUE,'BMCS remains a trust gate and never a direct cost multiplier.')
    AS seed(
        CONTRACT_ID,
        FEATURE_AREA,
        LOGICAL_RESOURCE_NAME,
        CURRENT_OBJECT_PATTERN,
        DATA_CLASS,
        CURRENT_ACCESS_MODE,
        FUTURE_NATIVE_ACCESS_MODE,
        REQUIRED_PRIVILEGES,
        WRITE_AUTHORITY,
        COMPATIBILITY_STATUS,
        TARGET_PHASE,
        ACTIVE_FLAG,
        COMMENTS
    )
) source
ON target.CONTRACT_ID = source.CONTRACT_ID
WHEN MATCHED THEN UPDATE SET
    target.FEATURE_AREA = source.FEATURE_AREA,
    target.LOGICAL_RESOURCE_NAME = source.LOGICAL_RESOURCE_NAME,
    target.CURRENT_OBJECT_PATTERN = source.CURRENT_OBJECT_PATTERN,
    target.DATA_CLASS = source.DATA_CLASS,
    target.CURRENT_ACCESS_MODE = source.CURRENT_ACCESS_MODE,
    target.FUTURE_NATIVE_ACCESS_MODE = source.FUTURE_NATIVE_ACCESS_MODE,
    target.REQUIRED_PRIVILEGES = source.REQUIRED_PRIVILEGES,
    target.WRITE_AUTHORITY = source.WRITE_AUTHORITY,
    target.COMPATIBILITY_STATUS = source.COMPATIBILITY_STATUS,
    target.TARGET_PHASE = source.TARGET_PHASE,
    target.ACTIVE_FLAG = source.ACTIVE_FLAG,
    target.UPDATED_BY = CURRENT_USER(),
    target.UPDATED_AT = CURRENT_TIMESTAMP(),
    target.COMMENTS = source.COMMENTS
WHEN NOT MATCHED THEN INSERT (
    CONTRACT_ID,
    FEATURE_AREA,
    LOGICAL_RESOURCE_NAME,
    CURRENT_OBJECT_PATTERN,
    DATA_CLASS,
    CURRENT_ACCESS_MODE,
    FUTURE_NATIVE_ACCESS_MODE,
    REQUIRED_PRIVILEGES,
    WRITE_AUTHORITY,
    COMPATIBILITY_STATUS,
    TARGET_PHASE,
    ACTIVE_FLAG,
    UPDATED_BY,
    UPDATED_AT,
    COMMENTS
)
VALUES (
    source.CONTRACT_ID,
    source.FEATURE_AREA,
    source.LOGICAL_RESOURCE_NAME,
    source.CURRENT_OBJECT_PATTERN,
    source.DATA_CLASS,
    source.CURRENT_ACCESS_MODE,
    source.FUTURE_NATIVE_ACCESS_MODE,
    source.REQUIRED_PRIVILEGES,
    source.WRITE_AUTHORITY,
    source.COMPATIBILITY_STATUS,
    source.TARGET_PHASE,
    source.ACTIVE_FLAG,
    CURRENT_USER(),
    CURRENT_TIMESTAMP(),
    source.COMMENTS
);


CREATE OR REPLACE VIEW
    KMAT_COST_MODEL_DB.CORE_ML
        .VW_NATIVE_COMPAT_RUNTIME_NAMESPACE_V1 AS
SELECT
    MAX(IFF(
        CONFIG_KEY = 'DATABASE_RESOLUTION_MODE',
        CONFIG_VALUE,
        NULL
    )) AS DATABASE_RESOLUTION_MODE,
    MAX(IFF(
        CONFIG_KEY = 'DEVELOPMENT_DATABASE_FALLBACK',
        CONFIG_VALUE,
        NULL
    )) AS DEVELOPMENT_DATABASE_FALLBACK,
    MAX(IFF(CONFIG_KEY = 'INPUT_SCHEMA', CONFIG_VALUE, NULL))
        AS INPUT_SCHEMA,
    MAX(IFF(CONFIG_KEY = 'OUTPUT_SCHEMA', CONFIG_VALUE, NULL))
        AS OUTPUT_SCHEMA,
    MAX(IFF(CONFIG_KEY = 'INTERNAL_SCHEMA', CONFIG_VALUE, NULL))
        AS INTERNAL_SCHEMA,
    MAX(IFF(CONFIG_KEY = 'ML_SCHEMA', CONFIG_VALUE, NULL))
        AS ML_SCHEMA,
    MAX(IFF(CONFIG_KEY = 'RFQ_STAGE_NAME', CONFIG_VALUE, NULL))
        AS RFQ_STAGE_NAME,
    MAX(IFF(CONFIG_KEY = 'DEFAULT_KMAT_ID', CONFIG_VALUE, NULL))
        AS DEFAULT_KMAT_ID
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_RUNTIME_NAMESPACE_V1
WHERE ACTIVE_FLAG = TRUE;


CREATE OR REPLACE VIEW
    KMAT_COST_MODEL_DB.CORE_ML
        .VW_NATIVE_COMPAT_DATA_CONTRACT_V1 AS
SELECT
    CONTRACT_ID,
    FEATURE_AREA,
    LOGICAL_RESOURCE_NAME,
    CURRENT_OBJECT_PATTERN,
    DATA_CLASS,
    CURRENT_ACCESS_MODE,
    FUTURE_NATIVE_ACCESS_MODE,
    REQUIRED_PRIVILEGES,
    WRITE_AUTHORITY,
    COMPATIBILITY_STATUS,
    TARGET_PHASE,
    COMMENTS
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_DATA_CONTRACT_V1
WHERE ACTIVE_FLAG = TRUE;

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

-- ============================================================
-- PHASE 14D.2 — DEPLOYED OBJECT NAMESPACE AUDIT
--
-- This script creates an audit snapshot only.
-- It does not recreate or modify any existing procedure or view.
-- ============================================================

CREATE TABLE IF NOT EXISTS
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1 (
            AUDIT_BATCH_ID VARCHAR NOT NULL,
            OBJECT_TYPE VARCHAR NOT NULL,
            OBJECT_DATABASE VARCHAR NOT NULL,
            OBJECT_SCHEMA VARCHAR NOT NULL,
            OBJECT_NAME VARCHAR NOT NULL,
            OBJECT_SIGNATURE VARCHAR,
            OBJECT_OWNER VARCHAR,
            OBJECT_LANGUAGE VARCHAR,
            OBJECT_FQN VARCHAR NOT NULL,
            OBJECT_DDL VARCHAR,
            OBJECT_DDL_HASH NUMBER,
            FIXED_DATABASE_REFERENCE_COUNT NUMBER,
            FIXED_CORE_INPUT_REFERENCE_COUNT NUMBER,
            FIXED_CORE_OUTPUT_REFERENCE_COUNT NUMBER,
            FIXED_CORE_INTERNAL_REFERENCE_COUNT NUMBER,
            FIXED_CORE_ML_REFERENCE_COUNT NUMBER,
            FIXED_WAREHOUSE_REFERENCE_COUNT NUMBER,
            RFQ_STAGE_REFERENCE_COUNT NUMBER,
            TEMP_OBJECT_REFERENCE_COUNT NUMBER,
            CURRENT_DATABASE_REFERENCE_COUNT NUMBER,
            CURRENT_SCHEMA_REFERENCE_COUNT NUMBER,
            CURRENT_USER_REFERENCE_COUNT NUMBER,
            CURRENT_ROLE_REFERENCE_COUNT NUMBER,
            CURRENT_WAREHOUSE_REFERENCE_COUNT NUMBER,
            DYNAMIC_SQL_INDICATOR_COUNT NUMBER,
            CORTEX_FUNCTION_REFERENCE_COUNT NUMBER,
            MODEL_REFERENCE_COUNT NUMBER,
            REWRITE_CLASSIFICATION VARCHAR,
            REWRITE_REASON VARCHAR,
            CAPTURED_BY VARCHAR NOT NULL,
            CAPTURED_AT TIMESTAMP_NTZ NOT NULL
        );

DELETE FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1
WHERE AUDIT_BATCH_ID =
      'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1';


INSERT INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1
(
    AUDIT_BATCH_ID,
    OBJECT_TYPE,
    OBJECT_DATABASE,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE,
    OBJECT_OWNER,
    OBJECT_LANGUAGE,
    OBJECT_FQN,
    OBJECT_DDL,
    OBJECT_DDL_HASH,
    FIXED_DATABASE_REFERENCE_COUNT,
    FIXED_CORE_INPUT_REFERENCE_COUNT,
    FIXED_CORE_OUTPUT_REFERENCE_COUNT,
    FIXED_CORE_INTERNAL_REFERENCE_COUNT,
    FIXED_CORE_ML_REFERENCE_COUNT,
    FIXED_WAREHOUSE_REFERENCE_COUNT,
    RFQ_STAGE_REFERENCE_COUNT,
    TEMP_OBJECT_REFERENCE_COUNT,
    CURRENT_DATABASE_REFERENCE_COUNT,
    CURRENT_SCHEMA_REFERENCE_COUNT,
    CURRENT_USER_REFERENCE_COUNT,
    CURRENT_ROLE_REFERENCE_COUNT,
    CURRENT_WAREHOUSE_REFERENCE_COUNT,
    DYNAMIC_SQL_INDICATOR_COUNT,
    CORTEX_FUNCTION_REFERENCE_COUNT,
    MODEL_REFERENCE_COUNT,
    REWRITE_CLASSIFICATION,
    REWRITE_REASON,
    CAPTURED_BY,
    CAPTURED_AT
)
WITH PROCEDURE_SOURCE AS (
    SELECT
        'PROCEDURE' AS OBJECT_TYPE,
        PROCEDURE_CATALOG AS OBJECT_DATABASE,
        PROCEDURE_SCHEMA AS OBJECT_SCHEMA,
        PROCEDURE_NAME AS OBJECT_NAME,
        ARGUMENT_SIGNATURE AS OBJECT_SIGNATURE,
        PROCEDURE_OWNER AS OBJECT_OWNER,
        PROCEDURE_LANGUAGE AS OBJECT_LANGUAGE,

        PROCEDURE_CATALOG
        || '.'
        || PROCEDURE_SCHEMA
        || '.'
        || PROCEDURE_NAME
        || ARGUMENT_SIGNATURE AS OBJECT_FQN,

        COALESCE(PROCEDURE_DEFINITION, '') AS OBJECT_DDL

    FROM
        KMAT_COST_MODEL_DB.INFORMATION_SCHEMA.PROCEDURES

    WHERE PROCEDURE_SCHEMA IN (
        'CORE_INTERNAL',
        'CORE_ML'
    )
),
VIEW_SOURCE AS (
    SELECT
        'VIEW' AS OBJECT_TYPE,
        TABLE_CATALOG AS OBJECT_DATABASE,
        TABLE_SCHEMA AS OBJECT_SCHEMA,
        TABLE_NAME AS OBJECT_NAME,
        NULL::VARCHAR AS OBJECT_SIGNATURE,
        TABLE_OWNER AS OBJECT_OWNER,
        NULL::VARCHAR AS OBJECT_LANGUAGE,

        TABLE_CATALOG
        || '.'
        || TABLE_SCHEMA
        || '.'
        || TABLE_NAME AS OBJECT_FQN,

        COALESCE(VIEW_DEFINITION, '') AS OBJECT_DDL

    FROM
        KMAT_COST_MODEL_DB.INFORMATION_SCHEMA.VIEWS

    WHERE TABLE_SCHEMA IN (
        'CORE_INPUT',
        'CORE_OUTPUT',
        'CORE_INTERNAL',
        'CORE_ML'
    )
),
ALL_OBJECTS AS (
    SELECT * FROM PROCEDURE_SOURCE
    UNION ALL
    SELECT * FROM VIEW_SOURCE
),
FLAGS AS (
    SELECT
        *,

        REGEXP_COUNT(
            UPPER(OBJECT_DDL),
            'KMAT_COST_MODEL_DB'
        ) AS FIXED_DATABASE_REFERENCE_COUNT,

        REGEXP_COUNT(
            UPPER(OBJECT_DDL),
            'KMAT_COST_MODEL_DB[.]CORE_INPUT[.]'
        ) AS FIXED_CORE_INPUT_REFERENCE_COUNT,

        REGEXP_COUNT(
            UPPER(OBJECT_DDL),
            'KMAT_COST_MODEL_DB[.]CORE_OUTPUT[.]'
        ) AS FIXED_CORE_OUTPUT_REFERENCE_COUNT,

        REGEXP_COUNT(
            UPPER(OBJECT_DDL),
            'KMAT_COST_MODEL_DB[.]CORE_INTERNAL[.]'
        ) AS FIXED_CORE_INTERNAL_REFERENCE_COUNT,

        REGEXP_COUNT(
            UPPER(OBJECT_DDL),
            'KMAT_COST_MODEL_DB[.]CORE_ML[.]'
        ) AS FIXED_CORE_ML_REFERENCE_COUNT,

        REGEXP_COUNT(
            UPPER(OBJECT_DDL),
            'KMAT_WH'
        ) AS FIXED_WAREHOUSE_REFERENCE_COUNT,

        REGEXP_COUNT(
            UPPER(OBJECT_DDL),
            'RFQ_DOC_STAGE'
        ) AS RFQ_STAGE_REFERENCE_COUNT,

        REGEXP_COUNT(
            UPPER(OBJECT_DDL),
            'CREATE[[:space:]]+(OR[[:space:]]+REPLACE[[:space:]]+)?TEMP'
        ) AS TEMP_OBJECT_REFERENCE_COUNT,

        REGEXP_COUNT(
            UPPER(OBJECT_DDL),
            'CURRENT_DATABASE[[:space:]]*[(]'
        ) AS CURRENT_DATABASE_REFERENCE_COUNT,

        REGEXP_COUNT(
            UPPER(OBJECT_DDL),
            'CURRENT_SCHEMA[[:space:]]*[(]'
        ) AS CURRENT_SCHEMA_REFERENCE_COUNT,

        REGEXP_COUNT(
            UPPER(OBJECT_DDL),
            'CURRENT_USER[[:space:]]*[(]'
        ) AS CURRENT_USER_REFERENCE_COUNT,

        REGEXP_COUNT(
            UPPER(OBJECT_DDL),
            'CURRENT_ROLE[[:space:]]*[(]'
        ) AS CURRENT_ROLE_REFERENCE_COUNT,

        REGEXP_COUNT(
            UPPER(OBJECT_DDL),
            'CURRENT_WAREHOUSE[[:space:]]*[(]'
        ) AS CURRENT_WAREHOUSE_REFERENCE_COUNT,

        (
            REGEXP_COUNT(
                UPPER(OBJECT_DDL),
                'EXECUTE[[:space:]]+IMMEDIATE'
            )
            +
            REGEXP_COUNT(
                UPPER(OBJECT_DDL),
                'SESSION[.]SQL[[:space:]]*[(]'
            )
        ) AS DYNAMIC_SQL_INDICATOR_COUNT,

        (
            REGEXP_COUNT(
                UPPER(OBJECT_DDL),
                'AI_COMPLETE[[:space:]]*[(]'
            )
            +
            REGEXP_COUNT(
                UPPER(OBJECT_DDL),
                'AI_EXTRACT[[:space:]]*[(]'
            )
            +
            REGEXP_COUNT(
                UPPER(OBJECT_DDL),
                'AI_CLASSIFY[[:space:]]*[(]'
            )
            +
            REGEXP_COUNT(
                UPPER(OBJECT_DDL),
                'SNOWFLAKE[.]CORTEX'
            )
        ) AS CORTEX_FUNCTION_REFERENCE_COUNT,

        (
            REGEXP_COUNT(
                UPPER(OBJECT_DDL),
                'MODEL_REGISTRY'
            )
            +
            REGEXP_COUNT(
                UPPER(OBJECT_DDL),
                'SNOWFLAKE[.]ML'
            )
            +
            REGEXP_COUNT(
                UPPER(OBJECT_DDL),
                '[.]PREDICT[[:space:]]*[(]'
            )
        ) AS MODEL_REFERENCE_COUNT

    FROM ALL_OBJECTS
),
CLASSIFIED AS (
    SELECT
        *,

        CASE
            WHEN TEMP_OBJECT_REFERENCE_COUNT > 0
                THEN 'BLOCKED_TEMP_OBJECT'

            WHEN FIXED_WAREHOUSE_REFERENCE_COUNT > 0
                THEN 'MANUAL_WAREHOUSE_REVIEW'

            WHEN MODEL_REFERENCE_COUNT > 0
                THEN 'DEFER_TO_PHASE_14E'

            WHEN RFQ_STAGE_REFERENCE_COUNT > 0
                THEN 'MANUAL_STAGE_CONTRACT_REVIEW'

            WHEN DYNAMIC_SQL_INDICATOR_COUNT > 0
                 AND FIXED_DATABASE_REFERENCE_COUNT > 0
                THEN 'MANUAL_DYNAMIC_SQL_REWRITE'

            WHEN OBJECT_TYPE = 'VIEW'
                 AND FIXED_DATABASE_REFERENCE_COUNT > 0
                THEN 'RELATIVE_NAMESPACE_VIEW_CANDIDATE'

            WHEN OBJECT_TYPE = 'PROCEDURE'
                 AND FIXED_DATABASE_REFERENCE_COUNT > 0
                THEN 'PROCEDURE_BODY_REWRITE_CANDIDATE'

            WHEN FIXED_DATABASE_REFERENCE_COUNT = 0
                THEN 'ALREADY_PORTABLE'

            ELSE 'MANUAL_REVIEW'
        END AS REWRITE_CLASSIFICATION,

        CASE
            WHEN TEMP_OBJECT_REFERENCE_COUNT > 0
                THEN
                    'Temporary object usage must be removed or redesigned.'

            WHEN FIXED_WAREHOUSE_REFERENCE_COUNT > 0
                THEN
                    'Runtime warehouse dependency requires explicit design.'

            WHEN MODEL_REFERENCE_COUNT > 0
                THEN
                    'Model portability belongs to Phase 14E.'

            WHEN RFQ_STAGE_REFERENCE_COUNT > 0
                THEN
                    'RFQ stage must be represented by an app-owned object or reference contract.'

            WHEN DYNAMIC_SQL_INDICATOR_COUNT > 0
                 AND FIXED_DATABASE_REFERENCE_COUNT > 0
                THEN
                    'Dynamic SQL requires parameterized, object-aware rewriting.'

            WHEN OBJECT_TYPE = 'VIEW'
                 AND FIXED_DATABASE_REFERENCE_COUNT > 0
                THEN
                    'View can be evaluated for schema-relative object references.'

            WHEN OBJECT_TYPE = 'PROCEDURE'
                 AND FIXED_DATABASE_REFERENCE_COUNT > 0
                THEN
                    'Procedure body contains fixed database references and needs exact body-level review.'

            WHEN FIXED_DATABASE_REFERENCE_COUNT = 0
                THEN
                    'No fixed KMAT database reference detected.'

            ELSE
                'Review the deployed DDL manually.'
        END AS REWRITE_REASON

    FROM FLAGS
)
SELECT
    'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1',
    OBJECT_TYPE,
    OBJECT_DATABASE,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE,
    OBJECT_OWNER,
    OBJECT_LANGUAGE,
    OBJECT_FQN,
    OBJECT_DDL,
    HASH(OBJECT_DDL),
    FIXED_DATABASE_REFERENCE_COUNT,
    FIXED_CORE_INPUT_REFERENCE_COUNT,
    FIXED_CORE_OUTPUT_REFERENCE_COUNT,
    FIXED_CORE_INTERNAL_REFERENCE_COUNT,
    FIXED_CORE_ML_REFERENCE_COUNT,
    FIXED_WAREHOUSE_REFERENCE_COUNT,
    RFQ_STAGE_REFERENCE_COUNT,
    TEMP_OBJECT_REFERENCE_COUNT,
    CURRENT_DATABASE_REFERENCE_COUNT,
    CURRENT_SCHEMA_REFERENCE_COUNT,
    CURRENT_USER_REFERENCE_COUNT,
    CURRENT_ROLE_REFERENCE_COUNT,
    CURRENT_WAREHOUSE_REFERENCE_COUNT,
    DYNAMIC_SQL_INDICATOR_COUNT,
    CORTEX_FUNCTION_REFERENCE_COUNT,
    MODEL_REFERENCE_COUNT,
    REWRITE_CLASSIFICATION,
    REWRITE_REASON,
    CURRENT_USER(),
    CURRENT_TIMESTAMP()
FROM CLASSIFIED;


SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COUNT_IF(
                TEMP_OBJECT_REFERENCE_COUNT > 0
            ) = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_2',

    'audit_batch_id',
        'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1',

    'total_object_count',
        COUNT(*),

    'procedure_count',
        COUNT_IF(OBJECT_TYPE = 'PROCEDURE'),

    'view_count',
        COUNT_IF(OBJECT_TYPE = 'VIEW'),

    'already_portable_count',
        COUNT_IF(
            REWRITE_CLASSIFICATION = 'ALREADY_PORTABLE'
        ),

    'procedure_body_rewrite_candidate_count',
        COUNT_IF(
            REWRITE_CLASSIFICATION =
                'PROCEDURE_BODY_REWRITE_CANDIDATE'
        ),

    'relative_namespace_view_candidate_count',
        COUNT_IF(
            REWRITE_CLASSIFICATION =
                'RELATIVE_NAMESPACE_VIEW_CANDIDATE'
        ),

    'manual_dynamic_sql_rewrite_count',
        COUNT_IF(
            REWRITE_CLASSIFICATION =
                'MANUAL_DYNAMIC_SQL_REWRITE'
        ),

    'manual_stage_contract_review_count',
        COUNT_IF(
            REWRITE_CLASSIFICATION =
                'MANUAL_STAGE_CONTRACT_REVIEW'
        ),

    'defer_to_phase14e_count',
        COUNT_IF(
            REWRITE_CLASSIFICATION =
                'DEFER_TO_PHASE_14E'
        ),

    'fixed_warehouse_object_count',
        COUNT_IF(
            FIXED_WAREHOUSE_REFERENCE_COUNT > 0
        ),

    'temporary_object_count',
        COUNT_IF(
            TEMP_OBJECT_REFERENCE_COUNT > 0
        ),

    'existing_object_changed',
        FALSE,

    'procedure_body_changed',
        FALSE,

    'view_definition_changed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D2_NAMESPACE_AUDIT_SUMMARY

FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1

WHERE AUDIT_BATCH_ID =
      'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1';


SELECT
    OBJECT_TYPE,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE,
    OBJECT_LANGUAGE,
    OBJECT_OWNER,
    FIXED_DATABASE_REFERENCE_COUNT,
    FIXED_WAREHOUSE_REFERENCE_COUNT,
    RFQ_STAGE_REFERENCE_COUNT,
    TEMP_OBJECT_REFERENCE_COUNT,
    DYNAMIC_SQL_INDICATOR_COUNT,
    CORTEX_FUNCTION_REFERENCE_COUNT,
    MODEL_REFERENCE_COUNT,
    REWRITE_CLASSIFICATION,
    REWRITE_REASON,
    OBJECT_DDL_HASH
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1
WHERE AUDIT_BATCH_ID =
      'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
ORDER BY
    CASE REWRITE_CLASSIFICATION
        WHEN 'BLOCKED_TEMP_OBJECT' THEN 1
        WHEN 'MANUAL_WAREHOUSE_REVIEW' THEN 2
        WHEN 'MANUAL_DYNAMIC_SQL_REWRITE' THEN 3
        WHEN 'MANUAL_STAGE_CONTRACT_REVIEW' THEN 4
        WHEN 'PROCEDURE_BODY_REWRITE_CANDIDATE' THEN 5
        WHEN 'RELATIVE_NAMESPACE_VIEW_CANDIDATE' THEN 6
        WHEN 'DEFER_TO_PHASE_14E' THEN 7
        WHEN 'ALREADY_PORTABLE' THEN 8
        ELSE 9
    END,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE;

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

-- ============================================================
-- PHASE 14D.2 — REWRITE CANDIDATE EXPORT
--
-- Read-only. This emits exact deployed DDL and a mechanically
-- transformed candidate for review. It does not execute candidates.
--
-- The candidate removes only the fixed database qualifier while
-- retaining schema qualification:
--
-- KMAT_COST_MODEL_DB.CORE_INPUT.TABLE
-- becomes
-- CORE_INPUT.TABLE
--
-- This is not approval to deploy the candidate.
-- ============================================================

SELECT
    OBJECT_TYPE,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE,
    OBJECT_LANGUAGE,
    OBJECT_OWNER,
    REWRITE_CLASSIFICATION,
    OBJECT_DDL_HASH AS ORIGINAL_DDL_HASH,
    OBJECT_DDL AS ORIGINAL_DDL,

    REPLACE(
        OBJECT_DDL,
        'KMAT_COST_MODEL_DB.',
        ''
    ) AS REVIEW_CANDIDATE_DDL,

    HASH(
        REPLACE(
            OBJECT_DDL,
            'KMAT_COST_MODEL_DB.',
            ''
        )
    ) AS REVIEW_CANDIDATE_DDL_HASH,

    CASE
        WHEN REWRITE_CLASSIFICATION IN (
            'PROCEDURE_BODY_REWRITE_CANDIDATE',
            'RELATIVE_NAMESPACE_VIEW_CANDIDATE'
        )
        THEN 'CANDIDATE_ONLY_REQUIRES_REVIEW'

        ELSE 'DO_NOT_USE_MECHANICAL_CANDIDATE'
    END AS CANDIDATE_STATUS

FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1

WHERE AUDIT_BATCH_ID =
      'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'

  AND FIXED_DATABASE_REFERENCE_COUNT > 0

ORDER BY
    OBJECT_TYPE,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE;

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

-- ============================================================
-- PHASE 14D.2 — AUDIT INTEGRITY VERIFICATION
--
-- Read-only.
-- ============================================================

WITH AUDIT_ROWS AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1
    WHERE AUDIT_BATCH_ID =
          'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COUNT(*) > 0
            AND COUNT_IF(
                OBJECT_DDL IS NULL
            ) = 0
            AND COUNT_IF(
                OBJECT_DDL_HASH IS NULL
            ) = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_2',

    'audit_batch_id',
        'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1',

    'total_object_count',
        COUNT(*),

    'null_ddl_count',
        COUNT_IF(
            OBJECT_DDL IS NULL
        ),

    'null_ddl_hash_count',
        COUNT_IF(
            OBJECT_DDL_HASH IS NULL
        ),

    'fixed_database_object_count',
        COUNT_IF(
            FIXED_DATABASE_REFERENCE_COUNT > 0
        ),

    'fixed_warehouse_object_count',
        COUNT_IF(
            FIXED_WAREHOUSE_REFERENCE_COUNT > 0
        ),

    'rfq_stage_object_count',
        COUNT_IF(
            RFQ_STAGE_REFERENCE_COUNT > 0
        ),

    'temporary_object_count',
        COUNT_IF(
            TEMP_OBJECT_REFERENCE_COUNT > 0
        ),

    'dynamic_sql_object_count',
        COUNT_IF(
            DYNAMIC_SQL_INDICATOR_COUNT > 0
        ),

    'cortex_object_count',
        COUNT_IF(
            CORTEX_FUNCTION_REFERENCE_COUNT > 0
        ),

    'model_object_count',
        COUNT_IF(
            MODEL_REFERENCE_COUNT > 0
        ),

    'procedure_body_changed',
        FALSE,

    'view_definition_changed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'ml_authority_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D2_AUDIT_INTEGRITY

FROM AUDIT_ROWS;

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

-- ============================================================
-- PHASE 14D.2 — BASELINE SAFETY VERIFICATION
--
-- Read-only. No runtime object should have changed in this subphase.
-- ============================================================

WITH baseline AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_BASELINE_V1
    WHERE BASELINE_ID =
          'PHASE14A_SIM_001_BASELINE_V1'
),
current_state AS (
    SELECT
        s.SIMULATION_ID,

        HASH(
            s.MATERIAL_COST_USD,
            s.LABOR_COST_USD,
            s.MACHINE_COST_USD,
            s.OVERHEAD_COST_USD,
            s.TOTAL_CONFIGURED_COST_USD,
            s.FLOOR_PRICE_USD,
            s.TARGET_PRICE_USD,
            s.CEILING_PRICE_USD,
            s.BASELINE_TOTAL_COST_USD,
            s.RISK_ADJUSTED_TOTAL_COST_USD,
            s.TOTAL_RISK_UPLIFT_USD,
            s.TOTAL_RISK_UPLIFT_PCT,
            s.CSS_SCORE,
            s.SCRAP_RATE_APPLIED,
            s.AVG_WEIGHTED_FMIS,
            s.MAX_TDS_FACTOR,
            s.BOM_MATCH_CONFIDENCE_SCORE,
            s.BMCS_REVIEW_STATUS,
            s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
            s.QUOTE_TRUST_STATUS,
            h.RESOLVED_SCRAP_RATE,
            h.CSS_RESOLVED_SOURCE,
            h.RESOLVED_FMIS_MULTIPLIER,
            h.FMIS_RESOLVED_SOURCE,
            h.RESOLVED_TDS_FACTOR,
            h.TDS_RESOLVED_SOURCE,
            h.RESOLVED_BMCS_STATUS,
            h.SAFETY_GATE_PASS_FLAG,
            h.COST_ENGINE_CONSUMPTION_ALLOWED_FLAG,
            h.OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG
        ) AS SNAPSHOT_HASH,

        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS ACTIVE_POLICY_COUNT,

        (
            SELECT COUNT_IF(
                DEPLOYMENT_MODE = 'SHADOW'
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS SHADOW_POLICY_COUNT,

        (
            SELECT COALESCE(
                COUNT_IF(
                    AUTO_USE_ALLOWED_FLAG = TRUE
                    OR OFFICIAL_COST_IMPACT_ALLOWED_FLAG = TRUE
                    OR BUSINESS_DECISION_ALLOWED_FLAG = TRUE
                ),
                0
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS POLICY_AUTHORITY_ENABLED_COUNT,

        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .ML_RUNTIME_AUTHORITY_REGISTRY_V1
            WHERE UPPER(AUTHORITY_STATUS) = 'ENABLED'
        ) AS ENABLED_RUNTIME_AUTHORITY_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_OUTPUT
            .KMAT_CONFIGURED_COST_SUMMARY s

    LEFT JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .VW_KMAT_PHASE10B_HIERARCHY_V1 h
        ON s.SIMULATION_ID = h.SIMULATION_ID

    WHERE s.SIMULATION_ID = 'SIM_001'

    QUALIFY ROW_NUMBER() OVER (
        PARTITION BY s.SIMULATION_ID
        ORDER BY s.CALCULATED_AT DESC
    ) = 1
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            baseline.SNAPSHOT_HASH =
                current_state.SNAPSHOT_HASH
            AND current_state
                .POLICY_AUTHORITY_ENABLED_COUNT = 0
            AND current_state
                .ENABLED_RUNTIME_AUTHORITY_COUNT = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_2',

    'baseline_id',
        baseline.BASELINE_ID,

    'simulation_id',
        baseline.SIMULATION_ID,

    'baseline_snapshot_hash',
        baseline.SNAPSHOT_HASH,

    'current_snapshot_hash',
        current_state.SNAPSHOT_HASH,

    'cost_and_governance_snapshot_match',
        baseline.SNAPSHOT_HASH =
        current_state.SNAPSHOT_HASH,

    'active_policy_count',
        current_state.ACTIVE_POLICY_COUNT,

    'shadow_policy_count',
        current_state.SHADOW_POLICY_COUNT,

    'policy_authority_enabled_count',
        current_state
            .POLICY_AUTHORITY_ENABLED_COUNT,

    'enabled_runtime_authority_count',
        current_state
            .ENABLED_RUNTIME_AUTHORITY_COUNT,

    'official_cost_changed',
        baseline.SNAPSHOT_HASH <>
        current_state.SNAPSHOT_HASH,

    'procedure_body_changed',
        FALSE,

    'view_definition_changed',
        FALSE,

    'ml_authority_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D2_BASELINE_VERIFICATION

FROM baseline
CROSS JOIN current_state;

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

SELECT
    REWRITE_CLASSIFICATION,
    COUNT(*) AS OBJECT_COUNT,
    COUNT_IF(OBJECT_TYPE = 'PROCEDURE')
        AS PROCEDURE_COUNT,
    COUNT_IF(OBJECT_TYPE = 'VIEW')
        AS VIEW_COUNT,
    SUM(FIXED_DATABASE_REFERENCE_COUNT)
        AS FIXED_DATABASE_REFERENCE_COUNT,
    SUM(DYNAMIC_SQL_INDICATOR_COUNT)
        AS DYNAMIC_SQL_INDICATOR_COUNT,
    SUM(RFQ_STAGE_REFERENCE_COUNT)
        AS RFQ_STAGE_REFERENCE_COUNT,
    SUM(CORTEX_FUNCTION_REFERENCE_COUNT)
        AS CORTEX_FUNCTION_REFERENCE_COUNT
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1
WHERE AUDIT_BATCH_ID =
      'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
GROUP BY REWRITE_CLASSIFICATION
ORDER BY
    CASE REWRITE_CLASSIFICATION
        WHEN 'BLOCKED_TEMP_OBJECT' THEN 1
        WHEN 'MANUAL_WAREHOUSE_REVIEW' THEN 2
        WHEN 'MANUAL_DYNAMIC_SQL_REWRITE' THEN 3
        WHEN 'MANUAL_STAGE_CONTRACT_REVIEW' THEN 4
        WHEN 'PROCEDURE_BODY_REWRITE_CANDIDATE' THEN 5
        WHEN 'RELATIVE_NAMESPACE_VIEW_CANDIDATE' THEN 6
        WHEN 'DEFER_TO_PHASE_14E' THEN 7
        WHEN 'ALREADY_PORTABLE' THEN 8
        ELSE 9
    END;

SELECT
    OBJECT_TYPE,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE,
    OBJECT_LANGUAGE,
    OBJECT_OWNER,

    FIXED_DATABASE_REFERENCE_COUNT,
    DYNAMIC_SQL_INDICATOR_COUNT,
    RFQ_STAGE_REFERENCE_COUNT,
    CORTEX_FUNCTION_REFERENCE_COUNT,

    REWRITE_CLASSIFICATION,
    REWRITE_REASON,
    OBJECT_DDL_HASH
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1
WHERE AUDIT_BATCH_ID =
      'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
  AND REWRITE_CLASSIFICATION <> 'ALREADY_PORTABLE'
ORDER BY
    REWRITE_CLASSIFICATION,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE;

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

-- ============================================================
-- PHASE 14D.3A — RUNTIME ROOT SCOPE
--
-- Records the objects directly referenced by the working
-- Phase 14D.1 Streamlit source.
--
-- No existing KMAT runtime object is changed.
-- ============================================================

CREATE TABLE IF NOT EXISTS
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_RUNTIME_ROOT_SCOPE_V1 (
            SCOPE_BATCH_ID VARCHAR NOT NULL,
            OBJECT_TYPE VARCHAR NOT NULL,
            OBJECT_SCHEMA VARCHAR NOT NULL,
            OBJECT_NAME VARCHAR NOT NULL,
            OBJECT_SIGNATURE VARCHAR,
            ROOT_USAGE VARCHAR NOT NULL,
            RUNTIME_REQUIRED_FLAG BOOLEAN NOT NULL,
            OBJECT_EXISTS_FLAG BOOLEAN,
            AUDIT_CLASSIFICATION VARCHAR,
            AUDIT_DDL_HASH NUMBER,
            RECORDED_BY VARCHAR NOT NULL,
            RECORDED_AT TIMESTAMP_NTZ NOT NULL
        );

DELETE FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_RUNTIME_ROOT_SCOPE_V1
WHERE SCOPE_BATCH_ID =
      'PHASE14D3A_RUNTIME_ROOT_SCOPE_V1';


INSERT INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_RUNTIME_ROOT_SCOPE_V1
(
    SCOPE_BATCH_ID,
    OBJECT_TYPE,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE,
    ROOT_USAGE,
    RUNTIME_REQUIRED_FLAG,
    OBJECT_EXISTS_FLAG,
    AUDIT_CLASSIFICATION,
    AUDIT_DDL_HASH,
    RECORDED_BY,
    RECORDED_AT
)
WITH ROOT_SEED AS (
    SELECT * FROM VALUES
        ('TABLE', 'CORE_INPUT', 'BMCS_SCORING_DETAIL', NULL, 'DIRECT_STREAMLIT_DATA', TRUE),
        ('TABLE', 'CORE_INPUT', 'CHARACTERISTIC_MASTER', NULL, 'DIRECT_STREAMLIT_DATA', TRUE),
        ('TABLE', 'CORE_INPUT', 'CHARACTERISTIC_VALUES', NULL, 'DIRECT_STREAMLIT_DATA', TRUE),
        ('TABLE', 'CORE_INPUT', 'COMPONENT_COST_ADJUSTMENTS', NULL, 'OPTIONAL_STREAMLIT_DATA', FALSE),
        ('TABLE', 'CORE_INPUT', 'RFQ_HEADER', NULL, 'DIRECT_STREAMLIT_DATA', TRUE),
        ('TABLE', 'CORE_INPUT', 'SIMULATION_HEADER', NULL, 'DIRECT_STREAMLIT_DATA', TRUE),
        ('TABLE', 'CORE_INPUT', 'SIMULATION_PARAMETERS', NULL, 'DIRECT_STREAMLIT_DATA', TRUE),
        ('TABLE', 'CORE_INPUT', 'SIMULATION_PRODUCTION_CONTEXT', NULL, 'DIRECT_STREAMLIT_DATA', TRUE),
        ('VIEW', 'CORE_INPUT', 'VW_RFQ_BMCS_STATUS', NULL, 'DIRECT_STREAMLIT_VIEW', TRUE),
        ('TABLE', 'CORE_OUTPUT', 'KMAT_CONFIGURED_COMPONENT_COSTS', NULL, 'DIRECT_STREAMLIT_DATA', TRUE),
        ('TABLE', 'CORE_OUTPUT', 'KMAT_CONFIGURED_COST_SUMMARY', NULL, 'DIRECT_STREAMLIT_DATA', TRUE),
        ('TABLE', 'CORE_OUTPUT', 'KMAT_CONFIGURED_OPERATION_COSTS', NULL, 'DIRECT_STREAMLIT_DATA', TRUE),
        ('TABLE', 'CORE_OUTPUT', 'KMAT_CONFIGURED_OVERHEAD_COSTS', NULL, 'DIRECT_STREAMLIT_DATA', TRUE),
        ('PROCEDURE', 'CORE_INTERNAL', 'PREPARE_RFQ_SIMULATION_INPUTS', '(RFQ_ID VARCHAR)', 'DIRECT_STREAMLIT_CALL', TRUE),
        ('PROCEDURE', 'CORE_INTERNAL', 'RUN_CORTEX_RFQ_INTAKE_PIPELINE', '(RFQ_ID VARCHAR)', 'DIRECT_STREAMLIT_CALL', TRUE),
        ('PROCEDURE', 'CORE_INTERNAL', 'RUN_CORTEX_RFQ_QUOTE_PIPELINE', '(RFQ_ID VARCHAR)', 'DIRECT_STREAMLIT_CALL', TRUE),
        ('PROCEDURE', 'CORE_INTERNAL', 'RUN_KMAT_COST_SIMULATION_GOVERNED_V3', '(P_SIMULATION_ID VARCHAR)', 'DIRECT_STREAMLIT_CALL', TRUE),
        ('PROCEDURE', 'CORE_INTERNAL', 'RUN_RULE_BASED_BMCS_SCORING', '(RFQ_ID VARCHAR)', 'DIRECT_STREAMLIT_CALL', TRUE),
        ('PROCEDURE', 'CORE_ML', 'PREPARE_KMAT_GOVERNED_COST_INPUT_V2', '(P_SIMULATION_ID VARCHAR)', 'DIRECT_STREAMLIT_CALL', TRUE),
        ('PROCEDURE', 'CORE_ML', 'RESOLVE_KMAT_COST_FACTOR_HIERARCHY_V1', '(P_SIMULATION_ID VARCHAR)', 'DIRECT_STREAMLIT_CALL', TRUE),
        ('PROCEDURE', 'CORE_ML', 'RESOLVE_ML_RUNTIME_AUTHORITY_SECURE_V1', '(P_RUNTIME_DECISION_ID VARCHAR, P_MODEL_DOMAIN VARCHAR, P_SIMULATION_ID VARCHAR, P_RULE_VALUE FLOAT, P_CANDIDATE_VALUE FLOAT, P_QUALITY_PASS_FLAG BOOLEAN, P_OOD_FLAG BOOLEAN, P_ENGINEER_APPROVED_FLAG BOOLEAN, P_ENGINEER_APPROVAL_REFERENCE VARCHAR)', 'DIRECT_STREAMLIT_CALL', TRUE),
        ('PROCEDURE', 'CORE_ML', 'SUBMIT_ML_DECISION_OVERRIDE_V2', '(P_OVERRIDE_ID VARCHAR, P_DECISION_ID VARCHAR, P_OVERRIDE_NUMERIC_VALUE FLOAT, P_OVERRIDE_TEXT_STATUS VARCHAR, P_OVERRIDE_REASON VARCHAR)', 'DIRECT_STREAMLIT_CALL', TRUE),
        ('PROCEDURE', 'CORE_ML', 'REVIEW_ML_DECISION_OVERRIDE_V2', '(P_OVERRIDE_ID VARCHAR, P_REVIEW_ACTION VARCHAR, P_REVIEW_NOTE VARCHAR)', 'DIRECT_STREAMLIT_CALL', TRUE),
        ('PROCEDURE', 'CORE_ML', 'RECORD_KMAT_MODEL_ACTUAL_OUTCOME_V1', '(P_OUTCOME_ID VARCHAR, P_SIMULATION_ID VARCHAR, P_MODEL_DOMAIN VARCHAR, P_OUTCOME_DATE DATE, P_ACTUAL_NUMERIC_VALUE FLOAT, P_ACTUAL_TEXT_STATUS VARCHAR, P_ACTUAL_MAPPING_CORRECT_FLAG BOOLEAN, P_OUTCOME_SOURCE VARCHAR, P_EVIDENCE_REFERENCE VARCHAR, P_NOTES VARCHAR, P_RECORDED_BY VARCHAR)', 'DIRECT_STREAMLIT_CALL', TRUE),
        ('PROCEDURE', 'CORE_ML', 'RECORD_KMAT_COST_ACTUAL_OUTCOME_V1', '(P_COST_OUTCOME_ID VARCHAR, P_SIMULATION_ID VARCHAR, P_OUTCOME_DATE DATE, P_ACTUAL_MATERIAL_COST_USD FLOAT, P_ACTUAL_LABOR_COST_USD FLOAT, P_ACTUAL_MACHINE_COST_USD FLOAT, P_ACTUAL_OVERHEAD_COST_USD FLOAT, P_ACTUAL_TOTAL_COST_USD FLOAT, P_ACTUAL_FINAL_PRICE_USD FLOAT, P_OUTCOME_SOURCE VARCHAR, P_EVIDENCE_REFERENCE VARCHAR, P_NOTES VARCHAR, P_RECORDED_BY VARCHAR)', 'DIRECT_STREAMLIT_CALL', TRUE),
        ('PROCEDURE', 'CORE_ML', 'RUN_KMAT_MONITORING_V1', '(P_MONITORING_RUN_ID VARCHAR, P_RUN_BY VARCHAR)', 'DIRECT_STREAMLIT_CALL', TRUE),
        ('PROCEDURE', 'CORE_ML', 'ACTIVATE_APPROVED_ML_DEPLOYMENT_SECURE_V1', '(P_DEPLOYMENT_REQUEST_ID VARCHAR, P_CONFIRMATION_PHRASE VARCHAR)', 'DISPLAY_ONLY_GOVERNANCE_ENTRY_POINT', FALSE),
        ('TABLE', 'CORE_ML', 'KMAT_COST_FACTOR_RESOLUTION_AUDIT_V1', NULL, 'DIRECT_STREAMLIT_DATA', TRUE),
        ('TABLE', 'CORE_ML', 'KMAT_GOVERNED_COST_INPUT_AUDIT_V2', NULL, 'DIRECT_STREAMLIT_DATA', TRUE),
        ('TABLE', 'CORE_ML', 'KMAT_MONITORING_RUN_V1', NULL, 'DIRECT_STREAMLIT_DATA', TRUE),
        ('VIEW', 'CORE_ML', 'VW_KMAT_PHASE10C_DECISION_DISPLAY_V1', NULL, 'DIRECT_STREAMLIT_VIEW', TRUE),
        ('VIEW', 'CORE_ML', 'VW_KMAT_COST_FEEDBACK_DETAIL_V1', NULL, 'DIRECT_STREAMLIT_VIEW', TRUE),
        ('VIEW', 'CORE_ML', 'VW_KMAT_MODEL_FEEDBACK_DETAIL_V1', NULL, 'DIRECT_STREAMLIT_VIEW', TRUE),
        ('VIEW', 'CORE_ML', 'VW_KMAT_MONITORING_DOMAIN_SUMMARY_V1', NULL, 'DIRECT_STREAMLIT_VIEW', TRUE),
        ('VIEW', 'CORE_ML', 'VW_KMAT_MONITORING_OPERATIONAL_SUMMARY_V1', NULL, 'DIRECT_STREAMLIT_VIEW', TRUE),
        ('VIEW', 'CORE_ML', 'VW_KMAT_PHASE11A_MONITORING_DASHBOARD_V1', NULL, 'DIRECT_STREAMLIT_VIEW', TRUE),
        ('VIEW', 'CORE_ML', 'VW_KMAT_PHASE13A_RUNTIME_AUTHORITY_V1', NULL, 'DIRECT_STREAMLIT_VIEW', TRUE),
        ('VIEW', 'CORE_ML', 'VW_KMAT_PHASE13B_SECURITY_DASHBOARD_V1', NULL, 'DIRECT_STREAMLIT_VIEW', TRUE),
        ('VIEW', 'CORE_ML', 'VW_KMAT_STREAMLIT_RUNTIME_INPUT_V1', NULL, 'DIRECT_STREAMLIT_VIEW', TRUE),
        ('VIEW', 'CORE_ML', 'VW_ML_DECISION_WITH_APPROVED_OVERRIDE_V2', NULL, 'DIRECT_STREAMLIT_VIEW', TRUE),
        ('VIEW', 'CORE_ML', 'VW_ML_POLICY_VERSION_SEAL_INTEGRITY_V1', NULL, 'DIRECT_STREAMLIT_VIEW', TRUE),
        ('VIEW', 'CORE_ML', 'VW_ML_RUNTIME_DECISION_CURRENT_V1', NULL, 'DIRECT_STREAMLIT_VIEW', TRUE)
    AS seed(
        OBJECT_TYPE,
        OBJECT_SCHEMA,
        OBJECT_NAME,
        OBJECT_SIGNATURE,
        ROOT_USAGE,
        RUNTIME_REQUIRED_FLAG
    )
),
AUDIT_MATCH AS (
    SELECT
        seed.*,
        audit.REWRITE_CLASSIFICATION,
        audit.OBJECT_DDL_HASH
    FROM ROOT_SEED seed
    LEFT JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1 audit
        ON audit.AUDIT_BATCH_ID =
           'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
       AND audit.OBJECT_TYPE = seed.OBJECT_TYPE
       AND audit.OBJECT_SCHEMA = seed.OBJECT_SCHEMA
       AND audit.OBJECT_NAME = seed.OBJECT_NAME
       AND (
            seed.OBJECT_TYPE <> 'PROCEDURE'
            OR seed.OBJECT_SIGNATURE IS NULL
            OR audit.OBJECT_SIGNATURE =
               seed.OBJECT_SIGNATURE
       )
)
SELECT
    'PHASE14D3A_RUNTIME_ROOT_SCOPE_V1',
    OBJECT_TYPE,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE,
    ROOT_USAGE,
    RUNTIME_REQUIRED_FLAG,

    CASE
        WHEN OBJECT_TYPE IN ('PROCEDURE', 'VIEW')
            THEN OBJECT_DDL_HASH IS NOT NULL

        WHEN OBJECT_TYPE = 'TABLE'
            THEN EXISTS (
                SELECT 1
                FROM
                    KMAT_COST_MODEL_DB
                        .INFORMATION_SCHEMA.TABLES table_info
                WHERE table_info.TABLE_SCHEMA =
                      AUDIT_MATCH.OBJECT_SCHEMA
                  AND table_info.TABLE_NAME =
                      AUDIT_MATCH.OBJECT_NAME
            )

        ELSE FALSE
    END AS OBJECT_EXISTS_FLAG,

    COALESCE(
        REWRITE_CLASSIFICATION,
        IFF(
            OBJECT_TYPE = 'TABLE',
            'DATA_CONTRACT_OBJECT',
            'NOT_PRESENT_IN_PHASE14D2_AUDIT'
        )
    ),

    OBJECT_DDL_HASH,
    CURRENT_USER(),
    CURRENT_TIMESTAMP()

FROM AUDIT_MATCH;


SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COUNT_IF(
                RUNTIME_REQUIRED_FLAG = TRUE
                AND OBJECT_EXISTS_FLAG = FALSE
            ) = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3A',

    'scope_batch_id',
        'PHASE14D3A_RUNTIME_ROOT_SCOPE_V1',

    'root_object_count',
        COUNT(*),

    'required_root_object_count',
        COUNT_IF(
            RUNTIME_REQUIRED_FLAG = TRUE
        ),

    'optional_or_display_root_count',
        COUNT_IF(
            RUNTIME_REQUIRED_FLAG = FALSE
        ),

    'missing_required_root_count',
        COUNT_IF(
            RUNTIME_REQUIRED_FLAG = TRUE
            AND OBJECT_EXISTS_FLAG = FALSE
        ),

    'direct_procedure_count',
        COUNT_IF(
            OBJECT_TYPE = 'PROCEDURE'
        ),

    'direct_view_count',
        COUNT_IF(
            OBJECT_TYPE = 'VIEW'
        ),

    'direct_table_count',
        COUNT_IF(
            OBJECT_TYPE = 'TABLE'
        ),

    'runtime_object_changed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3A_ROOT_SCOPE_SUMMARY

FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_RUNTIME_ROOT_SCOPE_V1

WHERE SCOPE_BATCH_ID =
      'PHASE14D3A_RUNTIME_ROOT_SCOPE_V1';


SELECT
    OBJECT_TYPE,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE,
    ROOT_USAGE,
    RUNTIME_REQUIRED_FLAG,
    OBJECT_EXISTS_FLAG,
    AUDIT_CLASSIFICATION,
    AUDIT_DDL_HASH
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_RUNTIME_ROOT_SCOPE_V1
WHERE SCOPE_BATCH_ID =
      'PHASE14D3A_RUNTIME_ROOT_SCOPE_V1'
ORDER BY
    RUNTIME_REQUIRED_FLAG DESC,
    OBJECT_TYPE,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE;


USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

-- ============================================================
-- PHASE 14D.3A — AUDITED OBJECT DEPENDENCY EDGES
--
-- Builds review edges by matching schema-qualified object names
-- inside the frozen deployed DDL.
--
-- This is a dependency inventory. It executes no candidate DDL.
-- ============================================================

CREATE TABLE IF NOT EXISTS
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_OBJECT_DEPENDENCY_EDGE_V1 (
            EDGE_BATCH_ID VARCHAR NOT NULL,
            PARENT_OBJECT_TYPE VARCHAR NOT NULL,
            PARENT_OBJECT_SCHEMA VARCHAR NOT NULL,
            PARENT_OBJECT_NAME VARCHAR NOT NULL,
            PARENT_OBJECT_SIGNATURE VARCHAR,
            PARENT_OBJECT_FQN VARCHAR NOT NULL,
            CHILD_OBJECT_TYPE VARCHAR NOT NULL,
            CHILD_OBJECT_SCHEMA VARCHAR NOT NULL,
            CHILD_OBJECT_NAME VARCHAR NOT NULL,
            CHILD_OBJECT_SIGNATURE VARCHAR,
            CHILD_OBJECT_FQN VARCHAR NOT NULL,
            DETECTION_METHOD VARCHAR NOT NULL,
            PARENT_DDL_HASH NUMBER,
            CHILD_DDL_HASH NUMBER,
            RECORDED_BY VARCHAR NOT NULL,
            RECORDED_AT TIMESTAMP_NTZ NOT NULL
        );

DELETE FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_OBJECT_DEPENDENCY_EDGE_V1
WHERE EDGE_BATCH_ID =
      'PHASE14D3A_OBJECT_DEPENDENCY_EDGE_V1';


INSERT INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_OBJECT_DEPENDENCY_EDGE_V1
(
    EDGE_BATCH_ID,
    PARENT_OBJECT_TYPE,
    PARENT_OBJECT_SCHEMA,
    PARENT_OBJECT_NAME,
    PARENT_OBJECT_SIGNATURE,
    PARENT_OBJECT_FQN,
    CHILD_OBJECT_TYPE,
    CHILD_OBJECT_SCHEMA,
    CHILD_OBJECT_NAME,
    CHILD_OBJECT_SIGNATURE,
    CHILD_OBJECT_FQN,
    DETECTION_METHOD,
    PARENT_DDL_HASH,
    CHILD_DDL_HASH,
    RECORDED_BY,
    RECORDED_AT
)
WITH AUDIT_OBJECTS AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1
    WHERE AUDIT_BATCH_ID =
          'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
),
MATCHED_EDGES AS (
    SELECT
        parent.OBJECT_TYPE
            AS PARENT_OBJECT_TYPE,
        parent.OBJECT_SCHEMA
            AS PARENT_OBJECT_SCHEMA,
        parent.OBJECT_NAME
            AS PARENT_OBJECT_NAME,
        parent.OBJECT_SIGNATURE
            AS PARENT_OBJECT_SIGNATURE,
        parent.OBJECT_FQN
            AS PARENT_OBJECT_FQN,

        child.OBJECT_TYPE
            AS CHILD_OBJECT_TYPE,
        child.OBJECT_SCHEMA
            AS CHILD_OBJECT_SCHEMA,
        child.OBJECT_NAME
            AS CHILD_OBJECT_NAME,
        child.OBJECT_SIGNATURE
            AS CHILD_OBJECT_SIGNATURE,
        child.OBJECT_FQN
            AS CHILD_OBJECT_FQN,

        CASE
            WHEN REGEXP_LIKE(
                UPPER(parent.OBJECT_DDL),
                '(^|[^A-Z0-9_$])'
                || 'KMAT_COST_MODEL_DB[.]'
                || child.OBJECT_SCHEMA
                || '[.]'
                || child.OBJECT_NAME
                || '([^A-Z0-9_$]|$)'
            )
            THEN 'FIXED_DATABASE_SCHEMA_OBJECT'

            ELSE 'SCHEMA_QUALIFIED_OBJECT'
        END AS DETECTION_METHOD,

        parent.OBJECT_DDL_HASH
            AS PARENT_DDL_HASH,
        child.OBJECT_DDL_HASH
            AS CHILD_DDL_HASH

    FROM AUDIT_OBJECTS parent
    JOIN AUDIT_OBJECTS child
      ON NOT (
            parent.OBJECT_TYPE = child.OBJECT_TYPE
        AND parent.OBJECT_SCHEMA = child.OBJECT_SCHEMA
        AND parent.OBJECT_NAME = child.OBJECT_NAME
        AND COALESCE(
                parent.OBJECT_SIGNATURE,
                ''
            ) = COALESCE(
                child.OBJECT_SIGNATURE,
                ''
            )
      )

     AND REGEXP_LIKE(
            UPPER(parent.OBJECT_DDL),

            '(^|[^A-Z0-9_$])'
            || '(KMAT_COST_MODEL_DB[.])?'
            || child.OBJECT_SCHEMA
            || '[.]'
            || child.OBJECT_NAME
            || '([^A-Z0-9_$]|$)'
         )
)
SELECT DISTINCT
    'PHASE14D3A_OBJECT_DEPENDENCY_EDGE_V1',
    PARENT_OBJECT_TYPE,
    PARENT_OBJECT_SCHEMA,
    PARENT_OBJECT_NAME,
    PARENT_OBJECT_SIGNATURE,
    PARENT_OBJECT_FQN,
    CHILD_OBJECT_TYPE,
    CHILD_OBJECT_SCHEMA,
    CHILD_OBJECT_NAME,
    CHILD_OBJECT_SIGNATURE,
    CHILD_OBJECT_FQN,
    DETECTION_METHOD,
    PARENT_DDL_HASH,
    CHILD_DDL_HASH,
    CURRENT_USER(),
    CURRENT_TIMESTAMP()
FROM MATCHED_EDGES;


SELECT OBJECT_CONSTRUCT(
    'status', 'SUCCESS',
    'phase', 'PHASE_14D_3A',
    'edge_batch_id',
        'PHASE14D3A_OBJECT_DEPENDENCY_EDGE_V1',
    'dependency_edge_count',
        COUNT(*),
    'parent_object_count',
        COUNT(DISTINCT PARENT_OBJECT_FQN),
    'child_object_count',
        COUNT(DISTINCT CHILD_OBJECT_FQN),
    'fixed_database_edge_count',
        COUNT_IF(
            DETECTION_METHOD =
                'FIXED_DATABASE_SCHEMA_OBJECT'
        ),
    'schema_qualified_edge_count',
        COUNT_IF(
            DETECTION_METHOD =
                'SCHEMA_QUALIFIED_OBJECT'
        ),
    'runtime_object_changed', FALSE,
    'native_app_package_created', FALSE
) AS PHASE14D3A_DEPENDENCY_EDGE_SUMMARY

FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_OBJECT_DEPENDENCY_EDGE_V1

WHERE EDGE_BATCH_ID =
      'PHASE14D3A_OBJECT_DEPENDENCY_EDGE_V1';

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

-- ============================================================
-- PHASE 14D.3A — RUNTIME DEPENDENCY CLOSURE
--
-- Calculates the transitive procedure/view dependency closure
-- for required Streamlit roots.
--
-- A cycle-safe path and maximum depth are used.
-- ============================================================

CREATE TABLE IF NOT EXISTS
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_RUNTIME_DEPENDENCY_SCOPE_V1 (
            SCOPE_BATCH_ID VARCHAR NOT NULL,
            ROOT_OBJECT_FQN VARCHAR NOT NULL,
            ROOT_USAGE VARCHAR NOT NULL,
            OBJECT_TYPE VARCHAR NOT NULL,
            OBJECT_SCHEMA VARCHAR NOT NULL,
            OBJECT_NAME VARCHAR NOT NULL,
            OBJECT_SIGNATURE VARCHAR,
            OBJECT_FQN VARCHAR NOT NULL,
            DEPENDENCY_DEPTH NUMBER NOT NULL,
            DIRECT_ROOT_FLAG BOOLEAN NOT NULL,
            REWRITE_CLASSIFICATION VARCHAR,
            REWRITE_WAVE VARCHAR NOT NULL,
            OBJECT_DDL_HASH NUMBER,
            DEPENDENCY_PATH VARCHAR NOT NULL,
            RECORDED_BY VARCHAR NOT NULL,
            RECORDED_AT TIMESTAMP_NTZ NOT NULL
        );

DELETE FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_RUNTIME_DEPENDENCY_SCOPE_V1
WHERE SCOPE_BATCH_ID =
      'PHASE14D3A_RUNTIME_DEPENDENCY_SCOPE_V1';


INSERT INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_RUNTIME_DEPENDENCY_SCOPE_V1
(
    SCOPE_BATCH_ID,
    ROOT_OBJECT_FQN,
    ROOT_USAGE,
    OBJECT_TYPE,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE,
    OBJECT_FQN,
    DEPENDENCY_DEPTH,
    DIRECT_ROOT_FLAG,
    REWRITE_CLASSIFICATION,
    REWRITE_WAVE,
    OBJECT_DDL_HASH,
    DEPENDENCY_PATH,
    RECORDED_BY,
    RECORDED_AT
)
WITH RECURSIVE
ROOTS AS (
    SELECT
        root.ROOT_USAGE,

        audit.OBJECT_TYPE,
        audit.OBJECT_SCHEMA,
        audit.OBJECT_NAME,
        audit.OBJECT_SIGNATURE,
        audit.OBJECT_FQN,
        audit.REWRITE_CLASSIFICATION,
        audit.OBJECT_DDL_HASH

    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_RUNTIME_ROOT_SCOPE_V1 root

    JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1 audit
      ON audit.AUDIT_BATCH_ID =
         'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
     AND audit.OBJECT_TYPE = root.OBJECT_TYPE
     AND audit.OBJECT_SCHEMA = root.OBJECT_SCHEMA
     AND audit.OBJECT_NAME = root.OBJECT_NAME
     AND (
            root.OBJECT_TYPE <> 'PROCEDURE'
            OR root.OBJECT_SIGNATURE IS NULL
            OR audit.OBJECT_SIGNATURE =
               root.OBJECT_SIGNATURE
         )

    WHERE root.SCOPE_BATCH_ID =
          'PHASE14D3A_RUNTIME_ROOT_SCOPE_V1'
      AND root.RUNTIME_REQUIRED_FLAG = TRUE
      AND root.OBJECT_TYPE IN (
            'PROCEDURE',
            'VIEW'
          )
),
DEPENDENCY_CLOSURE (
    ROOT_OBJECT_FQN,
    ROOT_USAGE,
    OBJECT_TYPE,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE,
    OBJECT_FQN,
    REWRITE_CLASSIFICATION,
    OBJECT_DDL_HASH,
    DEPENDENCY_DEPTH,
    DEPENDENCY_PATH
) AS (
    SELECT
        OBJECT_FQN,
        ROOT_USAGE,
        OBJECT_TYPE,
        OBJECT_SCHEMA,
        OBJECT_NAME,
        OBJECT_SIGNATURE,
        OBJECT_FQN,
        REWRITE_CLASSIFICATION,
        OBJECT_DDL_HASH,
        0,
        '|' || OBJECT_FQN || '|'
    FROM ROOTS

    UNION ALL

    SELECT
        closure.ROOT_OBJECT_FQN,
        closure.ROOT_USAGE,
        audit.OBJECT_TYPE,
        audit.OBJECT_SCHEMA,
        audit.OBJECT_NAME,
        audit.OBJECT_SIGNATURE,
        audit.OBJECT_FQN,
        audit.REWRITE_CLASSIFICATION,
        audit.OBJECT_DDL_HASH,
        closure.DEPENDENCY_DEPTH + 1,
        closure.DEPENDENCY_PATH
        || audit.OBJECT_FQN
        || '|'

    FROM DEPENDENCY_CLOSURE closure

    JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_DEPENDENCY_EDGE_V1 edge
      ON edge.EDGE_BATCH_ID =
         'PHASE14D3A_OBJECT_DEPENDENCY_EDGE_V1'
     AND edge.PARENT_OBJECT_FQN =
         closure.OBJECT_FQN

    JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1 audit
      ON audit.AUDIT_BATCH_ID =
         'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
     AND audit.OBJECT_FQN =
         edge.CHILD_OBJECT_FQN

    WHERE closure.DEPENDENCY_DEPTH < 20

      AND POSITION(
            '|' || audit.OBJECT_FQN || '|'
            IN closure.DEPENDENCY_PATH
          ) = 0
),
DEDUPED AS (
    SELECT
        *,
        ROW_NUMBER() OVER (
            PARTITION BY
                ROOT_OBJECT_FQN,
                OBJECT_FQN
            ORDER BY
                DEPENDENCY_DEPTH,
                DEPENDENCY_PATH
        ) AS ROW_PRIORITY
    FROM DEPENDENCY_CLOSURE
)
SELECT
    'PHASE14D3A_RUNTIME_DEPENDENCY_SCOPE_V1',
    ROOT_OBJECT_FQN,
    ROOT_USAGE,
    OBJECT_TYPE,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE,
    OBJECT_FQN,
    DEPENDENCY_DEPTH,
    DEPENDENCY_DEPTH = 0,
    REWRITE_CLASSIFICATION,

    CASE
        WHEN REWRITE_CLASSIFICATION =
             'ALREADY_PORTABLE'
            THEN 'NO_REWRITE_REQUIRED'

        WHEN REWRITE_CLASSIFICATION =
             'RELATIVE_NAMESPACE_VIEW_CANDIDATE'
            THEN 'PHASE_14D_3B_VIEW_SOURCE'

        WHEN REWRITE_CLASSIFICATION =
             'PROCEDURE_BODY_REWRITE_CANDIDATE'
            THEN 'PHASE_14D_3C_SQL_PROCEDURE_SOURCE'

        WHEN REWRITE_CLASSIFICATION =
             'MANUAL_DYNAMIC_SQL_REWRITE'
            THEN 'PHASE_14D_3D_PYTHON_DYNAMIC_SQL'

        WHEN REWRITE_CLASSIFICATION =
             'MANUAL_STAGE_CONTRACT_REVIEW'
            THEN 'PHASE_14D_3E_RFQ_STAGE_CONTRACT'

        WHEN REWRITE_CLASSIFICATION =
             'DEFER_TO_PHASE_14E'
            THEN 'PHASE_14E_MODEL_PORTABILITY'

        ELSE 'MANUAL_REVIEW'
    END,

    OBJECT_DDL_HASH,
    DEPENDENCY_PATH,
    CURRENT_USER(),
    CURRENT_TIMESTAMP()

FROM (
    SELECT
        deduped.*,
        audit.OBJECT_LANGUAGE
    FROM DEDUPED deduped
    LEFT JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1 audit
      ON audit.AUDIT_BATCH_ID =
         'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
     AND audit.OBJECT_FQN =
         deduped.OBJECT_FQN
    WHERE ROW_PRIORITY = 1
);


WITH DISTINCT_SCOPE AS (
    SELECT
        OBJECT_FQN,
        ANY_VALUE(OBJECT_TYPE) AS OBJECT_TYPE,
        ANY_VALUE(OBJECT_SCHEMA) AS OBJECT_SCHEMA,
        ANY_VALUE(OBJECT_NAME) AS OBJECT_NAME,
        ANY_VALUE(OBJECT_SIGNATURE) AS OBJECT_SIGNATURE,
        MIN(DEPENDENCY_DEPTH) AS MIN_DEPENDENCY_DEPTH,
        BOOLOR_AGG(DIRECT_ROOT_FLAG) AS DIRECT_ROOT_FLAG,
        ANY_VALUE(REWRITE_CLASSIFICATION)
            AS REWRITE_CLASSIFICATION,
        ANY_VALUE(REWRITE_WAVE)
            AS REWRITE_WAVE,
        ANY_VALUE(OBJECT_DDL_HASH)
            AS OBJECT_DDL_HASH
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_RUNTIME_DEPENDENCY_SCOPE_V1
    WHERE SCOPE_BATCH_ID =
          'PHASE14D3A_RUNTIME_DEPENDENCY_SCOPE_V1'
    GROUP BY OBJECT_FQN
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COUNT_IF(
                REWRITE_CLASSIFICATION =
                    'BLOCKED_TEMP_OBJECT'
            ) = 0
            AND COUNT_IF(
                REWRITE_CLASSIFICATION =
                    'MANUAL_WAREHOUSE_REVIEW'
            ) = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3A',

    'scope_batch_id',
        'PHASE14D3A_RUNTIME_DEPENDENCY_SCOPE_V1',

    'distinct_runtime_object_count',
        COUNT(*),

    'direct_root_count',
        COUNT_IF(
            DIRECT_ROOT_FLAG = TRUE
        ),

    'transitive_dependency_count',
        COUNT_IF(
            DIRECT_ROOT_FLAG = FALSE
        ),

    'already_portable_count',
        COUNT_IF(
            REWRITE_WAVE =
                'NO_REWRITE_REQUIRED'
        ),

    'view_source_candidate_count',
        COUNT_IF(
            REWRITE_WAVE =
                'PHASE_14D_3B_VIEW_SOURCE'
        ),

    'sql_procedure_source_candidate_count',
        COUNT_IF(
            REWRITE_WAVE =
                'PHASE_14D_3C_SQL_PROCEDURE_SOURCE'
        ),

    'python_dynamic_sql_candidate_count',
        COUNT_IF(
            REWRITE_WAVE =
                'PHASE_14D_3D_PYTHON_DYNAMIC_SQL'
        ),

    'rfq_stage_contract_count',
        COUNT_IF(
            REWRITE_WAVE =
                'PHASE_14D_3E_RFQ_STAGE_CONTRACT'
        ),

    'phase14e_model_object_count',
        COUNT_IF(
            REWRITE_WAVE =
                'PHASE_14E_MODEL_PORTABILITY'
        ),

    'blocked_temp_object_count',
        COUNT_IF(
            REWRITE_CLASSIFICATION =
                'BLOCKED_TEMP_OBJECT'
        ),

    'fixed_warehouse_review_count',
        COUNT_IF(
            REWRITE_CLASSIFICATION =
                'MANUAL_WAREHOUSE_REVIEW'
        ),

    'runtime_object_changed',
        FALSE,

    'procedure_body_changed',
        FALSE,

    'view_definition_changed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3A_RUNTIME_CLOSURE_SUMMARY

FROM DISTINCT_SCOPE;


WITH DISTINCT_SCOPE AS (
    SELECT
        OBJECT_FQN,
        ANY_VALUE(OBJECT_TYPE) AS OBJECT_TYPE,
        ANY_VALUE(OBJECT_SCHEMA) AS OBJECT_SCHEMA,
        ANY_VALUE(OBJECT_NAME) AS OBJECT_NAME,
        ANY_VALUE(OBJECT_SIGNATURE) AS OBJECT_SIGNATURE,
        MIN(DEPENDENCY_DEPTH) AS MIN_DEPENDENCY_DEPTH,
        BOOLOR_AGG(DIRECT_ROOT_FLAG) AS DIRECT_ROOT_FLAG,
        ANY_VALUE(REWRITE_CLASSIFICATION)
            AS REWRITE_CLASSIFICATION,
        ANY_VALUE(REWRITE_WAVE)
            AS REWRITE_WAVE,
        ANY_VALUE(OBJECT_DDL_HASH)
            AS OBJECT_DDL_HASH
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_RUNTIME_DEPENDENCY_SCOPE_V1
    WHERE SCOPE_BATCH_ID =
          'PHASE14D3A_RUNTIME_DEPENDENCY_SCOPE_V1'
    GROUP BY OBJECT_FQN
)
SELECT *
FROM DISTINCT_SCOPE
ORDER BY
    CASE REWRITE_WAVE
        WHEN 'PHASE_14D_3E_RFQ_STAGE_CONTRACT' THEN 1
        WHEN 'PHASE_14D_3D_PYTHON_DYNAMIC_SQL' THEN 2
        WHEN 'PHASE_14D_3C_SQL_PROCEDURE_SOURCE' THEN 3
        WHEN 'PHASE_14D_3B_VIEW_SOURCE' THEN 4
        WHEN 'PHASE_14E_MODEL_PORTABILITY' THEN 5
        WHEN 'NO_REWRITE_REQUIRED' THEN 6
        ELSE 7
    END,
    MIN_DEPENDENCY_DEPTH,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE;


    
USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

-- ============================================================
-- PHASE 14D.3A — REVIEW-ONLY PORTABLE SOURCE CANDIDATES
--
-- Stores transformed source text for the runtime dependency
-- closure. It does not execute that source.
--
-- Important:
-- GET_DDL does not preserve every deployment property, including
-- COPY GRANTS for views. These candidates are not deployment-ready.
-- ============================================================

CREATE TABLE IF NOT EXISTS
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PORTABLE_SOURCE_CANDIDATE_V1 (
            SOURCE_BATCH_ID VARCHAR NOT NULL,
            OBJECT_TYPE VARCHAR NOT NULL,
            OBJECT_SCHEMA VARCHAR NOT NULL,
            OBJECT_NAME VARCHAR NOT NULL,
            OBJECT_SIGNATURE VARCHAR,
            OBJECT_FQN VARCHAR NOT NULL,
            OBJECT_OWNER VARCHAR,
            OBJECT_LANGUAGE VARCHAR,
            REWRITE_CLASSIFICATION VARCHAR,
            REWRITE_WAVE VARCHAR NOT NULL,
            ORIGINAL_DDL VARCHAR NOT NULL,
            ORIGINAL_DDL_HASH NUMBER NOT NULL,
            PORTABLE_SOURCE_CANDIDATE VARCHAR NOT NULL,
            PORTABLE_SOURCE_HASH NUMBER NOT NULL,
            FIXED_DATABASE_REFERENCE_COUNT_BEFORE NUMBER NOT NULL,
            FIXED_DATABASE_REFERENCE_COUNT_AFTER NUMBER NOT NULL,
            DEPLOYMENT_READY_FLAG BOOLEAN NOT NULL,
            REVIEW_NOTES VARCHAR NOT NULL,
            GENERATED_BY VARCHAR NOT NULL,
            GENERATED_AT TIMESTAMP_NTZ NOT NULL
        );

DELETE FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PORTABLE_SOURCE_CANDIDATE_V1
WHERE SOURCE_BATCH_ID =
      'PHASE14D3A_PORTABLE_SOURCE_CANDIDATE_V1';


INSERT INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PORTABLE_SOURCE_CANDIDATE_V1
(
    SOURCE_BATCH_ID,
    OBJECT_TYPE,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE,
    OBJECT_FQN,
    OBJECT_OWNER,
    OBJECT_LANGUAGE,
    REWRITE_CLASSIFICATION,
    REWRITE_WAVE,
    ORIGINAL_DDL,
    ORIGINAL_DDL_HASH,
    PORTABLE_SOURCE_CANDIDATE,
    PORTABLE_SOURCE_HASH,
    FIXED_DATABASE_REFERENCE_COUNT_BEFORE,
    FIXED_DATABASE_REFERENCE_COUNT_AFTER,
    DEPLOYMENT_READY_FLAG,
    REVIEW_NOTES,
    GENERATED_BY,
    GENERATED_AT
)
WITH DISTINCT_SCOPE AS (
    SELECT
        OBJECT_FQN,
        ANY_VALUE(REWRITE_WAVE) AS REWRITE_WAVE
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_RUNTIME_DEPENDENCY_SCOPE_V1
    WHERE SCOPE_BATCH_ID =
          'PHASE14D3A_RUNTIME_DEPENDENCY_SCOPE_V1'
    GROUP BY OBJECT_FQN
),
CANDIDATES AS (
    SELECT
        audit.*,
        scope.REWRITE_WAVE,

        REPLACE(
            audit.OBJECT_DDL,
            'KMAT_COST_MODEL_DB.',
            ''
        ) AS PORTABLE_SOURCE_CANDIDATE

    FROM DISTINCT_SCOPE scope

    JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1 audit
      ON audit.AUDIT_BATCH_ID =
         'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
     AND audit.OBJECT_FQN =
         scope.OBJECT_FQN

    WHERE audit.FIXED_DATABASE_REFERENCE_COUNT > 0
)
SELECT
    'PHASE14D3A_PORTABLE_SOURCE_CANDIDATE_V1',
    OBJECT_TYPE,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE,
    OBJECT_FQN,
    OBJECT_OWNER,
    OBJECT_LANGUAGE,
    REWRITE_CLASSIFICATION,
    REWRITE_WAVE,
    OBJECT_DDL,
    OBJECT_DDL_HASH,
    PORTABLE_SOURCE_CANDIDATE,
    HASH(PORTABLE_SOURCE_CANDIDATE),
    FIXED_DATABASE_REFERENCE_COUNT,

    REGEXP_COUNT(
        UPPER(PORTABLE_SOURCE_CANDIDATE),
        'KMAT_COST_MODEL_DB'
    ),

    FALSE,

    CASE
        WHEN REWRITE_WAVE =
             'PHASE_14D_3B_VIEW_SOURCE'
            THEN
                'Review view dependencies, COPY GRANTS, tags, '
                || 'security mode and ownership before deployment.'

        WHEN REWRITE_WAVE =
             'PHASE_14D_3C_SQL_PROCEDURE_SOURCE'
            THEN
                'Review SQL body, grants, owner, execution mode '
                || 'and nested procedure calls before deployment.'

        WHEN REWRITE_WAVE =
             'PHASE_14D_3D_PYTHON_DYNAMIC_SQL'
            THEN
                'Do not deploy mechanical replacement. Rewrite '
                || 'dynamic SQL using controlled namespace helpers '
                || 'and bound values.'

        WHEN REWRITE_WAVE =
             'PHASE_14D_3E_RFQ_STAGE_CONTRACT'
            THEN
                'Do not deploy mechanical replacement. Replace '
                || 'fixed stage logic with the approved RFQ source '
                || 'contract.'

        ELSE
                'Manual review required.'
    END,

    CURRENT_USER(),
    CURRENT_TIMESTAMP()

FROM CANDIDATES;


SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COUNT(*) > 0
            AND COUNT_IF(
                FIXED_DATABASE_REFERENCE_COUNT_AFTER > 0
            ) = 0
            AND COUNT_IF(
                DEPLOYMENT_READY_FLAG = TRUE
            ) = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3A',

    'source_batch_id',
        'PHASE14D3A_PORTABLE_SOURCE_CANDIDATE_V1',

    'candidate_object_count',
        COUNT(*),

    'view_candidate_count',
        COUNT_IF(
            OBJECT_TYPE = 'VIEW'
        ),

    'procedure_candidate_count',
        COUNT_IF(
            OBJECT_TYPE = 'PROCEDURE'
        ),

    'fixed_database_reference_count_before',
        SUM(
            FIXED_DATABASE_REFERENCE_COUNT_BEFORE
        ),

    'fixed_database_reference_count_after',
        SUM(
            FIXED_DATABASE_REFERENCE_COUNT_AFTER
        ),

    'deployment_ready_count',
        COUNT_IF(
            DEPLOYMENT_READY_FLAG = TRUE
        ),

    'runtime_object_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3A_PORTABLE_SOURCE_SUMMARY

FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PORTABLE_SOURCE_CANDIDATE_V1

WHERE SOURCE_BATCH_ID =
      'PHASE14D3A_PORTABLE_SOURCE_CANDIDATE_V1';


SELECT
    OBJECT_TYPE,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE,
    OBJECT_OWNER,
    OBJECT_LANGUAGE,
    REWRITE_CLASSIFICATION,
    REWRITE_WAVE,
    ORIGINAL_DDL_HASH,
    PORTABLE_SOURCE_HASH,
    FIXED_DATABASE_REFERENCE_COUNT_BEFORE,
    FIXED_DATABASE_REFERENCE_COUNT_AFTER,
    DEPLOYMENT_READY_FLAG,
    REVIEW_NOTES,
    PORTABLE_SOURCE_CANDIDATE
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PORTABLE_SOURCE_CANDIDATE_V1
WHERE SOURCE_BATCH_ID =
      'PHASE14D3A_PORTABLE_SOURCE_CANDIDATE_V1'
ORDER BY
    CASE REWRITE_WAVE
        WHEN 'PHASE_14D_3E_RFQ_STAGE_CONTRACT' THEN 1
        WHEN 'PHASE_14D_3D_PYTHON_DYNAMIC_SQL' THEN 2
        WHEN 'PHASE_14D_3C_SQL_PROCEDURE_SOURCE' THEN 3
        WHEN 'PHASE_14D_3B_VIEW_SOURCE' THEN 4
        ELSE 5
    END,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE;

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

-- ============================================================
-- PHASE 14D.3A — INTEGRITY AND GOLDEN BASELINE
-- ============================================================

WITH ROOT_CHECK AS (
    SELECT
        COUNT(*) AS ROOT_COUNT,
        COUNT_IF(
            RUNTIME_REQUIRED_FLAG = TRUE
            AND OBJECT_EXISTS_FLAG = FALSE
        ) AS MISSING_REQUIRED_ROOT_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_RUNTIME_ROOT_SCOPE_V1
    WHERE SCOPE_BATCH_ID =
          'PHASE14D3A_RUNTIME_ROOT_SCOPE_V1'
),
SCOPE_CHECK AS (
    SELECT
        COUNT(DISTINCT OBJECT_FQN)
            AS DISTINCT_SCOPE_OBJECT_COUNT,
        COUNT_IF(
            OBJECT_DDL_HASH IS NULL
        ) AS NULL_SCOPE_HASH_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_RUNTIME_DEPENDENCY_SCOPE_V1
    WHERE SCOPE_BATCH_ID =
          'PHASE14D3A_RUNTIME_DEPENDENCY_SCOPE_V1'
),
SOURCE_CHECK AS (
    SELECT
        COUNT(*) AS SOURCE_CANDIDATE_COUNT,
        COUNT_IF(
            FIXED_DATABASE_REFERENCE_COUNT_AFTER > 0
        ) AS RESIDUAL_FIXED_DATABASE_CANDIDATE_COUNT,
        COUNT_IF(
            DEPLOYMENT_READY_FLAG = TRUE
        ) AS DEPLOYMENT_READY_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_PORTABLE_SOURCE_CANDIDATE_V1
    WHERE SOURCE_BATCH_ID =
          'PHASE14D3A_PORTABLE_SOURCE_CANDIDATE_V1'
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            ROOT_CHECK.MISSING_REQUIRED_ROOT_COUNT = 0
            AND SCOPE_CHECK.NULL_SCOPE_HASH_COUNT = 0
            AND SOURCE_CHECK
                .RESIDUAL_FIXED_DATABASE_CANDIDATE_COUNT = 0
            AND SOURCE_CHECK.DEPLOYMENT_READY_COUNT = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3A',

    'root_count',
        ROOT_CHECK.ROOT_COUNT,

    'missing_required_root_count',
        ROOT_CHECK.MISSING_REQUIRED_ROOT_COUNT,

    'distinct_scope_object_count',
        SCOPE_CHECK.DISTINCT_SCOPE_OBJECT_COUNT,

    'null_scope_hash_count',
        SCOPE_CHECK.NULL_SCOPE_HASH_COUNT,

    'source_candidate_count',
        SOURCE_CHECK.SOURCE_CANDIDATE_COUNT,

    'residual_fixed_database_candidate_count',
        SOURCE_CHECK
            .RESIDUAL_FIXED_DATABASE_CANDIDATE_COUNT,

    'deployment_ready_count',
        SOURCE_CHECK.DEPLOYMENT_READY_COUNT,

    'runtime_object_changed',
        FALSE,

    'procedure_body_changed',
        FALSE,

    'view_definition_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'ml_authority_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3A_INTEGRITY_VERIFICATION

FROM ROOT_CHECK
CROSS JOIN SCOPE_CHECK
CROSS JOIN SOURCE_CHECK;


WITH baseline AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_BASELINE_V1
    WHERE BASELINE_ID =
          'PHASE14A_SIM_001_BASELINE_V1'
),
current_state AS (
    SELECT
        s.SIMULATION_ID,

        HASH(
            s.MATERIAL_COST_USD,
            s.LABOR_COST_USD,
            s.MACHINE_COST_USD,
            s.OVERHEAD_COST_USD,
            s.TOTAL_CONFIGURED_COST_USD,
            s.FLOOR_PRICE_USD,
            s.TARGET_PRICE_USD,
            s.CEILING_PRICE_USD,
            s.BASELINE_TOTAL_COST_USD,
            s.RISK_ADJUSTED_TOTAL_COST_USD,
            s.TOTAL_RISK_UPLIFT_USD,
            s.TOTAL_RISK_UPLIFT_PCT,
            s.CSS_SCORE,
            s.SCRAP_RATE_APPLIED,
            s.AVG_WEIGHTED_FMIS,
            s.MAX_TDS_FACTOR,
            s.BOM_MATCH_CONFIDENCE_SCORE,
            s.BMCS_REVIEW_STATUS,
            s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
            s.QUOTE_TRUST_STATUS,
            h.RESOLVED_SCRAP_RATE,
            h.CSS_RESOLVED_SOURCE,
            h.RESOLVED_FMIS_MULTIPLIER,
            h.FMIS_RESOLVED_SOURCE,
            h.RESOLVED_TDS_FACTOR,
            h.TDS_RESOLVED_SOURCE,
            h.RESOLVED_BMCS_STATUS,
            h.SAFETY_GATE_PASS_FLAG,
            h.COST_ENGINE_CONSUMPTION_ALLOWED_FLAG,
            h.OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG
        ) AS SNAPSHOT_HASH,

        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS ACTIVE_POLICY_COUNT,

        (
            SELECT COUNT_IF(
                DEPLOYMENT_MODE = 'SHADOW'
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS SHADOW_POLICY_COUNT,

        (
            SELECT COALESCE(
                COUNT_IF(
                    AUTO_USE_ALLOWED_FLAG = TRUE
                    OR OFFICIAL_COST_IMPACT_ALLOWED_FLAG = TRUE
                    OR BUSINESS_DECISION_ALLOWED_FLAG = TRUE
                ),
                0
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS POLICY_AUTHORITY_ENABLED_COUNT,

        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .ML_RUNTIME_AUTHORITY_REGISTRY_V1
            WHERE UPPER(AUTHORITY_STATUS) = 'ENABLED'
        ) AS ENABLED_RUNTIME_AUTHORITY_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_OUTPUT
            .KMAT_CONFIGURED_COST_SUMMARY s

    LEFT JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .VW_KMAT_PHASE10B_HIERARCHY_V1 h
        ON s.SIMULATION_ID = h.SIMULATION_ID

    WHERE s.SIMULATION_ID = 'SIM_001'

    QUALIFY ROW_NUMBER() OVER (
        PARTITION BY s.SIMULATION_ID
        ORDER BY s.CALCULATED_AT DESC
    ) = 1
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            baseline.SNAPSHOT_HASH =
                current_state.SNAPSHOT_HASH
            AND current_state
                .POLICY_AUTHORITY_ENABLED_COUNT = 0
            AND current_state
                .ENABLED_RUNTIME_AUTHORITY_COUNT = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3A',

    'baseline_id',
        baseline.BASELINE_ID,

    'simulation_id',
        baseline.SIMULATION_ID,

    'baseline_snapshot_hash',
        baseline.SNAPSHOT_HASH,

    'current_snapshot_hash',
        current_state.SNAPSHOT_HASH,

    'cost_and_governance_snapshot_match',
        baseline.SNAPSHOT_HASH =
        current_state.SNAPSHOT_HASH,

    'active_policy_count',
        current_state.ACTIVE_POLICY_COUNT,

    'shadow_policy_count',
        current_state.SHADOW_POLICY_COUNT,

    'policy_authority_enabled_count',
        current_state
            .POLICY_AUTHORITY_ENABLED_COUNT,

    'enabled_runtime_authority_count',
        current_state
            .ENABLED_RUNTIME_AUTHORITY_COUNT,

    'official_cost_changed',
        baseline.SNAPSHOT_HASH <>
        current_state.SNAPSHOT_HASH,

    'runtime_object_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'ml_authority_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3A_BASELINE_VERIFICATION

FROM baseline
CROSS JOIN current_state;

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

-- PHASE 14D.3A HOTFIX
-- REGEXP_LIKE implicitly anchors the pattern in Snowflake.
-- Use REGEXP_COUNT for substring dependency detection.

DELETE FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_OBJECT_DEPENDENCY_EDGE_V1
WHERE EDGE_BATCH_ID =
      'PHASE14D3A_OBJECT_DEPENDENCY_EDGE_V1';

INSERT INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_OBJECT_DEPENDENCY_EDGE_V1
(
    EDGE_BATCH_ID,
    PARENT_OBJECT_TYPE,
    PARENT_OBJECT_SCHEMA,
    PARENT_OBJECT_NAME,
    PARENT_OBJECT_SIGNATURE,
    PARENT_OBJECT_FQN,
    CHILD_OBJECT_TYPE,
    CHILD_OBJECT_SCHEMA,
    CHILD_OBJECT_NAME,
    CHILD_OBJECT_SIGNATURE,
    CHILD_OBJECT_FQN,
    DETECTION_METHOD,
    PARENT_DDL_HASH,
    CHILD_DDL_HASH,
    RECORDED_BY,
    RECORDED_AT
)
WITH AUDIT_OBJECTS AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1
    WHERE AUDIT_BATCH_ID =
          'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
),
MATCHED_EDGES AS (
    SELECT
        parent.OBJECT_TYPE AS PARENT_OBJECT_TYPE,
        parent.OBJECT_SCHEMA AS PARENT_OBJECT_SCHEMA,
        parent.OBJECT_NAME AS PARENT_OBJECT_NAME,
        parent.OBJECT_SIGNATURE AS PARENT_OBJECT_SIGNATURE,
        parent.OBJECT_FQN AS PARENT_OBJECT_FQN,

        child.OBJECT_TYPE AS CHILD_OBJECT_TYPE,
        child.OBJECT_SCHEMA AS CHILD_OBJECT_SCHEMA,
        child.OBJECT_NAME AS CHILD_OBJECT_NAME,
        child.OBJECT_SIGNATURE AS CHILD_OBJECT_SIGNATURE,
        child.OBJECT_FQN AS CHILD_OBJECT_FQN,

        IFF(
            REGEXP_COUNT(
                UPPER(parent.OBJECT_DDL),
                '(^|[^A-Z0-9_$])'
                || 'KMAT_COST_MODEL_DB[.]'
                || child.OBJECT_SCHEMA
                || '[.]'
                || child.OBJECT_NAME
                || '([^A-Z0-9_$]|$)'
            ) > 0,
            'FIXED_DATABASE_SCHEMA_OBJECT',
            'SCHEMA_QUALIFIED_OBJECT'
        ) AS DETECTION_METHOD,

        parent.OBJECT_DDL_HASH AS PARENT_DDL_HASH,
        child.OBJECT_DDL_HASH AS CHILD_DDL_HASH

    FROM AUDIT_OBJECTS parent
    JOIN AUDIT_OBJECTS child
      ON NOT (
            parent.OBJECT_TYPE = child.OBJECT_TYPE
        AND parent.OBJECT_SCHEMA = child.OBJECT_SCHEMA
        AND parent.OBJECT_NAME = child.OBJECT_NAME
        AND COALESCE(parent.OBJECT_SIGNATURE, '') =
            COALESCE(child.OBJECT_SIGNATURE, '')
      )
     AND REGEXP_COUNT(
            UPPER(parent.OBJECT_DDL),
            '(^|[^A-Z0-9_$])'
            || '(KMAT_COST_MODEL_DB[.])?'
            || child.OBJECT_SCHEMA
            || '[.]'
            || child.OBJECT_NAME
            || '([^A-Z0-9_$]|$)'
         ) > 0
)
SELECT DISTINCT
    'PHASE14D3A_OBJECT_DEPENDENCY_EDGE_V1',
    PARENT_OBJECT_TYPE,
    PARENT_OBJECT_SCHEMA,
    PARENT_OBJECT_NAME,
    PARENT_OBJECT_SIGNATURE,
    PARENT_OBJECT_FQN,
    CHILD_OBJECT_TYPE,
    CHILD_OBJECT_SCHEMA,
    CHILD_OBJECT_NAME,
    CHILD_OBJECT_SIGNATURE,
    CHILD_OBJECT_FQN,
    DETECTION_METHOD,
    PARENT_DDL_HASH,
    CHILD_DDL_HASH,
    CURRENT_USER(),
    CURRENT_TIMESTAMP()
FROM MATCHED_EDGES;

WITH EDGE_CHECK AS (
    SELECT
        COUNT(*) AS DEPENDENCY_EDGE_COUNT,
        COUNT(DISTINCT PARENT_OBJECT_FQN)
            AS PARENT_OBJECT_COUNT,
        COUNT(DISTINCT CHILD_OBJECT_FQN)
            AS CHILD_OBJECT_COUNT,

        COUNT_IF(
            PARENT_OBJECT_NAME =
                'RUN_KMAT_COST_SIMULATION_GOVERNED_V3'
            AND CHILD_OBJECT_NAME =
                'RUN_KMAT_COST_SIMULATION_GOVERNED_V2'
        )
        +
        COUNT_IF(
            PARENT_OBJECT_NAME =
                'RUN_KMAT_COST_SIMULATION_GOVERNED_V3'
            AND CHILD_OBJECT_NAME =
                'RESOLVE_KMAT_COST_FACTOR_HIERARCHY_V1'
        )
        +
        COUNT_IF(
            PARENT_OBJECT_NAME =
                'RUN_CORTEX_RFQ_QUOTE_PIPELINE'
            AND CHILD_OBJECT_NAME =
                'RUN_CORTEX_BMCS_ASSESSMENT'
        )
        +
        COUNT_IF(
            PARENT_OBJECT_NAME =
                'RUN_CORTEX_RFQ_QUOTE_PIPELINE'
            AND CHILD_OBJECT_NAME =
                'PREPARE_RFQ_SIMULATION_INPUTS'
        )
        +
        COUNT_IF(
            PARENT_OBJECT_NAME =
                'RUN_CORTEX_RFQ_QUOTE_PIPELINE'
            AND CHILD_OBJECT_NAME =
                'RUN_KMAT_COST_SIMULATION'
        ) AS KNOWN_RUNTIME_EDGE_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_DEPENDENCY_EDGE_V1
    WHERE EDGE_BATCH_ID =
          'PHASE14D3A_OBJECT_DEPENDENCY_EDGE_V1'
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            DEPENDENCY_EDGE_COUNT > 0
            AND KNOWN_RUNTIME_EDGE_COUNT >= 5,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),
    'phase', 'PHASE_14D_3A_HOTFIX',
    'dependency_edge_count', DEPENDENCY_EDGE_COUNT,
    'parent_object_count', PARENT_OBJECT_COUNT,
    'child_object_count', CHILD_OBJECT_COUNT,
    'known_runtime_edge_count', KNOWN_RUNTIME_EDGE_COUNT,
    'minimum_known_runtime_edge_count', 5,
    'runtime_object_changed', FALSE,
    'candidate_source_executed', FALSE
) AS PHASE14D3A_DEPENDENCY_EDGE_SUMMARY
FROM EDGE_CHECK;

SELECT
    PARENT_OBJECT_SCHEMA,
    PARENT_OBJECT_NAME,
    PARENT_OBJECT_SIGNATURE,
    CHILD_OBJECT_SCHEMA,
    CHILD_OBJECT_NAME,
    CHILD_OBJECT_SIGNATURE,
    DETECTION_METHOD
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_OBJECT_DEPENDENCY_EDGE_V1
WHERE EDGE_BATCH_ID =
      'PHASE14D3A_OBJECT_DEPENDENCY_EDGE_V1'
  AND PARENT_OBJECT_NAME IN (
        'RUN_KMAT_COST_SIMULATION_GOVERNED_V3',
        'RUN_CORTEX_RFQ_QUOTE_PIPELINE'
      )
ORDER BY
    PARENT_OBJECT_NAME,
    CHILD_OBJECT_SCHEMA,
    CHILD_OBJECT_NAME;

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

-- ============================================================
-- PHASE 14D.3A — RUNTIME DEPENDENCY CLOSURE
--
-- Calculates the transitive procedure/view dependency closure
-- for required Streamlit roots.
--
-- A cycle-safe path and maximum depth are used.
-- ============================================================

CREATE TABLE IF NOT EXISTS
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_RUNTIME_DEPENDENCY_SCOPE_V1 (
            SCOPE_BATCH_ID VARCHAR NOT NULL,
            ROOT_OBJECT_FQN VARCHAR NOT NULL,
            ROOT_USAGE VARCHAR NOT NULL,
            OBJECT_TYPE VARCHAR NOT NULL,
            OBJECT_SCHEMA VARCHAR NOT NULL,
            OBJECT_NAME VARCHAR NOT NULL,
            OBJECT_SIGNATURE VARCHAR,
            OBJECT_FQN VARCHAR NOT NULL,
            DEPENDENCY_DEPTH NUMBER NOT NULL,
            DIRECT_ROOT_FLAG BOOLEAN NOT NULL,
            REWRITE_CLASSIFICATION VARCHAR,
            REWRITE_WAVE VARCHAR NOT NULL,
            OBJECT_DDL_HASH NUMBER,
            DEPENDENCY_PATH VARCHAR NOT NULL,
            RECORDED_BY VARCHAR NOT NULL,
            RECORDED_AT TIMESTAMP_NTZ NOT NULL
        );

DELETE FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_RUNTIME_DEPENDENCY_SCOPE_V1
WHERE SCOPE_BATCH_ID =
      'PHASE14D3A_RUNTIME_DEPENDENCY_SCOPE_V1';


INSERT INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_RUNTIME_DEPENDENCY_SCOPE_V1
(
    SCOPE_BATCH_ID,
    ROOT_OBJECT_FQN,
    ROOT_USAGE,
    OBJECT_TYPE,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE,
    OBJECT_FQN,
    DEPENDENCY_DEPTH,
    DIRECT_ROOT_FLAG,
    REWRITE_CLASSIFICATION,
    REWRITE_WAVE,
    OBJECT_DDL_HASH,
    DEPENDENCY_PATH,
    RECORDED_BY,
    RECORDED_AT
)
WITH RECURSIVE
ROOTS AS (
    SELECT
        root.ROOT_USAGE,

        audit.OBJECT_TYPE,
        audit.OBJECT_SCHEMA,
        audit.OBJECT_NAME,
        audit.OBJECT_SIGNATURE,
        audit.OBJECT_FQN,
        audit.REWRITE_CLASSIFICATION,
        audit.OBJECT_DDL_HASH

    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_RUNTIME_ROOT_SCOPE_V1 root

    JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1 audit
      ON audit.AUDIT_BATCH_ID =
         'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
     AND audit.OBJECT_TYPE = root.OBJECT_TYPE
     AND audit.OBJECT_SCHEMA = root.OBJECT_SCHEMA
     AND audit.OBJECT_NAME = root.OBJECT_NAME
     AND (
            root.OBJECT_TYPE <> 'PROCEDURE'
            OR root.OBJECT_SIGNATURE IS NULL
            OR audit.OBJECT_SIGNATURE =
               root.OBJECT_SIGNATURE
         )

    WHERE root.SCOPE_BATCH_ID =
          'PHASE14D3A_RUNTIME_ROOT_SCOPE_V1'
      AND root.RUNTIME_REQUIRED_FLAG = TRUE
      AND root.OBJECT_TYPE IN (
            'PROCEDURE',
            'VIEW'
          )
),
DEPENDENCY_CLOSURE (
    ROOT_OBJECT_FQN,
    ROOT_USAGE,
    OBJECT_TYPE,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE,
    OBJECT_FQN,
    REWRITE_CLASSIFICATION,
    OBJECT_DDL_HASH,
    DEPENDENCY_DEPTH,
    DEPENDENCY_PATH
) AS (
    SELECT
        OBJECT_FQN,
        ROOT_USAGE,
        OBJECT_TYPE,
        OBJECT_SCHEMA,
        OBJECT_NAME,
        OBJECT_SIGNATURE,
        OBJECT_FQN,
        REWRITE_CLASSIFICATION,
        OBJECT_DDL_HASH,
        0,
        '|' || OBJECT_FQN || '|'
    FROM ROOTS

    UNION ALL

    SELECT
        closure.ROOT_OBJECT_FQN,
        closure.ROOT_USAGE,
        audit.OBJECT_TYPE,
        audit.OBJECT_SCHEMA,
        audit.OBJECT_NAME,
        audit.OBJECT_SIGNATURE,
        audit.OBJECT_FQN,
        audit.REWRITE_CLASSIFICATION,
        audit.OBJECT_DDL_HASH,
        closure.DEPENDENCY_DEPTH + 1,
        closure.DEPENDENCY_PATH
        || audit.OBJECT_FQN
        || '|'

    FROM DEPENDENCY_CLOSURE closure

    JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_DEPENDENCY_EDGE_V1 edge
      ON edge.EDGE_BATCH_ID =
         'PHASE14D3A_OBJECT_DEPENDENCY_EDGE_V1'
     AND edge.PARENT_OBJECT_FQN =
         closure.OBJECT_FQN

    JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1 audit
      ON audit.AUDIT_BATCH_ID =
         'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
     AND audit.OBJECT_FQN =
         edge.CHILD_OBJECT_FQN

    WHERE closure.DEPENDENCY_DEPTH < 20

      AND POSITION(
            '|' || audit.OBJECT_FQN || '|'
            IN closure.DEPENDENCY_PATH
          ) = 0
),
DEDUPED AS (
    SELECT
        *,
        ROW_NUMBER() OVER (
            PARTITION BY
                ROOT_OBJECT_FQN,
                OBJECT_FQN
            ORDER BY
                DEPENDENCY_DEPTH,
                DEPENDENCY_PATH
        ) AS ROW_PRIORITY
    FROM DEPENDENCY_CLOSURE
)
SELECT
    'PHASE14D3A_RUNTIME_DEPENDENCY_SCOPE_V1',
    ROOT_OBJECT_FQN,
    ROOT_USAGE,
    OBJECT_TYPE,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE,
    OBJECT_FQN,
    DEPENDENCY_DEPTH,
    DEPENDENCY_DEPTH = 0,
    REWRITE_CLASSIFICATION,

    CASE
        WHEN REWRITE_CLASSIFICATION =
             'ALREADY_PORTABLE'
            THEN 'NO_REWRITE_REQUIRED'

        WHEN REWRITE_CLASSIFICATION =
             'RELATIVE_NAMESPACE_VIEW_CANDIDATE'
            THEN 'PHASE_14D_3B_VIEW_SOURCE'

        WHEN REWRITE_CLASSIFICATION =
             'PROCEDURE_BODY_REWRITE_CANDIDATE'
            THEN 'PHASE_14D_3C_SQL_PROCEDURE_SOURCE'

        WHEN REWRITE_CLASSIFICATION =
             'MANUAL_DYNAMIC_SQL_REWRITE'
            THEN 'PHASE_14D_3D_PYTHON_DYNAMIC_SQL'

        WHEN REWRITE_CLASSIFICATION =
             'MANUAL_STAGE_CONTRACT_REVIEW'
            THEN 'PHASE_14D_3E_RFQ_STAGE_CONTRACT'

        WHEN REWRITE_CLASSIFICATION =
             'DEFER_TO_PHASE_14E'
            THEN 'PHASE_14E_MODEL_PORTABILITY'

        ELSE 'MANUAL_REVIEW'
    END,

    OBJECT_DDL_HASH,
    DEPENDENCY_PATH,
    CURRENT_USER(),
    CURRENT_TIMESTAMP()

FROM (
    SELECT
        deduped.*,
        audit.OBJECT_LANGUAGE
    FROM DEDUPED deduped
    LEFT JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1 audit
      ON audit.AUDIT_BATCH_ID =
         'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
     AND audit.OBJECT_FQN =
         deduped.OBJECT_FQN
    WHERE ROW_PRIORITY = 1
);


WITH DISTINCT_SCOPE AS (
    SELECT
        OBJECT_FQN,
        ANY_VALUE(OBJECT_TYPE) AS OBJECT_TYPE,
        ANY_VALUE(OBJECT_SCHEMA) AS OBJECT_SCHEMA,
        ANY_VALUE(OBJECT_NAME) AS OBJECT_NAME,
        ANY_VALUE(OBJECT_SIGNATURE) AS OBJECT_SIGNATURE,
        MIN(DEPENDENCY_DEPTH) AS MIN_DEPENDENCY_DEPTH,
        BOOLOR_AGG(DIRECT_ROOT_FLAG) AS DIRECT_ROOT_FLAG,
        ANY_VALUE(REWRITE_CLASSIFICATION)
            AS REWRITE_CLASSIFICATION,
        ANY_VALUE(REWRITE_WAVE)
            AS REWRITE_WAVE,
        ANY_VALUE(OBJECT_DDL_HASH)
            AS OBJECT_DDL_HASH
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_RUNTIME_DEPENDENCY_SCOPE_V1
    WHERE SCOPE_BATCH_ID =
          'PHASE14D3A_RUNTIME_DEPENDENCY_SCOPE_V1'
    GROUP BY OBJECT_FQN
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COUNT_IF(
                REWRITE_CLASSIFICATION =
                    'BLOCKED_TEMP_OBJECT'
            ) = 0
            AND COUNT_IF(
                REWRITE_CLASSIFICATION =
                    'MANUAL_WAREHOUSE_REVIEW'
            ) = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3A',

    'scope_batch_id',
        'PHASE14D3A_RUNTIME_DEPENDENCY_SCOPE_V1',

    'distinct_runtime_object_count',
        COUNT(*),

    'direct_root_count',
        COUNT_IF(
            DIRECT_ROOT_FLAG = TRUE
        ),

    'transitive_dependency_count',
        COUNT_IF(
            DIRECT_ROOT_FLAG = FALSE
        ),

    'already_portable_count',
        COUNT_IF(
            REWRITE_WAVE =
                'NO_REWRITE_REQUIRED'
        ),

    'view_source_candidate_count',
        COUNT_IF(
            REWRITE_WAVE =
                'PHASE_14D_3B_VIEW_SOURCE'
        ),

    'sql_procedure_source_candidate_count',
        COUNT_IF(
            REWRITE_WAVE =
                'PHASE_14D_3C_SQL_PROCEDURE_SOURCE'
        ),

    'python_dynamic_sql_candidate_count',
        COUNT_IF(
            REWRITE_WAVE =
                'PHASE_14D_3D_PYTHON_DYNAMIC_SQL'
        ),

    'rfq_stage_contract_count',
        COUNT_IF(
            REWRITE_WAVE =
                'PHASE_14D_3E_RFQ_STAGE_CONTRACT'
        ),

    'phase14e_model_object_count',
        COUNT_IF(
            REWRITE_WAVE =
                'PHASE_14E_MODEL_PORTABILITY'
        ),

    'blocked_temp_object_count',
        COUNT_IF(
            REWRITE_CLASSIFICATION =
                'BLOCKED_TEMP_OBJECT'
        ),

    'fixed_warehouse_review_count',
        COUNT_IF(
            REWRITE_CLASSIFICATION =
                'MANUAL_WAREHOUSE_REVIEW'
        ),

    'runtime_object_changed',
        FALSE,

    'procedure_body_changed',
        FALSE,

    'view_definition_changed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3A_RUNTIME_CLOSURE_SUMMARY

FROM DISTINCT_SCOPE;


WITH DISTINCT_SCOPE AS (
    SELECT
        OBJECT_FQN,
        ANY_VALUE(OBJECT_TYPE) AS OBJECT_TYPE,
        ANY_VALUE(OBJECT_SCHEMA) AS OBJECT_SCHEMA,
        ANY_VALUE(OBJECT_NAME) AS OBJECT_NAME,
        ANY_VALUE(OBJECT_SIGNATURE) AS OBJECT_SIGNATURE,
        MIN(DEPENDENCY_DEPTH) AS MIN_DEPENDENCY_DEPTH,
        BOOLOR_AGG(DIRECT_ROOT_FLAG) AS DIRECT_ROOT_FLAG,
        ANY_VALUE(REWRITE_CLASSIFICATION)
            AS REWRITE_CLASSIFICATION,
        ANY_VALUE(REWRITE_WAVE)
            AS REWRITE_WAVE,
        ANY_VALUE(OBJECT_DDL_HASH)
            AS OBJECT_DDL_HASH
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_RUNTIME_DEPENDENCY_SCOPE_V1
    WHERE SCOPE_BATCH_ID =
          'PHASE14D3A_RUNTIME_DEPENDENCY_SCOPE_V1'
    GROUP BY OBJECT_FQN
)
SELECT *
FROM DISTINCT_SCOPE
ORDER BY
    CASE REWRITE_WAVE
        WHEN 'PHASE_14D_3E_RFQ_STAGE_CONTRACT' THEN 1
        WHEN 'PHASE_14D_3D_PYTHON_DYNAMIC_SQL' THEN 2
        WHEN 'PHASE_14D_3C_SQL_PROCEDURE_SOURCE' THEN 3
        WHEN 'PHASE_14D_3B_VIEW_SOURCE' THEN 4
        WHEN 'PHASE_14E_MODEL_PORTABILITY' THEN 5
        WHEN 'NO_REWRITE_REQUIRED' THEN 6
        ELSE 7
    END,
    MIN_DEPENDENCY_DEPTH,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE;

-- PHASE 14D.3A HOTFIX
-- Replace both the FQN prefix and the Python DB_NAME constant.
-- __RUNTIME_DATABASE__ is a review placeholder, not executable code.

DELETE FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PORTABLE_SOURCE_CANDIDATE_V1
WHERE SOURCE_BATCH_ID =
      'PHASE14D3A_PORTABLE_SOURCE_CANDIDATE_V1';

INSERT INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PORTABLE_SOURCE_CANDIDATE_V1
(
    SOURCE_BATCH_ID,
    OBJECT_TYPE,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE,
    OBJECT_FQN,
    OBJECT_OWNER,
    OBJECT_LANGUAGE,
    REWRITE_CLASSIFICATION,
    REWRITE_WAVE,
    ORIGINAL_DDL,
    ORIGINAL_DDL_HASH,
    PORTABLE_SOURCE_CANDIDATE,
    PORTABLE_SOURCE_HASH,
    FIXED_DATABASE_REFERENCE_COUNT_BEFORE,
    FIXED_DATABASE_REFERENCE_COUNT_AFTER,
    DEPLOYMENT_READY_FLAG,
    REVIEW_NOTES,
    GENERATED_BY,
    GENERATED_AT
)
WITH DISTINCT_SCOPE AS (
    SELECT
        OBJECT_FQN,
        ANY_VALUE(REWRITE_WAVE) AS REWRITE_WAVE
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_RUNTIME_DEPENDENCY_SCOPE_V1
    WHERE SCOPE_BATCH_ID =
          'PHASE14D3A_RUNTIME_DEPENDENCY_SCOPE_V1'
    GROUP BY OBJECT_FQN
),
CANDIDATES AS (
    SELECT
        audit.*,
        scope.REWRITE_WAVE,
        REPLACE(
            REPLACE(
                audit.OBJECT_DDL,
                'KMAT_COST_MODEL_DB.',
                ''
            ),
            'KMAT_COST_MODEL_DB',
            '__RUNTIME_DATABASE__'
        ) AS PORTABLE_SOURCE_CANDIDATE
    FROM DISTINCT_SCOPE scope
    JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1 audit
      ON audit.AUDIT_BATCH_ID =
         'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
     AND audit.OBJECT_FQN = scope.OBJECT_FQN
    WHERE audit.FIXED_DATABASE_REFERENCE_COUNT > 0
)
SELECT
    'PHASE14D3A_PORTABLE_SOURCE_CANDIDATE_V1',
    OBJECT_TYPE,
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE,
    OBJECT_FQN,
    OBJECT_OWNER,
    OBJECT_LANGUAGE,
    REWRITE_CLASSIFICATION,
    REWRITE_WAVE,
    OBJECT_DDL,
    OBJECT_DDL_HASH,
    PORTABLE_SOURCE_CANDIDATE,
    HASH(PORTABLE_SOURCE_CANDIDATE),
    FIXED_DATABASE_REFERENCE_COUNT,
    REGEXP_COUNT(
        UPPER(PORTABLE_SOURCE_CANDIDATE),
        'KMAT_COST_MODEL_DB'
    ),
    FALSE,
    CASE
        WHEN REWRITE_WAVE =
             'PHASE_14D_3B_VIEW_SOURCE'
            THEN
                'Review view dependencies, COPY GRANTS, owner, '
                || 'security mode and dependency order.'
        WHEN REWRITE_WAVE =
             'PHASE_14D_3C_SQL_PROCEDURE_SOURCE'
            THEN
                'Review signature, return type, owner, grants, '
                || 'EXECUTE AS OWNER and nested calls.'
        WHEN REWRITE_WAVE =
             'PHASE_14D_3D_PYTHON_DYNAMIC_SQL'
            THEN
                'Blocked from deployment. __RUNTIME_DATABASE__ '
                || 'is a review placeholder. Rewrite dynamic SQL '
                || 'with controlled namespaces and bound values.'
        WHEN REWRITE_WAVE =
             'PHASE_14D_3E_RFQ_STAGE_CONTRACT'
            THEN
                'Blocked from deployment. Replace stage logic '
                || 'with the approved RFQ source contract.'
        ELSE 'Manual review required.'
    END,
    CURRENT_USER(),
    CURRENT_TIMESTAMP()
FROM CANDIDATES;

SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COUNT(*) > 0
            AND COUNT_IF(
                FIXED_DATABASE_REFERENCE_COUNT_AFTER > 0
            ) = 0
            AND COUNT_IF(
                DEPLOYMENT_READY_FLAG = TRUE
            ) = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),
    'phase', 'PHASE_14D_3A_HOTFIX',
    'candidate_object_count', COUNT(*),
    'view_candidate_count',
        COUNT_IF(OBJECT_TYPE = 'VIEW'),
    'procedure_candidate_count',
        COUNT_IF(OBJECT_TYPE = 'PROCEDURE'),
    'fixed_database_reference_count_before',
        SUM(FIXED_DATABASE_REFERENCE_COUNT_BEFORE),
    'fixed_database_reference_count_after',
        SUM(FIXED_DATABASE_REFERENCE_COUNT_AFTER),
    'runtime_placeholder_count',
        SUM(
            REGEXP_COUNT(
                PORTABLE_SOURCE_CANDIDATE,
                '__RUNTIME_DATABASE__'
            )
        ),
    'deployment_ready_count',
        COUNT_IF(DEPLOYMENT_READY_FLAG = TRUE),
    'runtime_object_changed', FALSE,
    'candidate_source_executed', FALSE
) AS PHASE14D3A_PORTABLE_SOURCE_SUMMARY
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PORTABLE_SOURCE_CANDIDATE_V1
WHERE SOURCE_BATCH_ID =
      'PHASE14D3A_PORTABLE_SOURCE_CANDIDATE_V1';

-- PHASE 14D.3A HOTFIX INTEGRITY GATE
-- Run the original baseline query after this file.

WITH ROOT_CHECK AS (
    SELECT
        COUNT(*) AS ROOT_COUNT,
        COUNT_IF(
            RUNTIME_REQUIRED_FLAG = TRUE
            AND OBJECT_EXISTS_FLAG = FALSE
        ) AS MISSING_REQUIRED_ROOT_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_RUNTIME_ROOT_SCOPE_V1
    WHERE SCOPE_BATCH_ID =
          'PHASE14D3A_RUNTIME_ROOT_SCOPE_V1'
),
EDGE_CHECK AS (
    SELECT
        COUNT(*) AS DEPENDENCY_EDGE_COUNT,
        COUNT_IF(
            PARENT_OBJECT_NAME =
                'RUN_KMAT_COST_SIMULATION_GOVERNED_V3'
            AND CHILD_OBJECT_NAME =
                'RUN_KMAT_COST_SIMULATION_GOVERNED_V2'
        )
        +
        COUNT_IF(
            PARENT_OBJECT_NAME =
                'RUN_KMAT_COST_SIMULATION_GOVERNED_V3'
            AND CHILD_OBJECT_NAME =
                'RESOLVE_KMAT_COST_FACTOR_HIERARCHY_V1'
        )
        +
        COUNT_IF(
            PARENT_OBJECT_NAME =
                'RUN_CORTEX_RFQ_QUOTE_PIPELINE'
            AND CHILD_OBJECT_NAME =
                'RUN_CORTEX_BMCS_ASSESSMENT'
        )
        +
        COUNT_IF(
            PARENT_OBJECT_NAME =
                'RUN_CORTEX_RFQ_QUOTE_PIPELINE'
            AND CHILD_OBJECT_NAME =
                'PREPARE_RFQ_SIMULATION_INPUTS'
        )
        +
        COUNT_IF(
            PARENT_OBJECT_NAME =
                'RUN_CORTEX_RFQ_QUOTE_PIPELINE'
            AND CHILD_OBJECT_NAME =
                'RUN_KMAT_COST_SIMULATION'
        ) AS KNOWN_RUNTIME_EDGE_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_DEPENDENCY_EDGE_V1
    WHERE EDGE_BATCH_ID =
          'PHASE14D3A_OBJECT_DEPENDENCY_EDGE_V1'
),
SCOPE_CHECK AS (
    SELECT
        COUNT(DISTINCT OBJECT_FQN)
            AS DISTINCT_SCOPE_OBJECT_COUNT,
        COUNT_IF(
            OBJECT_DDL_HASH IS NULL
        ) AS NULL_SCOPE_HASH_COUNT,
        COUNT_IF(
            DEPENDENCY_DEPTH > 0
        ) AS TRANSITIVE_SCOPE_ROW_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_RUNTIME_DEPENDENCY_SCOPE_V1
    WHERE SCOPE_BATCH_ID =
          'PHASE14D3A_RUNTIME_DEPENDENCY_SCOPE_V1'
),
SOURCE_CHECK AS (
    SELECT
        COUNT(*) AS SOURCE_CANDIDATE_COUNT,
        COUNT_IF(
            FIXED_DATABASE_REFERENCE_COUNT_AFTER > 0
        ) AS RESIDUAL_FIXED_DATABASE_CANDIDATE_COUNT,
        COUNT_IF(
            DEPLOYMENT_READY_FLAG = TRUE
        ) AS DEPLOYMENT_READY_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_PORTABLE_SOURCE_CANDIDATE_V1
    WHERE SOURCE_BATCH_ID =
          'PHASE14D3A_PORTABLE_SOURCE_CANDIDATE_V1'
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            ROOT_CHECK.MISSING_REQUIRED_ROOT_COUNT = 0
            AND EDGE_CHECK.DEPENDENCY_EDGE_COUNT > 0
            AND EDGE_CHECK.KNOWN_RUNTIME_EDGE_COUNT >= 5
            AND SCOPE_CHECK.NULL_SCOPE_HASH_COUNT = 0
            AND SCOPE_CHECK.TRANSITIVE_SCOPE_ROW_COUNT > 0
            AND SOURCE_CHECK
                .RESIDUAL_FIXED_DATABASE_CANDIDATE_COUNT = 0
            AND SOURCE_CHECK.DEPLOYMENT_READY_COUNT = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),
    'phase', 'PHASE_14D_3A_HOTFIX',
    'root_count', ROOT_CHECK.ROOT_COUNT,
    'missing_required_root_count',
        ROOT_CHECK.MISSING_REQUIRED_ROOT_COUNT,
    'dependency_edge_count',
        EDGE_CHECK.DEPENDENCY_EDGE_COUNT,
    'known_runtime_edge_count',
        EDGE_CHECK.KNOWN_RUNTIME_EDGE_COUNT,
    'distinct_scope_object_count',
        SCOPE_CHECK.DISTINCT_SCOPE_OBJECT_COUNT,
    'transitive_scope_row_count',
        SCOPE_CHECK.TRANSITIVE_SCOPE_ROW_COUNT,
    'null_scope_hash_count',
        SCOPE_CHECK.NULL_SCOPE_HASH_COUNT,
    'source_candidate_count',
        SOURCE_CHECK.SOURCE_CANDIDATE_COUNT,
    'residual_fixed_database_candidate_count',
        SOURCE_CHECK
            .RESIDUAL_FIXED_DATABASE_CANDIDATE_COUNT,
    'deployment_ready_count',
        SOURCE_CHECK.DEPLOYMENT_READY_COUNT,
    'runtime_object_changed', FALSE,
    'procedure_body_changed', FALSE,
    'view_definition_changed', FALSE,
    'candidate_source_executed', FALSE,
    'official_cost_changed', FALSE,
    'ml_authority_changed', FALSE,
    'native_app_package_created', FALSE
) AS PHASE14D3A_INTEGRITY_VERIFICATION
FROM ROOT_CHECK
CROSS JOIN EDGE_CHECK
CROSS JOIN SCOPE_CHECK
CROSS JOIN SOURCE_CHECK;

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

-- ============================================================
-- PHASE 14D.3A — INTEGRITY AND GOLDEN BASELINE
-- ============================================================

WITH ROOT_CHECK AS (
    SELECT
        COUNT(*) AS ROOT_COUNT,
        COUNT_IF(
            RUNTIME_REQUIRED_FLAG = TRUE
            AND OBJECT_EXISTS_FLAG = FALSE
        ) AS MISSING_REQUIRED_ROOT_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_RUNTIME_ROOT_SCOPE_V1
    WHERE SCOPE_BATCH_ID =
          'PHASE14D3A_RUNTIME_ROOT_SCOPE_V1'
),
SCOPE_CHECK AS (
    SELECT
        COUNT(DISTINCT OBJECT_FQN)
            AS DISTINCT_SCOPE_OBJECT_COUNT,
        COUNT_IF(
            OBJECT_DDL_HASH IS NULL
        ) AS NULL_SCOPE_HASH_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_RUNTIME_DEPENDENCY_SCOPE_V1
    WHERE SCOPE_BATCH_ID =
          'PHASE14D3A_RUNTIME_DEPENDENCY_SCOPE_V1'
),
SOURCE_CHECK AS (
    SELECT
        COUNT(*) AS SOURCE_CANDIDATE_COUNT,
        COUNT_IF(
            FIXED_DATABASE_REFERENCE_COUNT_AFTER > 0
        ) AS RESIDUAL_FIXED_DATABASE_CANDIDATE_COUNT,
        COUNT_IF(
            DEPLOYMENT_READY_FLAG = TRUE
        ) AS DEPLOYMENT_READY_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_PORTABLE_SOURCE_CANDIDATE_V1
    WHERE SOURCE_BATCH_ID =
          'PHASE14D3A_PORTABLE_SOURCE_CANDIDATE_V1'
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            ROOT_CHECK.MISSING_REQUIRED_ROOT_COUNT = 0
            AND SCOPE_CHECK.NULL_SCOPE_HASH_COUNT = 0
            AND SOURCE_CHECK
                .RESIDUAL_FIXED_DATABASE_CANDIDATE_COUNT = 0
            AND SOURCE_CHECK.DEPLOYMENT_READY_COUNT = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3A',

    'root_count',
        ROOT_CHECK.ROOT_COUNT,

    'missing_required_root_count',
        ROOT_CHECK.MISSING_REQUIRED_ROOT_COUNT,

    'distinct_scope_object_count',
        SCOPE_CHECK.DISTINCT_SCOPE_OBJECT_COUNT,

    'null_scope_hash_count',
        SCOPE_CHECK.NULL_SCOPE_HASH_COUNT,

    'source_candidate_count',
        SOURCE_CHECK.SOURCE_CANDIDATE_COUNT,

    'residual_fixed_database_candidate_count',
        SOURCE_CHECK
            .RESIDUAL_FIXED_DATABASE_CANDIDATE_COUNT,

    'deployment_ready_count',
        SOURCE_CHECK.DEPLOYMENT_READY_COUNT,

    'runtime_object_changed',
        FALSE,

    'procedure_body_changed',
        FALSE,

    'view_definition_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'ml_authority_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3A_INTEGRITY_VERIFICATION

FROM ROOT_CHECK
CROSS JOIN SCOPE_CHECK
CROSS JOIN SOURCE_CHECK;


WITH baseline AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_BASELINE_V1
    WHERE BASELINE_ID =
          'PHASE14A_SIM_001_BASELINE_V1'
),
current_state AS (
    SELECT
        s.SIMULATION_ID,

        HASH(
            s.MATERIAL_COST_USD,
            s.LABOR_COST_USD,
            s.MACHINE_COST_USD,
            s.OVERHEAD_COST_USD,
            s.TOTAL_CONFIGURED_COST_USD,
            s.FLOOR_PRICE_USD,
            s.TARGET_PRICE_USD,
            s.CEILING_PRICE_USD,
            s.BASELINE_TOTAL_COST_USD,
            s.RISK_ADJUSTED_TOTAL_COST_USD,
            s.TOTAL_RISK_UPLIFT_USD,
            s.TOTAL_RISK_UPLIFT_PCT,
            s.CSS_SCORE,
            s.SCRAP_RATE_APPLIED,
            s.AVG_WEIGHTED_FMIS,
            s.MAX_TDS_FACTOR,
            s.BOM_MATCH_CONFIDENCE_SCORE,
            s.BMCS_REVIEW_STATUS,
            s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
            s.QUOTE_TRUST_STATUS,
            h.RESOLVED_SCRAP_RATE,
            h.CSS_RESOLVED_SOURCE,
            h.RESOLVED_FMIS_MULTIPLIER,
            h.FMIS_RESOLVED_SOURCE,
            h.RESOLVED_TDS_FACTOR,
            h.TDS_RESOLVED_SOURCE,
            h.RESOLVED_BMCS_STATUS,
            h.SAFETY_GATE_PASS_FLAG,
            h.COST_ENGINE_CONSUMPTION_ALLOWED_FLAG,
            h.OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG
        ) AS SNAPSHOT_HASH,

        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS ACTIVE_POLICY_COUNT,

        (
            SELECT COUNT_IF(
                DEPLOYMENT_MODE = 'SHADOW'
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS SHADOW_POLICY_COUNT,

        (
            SELECT COALESCE(
                COUNT_IF(
                    AUTO_USE_ALLOWED_FLAG = TRUE
                    OR OFFICIAL_COST_IMPACT_ALLOWED_FLAG = TRUE
                    OR BUSINESS_DECISION_ALLOWED_FLAG = TRUE
                ),
                0
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS POLICY_AUTHORITY_ENABLED_COUNT,

        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .ML_RUNTIME_AUTHORITY_REGISTRY_V1
            WHERE UPPER(AUTHORITY_STATUS) = 'ENABLED'
        ) AS ENABLED_RUNTIME_AUTHORITY_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_OUTPUT
            .KMAT_CONFIGURED_COST_SUMMARY s

    LEFT JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .VW_KMAT_PHASE10B_HIERARCHY_V1 h
        ON s.SIMULATION_ID = h.SIMULATION_ID

    WHERE s.SIMULATION_ID = 'SIM_001'

    QUALIFY ROW_NUMBER() OVER (
        PARTITION BY s.SIMULATION_ID
        ORDER BY s.CALCULATED_AT DESC
    ) = 1
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            baseline.SNAPSHOT_HASH =
                current_state.SNAPSHOT_HASH
            AND current_state
                .POLICY_AUTHORITY_ENABLED_COUNT = 0
            AND current_state
                .ENABLED_RUNTIME_AUTHORITY_COUNT = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3A',

    'baseline_id',
        baseline.BASELINE_ID,

    'simulation_id',
        baseline.SIMULATION_ID,

    'baseline_snapshot_hash',
        baseline.SNAPSHOT_HASH,

    'current_snapshot_hash',
        current_state.SNAPSHOT_HASH,

    'cost_and_governance_snapshot_match',
        baseline.SNAPSHOT_HASH =
        current_state.SNAPSHOT_HASH,

    'active_policy_count',
        current_state.ACTIVE_POLICY_COUNT,

    'shadow_policy_count',
        current_state.SHADOW_POLICY_COUNT,

    'policy_authority_enabled_count',
        current_state
            .POLICY_AUTHORITY_ENABLED_COUNT,

    'enabled_runtime_authority_count',
        current_state
            .ENABLED_RUNTIME_AUTHORITY_COUNT,

    'official_cost_changed',
        baseline.SNAPSHOT_HASH <>
        current_state.SNAPSHOT_HASH,

    'runtime_object_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'ml_authority_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3A_BASELINE_VERIFICATION

FROM baseline
CROSS JOIN current_state;

