WITH TARGETS AS (
    SELECT * FROM VALUES
        ('VW_KMAT_COST_FEEDBACK_DETAIL_V1', 'SYSADMIN', FALSE, 9005646585985175177),
        ('VW_KMAT_MODEL_FEEDBACK_DETAIL_V1', 'SYSADMIN', FALSE, 4824884542450775446),
        ('VW_KMAT_MONITORING_DOMAIN_SUMMARY_V1', 'SYSADMIN', FALSE, 5542945655262173490),
        ('VW_KMAT_MONITORING_OPERATIONAL_SUMMARY_V1', 'SYSADMIN', FALSE, -8041017097107196594),
        ('VW_KMAT_PHASE11A_MONITORING_DASHBOARD_V1', 'SYSADMIN', FALSE, -7542759719762926847),
        ('VW_KMAT_PHASE13A_RUNTIME_AUTHORITY_V1', 'SYSADMIN', FALSE, -7464515609872115832),
        ('VW_KMAT_PHASE13B_SECURITY_DASHBOARD_V1', 'KMAT_GOVERNANCE_DATA_OWNER_ROLE', TRUE, 3136737619057372411),
        ('VW_KMAT_STREAMLIT_RUNTIME_INPUT_V1', 'KMAT_GOVERNANCE_DATA_OWNER_ROLE', FALSE, 2634764660994638280),
        ('VW_ML_DECISION_WITH_APPROVED_OVERRIDE_V2', 'SYSADMIN', FALSE, 2840366902169611847),
        ('VW_ML_POLICY_VERSION_SEAL_INTEGRITY_V1', 'SYSADMIN', FALSE, 8900289695937012488),
        ('VW_ML_RUNTIME_DECISION_CURRENT_V1', 'SYSADMIN', FALSE, -7417445906172214070)
    AS target(
        VIEW_NAME,
        EXPECTED_OWNER,
        EXPECTED_SECURE_FLAG,
        EXPECTED_PHASE14D2_DDL_HASH
    )
),
CURRENT_VIEWS AS (
    SELECT
        TABLE_NAME AS VIEW_NAME,
        TABLE_OWNER AS CURRENT_OWNER,
        IFF(
            UPPER(COALESCE(IS_SECURE, 'NO')) = 'YES',
            TRUE,
            FALSE
        ) AS CURRENT_SECURE_FLAG,

        HASH(
            COALESCE(VIEW_DEFINITION, '')
        ) AS CURRENT_DDL_HASH

    FROM
        KMAT_COST_MODEL_DB.INFORMATION_SCHEMA.VIEWS

    WHERE TABLE_SCHEMA = 'CORE_ML'
),
CANDIDATES AS (
    SELECT
        OBJECT_NAME AS VIEW_NAME,
        PORTABLE_SOURCE_HASH
            AS CANDIDATE_SOURCE_HASH,
        FIXED_DATABASE_REFERENCE_COUNT_AFTER
            AS CANDIDATE_FIXED_DATABASE_COUNT,
        REGEXP_COUNT(
            PORTABLE_SOURCE_CANDIDATE,
            '__RUNTIME_DATABASE__'
        ) AS CANDIDATE_RUNTIME_PLACEHOLDER_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_PORTABLE_SOURCE_CANDIDATE_V1

    WHERE SOURCE_BATCH_ID =
          'PHASE14D3A_PORTABLE_SOURCE_CANDIDATE_V1'
      AND OBJECT_TYPE = 'VIEW'
      AND REWRITE_WAVE =
          'PHASE_14D_3B_VIEW_SOURCE'
)
SELECT
    'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1',
    'KMAT_COST_MODEL_DB',
    'CORE_ML',
    target.VIEW_NAME,
    target.EXPECTED_OWNER,
    target.EXPECTED_SECURE_FLAG,
    target.EXPECTED_PHASE14D2_DDL_HASH,
    current_view.CURRENT_OWNER,
    current_view.CURRENT_SECURE_FLAG,
    current_view.CURRENT_DDL_HASH,
    candidate.CANDIDATE_SOURCE_HASH,
    candidate.CANDIDATE_FIXED_DATABASE_COUNT,
    candidate.CANDIDATE_RUNTIME_PLACEHOLDER_COUNT,

    current_view.VIEW_NAME IS NOT NULL,

    COALESCE(
        current_view.CURRENT_DDL_HASH =
            target.EXPECTED_PHASE14D2_DDL_HASH,
        FALSE
    ),

    COALESCE(
        current_view.CURRENT_OWNER =
            target.EXPECTED_OWNER,
        FALSE
    ),

    COALESCE(
        current_view.CURRENT_SECURE_FLAG =
            target.EXPECTED_SECURE_FLAG,
        FALSE
    ),

    candidate.VIEW_NAME IS NOT NULL,

    COALESCE(
        candidate.CANDIDATE_FIXED_DATABASE_COUNT = 0
        AND candidate
            .CANDIDATE_RUNTIME_PLACEHOLDER_COUNT = 0,
        FALSE
    ),

    CASE
        WHEN current_view.VIEW_NAME IS NULL
            THEN 'MISSING_VIEW'

        WHEN current_view.CURRENT_DDL_HASH <>
             target.EXPECTED_PHASE14D2_DDL_HASH
            THEN 'DDL_DRIFT_DETECTED'

        WHEN current_view.CURRENT_OWNER <>
             target.EXPECTED_OWNER
            THEN 'OWNER_MISMATCH'

        WHEN current_view.CURRENT_SECURE_FLAG <>
             target.EXPECTED_SECURE_FLAG
            THEN 'SECURE_FLAG_MISMATCH'

        WHEN candidate.VIEW_NAME IS NULL
            THEN 'MISSING_PORTABLE_CANDIDATE'

        WHEN candidate
             .CANDIDATE_FIXED_DATABASE_COUNT > 0
            THEN 'FIXED_DATABASE_REMAINS'

        WHEN candidate
             .CANDIDATE_RUNTIME_PLACEHOLDER_COUNT > 0
            THEN 'RUNTIME_PLACEHOLDER_REMAINS'

        ELSE 'READY_FOR_DEPENDENCY_GATE'
    END,

    CURRENT_USER(),
    CURRENT_TIMESTAMP()

FROM TARGETS target

LEFT JOIN CURRENT_VIEWS current_view
    ON target.VIEW_NAME =
       current_view.VIEW_NAME

LEFT JOIN CANDIDATES candidate
    ON target.VIEW_NAME =
       candidate.VIEW_NAME;


INSERT INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_COLUMN_SNAPSHOT_V1
(
    PLAN_BATCH_ID,
    VIEW_DATABASE,
    VIEW_SCHEMA,
    VIEW_NAME,
    ORDINAL_POSITION,
    COLUMN_NAME,
    DATA_TYPE,
    IS_NULLABLE,
    CHARACTER_MAXIMUM_LENGTH,
    NUMERIC_PRECISION,
    NUMERIC_SCALE,
    COLUMN_DEFAULT,
    CAPTURED_BY,
    CAPTURED_AT
)
SELECT
    'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1',
    column_info.TABLE_CATALOG,
    column_info.TABLE_SCHEMA,
    column_info.TABLE_NAME,
    column_info.ORDINAL_POSITION,
    column_info.COLUMN_NAME,
    column_info.DATA_TYPE,
    column_info.IS_NULLABLE,
    column_info.CHARACTER_MAXIMUM_LENGTH,
    column_info.NUMERIC_PRECISION,
    column_info.NUMERIC_SCALE,
    column_info.COLUMN_DEFAULT,
    CURRENT_USER(),
    CURRENT_TIMESTAMP()

FROM
    KMAT_COST_MODEL_DB.INFORMATION_SCHEMA.COLUMNS
        column_info

JOIN
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_REWRITE_TARGET_V1 target
  ON target.PLAN_BATCH_ID =
     'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'
 AND target.VIEW_DATABASE =
     column_info.TABLE_CATALOG
 AND target.VIEW_SCHEMA =
     column_info.TABLE_SCHEMA
 AND target.VIEW_NAME =
     column_info.TABLE_NAME;


INSERT INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_GRANT_SNAPSHOT_V1
(
    PLAN_BATCH_ID,
    VIEW_DATABASE,
    VIEW_SCHEMA,
    VIEW_NAME,
    GRANTOR,
    GRANTEE,
    PRIVILEGE_TYPE,
    IS_GRANTABLE,
    CAPTURED_BY,
    CAPTURED_AT
)
SELECT
    'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1',
    grant_info.TABLE_CATALOG,
    grant_info.TABLE_SCHEMA,
    grant_info.TABLE_NAME,
    grant_info.GRANTOR,
    grant_info.GRANTEE,
    grant_info.PRIVILEGE_TYPE,
    grant_info.IS_GRANTABLE,
    CURRENT_USER(),
    CURRENT_TIMESTAMP()

FROM
    KMAT_COST_MODEL_DB.INFORMATION_SCHEMA.TABLE_PRIVILEGES
        grant_info

JOIN
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_REWRITE_TARGET_V1 target
  ON target.PLAN_BATCH_ID =
     'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'
 AND target.VIEW_DATABASE =
     grant_info.TABLE_CATALOG
 AND target.VIEW_SCHEMA =
     grant_info.TABLE_SCHEMA
 AND target.VIEW_NAME =
     grant_info.TABLE_NAME;


SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COUNT(*) = 11
            AND COUNT_IF(
                PREFLIGHT_STATUS =
                    'READY_FOR_DEPENDENCY_GATE'
            ) = 11,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3B_1',

    'plan_batch_id',
        'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1',

    'target_view_count',
        COUNT(*),

    'existing_view_count',
        COUNT_IF(
            VIEW_EXISTS_FLAG = TRUE
        ),

    'ddl_hash_match_count',
        COUNT_IF(
            DDL_HASH_MATCH_FLAG = TRUE
        ),

    'owner_match_count',
        COUNT_IF(
            OWNER_MATCH_FLAG = TRUE
        ),

    'secure_flag_match_count',
        COUNT_IF(
            SECURE_FLAG_MATCH_FLAG = TRUE
        ),

    'candidate_available_count',
        COUNT_IF(
            CANDIDATE_AVAILABLE_FLAG = TRUE
        ),

    'candidate_clean_count',
        COUNT_IF(
            CANDIDATE_CLEAN_FLAG = TRUE
        ),

    'column_snapshot_count',
        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .NATIVE_COMPAT_VIEW_COLUMN_SNAPSHOT_V1
            WHERE PLAN_BATCH_ID =
                  'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'
        ),

    'grant_snapshot_count',
        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .NATIVE_COMPAT_VIEW_GRANT_SNAPSHOT_V1
            WHERE PLAN_BATCH_ID =
                  'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'
        ),

    'view_definition_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3B1_VIEW_METADATA_SUMMARY

FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_REWRITE_TARGET_V1

WHERE PLAN_BATCH_ID =
      'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1';


SELECT
    VIEW_NAME,
    EXPECTED_OWNER,
    CURRENT_OWNER,
    EXPECTED_SECURE_FLAG,
    CURRENT_SECURE_FLAG,
    EXPECTED_PHASE14D2_DDL_HASH,
    CURRENT_DDL_HASH,
    CANDIDATE_SOURCE_HASH,
    DDL_HASH_MATCH_FLAG,
    OWNER_MATCH_FLAG,
    SECURE_FLAG_MATCH_FLAG,
    CANDIDATE_AVAILABLE_FLAG,
    CANDIDATE_CLEAN_FLAG,
    PREFLIGHT_STATUS
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_REWRITE_TARGET_V1
WHERE PLAN_BATCH_ID =
      'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'
ORDER BY VIEW_NAME;

-- ============================================================
-- PHASE 14D.3B.1 — VIEW DEPENDENCY AND DEPLOYMENT ORDER
--
-- Calculates the replacement order for the 11 candidate views.
-- Child views are ordered before parent views.
--
-- No candidate source is executed.
-- ============================================================

CREATE TABLE IF NOT EXISTS
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_REWRITE_ORDER_V1 (
            PLAN_BATCH_ID VARCHAR NOT NULL,
            VIEW_SCHEMA VARCHAR NOT NULL,
            VIEW_NAME VARCHAR NOT NULL,
            VIEW_FQN VARCHAR NOT NULL,
            DEPENDENCY_LEVEL NUMBER NOT NULL,
            INTERNAL_TARGET_DEPENDENCY_COUNT NUMBER NOT NULL,
            EXTERNAL_SCOPE_DEPENDENCY_COUNT NUMBER NOT NULL,
            CYCLE_DETECTED_FLAG BOOLEAN NOT NULL,
            APPLY_SEQUENCE NUMBER NOT NULL,
            OWNER_ROLE VARCHAR NOT NULL,
            SECURE_FLAG BOOLEAN NOT NULL,
            ORIGINAL_DDL_HASH NUMBER NOT NULL,
            CANDIDATE_SOURCE_HASH NUMBER NOT NULL,
            PLAN_STATUS VARCHAR NOT NULL,
            GENERATED_BY VARCHAR NOT NULL,
            GENERATED_AT TIMESTAMP_NTZ NOT NULL
        );

DELETE FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_REWRITE_ORDER_V1
WHERE PLAN_BATCH_ID =
      'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1';


INSERT INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_REWRITE_ORDER_V1
(
    PLAN_BATCH_ID,
    VIEW_SCHEMA,
    VIEW_NAME,
    VIEW_FQN,
    DEPENDENCY_LEVEL,
    INTERNAL_TARGET_DEPENDENCY_COUNT,
    EXTERNAL_SCOPE_DEPENDENCY_COUNT,
    CYCLE_DETECTED_FLAG,
    APPLY_SEQUENCE,
    OWNER_ROLE,
    SECURE_FLAG,
    ORIGINAL_DDL_HASH,
    CANDIDATE_SOURCE_HASH,
    PLAN_STATUS,
    GENERATED_BY,
    GENERATED_AT
)
WITH RECURSIVE
TARGETS AS (
    SELECT
        VIEW_SCHEMA,
        VIEW_NAME,
        VIEW_DATABASE
        || '.'
        || VIEW_SCHEMA
        || '.'
        || VIEW_NAME AS VIEW_FQN,
        CURRENT_OWNER AS OWNER_ROLE,
        CURRENT_SECURE_FLAG AS SECURE_FLAG,
        CURRENT_DDL_HASH AS ORIGINAL_DDL_HASH,
        CANDIDATE_SOURCE_HASH

    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_VIEW_REWRITE_TARGET_V1

    WHERE PLAN_BATCH_ID =
          'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'
),
TARGET_EDGES AS (
    SELECT DISTINCT
        parent.VIEW_FQN AS PARENT_FQN,
        child.VIEW_FQN AS CHILD_FQN

    FROM TARGETS parent

    JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_DEPENDENCY_EDGE_V1 edge
      ON edge.EDGE_BATCH_ID =
         'PHASE14D3A_OBJECT_DEPENDENCY_EDGE_V1'
     AND edge.PARENT_OBJECT_FQN =
         parent.VIEW_FQN

    JOIN TARGETS child
      ON child.VIEW_FQN =
         edge.CHILD_OBJECT_FQN
),
PATHS (
    ROOT_FQN,
    CURRENT_FQN,
    DEPTH,
    PATH_TEXT,
    CYCLE_DETECTED_FLAG
) AS (
    SELECT
        VIEW_FQN,
        VIEW_FQN,
        0,
        '|' || VIEW_FQN || '|',
        FALSE
    FROM TARGETS

    UNION ALL

    SELECT
        path.ROOT_FQN,
        edge.CHILD_FQN,
        path.DEPTH + 1,
        path.PATH_TEXT
        || edge.CHILD_FQN
        || '|',

        POSITION(
            '|' || edge.CHILD_FQN || '|'
            IN path.PATH_TEXT
        ) > 0

    FROM PATHS path

    JOIN TARGET_EDGES edge
      ON edge.PARENT_FQN =
         path.CURRENT_FQN

    WHERE path.DEPTH < 20
      AND path.CYCLE_DETECTED_FLAG = FALSE
),
LEVELS AS (
    SELECT
        target.VIEW_SCHEMA,
        target.VIEW_NAME,
        target.VIEW_FQN,
        target.OWNER_ROLE,
        target.SECURE_FLAG,
        target.ORIGINAL_DDL_HASH,
        target.CANDIDATE_SOURCE_HASH,

        COALESCE(
            MAX(
                IFF(
                    path.CYCLE_DETECTED_FLAG = FALSE,
                    path.DEPTH,
                    NULL
                )
            ),
            0
        ) AS DEPENDENCY_LEVEL,

        COUNT(
            DISTINCT target_edge.CHILD_FQN
        ) AS INTERNAL_TARGET_DEPENDENCY_COUNT,

        COUNT(
            DISTINCT IFF(
                external_edge.CHILD_OBJECT_FQN IS NOT NULL,
                external_edge.CHILD_OBJECT_FQN,
                NULL
            )
        ) AS EXTERNAL_SCOPE_DEPENDENCY_COUNT,

        COALESCE(
            BOOLOR_AGG(
                path.CYCLE_DETECTED_FLAG
            ),
            FALSE
        ) AS CYCLE_DETECTED_FLAG

    FROM TARGETS target

    LEFT JOIN PATHS path
      ON path.ROOT_FQN =
         target.VIEW_FQN

    LEFT JOIN TARGET_EDGES target_edge
      ON target_edge.PARENT_FQN =
         target.VIEW_FQN

    LEFT JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_DEPENDENCY_EDGE_V1
            external_edge
      ON external_edge.EDGE_BATCH_ID =
         'PHASE14D3A_OBJECT_DEPENDENCY_EDGE_V1'
     AND external_edge.PARENT_OBJECT_FQN =
         target.VIEW_FQN
     AND external_edge.CHILD_OBJECT_FQN
         NOT IN (
            SELECT VIEW_FQN
            FROM TARGETS
         )

    GROUP BY
        target.VIEW_SCHEMA,
        target.VIEW_NAME,
        target.VIEW_FQN,
        target.OWNER_ROLE,
        target.SECURE_FLAG,
        target.ORIGINAL_DDL_HASH,
        target.CANDIDATE_SOURCE_HASH
),
ORDERED AS (
    SELECT
        *,
        ROW_NUMBER() OVER (
            ORDER BY
                DEPENDENCY_LEVEL,
                VIEW_SCHEMA,
                VIEW_NAME
        ) AS APPLY_SEQUENCE
    FROM LEVELS
)
SELECT
    'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1',
    VIEW_SCHEMA,
    VIEW_NAME,
    VIEW_FQN,
    DEPENDENCY_LEVEL,
    INTERNAL_TARGET_DEPENDENCY_COUNT,
    EXTERNAL_SCOPE_DEPENDENCY_COUNT,
    CYCLE_DETECTED_FLAG,
    APPLY_SEQUENCE,
    OWNER_ROLE,
    SECURE_FLAG,
    ORIGINAL_DDL_HASH,
    CANDIDATE_SOURCE_HASH,

    CASE
        WHEN CYCLE_DETECTED_FLAG = TRUE
            THEN 'BLOCKED_DEPENDENCY_CYCLE'

        WHEN ORIGINAL_DDL_HASH IS NULL
             OR CANDIDATE_SOURCE_HASH IS NULL
            THEN 'BLOCKED_MISSING_HASH'

        ELSE 'READY_FOR_VIEW_REWRITE_REVIEW'
    END,

    CURRENT_USER(),
    CURRENT_TIMESTAMP()

FROM ORDERED;


SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COUNT(*) = 11
            AND COUNT_IF(
                CYCLE_DETECTED_FLAG = TRUE
            ) = 0
            AND COUNT_IF(
                PLAN_STATUS =
                    'READY_FOR_VIEW_REWRITE_REVIEW'
            ) = 11,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3B_1',

    'plan_batch_id',
        'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1',

    'planned_view_count',
        COUNT(*),

    'secure_view_count',
        COUNT_IF(
            SECURE_FLAG = TRUE
        ),

    'cycle_detected_count',
        COUNT_IF(
            CYCLE_DETECTED_FLAG = TRUE
        ),

    'max_dependency_level',
        MAX(DEPENDENCY_LEVEL),

    'view_with_internal_target_dependencies_count',
        COUNT_IF(
            INTERNAL_TARGET_DEPENDENCY_COUNT > 0
        ),

    'view_with_external_scope_dependencies_count',
        COUNT_IF(
            EXTERNAL_SCOPE_DEPENDENCY_COUNT > 0
        ),

    'candidate_source_executed',
        FALSE,

    'view_definition_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3B1_DEPENDENCY_ORDER_SUMMARY

FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_REWRITE_ORDER_V1

WHERE PLAN_BATCH_ID =
      'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1';


SELECT
    APPLY_SEQUENCE,
    DEPENDENCY_LEVEL,
    VIEW_SCHEMA,
    VIEW_NAME,
    OWNER_ROLE,
    SECURE_FLAG,
    INTERNAL_TARGET_DEPENDENCY_COUNT,
    EXTERNAL_SCOPE_DEPENDENCY_COUNT,
    CYCLE_DETECTED_FLAG,
    ORIGINAL_DDL_HASH,
    CANDIDATE_SOURCE_HASH,
    PLAN_STATUS
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_REWRITE_ORDER_V1
WHERE PLAN_BATCH_ID =
      'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'
ORDER BY APPLY_SEQUENCE;

-- ============================================================
-- PHASE 14D.3B.1 — SOURCE AND CONTRACT REVIEW EXPORT
--
-- Read-only export for the exact 11 candidate views.
-- No source is executed.
-- ============================================================

SELECT
    rewrite_order.APPLY_SEQUENCE,
    rewrite_order.DEPENDENCY_LEVEL,

    candidate.OBJECT_SCHEMA,
    candidate.OBJECT_NAME,

    rewrite_order.OWNER_ROLE,
    rewrite_order.SECURE_FLAG,

    rewrite_order.INTERNAL_TARGET_DEPENDENCY_COUNT,
    rewrite_order.EXTERNAL_SCOPE_DEPENDENCY_COUNT,

    candidate.ORIGINAL_DDL_HASH,
    candidate.PORTABLE_SOURCE_HASH,

    candidate.FIXED_DATABASE_REFERENCE_COUNT_BEFORE,
    candidate.FIXED_DATABASE_REFERENCE_COUNT_AFTER,

    rewrite_order.PLAN_STATUS,
    candidate.REVIEW_NOTES,

    candidate.ORIGINAL_DDL,
    candidate.PORTABLE_SOURCE_CANDIDATE

FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_REWRITE_ORDER_V1
        rewrite_order

JOIN
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PORTABLE_SOURCE_CANDIDATE_V1
        candidate
  ON candidate.SOURCE_BATCH_ID =
     'PHASE14D3A_PORTABLE_SOURCE_CANDIDATE_V1'
 AND candidate.OBJECT_TYPE = 'VIEW'
 AND candidate.OBJECT_SCHEMA =
     rewrite_order.VIEW_SCHEMA
 AND candidate.OBJECT_NAME =
     rewrite_order.VIEW_NAME

WHERE rewrite_order.PLAN_BATCH_ID =
      'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'

ORDER BY rewrite_order.APPLY_SEQUENCE;


SELECT
    VIEW_NAME,
    COUNT(*) AS COLUMN_COUNT,
    HASH_AGG(
        HASH(
            ORDINAL_POSITION,
            COLUMN_NAME,
            DATA_TYPE,
            IS_NULLABLE,
            CHARACTER_MAXIMUM_LENGTH,
            NUMERIC_PRECISION,
            NUMERIC_SCALE,
            COLUMN_DEFAULT
        )
    ) AS COLUMN_CONTRACT_HASH
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_COLUMN_SNAPSHOT_V1
WHERE PLAN_BATCH_ID =
      'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'
GROUP BY VIEW_NAME
ORDER BY VIEW_NAME;


SELECT
    VIEW_NAME,
    GRANTEE,
    PRIVILEGE_TYPE,
    IS_GRANTABLE,
    GRANTOR
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_GRANT_SNAPSHOT_V1
WHERE PLAN_BATCH_ID =
      'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'
ORDER BY
    VIEW_NAME,
    GRANTEE,
    PRIVILEGE_TYPE;

-- ============================================================
-- PHASE 14D.3B.1 — FINAL GATE AND GOLDEN BASELINE
-- ============================================================

WITH METADATA AS (
    SELECT
        COUNT(*) AS TARGET_VIEW_COUNT,

        COUNT_IF(
            PREFLIGHT_STATUS =
                'READY_FOR_DEPENDENCY_GATE'
        ) AS READY_METADATA_COUNT,

        COUNT_IF(
            DDL_HASH_MATCH_FLAG = FALSE
        ) AS DDL_DRIFT_COUNT,

        COUNT_IF(
            OWNER_MATCH_FLAG = FALSE
        ) AS OWNER_MISMATCH_COUNT,

        COUNT_IF(
            SECURE_FLAG_MATCH_FLAG = FALSE
        ) AS SECURE_FLAG_MISMATCH_COUNT,

        COUNT_IF(
            CANDIDATE_CLEAN_FLAG = FALSE
        ) AS UNCLEAN_CANDIDATE_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_VIEW_REWRITE_TARGET_V1

    WHERE PLAN_BATCH_ID =
          'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'
),
DEPENDENCIES AS (
    SELECT
        COUNT(*) AS PLANNED_VIEW_COUNT,

        COUNT_IF(
            CYCLE_DETECTED_FLAG = TRUE
        ) AS CYCLE_DETECTED_COUNT,

        COUNT_IF(
            PLAN_STATUS <>
                'READY_FOR_VIEW_REWRITE_REVIEW'
        ) AS BLOCKED_PLAN_COUNT,

        MAX(DEPENDENCY_LEVEL)
            AS MAX_DEPENDENCY_LEVEL

    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_VIEW_REWRITE_ORDER_V1

    WHERE PLAN_BATCH_ID =
          'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'
),
CONTRACTS AS (
    SELECT
        COUNT(*) AS COLUMN_SNAPSHOT_COUNT,

        COUNT(DISTINCT VIEW_NAME)
            AS VIEW_WITH_COLUMN_SNAPSHOT_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_VIEW_COLUMN_SNAPSHOT_V1

    WHERE PLAN_BATCH_ID =
          'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'
),
GRANTS AS (
    SELECT
        COUNT(*) AS GRANT_SNAPSHOT_COUNT,

        COUNT(DISTINCT VIEW_NAME)
            AS VIEW_WITH_EXPLICIT_GRANT_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_VIEW_GRANT_SNAPSHOT_V1

    WHERE PLAN_BATCH_ID =
          'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            METADATA.TARGET_VIEW_COUNT = 11
            AND METADATA.READY_METADATA_COUNT = 11
            AND METADATA.DDL_DRIFT_COUNT = 0
            AND METADATA.OWNER_MISMATCH_COUNT = 0
            AND METADATA.SECURE_FLAG_MISMATCH_COUNT = 0
            AND METADATA.UNCLEAN_CANDIDATE_COUNT = 0
            AND DEPENDENCIES.PLANNED_VIEW_COUNT = 11
            AND DEPENDENCIES.CYCLE_DETECTED_COUNT = 0
            AND DEPENDENCIES.BLOCKED_PLAN_COUNT = 0
            AND CONTRACTS
                .VIEW_WITH_COLUMN_SNAPSHOT_COUNT = 11,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3B_1',

    'target_view_count',
        METADATA.TARGET_VIEW_COUNT,

    'ready_metadata_count',
        METADATA.READY_METADATA_COUNT,

    'ddl_drift_count',
        METADATA.DDL_DRIFT_COUNT,

    'owner_mismatch_count',
        METADATA.OWNER_MISMATCH_COUNT,

    'secure_flag_mismatch_count',
        METADATA.SECURE_FLAG_MISMATCH_COUNT,

    'unclean_candidate_count',
        METADATA.UNCLEAN_CANDIDATE_COUNT,

    'planned_view_count',
        DEPENDENCIES.PLANNED_VIEW_COUNT,

    'dependency_cycle_count',
        DEPENDENCIES.CYCLE_DETECTED_COUNT,

    'blocked_plan_count',
        DEPENDENCIES.BLOCKED_PLAN_COUNT,

    'max_dependency_level',
        DEPENDENCIES.MAX_DEPENDENCY_LEVEL,

    'column_snapshot_count',
        CONTRACTS.COLUMN_SNAPSHOT_COUNT,

    'view_with_column_snapshot_count',
        CONTRACTS
            .VIEW_WITH_COLUMN_SNAPSHOT_COUNT,

    'grant_snapshot_count',
        GRANTS.GRANT_SNAPSHOT_COUNT,

    'view_with_explicit_grant_count',
        GRANTS
            .VIEW_WITH_EXPLICIT_GRANT_COUNT,

    'candidate_source_executed',
        FALSE,

    'view_definition_changed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'ml_authority_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3B1_FINAL_GATE

FROM METADATA
CROSS JOIN DEPENDENCIES
CROSS JOIN CONTRACTS
CROSS JOIN GRANTS;


WITH baseline AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_BASELINE_V1
    WHERE BASELINE_ID =
          'PHASE14A_SIM_001_BASELINE_V1'
),
current_state AS (
    SELECT
        s.SIMULATION_ID,

        HASH(
            s.MATERIAL_COST_USD,
            s.LABOR_COST_USD,
            s.MACHINE_COST_USD,
            s.OVERHEAD_COST_USD,
            s.TOTAL_CONFIGURED_COST_USD,
            s.FLOOR_PRICE_USD,
            s.TARGET_PRICE_USD,
            s.CEILING_PRICE_USD,
            s.BASELINE_TOTAL_COST_USD,
            s.RISK_ADJUSTED_TOTAL_COST_USD,
            s.TOTAL_RISK_UPLIFT_USD,
            s.TOTAL_RISK_UPLIFT_PCT,
            s.CSS_SCORE,
            s.SCRAP_RATE_APPLIED,
            s.AVG_WEIGHTED_FMIS,
            s.MAX_TDS_FACTOR,
            s.BOM_MATCH_CONFIDENCE_SCORE,
            s.BMCS_REVIEW_STATUS,
            s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
            s.QUOTE_TRUST_STATUS,
            h.RESOLVED_SCRAP_RATE,
            h.CSS_RESOLVED_SOURCE,
            h.RESOLVED_FMIS_MULTIPLIER,
            h.FMIS_RESOLVED_SOURCE,
            h.RESOLVED_TDS_FACTOR,
            h.TDS_RESOLVED_SOURCE,
            h.RESOLVED_BMCS_STATUS,
            h.SAFETY_GATE_PASS_FLAG,
            h.COST_ENGINE_CONSUMPTION_ALLOWED_FLAG,
            h.OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG
        ) AS SNAPSHOT_HASH,

        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS ACTIVE_POLICY_COUNT,

        (
            SELECT COUNT_IF(
                DEPLOYMENT_MODE = 'SHADOW'
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS SHADOW_POLICY_COUNT,

        (
            SELECT COALESCE(
                COUNT_IF(
                    AUTO_USE_ALLOWED_FLAG = TRUE
                    OR OFFICIAL_COST_IMPACT_ALLOWED_FLAG = TRUE
                    OR BUSINESS_DECISION_ALLOWED_FLAG = TRUE
                ),
                0
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS POLICY_AUTHORITY_ENABLED_COUNT,

        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .ML_RUNTIME_AUTHORITY_REGISTRY_V1
            WHERE UPPER(AUTHORITY_STATUS) = 'ENABLED'
        ) AS ENABLED_RUNTIME_AUTHORITY_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_OUTPUT
            .KMAT_CONFIGURED_COST_SUMMARY s

    LEFT JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .VW_KMAT_PHASE10B_HIERARCHY_V1 h
        ON s.SIMULATION_ID = h.SIMULATION_ID

    WHERE s.SIMULATION_ID = 'SIM_001'

    QUALIFY ROW_NUMBER() OVER (
        PARTITION BY s.SIMULATION_ID
        ORDER BY s.CALCULATED_AT DESC
    ) = 1
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            baseline.SNAPSHOT_HASH =
                current_state.SNAPSHOT_HASH
            AND current_state
                .POLICY_AUTHORITY_ENABLED_COUNT = 0
            AND current_state
                .ENABLED_RUNTIME_AUTHORITY_COUNT = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3B_1',

    'baseline_id',
        baseline.BASELINE_ID,

    'simulation_id',
        baseline.SIMULATION_ID,

    'baseline_snapshot_hash',
        baseline.SNAPSHOT_HASH,

    'current_snapshot_hash',
        current_state.SNAPSHOT_HASH,

    'cost_and_governance_snapshot_match',
        baseline.SNAPSHOT_HASH =
        current_state.SNAPSHOT_HASH,

    'active_policy_count',
        current_state.ACTIVE_POLICY_COUNT,

    'shadow_policy_count',
        current_state.SHADOW_POLICY_COUNT,

    'policy_authority_enabled_count',
        current_state
            .POLICY_AUTHORITY_ENABLED_COUNT,

    'enabled_runtime_authority_count',
        current_state
            .ENABLED_RUNTIME_AUTHORITY_COUNT,

    'official_cost_changed',
        baseline.SNAPSHOT_HASH <>
        current_state.SNAPSHOT_HASH,

    'view_definition_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'ml_authority_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3B1_BASELINE_VERIFICATION

FROM baseline
CROSS JOIN current_state;

-- ============================================================
-- PHASE 14D.3B.1 HOTFIX — SECURE VIEW CONTRACT
--
-- The first metadata gate hardcoded only one secure view.
-- The deployed metadata reports four secure views.
--
-- This hotfix treats the frozen deployed DDL and current metadata
-- as the source of truth, then verifies that each portable source
-- candidate preserves the same SECURE / STANDARD view type.
--
-- No runtime view is changed.
-- No candidate source is executed.
-- ============================================================

ALTER TABLE IF EXISTS
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_REWRITE_TARGET_V1
ADD COLUMN IF NOT EXISTS
    CANDIDATE_SECURE_FLAG BOOLEAN;

ALTER TABLE IF EXISTS
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_REWRITE_TARGET_V1
ADD COLUMN IF NOT EXISTS
    SECURE_CONTRACT_MATCH_FLAG BOOLEAN;

ALTER TABLE IF EXISTS
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_REWRITE_TARGET_V1
ADD COLUMN IF NOT EXISTS
    SECURE_CONTRACT_SOURCE VARCHAR;


MERGE INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_REWRITE_TARGET_V1 target

USING (
    SELECT
        OBJECT_NAME AS VIEW_NAME,

        REGEXP_COUNT(
            UPPER(PORTABLE_SOURCE_CANDIDATE),
            'CREATE[[:space:]]+'
            || '(OR[[:space:]]+REPLACE[[:space:]]+)?'
            || 'SECURE[[:space:]]+VIEW'
        ) > 0 AS CANDIDATE_SECURE_FLAG

    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_PORTABLE_SOURCE_CANDIDATE_V1

    WHERE SOURCE_BATCH_ID =
          'PHASE14D3A_PORTABLE_SOURCE_CANDIDATE_V1'
      AND OBJECT_TYPE = 'VIEW'
      AND REWRITE_WAVE =
          'PHASE_14D_3B_VIEW_SOURCE'
) candidate

ON target.PLAN_BATCH_ID =
   'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'
AND target.VIEW_SCHEMA = 'CORE_ML'
AND target.VIEW_NAME = candidate.VIEW_NAME

WHEN MATCHED THEN UPDATE SET

    -- The current object is accepted only because its DDL hash
    -- already matches the frozen Phase 14D.2 audit.
    target.EXPECTED_SECURE_FLAG =
        target.CURRENT_SECURE_FLAG,

    target.CANDIDATE_SECURE_FLAG =
        candidate.CANDIDATE_SECURE_FLAG,

    target.SECURE_FLAG_MATCH_FLAG =
        (
            target.CURRENT_SECURE_FLAG =
            candidate.CANDIDATE_SECURE_FLAG
        ),

    target.SECURE_CONTRACT_MATCH_FLAG =
        (
            target.DDL_HASH_MATCH_FLAG = TRUE
            AND target.CURRENT_SECURE_FLAG =
                candidate.CANDIDATE_SECURE_FLAG
        ),

    target.SECURE_CONTRACT_SOURCE =
        'FROZEN_PHASE14D2_DDL'
        || '_PLUS_CURRENT_METADATA'
        || '_PLUS_PORTABLE_CANDIDATE',

    target.PREFLIGHT_STATUS =
        CASE
            WHEN target.VIEW_EXISTS_FLAG = FALSE
                THEN 'MISSING_VIEW'

            WHEN target.DDL_HASH_MATCH_FLAG = FALSE
                THEN 'DDL_DRIFT_DETECTED'

            WHEN target.OWNER_MATCH_FLAG = FALSE
                THEN 'OWNER_MISMATCH'

            WHEN target.CANDIDATE_AVAILABLE_FLAG = FALSE
                THEN 'MISSING_PORTABLE_CANDIDATE'

            WHEN target.CANDIDATE_CLEAN_FLAG = FALSE
                THEN 'UNCLEAN_PORTABLE_CANDIDATE'

            WHEN target.CURRENT_SECURE_FLAG <>
                 candidate.CANDIDATE_SECURE_FLAG
                THEN 'CANDIDATE_SECURE_FLAG_MISMATCH'

            ELSE 'READY_FOR_DEPENDENCY_GATE'
        END,

    target.CAPTURED_BY = CURRENT_USER(),
    target.CAPTURED_AT = CURRENT_TIMESTAMP();


SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COUNT(*) = 11
            AND COUNT_IF(
                PREFLIGHT_STATUS =
                    'READY_FOR_DEPENDENCY_GATE'
            ) = 11
            AND COUNT_IF(
                SECURE_CONTRACT_MATCH_FLAG = FALSE
                OR SECURE_CONTRACT_MATCH_FLAG IS NULL
            ) = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3B_1_HOTFIX',

    'plan_batch_id',
        'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1',

    'target_view_count',
        COUNT(*),

    'deployed_secure_view_count',
        COUNT_IF(
            CURRENT_SECURE_FLAG = TRUE
        ),

    'candidate_secure_view_count',
        COUNT_IF(
            CANDIDATE_SECURE_FLAG = TRUE
        ),

    'secure_contract_match_count',
        COUNT_IF(
            SECURE_CONTRACT_MATCH_FLAG = TRUE
        ),

    'secure_contract_mismatch_count',
        COUNT_IF(
            SECURE_CONTRACT_MATCH_FLAG = FALSE
            OR SECURE_CONTRACT_MATCH_FLAG IS NULL
        ),

    'ready_metadata_count',
        COUNT_IF(
            PREFLIGHT_STATUS =
                'READY_FOR_DEPENDENCY_GATE'
        ),

    'ddl_drift_count',
        COUNT_IF(
            DDL_HASH_MATCH_FLAG = FALSE
        ),

    'owner_mismatch_count',
        COUNT_IF(
            OWNER_MATCH_FLAG = FALSE
        ),

    'unclean_candidate_count',
        COUNT_IF(
            CANDIDATE_CLEAN_FLAG = FALSE
        ),

    'view_definition_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3B1_SECURE_CONTRACT_SUMMARY

FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_REWRITE_TARGET_V1

WHERE PLAN_BATCH_ID =
      'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1';


SELECT
    VIEW_NAME,
    CURRENT_OWNER,
    CURRENT_SECURE_FLAG,
    CANDIDATE_SECURE_FLAG,
    SECURE_CONTRACT_MATCH_FLAG,
    DDL_HASH_MATCH_FLAG,
    OWNER_MATCH_FLAG,
    CANDIDATE_AVAILABLE_FLAG,
    CANDIDATE_CLEAN_FLAG,
    PREFLIGHT_STATUS,
    SECURE_CONTRACT_SOURCE
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_REWRITE_TARGET_V1
WHERE PLAN_BATCH_ID =
      'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'
ORDER BY
    CURRENT_SECURE_FLAG DESC,
    VIEW_NAME;

-- ============================================================
-- PHASE 14D.3B.1 HOTFIX — REFRESH VIEW ORDER METADATA
--
-- Rebuilds the existing review-order table so the SECURE_FLAG
-- column reflects the corrected deployed secure-view contract.
--
-- No view definition is changed.
-- ============================================================

UPDATE
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_REWRITE_ORDER_V1 rewrite_order

SET
    SECURE_FLAG = target.CURRENT_SECURE_FLAG,
    OWNER_ROLE = target.CURRENT_OWNER,
    PLAN_STATUS =
        CASE
            WHEN target.PREFLIGHT_STATUS <>
                 'READY_FOR_DEPENDENCY_GATE'
                THEN 'BLOCKED_METADATA_PREFLIGHT'

            WHEN rewrite_order.CYCLE_DETECTED_FLAG = TRUE
                THEN 'BLOCKED_DEPENDENCY_CYCLE'

            WHEN rewrite_order.ORIGINAL_DDL_HASH IS NULL
                 OR rewrite_order.CANDIDATE_SOURCE_HASH IS NULL
                THEN 'BLOCKED_MISSING_HASH'

            ELSE 'READY_FOR_VIEW_REWRITE_REVIEW'
        END,

    GENERATED_BY = CURRENT_USER(),
    GENERATED_AT = CURRENT_TIMESTAMP()

FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_REWRITE_TARGET_V1 target

WHERE rewrite_order.PLAN_BATCH_ID =
      'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'

  AND target.PLAN_BATCH_ID =
      'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'

  AND rewrite_order.VIEW_SCHEMA =
      target.VIEW_SCHEMA

  AND rewrite_order.VIEW_NAME =
      target.VIEW_NAME;


SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COUNT(*) = 11
            AND COUNT_IF(
                PLAN_STATUS =
                    'READY_FOR_VIEW_REWRITE_REVIEW'
            ) = 11
            AND COUNT_IF(
                CYCLE_DETECTED_FLAG = TRUE
            ) = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3B_1_HOTFIX',

    'planned_view_count',
        COUNT(*),

    'secure_view_count',
        COUNT_IF(
            SECURE_FLAG = TRUE
        ),

    'standard_view_count',
        COUNT_IF(
            SECURE_FLAG = FALSE
        ),

    'cycle_detected_count',
        COUNT_IF(
            CYCLE_DETECTED_FLAG = TRUE
        ),

    'ready_plan_count',
        COUNT_IF(
            PLAN_STATUS =
                'READY_FOR_VIEW_REWRITE_REVIEW'
        ),

    'blocked_plan_count',
        COUNT_IF(
            PLAN_STATUS <>
                'READY_FOR_VIEW_REWRITE_REVIEW'
        ),

    'max_dependency_level',
        MAX(DEPENDENCY_LEVEL),

    'view_with_internal_target_dependencies_count',
        COUNT_IF(
            INTERNAL_TARGET_DEPENDENCY_COUNT > 0
        ),

    'view_with_external_scope_dependencies_count',
        COUNT_IF(
            EXTERNAL_SCOPE_DEPENDENCY_COUNT > 0
        ),

    'view_definition_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3B1_ORDER_REFRESH_SUMMARY

FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_REWRITE_ORDER_V1

WHERE PLAN_BATCH_ID =
      'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1';


SELECT
    APPLY_SEQUENCE,
    DEPENDENCY_LEVEL,
    VIEW_NAME,
    OWNER_ROLE,
    SECURE_FLAG,
    INTERNAL_TARGET_DEPENDENCY_COUNT,
    EXTERNAL_SCOPE_DEPENDENCY_COUNT,
    CYCLE_DETECTED_FLAG,
    PLAN_STATUS
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_VIEW_REWRITE_ORDER_V1
WHERE PLAN_BATCH_ID =
      'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'
ORDER BY APPLY_SEQUENCE;

-- ============================================================
-- PHASE 14D.3B.1 HOTFIX — FINAL GATE AND GOLDEN BASELINE
-- ============================================================

WITH METADATA AS (
    SELECT
        COUNT(*) AS TARGET_VIEW_COUNT,

        COUNT_IF(
            PREFLIGHT_STATUS =
                'READY_FOR_DEPENDENCY_GATE'
        ) AS READY_METADATA_COUNT,

        COUNT_IF(
            DDL_HASH_MATCH_FLAG = FALSE
        ) AS DDL_DRIFT_COUNT,

        COUNT_IF(
            OWNER_MATCH_FLAG = FALSE
        ) AS OWNER_MISMATCH_COUNT,

        COUNT_IF(
            SECURE_CONTRACT_MATCH_FLAG = FALSE
            OR SECURE_CONTRACT_MATCH_FLAG IS NULL
        ) AS SECURE_CONTRACT_MISMATCH_COUNT,

        COUNT_IF(
            CURRENT_SECURE_FLAG = TRUE
        ) AS DEPLOYED_SECURE_VIEW_COUNT,

        COUNT_IF(
            CANDIDATE_SECURE_FLAG = TRUE
        ) AS CANDIDATE_SECURE_VIEW_COUNT,

        COUNT_IF(
            CANDIDATE_CLEAN_FLAG = FALSE
        ) AS UNCLEAN_CANDIDATE_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_VIEW_REWRITE_TARGET_V1

    WHERE PLAN_BATCH_ID =
          'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'
),
DEPENDENCIES AS (
    SELECT
        COUNT(*) AS PLANNED_VIEW_COUNT,

        COUNT_IF(
            CYCLE_DETECTED_FLAG = TRUE
        ) AS CYCLE_DETECTED_COUNT,

        COUNT_IF(
            PLAN_STATUS <>
                'READY_FOR_VIEW_REWRITE_REVIEW'
        ) AS BLOCKED_PLAN_COUNT,

        MAX(DEPENDENCY_LEVEL)
            AS MAX_DEPENDENCY_LEVEL

    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_VIEW_REWRITE_ORDER_V1

    WHERE PLAN_BATCH_ID =
          'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'
),
CONTRACTS AS (
    SELECT
        COUNT(*) AS COLUMN_SNAPSHOT_COUNT,

        COUNT(DISTINCT VIEW_NAME)
            AS VIEW_WITH_COLUMN_SNAPSHOT_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_VIEW_COLUMN_SNAPSHOT_V1

    WHERE PLAN_BATCH_ID =
          'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'
),
GRANTS AS (
    SELECT
        COUNT(*) AS GRANT_SNAPSHOT_COUNT,

        COUNT(DISTINCT VIEW_NAME)
            AS VIEW_WITH_EXPLICIT_GRANT_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_VIEW_GRANT_SNAPSHOT_V1

    WHERE PLAN_BATCH_ID =
          'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            METADATA.TARGET_VIEW_COUNT = 11
            AND METADATA.READY_METADATA_COUNT = 11
            AND METADATA.DDL_DRIFT_COUNT = 0
            AND METADATA.OWNER_MISMATCH_COUNT = 0
            AND METADATA.SECURE_CONTRACT_MISMATCH_COUNT = 0
            AND METADATA.DEPLOYED_SECURE_VIEW_COUNT =
                METADATA.CANDIDATE_SECURE_VIEW_COUNT
            AND METADATA.UNCLEAN_CANDIDATE_COUNT = 0
            AND DEPENDENCIES.PLANNED_VIEW_COUNT = 11
            AND DEPENDENCIES.CYCLE_DETECTED_COUNT = 0
            AND DEPENDENCIES.BLOCKED_PLAN_COUNT = 0
            AND CONTRACTS
                .VIEW_WITH_COLUMN_SNAPSHOT_COUNT = 11,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3B_1_HOTFIX',

    'target_view_count',
        METADATA.TARGET_VIEW_COUNT,

    'ready_metadata_count',
        METADATA.READY_METADATA_COUNT,

    'ddl_drift_count',
        METADATA.DDL_DRIFT_COUNT,

    'owner_mismatch_count',
        METADATA.OWNER_MISMATCH_COUNT,

    'deployed_secure_view_count',
        METADATA.DEPLOYED_SECURE_VIEW_COUNT,

    'candidate_secure_view_count',
        METADATA.CANDIDATE_SECURE_VIEW_COUNT,

    'secure_contract_mismatch_count',
        METADATA.SECURE_CONTRACT_MISMATCH_COUNT,

    'unclean_candidate_count',
        METADATA.UNCLEAN_CANDIDATE_COUNT,

    'planned_view_count',
        DEPENDENCIES.PLANNED_VIEW_COUNT,

    'dependency_cycle_count',
        DEPENDENCIES.CYCLE_DETECTED_COUNT,

    'blocked_plan_count',
        DEPENDENCIES.BLOCKED_PLAN_COUNT,

    'max_dependency_level',
        DEPENDENCIES.MAX_DEPENDENCY_LEVEL,

    'column_snapshot_count',
        CONTRACTS.COLUMN_SNAPSHOT_COUNT,

    'view_with_column_snapshot_count',
        CONTRACTS
            .VIEW_WITH_COLUMN_SNAPSHOT_COUNT,

    'grant_snapshot_count',
        GRANTS.GRANT_SNAPSHOT_COUNT,

    'view_with_explicit_grant_count',
        GRANTS
            .VIEW_WITH_EXPLICIT_GRANT_COUNT,

    'candidate_source_executed',
        FALSE,

    'view_definition_changed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'ml_authority_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3B1_FINAL_GATE

FROM METADATA
CROSS JOIN DEPENDENCIES
CROSS JOIN CONTRACTS
CROSS JOIN GRANTS;


WITH baseline AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_BASELINE_V1
    WHERE BASELINE_ID =
          'PHASE14A_SIM_001_BASELINE_V1'
),
current_state AS (
    SELECT
        s.SIMULATION_ID,

        HASH(
            s.MATERIAL_COST_USD,
            s.LABOR_COST_USD,
            s.MACHINE_COST_USD,
            s.OVERHEAD_COST_USD,
            s.TOTAL_CONFIGURED_COST_USD,
            s.FLOOR_PRICE_USD,
            s.TARGET_PRICE_USD,
            s.CEILING_PRICE_USD,
            s.BASELINE_TOTAL_COST_USD,
            s.RISK_ADJUSTED_TOTAL_COST_USD,
            s.TOTAL_RISK_UPLIFT_USD,
            s.TOTAL_RISK_UPLIFT_PCT,
            s.CSS_SCORE,
            s.SCRAP_RATE_APPLIED,
            s.AVG_WEIGHTED_FMIS,
            s.MAX_TDS_FACTOR,
            s.BOM_MATCH_CONFIDENCE_SCORE,
            s.BMCS_REVIEW_STATUS,
            s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
            s.QUOTE_TRUST_STATUS,
            h.RESOLVED_SCRAP_RATE,
            h.CSS_RESOLVED_SOURCE,
            h.RESOLVED_FMIS_MULTIPLIER,
            h.FMIS_RESOLVED_SOURCE,
            h.RESOLVED_TDS_FACTOR,
            h.TDS_RESOLVED_SOURCE,
            h.RESOLVED_BMCS_STATUS,
            h.SAFETY_GATE_PASS_FLAG,
            h.COST_ENGINE_CONSUMPTION_ALLOWED_FLAG,
            h.OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG
        ) AS SNAPSHOT_HASH,

        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS ACTIVE_POLICY_COUNT,

        (
            SELECT COUNT_IF(
                DEPLOYMENT_MODE = 'SHADOW'
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS SHADOW_POLICY_COUNT,

        (
            SELECT COALESCE(
                COUNT_IF(
                    AUTO_USE_ALLOWED_FLAG = TRUE
                    OR OFFICIAL_COST_IMPACT_ALLOWED_FLAG = TRUE
                    OR BUSINESS_DECISION_ALLOWED_FLAG = TRUE
                ),
                0
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS POLICY_AUTHORITY_ENABLED_COUNT,

        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .ML_RUNTIME_AUTHORITY_REGISTRY_V1
            WHERE UPPER(AUTHORITY_STATUS) = 'ENABLED'
        ) AS ENABLED_RUNTIME_AUTHORITY_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_OUTPUT
            .KMAT_CONFIGURED_COST_SUMMARY s

    LEFT JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .VW_KMAT_PHASE10B_HIERARCHY_V1 h
        ON s.SIMULATION_ID = h.SIMULATION_ID

    WHERE s.SIMULATION_ID = 'SIM_001'

    QUALIFY ROW_NUMBER() OVER (
        PARTITION BY s.SIMULATION_ID
        ORDER BY s.CALCULATED_AT DESC
    ) = 1
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            baseline.SNAPSHOT_HASH =
                current_state.SNAPSHOT_HASH
            AND current_state
                .POLICY_AUTHORITY_ENABLED_COUNT = 0
            AND current_state
                .ENABLED_RUNTIME_AUTHORITY_COUNT = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3B_1_HOTFIX',

    'baseline_id',
        baseline.BASELINE_ID,

    'simulation_id',
        baseline.SIMULATION_ID,

    'baseline_snapshot_hash',
        baseline.SNAPSHOT_HASH,

    'current_snapshot_hash',
        current_state.SNAPSHOT_HASH,

    'cost_and_governance_snapshot_match',
        baseline.SNAPSHOT_HASH =
        current_state.SNAPSHOT_HASH,

    'active_policy_count',
        current_state.ACTIVE_POLICY_COUNT,

    'shadow_policy_count',
        current_state.SHADOW_POLICY_COUNT,

    'policy_authority_enabled_count',
        current_state
            .POLICY_AUTHORITY_ENABLED_COUNT,

    'enabled_runtime_authority_count',
        current_state
            .ENABLED_RUNTIME_AUTHORITY_COUNT,

    'official_cost_changed',
        baseline.SNAPSHOT_HASH <>
        current_state.SNAPSHOT_HASH,

    'view_definition_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'ml_authority_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3B1_BASELINE_VERIFICATION

FROM baseline
CROSS JOIN current_state;

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

CREATE TABLE IF NOT EXISTS
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_SQL_PROCEDURE_TARGET_V1 (
            PLAN_BATCH_ID VARCHAR NOT NULL,
            PROCEDURE_SCHEMA VARCHAR NOT NULL,
            PROCEDURE_NAME VARCHAR NOT NULL,
            ARGUMENT_SIGNATURE VARCHAR NOT NULL,
            EXPECTED_OWNER VARCHAR NOT NULL,
            EXPECTED_DDL_HASH NUMBER NOT NULL,
            CURRENT_OWNER VARCHAR,
            PROCEDURE_LANGUAGE VARCHAR,
            CURRENT_DDL_HASH NUMBER,
            CANDIDATE_SOURCE_HASH NUMBER,
            FIXED_DATABASE_COUNT_AFTER NUMBER,
            RUNTIME_PLACEHOLDER_COUNT NUMBER,
            OWNER_RIGHTS_FLAG BOOLEAN,
            USES_CURRENT_USER_FLAG BOOLEAN,
            USES_CURRENT_SESSION_FLAG BOOLEAN,
            USES_CURRENT_ROLE_FLAG BOOLEAN,
            USES_CURRENT_WAREHOUSE_FLAG BOOLEAN,
            TRANSACTION_CONTROL_FLAG BOOLEAN,
            NESTED_PROCEDURE_DEPENDENCY_COUNT NUMBER,
            PORTABILITY_CLASSIFICATION VARCHAR NOT NULL,
            PREFLIGHT_STATUS VARCHAR NOT NULL,
            CAPTURED_BY VARCHAR NOT NULL,
            CAPTURED_AT TIMESTAMP_NTZ NOT NULL
        );

DELETE FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_SQL_PROCEDURE_TARGET_V1
WHERE PLAN_BATCH_ID =
      'PHASE14D3C_SQL_PROCEDURE_PLAN_V1';

INSERT INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_SQL_PROCEDURE_TARGET_V1
WITH TARGETS AS (
    SELECT * FROM VALUES
        ('CORE_INTERNAL', 'RUN_KMAT_COST_SIMULATION_GOVERNED_V2', '(P_SIMULATION_ID VARCHAR)', 'SYSADMIN', 5459128958821620492),
        ('CORE_INTERNAL', 'RUN_KMAT_COST_SIMULATION_GOVERNED_V3', '(P_SIMULATION_ID VARCHAR)', 'SYSADMIN', -1141157281068169553),
        ('CORE_ML', 'PREPARE_KMAT_GOVERNED_COST_INPUT_V2', '(P_SIMULATION_ID VARCHAR)', 'SYSADMIN', 5511366353286591906),
        ('CORE_ML', 'RECORD_KMAT_COST_ACTUAL_OUTCOME_V1', '(P_COST_OUTCOME_ID VARCHAR, P_SIMULATION_ID VARCHAR, P_OUTCOME_DATE DATE, P_ACTUAL_MATERIAL_COST_USD FLOAT, P_ACTUAL_LABOR_COST_USD FLOAT, P_ACTUAL_MACHINE_COST_USD FLOAT, P_ACTUAL_OVERHEAD_COST_USD FLOAT, P_ACTUAL_TOTAL_COST_USD FLOAT, P_ACTUAL_FINAL_PRICE_USD FLOAT, P_OUTCOME_SOURCE VARCHAR, P_EVIDENCE_REFERENCE VARCHAR, P_NOTES VARCHAR, P_RECORDED_BY VARCHAR)', 'SYSADMIN', 1788878332117721761),
        ('CORE_ML', 'RECORD_KMAT_MODEL_ACTUAL_OUTCOME_V1', '(P_OUTCOME_ID VARCHAR, P_SIMULATION_ID VARCHAR, P_MODEL_DOMAIN VARCHAR, P_OUTCOME_DATE DATE, P_ACTUAL_NUMERIC_VALUE FLOAT, P_ACTUAL_TEXT_STATUS VARCHAR, P_ACTUAL_MAPPING_CORRECT_FLAG BOOLEAN, P_OUTCOME_SOURCE VARCHAR, P_EVIDENCE_REFERENCE VARCHAR, P_NOTES VARCHAR, P_RECORDED_BY VARCHAR)', 'SYSADMIN', 7519621897808226030),
        ('CORE_ML', 'RESOLVE_ML_RUNTIME_AUTHORITY_SECURE_V1', '(P_RUNTIME_DECISION_ID VARCHAR, P_MODEL_DOMAIN VARCHAR, P_SIMULATION_ID VARCHAR, P_RULE_VALUE FLOAT, P_CANDIDATE_VALUE FLOAT, P_QUALITY_PASS_FLAG BOOLEAN, P_OOD_FLAG BOOLEAN, P_ENGINEER_APPROVED_FLAG BOOLEAN, P_ENGINEER_APPROVAL_REFERENCE VARCHAR)', 'KMAT_GOVERNANCE_EXECUTOR_ROLE', -669773161106802348),
        ('CORE_ML', 'REVIEW_ML_DECISION_OVERRIDE_V2', '(P_OVERRIDE_ID VARCHAR, P_REVIEW_ACTION VARCHAR, P_REVIEW_NOTE VARCHAR)', 'KMAT_GOVERNANCE_EXECUTOR_ROLE', -6398721979574433576),
        ('CORE_ML', 'RUN_KMAT_MONITORING_V1', '(P_MONITORING_RUN_ID VARCHAR, P_RUN_BY VARCHAR)', 'SYSADMIN', 6593044306893085317),
        ('CORE_ML', 'SUBMIT_ML_DECISION_OVERRIDE_V2', '(P_OVERRIDE_ID VARCHAR, P_DECISION_ID VARCHAR, P_OVERRIDE_NUMERIC_VALUE FLOAT, P_OVERRIDE_TEXT_STATUS VARCHAR, P_OVERRIDE_REASON VARCHAR)', 'KMAT_GOVERNANCE_EXECUTOR_ROLE', -712316323569189422)
    AS t(
        PROCEDURE_SCHEMA,
        PROCEDURE_NAME,
        ARGUMENT_SIGNATURE,
        EXPECTED_OWNER,
        EXPECTED_DDL_HASH
    )
),
CURRENT_PROCEDURES AS (
    SELECT
        PROCEDURE_SCHEMA,
        PROCEDURE_NAME,
        ARGUMENT_SIGNATURE,
        PROCEDURE_OWNER,
        PROCEDURE_LANGUAGE,
        COALESCE(PROCEDURE_DEFINITION, '') AS CURRENT_DDL
    FROM
        KMAT_COST_MODEL_DB.INFORMATION_SCHEMA.PROCEDURES
    WHERE PROCEDURE_SCHEMA IN (
        'CORE_INTERNAL',
        'CORE_ML'
    )
),
CANDIDATES AS (
    SELECT
        OBJECT_SCHEMA,
        OBJECT_NAME,
        OBJECT_SIGNATURE,
        OBJECT_FQN,
        PORTABLE_SOURCE_CANDIDATE,
        PORTABLE_SOURCE_HASH,
        FIXED_DATABASE_REFERENCE_COUNT_AFTER
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_PORTABLE_SOURCE_CANDIDATE_V1
    WHERE SOURCE_BATCH_ID =
          'PHASE14D3A_PORTABLE_SOURCE_CANDIDATE_V1'
      AND OBJECT_TYPE = 'PROCEDURE'
      AND REWRITE_WAVE =
          'PHASE_14D_3C_SQL_PROCEDURE_SOURCE'
),
DEPENDENCY_COUNTS AS (
    SELECT
        PARENT_OBJECT_SCHEMA,
        PARENT_OBJECT_NAME,
        PARENT_OBJECT_SIGNATURE,
        COUNT(*) AS DEPENDENCY_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_DEPENDENCY_EDGE_V1
    WHERE EDGE_BATCH_ID =
          'PHASE14D3A_OBJECT_DEPENDENCY_EDGE_V1'
      AND CHILD_OBJECT_TYPE = 'PROCEDURE'
    GROUP BY
        PARENT_OBJECT_SCHEMA,
        PARENT_OBJECT_NAME,
        PARENT_OBJECT_SIGNATURE
),
JOINED AS (
    SELECT
        target.*,
        current_proc.PROCEDURE_OWNER,
        current_proc.PROCEDURE_LANGUAGE,
        current_proc.CURRENT_DDL,
        candidate.PORTABLE_SOURCE_CANDIDATE,
        candidate.PORTABLE_SOURCE_HASH,
        candidate.FIXED_DATABASE_REFERENCE_COUNT_AFTER,
        COALESCE(
            dependency.DEPENDENCY_COUNT,
            0
        ) AS DEPENDENCY_COUNT
    FROM TARGETS target
    LEFT JOIN CURRENT_PROCEDURES current_proc
      ON current_proc.PROCEDURE_SCHEMA =
         target.PROCEDURE_SCHEMA
     AND current_proc.PROCEDURE_NAME =
         target.PROCEDURE_NAME
     AND current_proc.ARGUMENT_SIGNATURE =
         target.ARGUMENT_SIGNATURE
    LEFT JOIN CANDIDATES candidate
      ON candidate.OBJECT_SCHEMA =
         target.PROCEDURE_SCHEMA
     AND candidate.OBJECT_NAME =
         target.PROCEDURE_NAME
     AND candidate.OBJECT_SIGNATURE =
         target.ARGUMENT_SIGNATURE
    LEFT JOIN DEPENDENCY_COUNTS dependency
      ON dependency.PARENT_OBJECT_SCHEMA =
         target.PROCEDURE_SCHEMA
     AND dependency.PARENT_OBJECT_NAME =
         target.PROCEDURE_NAME
     AND dependency.PARENT_OBJECT_SIGNATURE =
         target.ARGUMENT_SIGNATURE
),
FLAGS AS (
    SELECT
        *,
        HASH(CURRENT_DDL) AS CURRENT_DDL_HASH,

        COALESCE(
            REGEXP_COUNT(
                UPPER(PORTABLE_SOURCE_CANDIDATE),
                'KMAT_COST_MODEL_DB'
            ),
            0
        ) AS RESIDUAL_DATABASE_COUNT,

        COALESCE(
            REGEXP_COUNT(
                PORTABLE_SOURCE_CANDIDATE,
                '__RUNTIME_DATABASE__'
            ),
            0
        ) AS RUNTIME_PLACEHOLDER_COUNT,

        (
            CURRENT_DDL IS NOT NULL
            AND REGEXP_COUNT(
                UPPER(CURRENT_DDL),
                'EXECUTE[[:space:]]+AS[[:space:]]+CALLER'
            ) = 0
            AND REGEXP_COUNT(
                UPPER(CURRENT_DDL),
                'EXECUTE[[:space:]]+AS[[:space:]]+RESTRICTED[[:space:]]+CALLER'
            ) = 0
        ) AS OWNER_RIGHTS_FLAG,

        COALESCE(
            REGEXP_COUNT(
                UPPER(PORTABLE_SOURCE_CANDIDATE),
                'CURRENT_USER[[:space:]]*[(]'
            ),
            0
        ) > 0 AS USES_CURRENT_USER_FLAG,

        COALESCE(
            REGEXP_COUNT(
                UPPER(PORTABLE_SOURCE_CANDIDATE),
                'CURRENT_SESSION[[:space:]]*[(]'
            ),
            0
        ) > 0 AS USES_CURRENT_SESSION_FLAG,

        COALESCE(
            REGEXP_COUNT(
                UPPER(PORTABLE_SOURCE_CANDIDATE),
                'CURRENT_ROLE[[:space:]]*[(]'
            ),
            0
        ) > 0 AS USES_CURRENT_ROLE_FLAG,

        COALESCE(
            REGEXP_COUNT(
                UPPER(PORTABLE_SOURCE_CANDIDATE),
                'CURRENT_WAREHOUSE[[:space:]]*[(]'
            ),
            0
        ) > 0 AS USES_CURRENT_WAREHOUSE_FLAG,

        COALESCE(
            REGEXP_COUNT(
                UPPER(PORTABLE_SOURCE_CANDIDATE),
                'BEGIN[[:space:]]+TRANSACTION'
            )
            +
            REGEXP_COUNT(
                UPPER(PORTABLE_SOURCE_CANDIDATE),
                'COMMIT[[:space:]]*;'
            )
            +
            REGEXP_COUNT(
                UPPER(PORTABLE_SOURCE_CANDIDATE),
                'ROLLBACK[[:space:]]*;'
            ),
            0
        ) > 0 AS TRANSACTION_CONTROL_FLAG
    FROM JOINED
)
SELECT
    'PHASE14D3C_SQL_PROCEDURE_PLAN_V1',
    PROCEDURE_SCHEMA,
    PROCEDURE_NAME,
    ARGUMENT_SIGNATURE,
    EXPECTED_OWNER,
    EXPECTED_DDL_HASH,
    PROCEDURE_OWNER,
    PROCEDURE_LANGUAGE,
    CURRENT_DDL_HASH,
    PORTABLE_SOURCE_HASH,
    RESIDUAL_DATABASE_COUNT,
    RUNTIME_PLACEHOLDER_COUNT,
    OWNER_RIGHTS_FLAG,
    USES_CURRENT_USER_FLAG,
    USES_CURRENT_SESSION_FLAG,
    USES_CURRENT_ROLE_FLAG,
    USES_CURRENT_WAREHOUSE_FLAG,
    TRANSACTION_CONTROL_FLAG,
    DEPENDENCY_COUNT,

    CASE
        WHEN USES_CURRENT_USER_FLAG
          OR USES_CURRENT_SESSION_FLAG
          OR USES_CURRENT_ROLE_FLAG
          OR USES_CURRENT_WAREHOUSE_FLAG
            THEN 'IDENTITY_SENSITIVE_SECURE_WRAPPER'
        ELSE 'SCHEMA_RELATIVE_SOURCE_READY'
    END,

    CASE
        WHEN CURRENT_DDL IS NULL
            THEN 'MISSING_PROCEDURE'
        WHEN PROCEDURE_LANGUAGE <> 'SQL'
            THEN 'LANGUAGE_MISMATCH'
        WHEN PROCEDURE_OWNER <> EXPECTED_OWNER
            THEN 'OWNER_MISMATCH'
        WHEN CURRENT_DDL_HASH <> EXPECTED_DDL_HASH
            THEN 'DDL_DRIFT_DETECTED'
        WHEN PORTABLE_SOURCE_CANDIDATE IS NULL
            THEN 'MISSING_PORTABLE_SOURCE'
        WHEN RESIDUAL_DATABASE_COUNT > 0
            THEN 'FIXED_DATABASE_REMAINS'
        WHEN RUNTIME_PLACEHOLDER_COUNT > 0
            THEN 'RUNTIME_PLACEHOLDER_REMAINS'
        WHEN OWNER_RIGHTS_FLAG = FALSE
            THEN 'OWNER_RIGHTS_REQUIRED'
        ELSE 'READY_FOR_CONTRACT_REVIEW'
    END,

    CURRENT_USER(),
    CURRENT_TIMESTAMP()
FROM FLAGS;

SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COUNT(*) = 9
            AND COUNT_IF(
                PREFLIGHT_STATUS =
                    'READY_FOR_CONTRACT_REVIEW'
            ) = 9,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),
    'phase', 'PHASE_14D_3C',
    'target_procedure_count', COUNT(*),
    'ready_procedure_count',
        COUNT_IF(
            PREFLIGHT_STATUS =
                'READY_FOR_CONTRACT_REVIEW'
        ),
    'schema_relative_source_ready_count',
        COUNT_IF(
            PORTABILITY_CLASSIFICATION =
                'SCHEMA_RELATIVE_SOURCE_READY'
        ),
    'identity_sensitive_wrapper_count',
        COUNT_IF(
            PORTABILITY_CLASSIFICATION =
                'IDENTITY_SENSITIVE_SECURE_WRAPPER'
        ),
    'owner_rights_count',
        COUNT_IF(OWNER_RIGHTS_FLAG = TRUE),
    'transaction_control_procedure_count',
        COUNT_IF(TRANSACTION_CONTROL_FLAG = TRUE),
    'fixed_database_remaining_count',
        SUM(FIXED_DATABASE_COUNT_AFTER),
    'runtime_placeholder_count',
        SUM(RUNTIME_PLACEHOLDER_COUNT),
    'procedure_body_changed', FALSE,
    'candidate_source_executed', FALSE,
    'official_cost_changed', FALSE,
    'native_app_package_created', FALSE
) AS PHASE14D3C_CONTRACT_SUMMARY
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_SQL_PROCEDURE_TARGET_V1
WHERE PLAN_BATCH_ID =
      'PHASE14D3C_SQL_PROCEDURE_PLAN_V1';

SELECT
    PROCEDURE_SCHEMA,
    PROCEDURE_NAME,
    ARGUMENT_SIGNATURE,
    CURRENT_OWNER,
    PROCEDURE_LANGUAGE,
    OWNER_RIGHTS_FLAG,
    USES_CURRENT_USER_FLAG,
    USES_CURRENT_SESSION_FLAG,
    TRANSACTION_CONTROL_FLAG,
    NESTED_PROCEDURE_DEPENDENCY_COUNT,
    PORTABILITY_CLASSIFICATION,
    PREFLIGHT_STATUS
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_SQL_PROCEDURE_TARGET_V1
WHERE PLAN_BATCH_ID =
      'PHASE14D3C_SQL_PROCEDURE_PLAN_V1'
ORDER BY
    PORTABILITY_CLASSIFICATION,
    PROCEDURE_SCHEMA,
    PROCEDURE_NAME;

SELECT
    target.PROCEDURE_SCHEMA,
    target.PROCEDURE_NAME,
    target.ARGUMENT_SIGNATURE,
    target.CURRENT_OWNER,
    target.PORTABILITY_CLASSIFICATION,
    target.TRANSACTION_CONTROL_FLAG,
    target.NESTED_PROCEDURE_DEPENDENCY_COUNT,
    candidate.ORIGINAL_DDL_HASH,
    candidate.PORTABLE_SOURCE_HASH,
    candidate.REVIEW_NOTES,
    candidate.PORTABLE_SOURCE_CANDIDATE
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_SQL_PROCEDURE_TARGET_V1 target
JOIN
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PORTABLE_SOURCE_CANDIDATE_V1 candidate
  ON candidate.SOURCE_BATCH_ID =
     'PHASE14D3A_PORTABLE_SOURCE_CANDIDATE_V1'
 AND candidate.OBJECT_SCHEMA =
     target.PROCEDURE_SCHEMA
 AND candidate.OBJECT_NAME =
     target.PROCEDURE_NAME
 AND candidate.OBJECT_SIGNATURE =
     target.ARGUMENT_SIGNATURE
WHERE target.PLAN_BATCH_ID =
      'PHASE14D3C_SQL_PROCEDURE_PLAN_V1'
ORDER BY
    CASE target.PORTABILITY_CLASSIFICATION
        WHEN 'SCHEMA_RELATIVE_SOURCE_READY' THEN 1
        ELSE 2
    END,
    target.PROCEDURE_SCHEMA,
    target.PROCEDURE_NAME;

SELECT
    edge.PARENT_OBJECT_SCHEMA,
    edge.PARENT_OBJECT_NAME,
    edge.PARENT_OBJECT_SIGNATURE,
    edge.CHILD_OBJECT_SCHEMA,
    edge.CHILD_OBJECT_NAME,
    edge.CHILD_OBJECT_SIGNATURE,
    edge.DETECTION_METHOD
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_OBJECT_DEPENDENCY_EDGE_V1 edge
JOIN
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_SQL_PROCEDURE_TARGET_V1 target
  ON target.PLAN_BATCH_ID =
     'PHASE14D3C_SQL_PROCEDURE_PLAN_V1'
 AND target.PROCEDURE_SCHEMA =
     edge.PARENT_OBJECT_SCHEMA
 AND target.PROCEDURE_NAME =
     edge.PARENT_OBJECT_NAME
 AND target.ARGUMENT_SIGNATURE =
     edge.PARENT_OBJECT_SIGNATURE
WHERE edge.EDGE_BATCH_ID =
      'PHASE14D3A_OBJECT_DEPENDENCY_EDGE_V1'
ORDER BY
    edge.PARENT_OBJECT_SCHEMA,
    edge.PARENT_OBJECT_NAME,
    edge.CHILD_OBJECT_SCHEMA,
    edge.CHILD_OBJECT_NAME;

WITH CONTRACT AS (
    SELECT
        COUNT(*) AS TARGET_COUNT,
        COUNT_IF(
            PREFLIGHT_STATUS =
                'READY_FOR_CONTRACT_REVIEW'
        ) AS READY_COUNT,
        COUNT_IF(
            PORTABILITY_CLASSIFICATION =
                'SCHEMA_RELATIVE_SOURCE_READY'
        ) AS PORTABLE_COUNT,
        COUNT_IF(
            PORTABILITY_CLASSIFICATION =
                'IDENTITY_SENSITIVE_SECURE_WRAPPER'
        ) AS IDENTITY_SENSITIVE_COUNT,
        COUNT_IF(
            OWNER_RIGHTS_FLAG = FALSE
        ) AS OWNER_RIGHTS_FAILURE_COUNT,
        SUM(FIXED_DATABASE_COUNT_AFTER)
            AS FIXED_DATABASE_REMAINING_COUNT,
        SUM(RUNTIME_PLACEHOLDER_COUNT)
            AS RUNTIME_PLACEHOLDER_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_SQL_PROCEDURE_TARGET_V1
    WHERE PLAN_BATCH_ID =
          'PHASE14D3C_SQL_PROCEDURE_PLAN_V1'
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            TARGET_COUNT = 9
            AND READY_COUNT = 9
            AND PORTABLE_COUNT = 6
            AND IDENTITY_SENSITIVE_COUNT = 3
            AND OWNER_RIGHTS_FAILURE_COUNT = 0
            AND FIXED_DATABASE_REMAINING_COUNT = 0
            AND RUNTIME_PLACEHOLDER_COUNT = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),
    'phase', 'PHASE_14D_3C',
    'target_procedure_count', TARGET_COUNT,
    'ready_procedure_count', READY_COUNT,
    'schema_relative_source_ready_count',
        PORTABLE_COUNT,
    'identity_sensitive_wrapper_count',
        IDENTITY_SENSITIVE_COUNT,
    'owner_rights_failure_count',
        OWNER_RIGHTS_FAILURE_COUNT,
    'fixed_database_remaining_count',
        FIXED_DATABASE_REMAINING_COUNT,
    'runtime_placeholder_count',
        RUNTIME_PLACEHOLDER_COUNT,
    'procedure_body_changed', FALSE,
    'candidate_source_executed', FALSE,
    'official_cost_changed', FALSE,
    'ml_authority_changed', FALSE,
    'native_app_package_created', FALSE
) AS PHASE14D3C_FINAL_GATE
FROM CONTRACT;

WITH baseline AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_BASELINE_V1
    WHERE BASELINE_ID =
          'PHASE14A_SIM_001_BASELINE_V1'
),
current_state AS (
    SELECT
        s.SIMULATION_ID,
        HASH(
            s.MATERIAL_COST_USD,
            s.LABOR_COST_USD,
            s.MACHINE_COST_USD,
            s.OVERHEAD_COST_USD,
            s.TOTAL_CONFIGURED_COST_USD,
            s.FLOOR_PRICE_USD,
            s.TARGET_PRICE_USD,
            s.CEILING_PRICE_USD,
            s.BASELINE_TOTAL_COST_USD,
            s.RISK_ADJUSTED_TOTAL_COST_USD,
            s.TOTAL_RISK_UPLIFT_USD,
            s.TOTAL_RISK_UPLIFT_PCT,
            s.CSS_SCORE,
            s.SCRAP_RATE_APPLIED,
            s.AVG_WEIGHTED_FMIS,
            s.MAX_TDS_FACTOR,
            s.BOM_MATCH_CONFIDENCE_SCORE,
            s.BMCS_REVIEW_STATUS,
            s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
            s.QUOTE_TRUST_STATUS,
            h.RESOLVED_SCRAP_RATE,
            h.CSS_RESOLVED_SOURCE,
            h.RESOLVED_FMIS_MULTIPLIER,
            h.FMIS_RESOLVED_SOURCE,
            h.RESOLVED_TDS_FACTOR,
            h.TDS_RESOLVED_SOURCE,
            h.RESOLVED_BMCS_STATUS,
            h.SAFETY_GATE_PASS_FLAG,
            h.COST_ENGINE_CONSUMPTION_ALLOWED_FLAG,
            h.OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG
        ) AS SNAPSHOT_HASH,
        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS ACTIVE_POLICY_COUNT,
        (
            SELECT COUNT_IF(
                DEPLOYMENT_MODE = 'SHADOW'
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS SHADOW_POLICY_COUNT,
        (
            SELECT COUNT_IF(
                AUTO_USE_ALLOWED_FLAG = TRUE
                OR OFFICIAL_COST_IMPACT_ALLOWED_FLAG = TRUE
                OR BUSINESS_DECISION_ALLOWED_FLAG = TRUE
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS POLICY_AUTHORITY_ENABLED_COUNT,
        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .ML_RUNTIME_AUTHORITY_REGISTRY_V1
            WHERE UPPER(AUTHORITY_STATUS) = 'ENABLED'
        ) AS ENABLED_RUNTIME_AUTHORITY_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_OUTPUT
            .KMAT_CONFIGURED_COST_SUMMARY s
    LEFT JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .VW_KMAT_PHASE10B_HIERARCHY_V1 h
      ON s.SIMULATION_ID = h.SIMULATION_ID
    WHERE s.SIMULATION_ID = 'SIM_001'
    QUALIFY ROW_NUMBER() OVER (
        PARTITION BY s.SIMULATION_ID
        ORDER BY s.CALCULATED_AT DESC
    ) = 1
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            baseline.SNAPSHOT_HASH =
                current_state.SNAPSHOT_HASH
            AND current_state
                .POLICY_AUTHORITY_ENABLED_COUNT = 0
            AND current_state
                .ENABLED_RUNTIME_AUTHORITY_COUNT = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),
    'phase', 'PHASE_14D_3C',
    'baseline_id', baseline.BASELINE_ID,
    'simulation_id', baseline.SIMULATION_ID,
    'baseline_snapshot_hash',
        baseline.SNAPSHOT_HASH,
    'current_snapshot_hash',
        current_state.SNAPSHOT_HASH,
    'cost_and_governance_snapshot_match',
        baseline.SNAPSHOT_HASH =
        current_state.SNAPSHOT_HASH,
    'active_policy_count',
        current_state.ACTIVE_POLICY_COUNT,
    'shadow_policy_count',
        current_state.SHADOW_POLICY_COUNT,
    'policy_authority_enabled_count',
        current_state.POLICY_AUTHORITY_ENABLED_COUNT,
    'enabled_runtime_authority_count',
        current_state.ENABLED_RUNTIME_AUTHORITY_COUNT,
    'official_cost_changed',
        baseline.SNAPSHOT_HASH <>
        current_state.SNAPSHOT_HASH,
    'procedure_body_changed', FALSE,
    'candidate_source_executed', FALSE,
    'ml_authority_changed', FALSE,
    'native_app_package_created', FALSE
) AS PHASE14D3C_BASELINE_VERIFICATION
FROM baseline
CROSS JOIN current_state;

CREATE TABLE IF NOT EXISTS
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_RFQ_CONTRACT_V1 (
            PLAN_BATCH_ID VARCHAR NOT NULL,
            PROCEDURE_SCHEMA VARCHAR NOT NULL,
            PROCEDURE_NAME VARCHAR NOT NULL,
            ARGUMENT_SIGNATURE VARCHAR NOT NULL,
            BUSINESS_DOMAIN VARCHAR NOT NULL,
            REFACTOR_SEQUENCE NUMBER NOT NULL,
            EXPECTED_DDL_HASH NUMBER NOT NULL,
            CURRENT_DDL_HASH NUMBER,
            PROCEDURE_OWNER VARCHAR,
            PROCEDURE_LANGUAGE VARCHAR,
            OWNER_RIGHTS_FLAG BOOLEAN,
            EXPECTED_DYNAMIC_SQL_COUNT NUMBER NOT NULL,
            CURRENT_DYNAMIC_SQL_COUNT NUMBER,
            FIXED_DATABASE_COUNT NUMBER,
            FIXED_WAREHOUSE_COUNT NUMBER,
            TEMP_OBJECT_COUNT NUMBER,
            CURRENT_USER_COUNT NUMBER,
            CURRENT_SESSION_COUNT NUMBER,
            SQL_ESCAPE_REFERENCE_COUNT NUMBER,
            QMARK_BIND_REFERENCE_COUNT NUMBER,
            IDENTIFIER_BIND_REFERENCE_COUNT NUMBER,
            RUNTIME_PLACEHOLDER_COUNT NUMBER,
            NESTED_PROCEDURE_DEPENDENCY_COUNT NUMBER,
            REFACTOR_STRATEGY VARCHAR NOT NULL,
            PREFLIGHT_STATUS VARCHAR NOT NULL,
            CAPTURED_BY VARCHAR NOT NULL,
            CAPTURED_AT TIMESTAMP_NTZ NOT NULL
        );

DELETE FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_RFQ_CONTRACT_V1
WHERE PLAN_BATCH_ID =
      'PHASE14D3D1_PYTHON_RFQ_PLAN_V1';

INSERT INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_RFQ_CONTRACT_V1
WITH TARGETS AS (
    SELECT * FROM VALUES
        ('PREPARE_RFQ_SIMULATION_INPUTS', '(RFQ_ID VARCHAR)', -6251348384323678794, 10, 'RFQ_CONFIGURATION_TO_SIMULATION_INPUTS', 1),
        ('RUN_RULE_BASED_BMCS_SCORING', '(RFQ_ID VARCHAR)', -6490293137006003591, 7, 'RULE_BASED_BMCS', 2),
        ('RUN_CORTEX_BMCS_ASSESSMENT', '(RFQ_ID VARCHAR)', 7001001297441927869, 7, 'CORTEX_BMCS_ADVISORY', 3),
        ('RUN_CORTEX_RFQ_QUOTE_PIPELINE', '(RFQ_ID VARCHAR)', -3637676842551177783, 6, 'RFQ_QUOTE_ORCHESTRATOR', 4)
    AS target(
        PROCEDURE_NAME,
        ARGUMENT_SIGNATURE,
        EXPECTED_DDL_HASH,
        EXPECTED_DYNAMIC_SQL_COUNT,
        BUSINESS_DOMAIN,
        REFACTOR_SEQUENCE
    )
),
AUDIT AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1
    WHERE AUDIT_BATCH_ID =
          'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
      AND OBJECT_TYPE = 'PROCEDURE'
      AND OBJECT_SCHEMA = 'CORE_INTERNAL'
),
CANDIDATE AS (
    SELECT
        OBJECT_NAME,
        OBJECT_SIGNATURE,
        PORTABLE_SOURCE_CANDIDATE
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_PORTABLE_SOURCE_CANDIDATE_V1
    WHERE SOURCE_BATCH_ID =
          'PHASE14D3A_PORTABLE_SOURCE_CANDIDATE_V1'
      AND OBJECT_TYPE = 'PROCEDURE'
),
DEPENDENCIES AS (
    SELECT
        PARENT_OBJECT_NAME,
        PARENT_OBJECT_SIGNATURE,
        COUNT(*) AS DEPENDENCY_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_DEPENDENCY_EDGE_V1
    WHERE EDGE_BATCH_ID =
          'PHASE14D3A_OBJECT_DEPENDENCY_EDGE_V1'
      AND PARENT_OBJECT_SCHEMA = 'CORE_INTERNAL'
      AND CHILD_OBJECT_TYPE = 'PROCEDURE'
    GROUP BY
        PARENT_OBJECT_NAME,
        PARENT_OBJECT_SIGNATURE
),
SOURCE AS (
    SELECT
        target.*,
        audit.OBJECT_DDL,
        audit.OBJECT_DDL_HASH,
        audit.OBJECT_OWNER,
        audit.OBJECT_LANGUAGE,
        audit.DYNAMIC_SQL_INDICATOR_COUNT,
        audit.FIXED_DATABASE_REFERENCE_COUNT,
        audit.FIXED_WAREHOUSE_REFERENCE_COUNT,
        audit.TEMP_OBJECT_REFERENCE_COUNT,
        candidate.PORTABLE_SOURCE_CANDIDATE,
        COALESCE(
            dependency.DEPENDENCY_COUNT,
            0
        ) AS DEPENDENCY_COUNT
    FROM TARGETS target
    LEFT JOIN AUDIT audit
      ON audit.OBJECT_NAME =
         target.PROCEDURE_NAME
     AND audit.OBJECT_SIGNATURE =
         target.ARGUMENT_SIGNATURE
    LEFT JOIN CANDIDATE candidate
      ON candidate.OBJECT_NAME =
         target.PROCEDURE_NAME
     AND candidate.OBJECT_SIGNATURE =
         target.ARGUMENT_SIGNATURE
    LEFT JOIN DEPENDENCIES dependency
      ON dependency.PARENT_OBJECT_NAME =
         target.PROCEDURE_NAME
     AND dependency.PARENT_OBJECT_SIGNATURE =
         target.ARGUMENT_SIGNATURE
),
FLAGS AS (
    SELECT
        *,
        (
            OBJECT_DDL IS NOT NULL
            AND REGEXP_COUNT(
                UPPER(OBJECT_DDL),
                'EXECUTE[[:space:]]+AS[[:space:]]+CALLER'
            ) = 0
            AND REGEXP_COUNT(
                UPPER(OBJECT_DDL),
                'EXECUTE[[:space:]]+AS[[:space:]]+RESTRICTED'
            ) = 0
        ) AS OWNER_RIGHTS_FLAG,

        COALESCE(
            REGEXP_COUNT(
                UPPER(OBJECT_DDL),
                'CURRENT_USER[[:space:]]*[(]'
            ),
            0
        ) AS CURRENT_USER_COUNT,

        COALESCE(
            REGEXP_COUNT(
                UPPER(OBJECT_DDL),
                'CURRENT_SESSION[[:space:]]*[(]'
            ),
            0
        ) AS CURRENT_SESSION_COUNT,

        COALESCE(
            REGEXP_COUNT(
                OBJECT_DDL,
                'sql_escape[[:space:]]*[(]'
            ),
            0
        ) AS SQL_ESCAPE_REFERENCE_COUNT,

        COALESCE(
            REGEXP_COUNT(
                PORTABLE_SOURCE_CANDIDATE,
                'params[[:space:]]*='
            ),
            0
        ) AS QMARK_BIND_REFERENCE_COUNT,

        COALESCE(
            REGEXP_COUNT(
                UPPER(PORTABLE_SOURCE_CANDIDATE),
                'IDENTIFIER[[:space:]]*[(][[:space:]]*[?]'
            ),
            0
        ) AS IDENTIFIER_BIND_REFERENCE_COUNT,

        COALESCE(
            REGEXP_COUNT(
                PORTABLE_SOURCE_CANDIDATE,
                '__RUNTIME_DATABASE__'
            ),
            0
        ) AS RUNTIME_PLACEHOLDER_COUNT

    FROM SOURCE
)
SELECT
    'PHASE14D3D1_PYTHON_RFQ_PLAN_V1',
    'CORE_INTERNAL',
    PROCEDURE_NAME,
    ARGUMENT_SIGNATURE,
    BUSINESS_DOMAIN,
    REFACTOR_SEQUENCE,
    EXPECTED_DDL_HASH,
    OBJECT_DDL_HASH,
    OBJECT_OWNER,
    OBJECT_LANGUAGE,
    OWNER_RIGHTS_FLAG,
    EXPECTED_DYNAMIC_SQL_COUNT,
    DYNAMIC_SQL_INDICATOR_COUNT,
    FIXED_DATABASE_REFERENCE_COUNT,
    FIXED_WAREHOUSE_REFERENCE_COUNT,
    TEMP_OBJECT_REFERENCE_COUNT,
    CURRENT_USER_COUNT,
    CURRENT_SESSION_COUNT,
    SQL_ESCAPE_REFERENCE_COUNT,
    QMARK_BIND_REFERENCE_COUNT,
    IDENTIFIER_BIND_REFERENCE_COUNT,
    RUNTIME_PLACEHOLDER_COUNT,
    DEPENDENCY_COUNT,

    'STATIC_SCHEMA_RELATIVE_OBJECTS'
    || '_PLUS_QMARK_VALUE_BINDS'
    || '_NO_DB_NAME_CONSTANT',

    CASE
        WHEN OBJECT_DDL IS NULL
            THEN 'MISSING_PROCEDURE'
        WHEN OBJECT_LANGUAGE <> 'PYTHON'
            THEN 'LANGUAGE_MISMATCH'
        WHEN OBJECT_OWNER <> 'SYSADMIN'
            THEN 'OWNER_MISMATCH'
        WHEN OBJECT_DDL_HASH <> EXPECTED_DDL_HASH
            THEN 'DDL_DRIFT_DETECTED'
        WHEN DYNAMIC_SQL_INDICATOR_COUNT <>
             EXPECTED_DYNAMIC_SQL_COUNT
            THEN 'DYNAMIC_SQL_COUNT_DRIFT'
        WHEN OWNER_RIGHTS_FLAG = FALSE
            THEN 'OWNER_RIGHTS_REQUIRED'
        WHEN FIXED_WAREHOUSE_REFERENCE_COUNT > 0
            THEN 'FIXED_WAREHOUSE_BLOCKER'
        WHEN TEMP_OBJECT_REFERENCE_COUNT > 0
            THEN 'TEMP_OBJECT_BLOCKER'
        WHEN PORTABLE_SOURCE_CANDIDATE IS NULL
            THEN 'MISSING_REVIEW_SOURCE'
        ELSE 'READY_FOR_EXPLICIT_REFACTOR'
    END,

    CURRENT_USER(),
    CURRENT_TIMESTAMP()
FROM FLAGS;

SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COUNT(*) = 4
            AND COUNT_IF(
                PREFLIGHT_STATUS =
                    'READY_FOR_EXPLICIT_REFACTOR'
            ) = 4,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),
    'phase', 'PHASE_14D_3D_1',
    'target_procedure_count', COUNT(*),
    'ready_procedure_count',
        COUNT_IF(
            PREFLIGHT_STATUS =
                'READY_FOR_EXPLICIT_REFACTOR'
        ),
    'owner_rights_count',
        COUNT_IF(OWNER_RIGHTS_FLAG = TRUE),
    'fixed_warehouse_blocker_count',
        COUNT_IF(FIXED_WAREHOUSE_COUNT > 0),
    'temporary_object_blocker_count',
        COUNT_IF(TEMP_OBJECT_COUNT > 0),
    'legacy_sql_escape_procedure_count',
        COUNT_IF(SQL_ESCAPE_REFERENCE_COUNT > 0),
    'current_qmark_bind_procedure_count',
        COUNT_IF(QMARK_BIND_REFERENCE_COUNT > 0),
    'runtime_placeholder_procedure_count',
        COUNT_IF(RUNTIME_PLACEHOLDER_COUNT > 0),
    'procedure_body_changed', FALSE,
    'candidate_source_executed', FALSE,
    'official_cost_changed', FALSE,
    'native_app_package_created', FALSE
) AS PHASE14D3D1_CONTRACT_SUMMARY
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_RFQ_CONTRACT_V1
WHERE PLAN_BATCH_ID =
      'PHASE14D3D1_PYTHON_RFQ_PLAN_V1';

SELECT
    REFACTOR_SEQUENCE,
    PROCEDURE_NAME,
    BUSINESS_DOMAIN,
    EXPECTED_DYNAMIC_SQL_COUNT,
    CURRENT_DYNAMIC_SQL_COUNT,
    SQL_ESCAPE_REFERENCE_COUNT,
    QMARK_BIND_REFERENCE_COUNT,
    NESTED_PROCEDURE_DEPENDENCY_COUNT,
    REFACTOR_STRATEGY,
    PREFLIGHT_STATUS
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_RFQ_CONTRACT_V1
WHERE PLAN_BATCH_ID =
      'PHASE14D3D1_PYTHON_RFQ_PLAN_V1'
ORDER BY REFACTOR_SEQUENCE;

CREATE TABLE IF NOT EXISTS
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_REFACTOR_RULE_V1 (
            PLAN_BATCH_ID VARCHAR NOT NULL,
            RULE_ORDER NUMBER NOT NULL,
            RULE_KEY VARCHAR NOT NULL,
            RULE_VALUE VARCHAR NOT NULL,
            REQUIRED_FLAG BOOLEAN NOT NULL,
            RULE_REASON VARCHAR NOT NULL
        );

DELETE FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_REFACTOR_RULE_V1
WHERE PLAN_BATCH_ID =
      'PHASE14D3D1_PYTHON_RFQ_PLAN_V1';

INSERT INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_REFACTOR_RULE_V1
VALUES
(
    'PHASE14D3D1_PYTHON_RFQ_PLAN_V1',
    1,
    'OBJECT_NAMESPACE',
    'CORE_INPUT / CORE_OUTPUT / CORE_INTERNAL',
    TRUE,
    'Use static schema-relative object names. Remove DB_NAME.'
),
(
    'PHASE14D3D1_PYTHON_RFQ_PLAN_V1',
    2,
    'VALUE_BINDING',
    'session.sql(sql_text, params=[...])',
    TRUE,
    'Use Snowpark qmark parameters for every data value.'
),
(
    'PHASE14D3D1_PYTHON_RFQ_PLAN_V1',
    3,
    'OBJECT_BINDING',
    'IDENTIFIER(?) only when an object name is genuinely variable',
    TRUE,
    'Do not concatenate untrusted object identifiers.'
),
(
    'PHASE14D3D1_PYTHON_RFQ_PLAN_V1',
    4,
    'PROCEDURE_CALLS',
    'Static CALL CORE_INTERNAL.PROCEDURE(?) with value binds',
    TRUE,
    'Procedure names are fixed dependencies, not user input.'
),
(
    'PHASE14D3D1_PYTHON_RFQ_PLAN_V1',
    5,
    'EXECUTION_RIGHTS',
    'EXECUTE AS OWNER',
    TRUE,
    'Preserve existing owner-rights execution.'
),
(
    'PHASE14D3D1_PYTHON_RFQ_PLAN_V1',
    6,
    'BUSINESS_LOGIC',
    'NO CHANGE',
    TRUE,
    'Preserve BMCS formula, review thresholds and quote flow.'
),
(
    'PHASE14D3D1_PYTHON_RFQ_PLAN_V1',
    7,
    'DEFERRED_ENGINE',
    'RUN_KMAT_COST_SIMULATION handled separately',
    TRUE,
    'The deterministic engine requires an isolated refactor gate.'
),
(
    'PHASE14D3D1_PYTHON_RFQ_PLAN_V1',
    8,
    'DEFERRED_STAGE',
    'RUN_CORTEX_RFQ_INTAKE_PIPELINE handled in Phase 14D.3E',
    TRUE,
    'The staged-document contract is a separate portability boundary.'
);

SELECT *
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_REFACTOR_RULE_V1
WHERE PLAN_BATCH_ID =
      'PHASE14D3D1_PYTHON_RFQ_PLAN_V1'
ORDER BY RULE_ORDER;

SELECT
    contract.REFACTOR_SEQUENCE,
    contract.PROCEDURE_NAME,
    contract.ARGUMENT_SIGNATURE,
    contract.BUSINESS_DOMAIN,
    contract.EXPECTED_DDL_HASH,
    contract.CURRENT_DDL_HASH,
    contract.NESTED_PROCEDURE_DEPENDENCY_COUNT,
    audit.OBJECT_DDL AS ORIGINAL_DDL,
    candidate.PORTABLE_SOURCE_CANDIDATE
        AS REVIEW_SOURCE_WITH_PLACEHOLDER
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_RFQ_CONTRACT_V1 contract
JOIN
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1 audit
  ON audit.AUDIT_BATCH_ID =
     'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
 AND audit.OBJECT_SCHEMA =
     contract.PROCEDURE_SCHEMA
 AND audit.OBJECT_NAME =
     contract.PROCEDURE_NAME
 AND audit.OBJECT_SIGNATURE =
     contract.ARGUMENT_SIGNATURE
JOIN
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PORTABLE_SOURCE_CANDIDATE_V1 candidate
  ON candidate.SOURCE_BATCH_ID =
     'PHASE14D3A_PORTABLE_SOURCE_CANDIDATE_V1'
 AND candidate.OBJECT_SCHEMA =
     contract.PROCEDURE_SCHEMA
 AND candidate.OBJECT_NAME =
     contract.PROCEDURE_NAME
 AND candidate.OBJECT_SIGNATURE =
     contract.ARGUMENT_SIGNATURE
WHERE contract.PLAN_BATCH_ID =
      'PHASE14D3D1_PYTHON_RFQ_PLAN_V1'
ORDER BY contract.REFACTOR_SEQUENCE;

WITH CONTRACT AS (
    SELECT
        COUNT(*) AS TARGET_COUNT,
        COUNT_IF(
            PREFLIGHT_STATUS =
                'READY_FOR_EXPLICIT_REFACTOR'
        ) AS READY_COUNT,
        COUNT_IF(
            OWNER_RIGHTS_FLAG = FALSE
        ) AS OWNER_RIGHTS_FAILURE_COUNT,
        COUNT_IF(
            FIXED_WAREHOUSE_COUNT > 0
        ) AS WAREHOUSE_BLOCKER_COUNT,
        COUNT_IF(
            TEMP_OBJECT_COUNT > 0
        ) AS TEMP_BLOCKER_COUNT,
        COUNT_IF(
            CURRENT_USER_COUNT > 0
            OR CURRENT_SESSION_COUNT > 0
        ) AS IDENTITY_SENSITIVE_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_PYTHON_RFQ_CONTRACT_V1
    WHERE PLAN_BATCH_ID =
          'PHASE14D3D1_PYTHON_RFQ_PLAN_V1'
),
DEFERRED_ENGINE AS (
    SELECT
        COUNT(*) AS ENGINE_COUNT,
        COUNT_IF(
            OBJECT_DDL_HASH =
                -4107916750694060430
        ) AS ENGINE_HASH_MATCH_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1
    WHERE AUDIT_BATCH_ID =
          'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
      AND OBJECT_SCHEMA = 'CORE_INTERNAL'
      AND OBJECT_NAME =
          'RUN_KMAT_COST_SIMULATION'
      AND OBJECT_SIGNATURE =
          '(SIMULATION_ID VARCHAR)'
),
DEFERRED_STAGE AS (
    SELECT
        COUNT(*) AS STAGE_COUNT,
        COUNT_IF(
            OBJECT_DDL_HASH =
                1228458495994061364
        ) AS STAGE_HASH_MATCH_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1
    WHERE AUDIT_BATCH_ID =
          'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
      AND OBJECT_SCHEMA = 'CORE_INTERNAL'
      AND OBJECT_NAME =
          'RUN_CORTEX_RFQ_INTAKE_PIPELINE'
      AND OBJECT_SIGNATURE =
          '(RFQ_ID VARCHAR)'
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            CONTRACT.TARGET_COUNT = 4
            AND CONTRACT.READY_COUNT = 4
            AND CONTRACT.OWNER_RIGHTS_FAILURE_COUNT = 0
            AND CONTRACT.WAREHOUSE_BLOCKER_COUNT = 0
            AND CONTRACT.TEMP_BLOCKER_COUNT = 0
            AND CONTRACT.IDENTITY_SENSITIVE_COUNT = 0
            AND DEFERRED_ENGINE.ENGINE_COUNT = 1
            AND DEFERRED_ENGINE.ENGINE_HASH_MATCH_COUNT = 1
            AND DEFERRED_STAGE.STAGE_COUNT = 1
            AND DEFERRED_STAGE.STAGE_HASH_MATCH_COUNT = 1,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),
    'phase', 'PHASE_14D_3D_1',
    'target_procedure_count',
        CONTRACT.TARGET_COUNT,
    'ready_procedure_count',
        CONTRACT.READY_COUNT,
    'owner_rights_failure_count',
        CONTRACT.OWNER_RIGHTS_FAILURE_COUNT,
    'fixed_warehouse_blocker_count',
        CONTRACT.WAREHOUSE_BLOCKER_COUNT,
    'temporary_object_blocker_count',
        CONTRACT.TEMP_BLOCKER_COUNT,
    'identity_sensitive_procedure_count',
        CONTRACT.IDENTITY_SENSITIVE_COUNT,
    'deferred_deterministic_engine_count',
        DEFERRED_ENGINE.ENGINE_COUNT,
    'deferred_engine_hash_match_count',
        DEFERRED_ENGINE.ENGINE_HASH_MATCH_COUNT,
    'deferred_stage_procedure_count',
        DEFERRED_STAGE.STAGE_COUNT,
    'deferred_stage_hash_match_count',
        DEFERRED_STAGE.STAGE_HASH_MATCH_COUNT,
    'procedure_body_changed', FALSE,
    'refactored_source_executed', FALSE,
    'official_cost_changed', FALSE,
    'ml_authority_changed', FALSE,
    'native_app_package_created', FALSE
) AS PHASE14D3D1_FINAL_GATE
FROM CONTRACT
CROSS JOIN DEFERRED_ENGINE
CROSS JOIN DEFERRED_STAGE;

WITH baseline AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_BASELINE_V1
    WHERE BASELINE_ID =
          'PHASE14A_SIM_001_BASELINE_V1'
),
current_state AS (
    SELECT
        s.SIMULATION_ID,
        HASH(
            s.MATERIAL_COST_USD,
            s.LABOR_COST_USD,
            s.MACHINE_COST_USD,
            s.OVERHEAD_COST_USD,
            s.TOTAL_CONFIGURED_COST_USD,
            s.FLOOR_PRICE_USD,
            s.TARGET_PRICE_USD,
            s.CEILING_PRICE_USD,
            s.BASELINE_TOTAL_COST_USD,
            s.RISK_ADJUSTED_TOTAL_COST_USD,
            s.TOTAL_RISK_UPLIFT_USD,
            s.TOTAL_RISK_UPLIFT_PCT,
            s.CSS_SCORE,
            s.SCRAP_RATE_APPLIED,
            s.AVG_WEIGHTED_FMIS,
            s.MAX_TDS_FACTOR,
            s.BOM_MATCH_CONFIDENCE_SCORE,
            s.BMCS_REVIEW_STATUS,
            s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
            s.QUOTE_TRUST_STATUS,
            h.RESOLVED_SCRAP_RATE,
            h.CSS_RESOLVED_SOURCE,
            h.RESOLVED_FMIS_MULTIPLIER,
            h.FMIS_RESOLVED_SOURCE,
            h.RESOLVED_TDS_FACTOR,
            h.TDS_RESOLVED_SOURCE,
            h.RESOLVED_BMCS_STATUS,
            h.SAFETY_GATE_PASS_FLAG,
            h.COST_ENGINE_CONSUMPTION_ALLOWED_FLAG,
            h.OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG
        ) AS SNAPSHOT_HASH,
        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS ACTIVE_POLICY_COUNT,
        (
            SELECT COUNT_IF(
                DEPLOYMENT_MODE = 'SHADOW'
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS SHADOW_POLICY_COUNT,
        (
            SELECT COUNT_IF(
                AUTO_USE_ALLOWED_FLAG = TRUE
                OR OFFICIAL_COST_IMPACT_ALLOWED_FLAG = TRUE
                OR BUSINESS_DECISION_ALLOWED_FLAG = TRUE
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS POLICY_AUTHORITY_ENABLED_COUNT,
        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .ML_RUNTIME_AUTHORITY_REGISTRY_V1
            WHERE UPPER(AUTHORITY_STATUS) = 'ENABLED'
        ) AS ENABLED_RUNTIME_AUTHORITY_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_OUTPUT
            .KMAT_CONFIGURED_COST_SUMMARY s
    LEFT JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .VW_KMAT_PHASE10B_HIERARCHY_V1 h
      ON s.SIMULATION_ID = h.SIMULATION_ID
    WHERE s.SIMULATION_ID = 'SIM_001'
    QUALIFY ROW_NUMBER() OVER (
        PARTITION BY s.SIMULATION_ID
        ORDER BY s.CALCULATED_AT DESC
    ) = 1
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            baseline.SNAPSHOT_HASH =
                current_state.SNAPSHOT_HASH
            AND current_state
                .POLICY_AUTHORITY_ENABLED_COUNT = 0
            AND current_state
                .ENABLED_RUNTIME_AUTHORITY_COUNT = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),
    'phase', 'PHASE_14D_3D_1',
    'baseline_id', baseline.BASELINE_ID,
    'simulation_id', baseline.SIMULATION_ID,
    'baseline_snapshot_hash',
        baseline.SNAPSHOT_HASH,
    'current_snapshot_hash',
        current_state.SNAPSHOT_HASH,
    'cost_and_governance_snapshot_match',
        baseline.SNAPSHOT_HASH =
        current_state.SNAPSHOT_HASH,
    'active_policy_count',
        current_state.ACTIVE_POLICY_COUNT,
    'shadow_policy_count',
        current_state.SHADOW_POLICY_COUNT,
    'policy_authority_enabled_count',
        current_state.POLICY_AUTHORITY_ENABLED_COUNT,
    'enabled_runtime_authority_count',
        current_state.ENABLED_RUNTIME_AUTHORITY_COUNT,
    'official_cost_changed',
        baseline.SNAPSHOT_HASH <>
        current_state.SNAPSHOT_HASH,
    'procedure_body_changed', FALSE,
    'refactored_source_executed', FALSE,
    'ml_authority_changed', FALSE,
    'native_app_package_created', FALSE
) AS PHASE14D3D1_BASELINE_VERIFICATION
FROM baseline
CROSS JOIN current_state;

CREATE TABLE IF NOT EXISTS
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1 (
            CANDIDATE_ID VARCHAR NOT NULL,
            PHASE VARCHAR NOT NULL,
            PROCEDURE_SCHEMA VARCHAR NOT NULL,
            PROCEDURE_NAME VARCHAR NOT NULL,
            ARGUMENT_SIGNATURE VARCHAR NOT NULL,
            ORIGINAL_DDL_HASH NUMBER NOT NULL,
            CANDIDATE_SOURCE VARCHAR NOT NULL,
            CANDIDATE_SOURCE_HASH NUMBER NOT NULL,
            FIXED_DATABASE_REFERENCE_COUNT NUMBER NOT NULL,
            DB_NAME_CONSTANT_COUNT NUMBER NOT NULL,
            SQL_ESCAPE_REFERENCE_COUNT NUMBER NOT NULL,
            QMARK_PARAMETER_COUNT NUMBER NOT NULL,
            PARAMS_ARGUMENT_COUNT NUMBER NOT NULL,
            SCHEMA_RELATIVE_REFERENCE_COUNT NUMBER NOT NULL,
            OWNER_RIGHTS_REQUIRED_FLAG BOOLEAN NOT NULL,
            BUSINESS_LOGIC_CHANGED_FLAG BOOLEAN NOT NULL,
            DEPLOYMENT_READY_FLAG BOOLEAN NOT NULL,
            CANDIDATE_STATUS VARCHAR NOT NULL,
            RECORDED_BY VARCHAR NOT NULL,
            RECORDED_AT TIMESTAMP_NTZ NOT NULL
        );

DELETE FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1
WHERE CANDIDATE_ID =
      'PHASE14D3D2A_PREPARE_RFQ_V1';

INSERT INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1
WITH SOURCE AS (
    SELECT $$
import json
import re


def normalize_text(value):
    if value is None:
        return ""
    return str(value).strip().upper()


def parse_json(value):
    if value is None:
        return {}

    if isinstance(value, dict):
        return value

    if isinstance(value, str):
        try:
            return json.loads(value)
        except Exception:
            return {}

    try:
        return dict(value)
    except Exception:
        return {}


def run(session, RFQ_ID):
    rows = session.sql(
        """
        SELECT
            h.RFQ_ID,
            h.KMAT_ID,
            h.CUSTOMER_ID,
            h.CUSTOMER_NAME,
            h.SOURCE_DOCUMENT_NAME,
            c.SIMULATION_ID,
            c.CONFIGURATION_VERSION,
            TO_JSON(
                c.EXTRACTED_CONFIGURATION_JSON
            ) AS CONFIG_JSON_STR
        FROM CORE_INPUT.RFQ_HEADER h
        JOIN CORE_INPUT.RFQ_CONFIGURATION c
            ON h.RFQ_ID = c.RFQ_ID
           AND h.KMAT_ID = c.KMAT_ID
        WHERE h.RFQ_ID = ?
          AND c.ACTIVE_FLAG = TRUE
        QUALIFY ROW_NUMBER() OVER (
            PARTITION BY h.RFQ_ID
            ORDER BY
                c.CONFIGURATION_VERSION DESC,
                c.CREATED_AT DESC
        ) = 1
        """,
        params=[RFQ_ID],
    ).collect()

    if len(rows) == 0:
        return json.dumps({
            "status": "ERROR",
            "message": (
                "No active RFQ configuration found "
                f"for RFQ_ID={RFQ_ID}"
            ),
        })

    row = rows[0]

    kmat_id = row["KMAT_ID"]
    simulation_id = row["SIMULATION_ID"]
    customer_id = row["CUSTOMER_ID"]
    source_document_name = row["SOURCE_DOCUMENT_NAME"]
    config_json = parse_json(row["CONFIG_JSON_STR"])

    if not config_json:
        return json.dumps({
            "status": "ERROR",
            "message": (
                "Extracted configuration JSON is empty "
                f"for RFQ_ID={RFQ_ID}"
            ),
        })

    allowed_rows = session.sql(
        """
        SELECT
            CHARACTERISTIC_NAME,
            ALLOWED_VALUE
        FROM CORE_INPUT.CHARACTERISTIC_MASTER
        WHERE KMAT_ID = ?
          AND ACTIVE_FLAG = TRUE
        """,
        params=[kmat_id],
    ).collect()

    allowed_map = {}

    for allowed_row in allowed_rows:
        char_name = normalize_text(
            allowed_row["CHARACTERISTIC_NAME"]
        )
        allowed_value = normalize_text(
            allowed_row["ALLOWED_VALUE"]
        )

        if char_name not in allowed_map:
            allowed_map[char_name] = set()

        allowed_map[char_name].add(allowed_value)

    selected_values = {}

    for char_name in allowed_map.keys():
        extracted_value = normalize_text(
            config_json.get(char_name)
        )

        if extracted_value == "":
            return json.dumps({
                "status": "ERROR",
                "message": (
                    "Missing extracted value for required "
                    f"characteristic {char_name}"
                ),
                "rfq_id": RFQ_ID,
                "simulation_id": simulation_id,
            })

        if extracted_value not in allowed_map[char_name]:
            return json.dumps({
                "status": "ERROR",
                "message": (
                    f"Invalid extracted value {extracted_value} "
                    f"for characteristic {char_name}"
                ),
                "rfq_id": RFQ_ID,
                "simulation_id": simulation_id,
            })

        selected_values[char_name] = extracted_value

    session.sql(
        """
        DELETE FROM CORE_INPUT.CHARACTERISTIC_VALUES
        WHERE SIMULATION_ID = ?
        """,
        params=[simulation_id],
    ).collect()

    session.sql(
        """
        DELETE FROM CORE_INPUT.SIMULATION_PARAMETERS
        WHERE SIMULATION_ID = ?
        """,
        params=[simulation_id],
    ).collect()

    session.sql(
        """
        DELETE FROM CORE_INPUT.SIMULATION_PRODUCTION_CONTEXT
        WHERE SIMULATION_ID = ?
        """,
        params=[simulation_id],
    ).collect()

    session.sql(
        """
        DELETE FROM CORE_INPUT.SIMULATION_HEADER
        WHERE SIMULATION_ID = ?
        """,
        params=[simulation_id],
    ).collect()

    scenario_name = (
        f"RFQ Cost Simulation - {RFQ_ID} - "
        f"{source_document_name}"
    )

    session.sql(
        """
        INSERT INTO CORE_INPUT.SIMULATION_HEADER
        (
            SIMULATION_ID,
            KMAT_ID,
            CUSTOMER_ID,
            SCENARIO_NAME
        )
        VALUES (?, ?, ?, ?)
        """,
        params=[
            simulation_id,
            kmat_id,
            customer_id,
            scenario_name,
        ],
    ).collect()

    value_params = [
        (
            simulation_id,
            kmat_id,
            char_name,
            selected_value,
        )
        for char_name, selected_value
        in selected_values.items()
    ]

    values_clause = ", ".join(
        ["(?, ?, ?, ?)"] * len(value_params)
    )

    flattened_value_params = [
        value
        for value_row in value_params
        for value in value_row
    ]

    session.sql(
        f"""
        INSERT INTO CORE_INPUT.CHARACTERISTIC_VALUES
        (
            SIMULATION_ID,
            KMAT_ID,
            CHARACTERISTIC_NAME,
            SELECTED_VALUE
        )
        VALUES {values_clause}
        """,
        params=flattened_value_params,
    ).collect()

    session.sql(
        """
        INSERT INTO CORE_INPUT.SIMULATION_PARAMETERS
        (
            SIMULATION_ID,
            MATERIAL_COST_MULTIPLIER,
            LABOR_RATE_MULTIPLIER,
            MACHINE_RATE_MULTIPLIER,
            OVERHEAD_MULTIPLIER,
            TARGET_MARGIN_PCT,
            FLOOR_MARKUP_PCT,
            CEILING_MARKUP_PCT
        )
        VALUES
        (
            ?,
            1.00,
            1.00,
            1.00,
            1.00,
            0.35,
            0.10,
            0.60
        )
        """,
        params=[simulation_id],
    ).collect()

    session.sql(
        """
        INSERT INTO CORE_INPUT.SIMULATION_PRODUCTION_CONTEXT
        (
            SIMULATION_ID,
            KMAT_ID,
            PLANT_ID,
            PRODUCTION_LINE_ID,
            PLANNED_PRODUCTION_DATE,
            BATCH_QUANTITY
        )
        VALUES
        (
            ?,
            ?,
            'PLANT_US_01',
            'TRUCK_LINE_01',
            '2026-09-15',
            10
        )
        """,
        params=[
            simulation_id,
            kmat_id,
        ],
    ).collect()

    return json.dumps({
        "status": "SUCCESS",
        "rfq_id": RFQ_ID,
        "simulation_id": simulation_id,
        "kmat_id": kmat_id,
        "selected_values": selected_values,
        "message": (
            "RFQ extracted configuration copied into "
            "normal simulation input tables."
        ),
    })

$$ AS CANDIDATE_SOURCE
)
SELECT
    'PHASE14D3D2A_PREPARE_RFQ_V1',
    'PHASE_14D_3D_2A',
    'CORE_INTERNAL',
    'PREPARE_RFQ_SIMULATION_INPUTS',
    '(RFQ_ID VARCHAR)',
    -6251348384323678794,
    CANDIDATE_SOURCE,
    HASH(CANDIDATE_SOURCE),

    REGEXP_COUNT(
        UPPER(CANDIDATE_SOURCE),
        'KMAT_COST_MODEL_DB'
    ),

    REGEXP_COUNT(
        CANDIDATE_SOURCE,
        'DB_NAME[[:space:]]*='
    ),

    REGEXP_COUNT(
        CANDIDATE_SOURCE,
        'sql_escape[[:space:]]*[(]'
    ),

    REGEXP_COUNT(
        CANDIDATE_SOURCE,
        '[?]'
    ),

    REGEXP_COUNT(
        CANDIDATE_SOURCE,
        'params[[:space:]]*='
    ),

    REGEXP_COUNT(
        UPPER(CANDIDATE_SOURCE),
        'CORE_INPUT[.]'
    ),

    TRUE,
    FALSE,
    FALSE,

    CASE
        WHEN REGEXP_COUNT(
            UPPER(CANDIDATE_SOURCE),
            'KMAT_COST_MODEL_DB'
        ) > 0
            THEN 'FIXED_DATABASE_REMAINS'

        WHEN REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'DB_NAME[[:space:]]*='
        ) > 0
            THEN 'DB_NAME_CONSTANT_REMAINS'

        WHEN REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'sql_escape[[:space:]]*[(]'
        ) > 0
            THEN 'LEGACY_SQL_ESCAPE_REMAINS'

        WHEN REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'params[[:space:]]*='
        ) < 10
            THEN 'INSUFFICIENT_VALUE_BINDING'

        ELSE 'STATIC_REVIEW_PASSED'
    END,

    CURRENT_USER(),
    CURRENT_TIMESTAMP()

FROM SOURCE;


SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COUNT(*) = 1
            AND COUNT_IF(
                CANDIDATE_STATUS =
                    'STATIC_REVIEW_PASSED'
            ) = 1
            AND SUM(
                FIXED_DATABASE_REFERENCE_COUNT
            ) = 0
            AND SUM(
                DB_NAME_CONSTANT_COUNT
            ) = 0
            AND SUM(
                SQL_ESCAPE_REFERENCE_COUNT
            ) = 0
            AND MIN(
                PARAMS_ARGUMENT_COUNT
            ) >= 10
            AND COUNT_IF(
                BUSINESS_LOGIC_CHANGED_FLAG = TRUE
            ) = 0
            AND COUNT_IF(
                DEPLOYMENT_READY_FLAG = TRUE
            ) = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3D_2A',

    'candidate_id',
        'PHASE14D3D2A_PREPARE_RFQ_V1',

    'candidate_count',
        COUNT(*),

    'fixed_database_reference_count',
        SUM(
            FIXED_DATABASE_REFERENCE_COUNT
        ),

    'db_name_constant_count',
        SUM(
            DB_NAME_CONSTANT_COUNT
        ),

    'sql_escape_reference_count',
        SUM(
            SQL_ESCAPE_REFERENCE_COUNT
        ),

    'qmark_parameter_count',
        SUM(
            QMARK_PARAMETER_COUNT
        ),

    'params_argument_count',
        SUM(
            PARAMS_ARGUMENT_COUNT
        ),

    'schema_relative_reference_count',
        SUM(
            SCHEMA_RELATIVE_REFERENCE_COUNT
        ),

    'business_logic_changed',
        BOOLOR_AGG(
            BUSINESS_LOGIC_CHANGED_FLAG
        ),

    'deployment_ready_count',
        COUNT_IF(
            DEPLOYMENT_READY_FLAG = TRUE
        ),

    'procedure_body_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3D2A_CANDIDATE_SUMMARY

FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1
WHERE CANDIDATE_ID =
      'PHASE14D3D2A_PREPARE_RFQ_V1';

WITH CANDIDATE AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1
    WHERE CANDIDATE_ID =
          'PHASE14D3D2A_PREPARE_RFQ_V1'
),
ORIGINAL AS (
    SELECT
        OBJECT_DDL_HASH
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1
    WHERE AUDIT_BATCH_ID =
          'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
      AND OBJECT_SCHEMA = 'CORE_INTERNAL'
      AND OBJECT_NAME =
          'PREPARE_RFQ_SIMULATION_INPUTS'
      AND OBJECT_SIGNATURE =
          '(RFQ_ID VARCHAR)'
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            CANDIDATE.CANDIDATE_STATUS =
                'STATIC_REVIEW_PASSED'
            AND ORIGINAL.OBJECT_DDL_HASH =
                CANDIDATE.ORIGINAL_DDL_HASH
            AND CANDIDATE
                .FIXED_DATABASE_REFERENCE_COUNT = 0
            AND CANDIDATE.DB_NAME_CONSTANT_COUNT = 0
            AND CANDIDATE
                .SQL_ESCAPE_REFERENCE_COUNT = 0
            AND CANDIDATE
                .PARAMS_ARGUMENT_COUNT >= 10
            AND CANDIDATE
                .BUSINESS_LOGIC_CHANGED_FLAG = FALSE
            AND CANDIDATE
                .DEPLOYMENT_READY_FLAG = FALSE,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3D_2A',

    'candidate_id',
        CANDIDATE.CANDIDATE_ID,

    'original_ddl_hash',
        ORIGINAL.OBJECT_DDL_HASH,

    'expected_original_ddl_hash',
        CANDIDATE.ORIGINAL_DDL_HASH,

    'candidate_source_hash',
        CANDIDATE.CANDIDATE_SOURCE_HASH,

    'fixed_database_reference_count',
        CANDIDATE
            .FIXED_DATABASE_REFERENCE_COUNT,

    'db_name_constant_count',
        CANDIDATE.DB_NAME_CONSTANT_COUNT,

    'sql_escape_reference_count',
        CANDIDATE.SQL_ESCAPE_REFERENCE_COUNT,

    'params_argument_count',
        CANDIDATE.PARAMS_ARGUMENT_COUNT,

    'business_logic_changed',
        CANDIDATE.BUSINESS_LOGIC_CHANGED_FLAG,

    'deployment_ready',
        CANDIDATE.DEPLOYMENT_READY_FLAG,

    'procedure_body_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3D2A_FINAL_GATE

FROM CANDIDATE
CROSS JOIN ORIGINAL;


WITH baseline AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_BASELINE_V1
    WHERE BASELINE_ID =
          'PHASE14A_SIM_001_BASELINE_V1'
),
current_state AS (
    SELECT
        s.SIMULATION_ID,

        HASH(
            s.MATERIAL_COST_USD,
            s.LABOR_COST_USD,
            s.MACHINE_COST_USD,
            s.OVERHEAD_COST_USD,
            s.TOTAL_CONFIGURED_COST_USD,
            s.FLOOR_PRICE_USD,
            s.TARGET_PRICE_USD,
            s.CEILING_PRICE_USD,
            s.BASELINE_TOTAL_COST_USD,
            s.RISK_ADJUSTED_TOTAL_COST_USD,
            s.TOTAL_RISK_UPLIFT_USD,
            s.TOTAL_RISK_UPLIFT_PCT,
            s.CSS_SCORE,
            s.SCRAP_RATE_APPLIED,
            s.AVG_WEIGHTED_FMIS,
            s.MAX_TDS_FACTOR,
            s.BOM_MATCH_CONFIDENCE_SCORE,
            s.BMCS_REVIEW_STATUS,
            s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
            s.QUOTE_TRUST_STATUS,
            h.RESOLVED_SCRAP_RATE,
            h.CSS_RESOLVED_SOURCE,
            h.RESOLVED_FMIS_MULTIPLIER,
            h.FMIS_RESOLVED_SOURCE,
            h.RESOLVED_TDS_FACTOR,
            h.TDS_RESOLVED_SOURCE,
            h.RESOLVED_BMCS_STATUS,
            h.SAFETY_GATE_PASS_FLAG,
            h.COST_ENGINE_CONSUMPTION_ALLOWED_FLAG,
            h.OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG
        ) AS SNAPSHOT_HASH,

        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS ACTIVE_POLICY_COUNT,

        (
            SELECT COUNT_IF(
                DEPLOYMENT_MODE = 'SHADOW'
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS SHADOW_POLICY_COUNT,

        (
            SELECT COUNT_IF(
                AUTO_USE_ALLOWED_FLAG = TRUE
                OR OFFICIAL_COST_IMPACT_ALLOWED_FLAG = TRUE
                OR BUSINESS_DECISION_ALLOWED_FLAG = TRUE
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS POLICY_AUTHORITY_ENABLED_COUNT,

        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .ML_RUNTIME_AUTHORITY_REGISTRY_V1
            WHERE UPPER(AUTHORITY_STATUS) = 'ENABLED'
        ) AS ENABLED_RUNTIME_AUTHORITY_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_OUTPUT
            .KMAT_CONFIGURED_COST_SUMMARY s

    LEFT JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .VW_KMAT_PHASE10B_HIERARCHY_V1 h
      ON s.SIMULATION_ID = h.SIMULATION_ID

    WHERE s.SIMULATION_ID = 'SIM_001'

    QUALIFY ROW_NUMBER() OVER (
        PARTITION BY s.SIMULATION_ID
        ORDER BY s.CALCULATED_AT DESC
    ) = 1
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            baseline.SNAPSHOT_HASH =
                current_state.SNAPSHOT_HASH
            AND current_state
                .POLICY_AUTHORITY_ENABLED_COUNT = 0
            AND current_state
                .ENABLED_RUNTIME_AUTHORITY_COUNT = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3D_2A',

    'baseline_snapshot_hash',
        baseline.SNAPSHOT_HASH,

    'current_snapshot_hash',
        current_state.SNAPSHOT_HASH,

    'cost_and_governance_snapshot_match',
        baseline.SNAPSHOT_HASH =
        current_state.SNAPSHOT_HASH,

    'active_policy_count',
        current_state.ACTIVE_POLICY_COUNT,

    'shadow_policy_count',
        current_state.SHADOW_POLICY_COUNT,

    'policy_authority_enabled_count',
        current_state
            .POLICY_AUTHORITY_ENABLED_COUNT,

    'enabled_runtime_authority_count',
        current_state
            .ENABLED_RUNTIME_AUTHORITY_COUNT,

    'official_cost_changed',
        baseline.SNAPSHOT_HASH <>
        current_state.SNAPSHOT_HASH,

    'procedure_body_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3D2A_BASELINE_VERIFICATION

FROM baseline
CROSS JOIN current_state;

DELETE FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1
WHERE CANDIDATE_ID =
      'PHASE14D3D2B_RULE_BMCS_V1';

INSERT INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1
WITH SOURCE AS (
    SELECT $$
import json
import re


def normalize_text(value):
    if value is None:
        return ""
    return str(value).strip().upper()


def normalize_for_matching(value):
    if value is None:
        return ""

    text = str(value).lower()
    text = re.sub(r"[^a-z0-9]+", " ", text)
    text = re.sub(r"\s+", " ", text).strip()
    return text


def parse_variant(value):
    if value is None:
        return {}

    if isinstance(value, dict):
        return value

    if isinstance(value, str):
        try:
            return json.loads(value)
        except Exception:
            return {}

    try:
        return dict(value)
    except Exception:
        return {}


def calculate_bmcs(
    required_count,
    valid_count,
    evidence_count,
    source_text_normalized,
):
    valid_ratio = valid_count / required_count
    evidence_ratio = evidence_count / required_count

    validity_component = valid_ratio * 55.00
    evidence_component = evidence_ratio * 41.00

    ambiguity_terms = [
        "not fully specified",
        "not specified",
        "unclear",
        "not clear",
        "unknown",
        "not confirmed",
    ]

    matched_ambiguity_terms = [
        term
        for term in ambiguity_terms
        if (
            normalize_for_matching(term)
            in source_text_normalized
        )
    ]

    ambiguity_penalty = (
        7.75
        if matched_ambiguity_terms
        else 0.00
    )

    bmcs_score = (
        validity_component
        + evidence_component
        - ambiguity_penalty
    )
    bmcs_score = max(
        0.00,
        min(100.00, bmcs_score),
    )

    return {
        "validity_component": round(
            validity_component,
            2,
        ),
        "evidence_component": round(
            evidence_component,
            2,
        ),
        "ambiguity_penalty": round(
            ambiguity_penalty,
            2,
        ),
        "matched_ambiguity_terms":
            matched_ambiguity_terms,
        "bmcs_score": round(
            bmcs_score,
            2,
        ),
    }


def insert_detail_row(
    session,
    rfq_id,
    simulation_id,
    kmat_id,
    configuration_version,
    characteristic_name,
    extracted_value,
    valid_value_flag,
    matched_signal_flag,
    matched_signal_phrases,
    notes,
):
    session.sql(
        """
        INSERT INTO CORE_INPUT.BMCS_SCORING_DETAIL
        (
            RFQ_ID,
            SIMULATION_ID,
            KMAT_ID,
            CONFIGURATION_VERSION,
            CHARACTERISTIC_NAME,
            EXTRACTED_VALUE,
            VALID_VALUE_FLAG,
            MATCHED_SIGNAL_FLAG,
            MATCHED_SIGNAL_PHRASES,
            CHARACTERISTIC_SCORE_NOTES
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        params=[
            rfq_id,
            simulation_id,
            kmat_id,
            configuration_version,
            characteristic_name,
            extracted_value,
            valid_value_flag,
            matched_signal_flag,
            matched_signal_phrases,
            notes,
        ],
    ).collect()


def run(session, RFQ_ID):
    rows = session.sql(
        """
        SELECT
            h.RFQ_ID,
            h.KMAT_ID,
            h.CUSTOMER_ID,
            h.CUSTOMER_NAME,
            h.SOURCE_DOCUMENT_NAME,
            h.SOURCE_DOCUMENT_TEXT,
            c.SIMULATION_ID,
            c.CONFIGURATION_VERSION,
            TO_JSON(
                c.EXTRACTED_CONFIGURATION_JSON
            ) AS EXTRACTED_CONFIGURATION_JSON_STR
        FROM CORE_INPUT.RFQ_HEADER h
        JOIN CORE_INPUT.RFQ_CONFIGURATION c
            ON h.RFQ_ID = c.RFQ_ID
           AND h.KMAT_ID = c.KMAT_ID
        WHERE h.RFQ_ID = ?
          AND c.ACTIVE_FLAG = TRUE
        QUALIFY ROW_NUMBER() OVER (
            PARTITION BY h.RFQ_ID
            ORDER BY
                c.CONFIGURATION_VERSION DESC,
                c.CREATED_AT DESC
        ) = 1
        """,
        params=[RFQ_ID],
    ).collect()

    if len(rows) == 0:
        return json.dumps({
            "status": "ERROR",
            "message": (
                "No active RFQ configuration found "
                f"for RFQ_ID={RFQ_ID}"
            ),
        })

    row = rows[0]

    kmat_id = row["KMAT_ID"]
    simulation_id = row["SIMULATION_ID"]
    configuration_version = int(
        row["CONFIGURATION_VERSION"]
    )

    source_text = (
        row["SOURCE_DOCUMENT_TEXT"]
        or ""
    )
    source_text_normalized = (
        normalize_for_matching(source_text)
    )

    extracted_config = parse_variant(
        row[
            "EXTRACTED_CONFIGURATION_JSON_STR"
        ]
    )

    allowed_rows = session.sql(
        """
        SELECT
            CHARACTERISTIC_NAME,
            ALLOWED_VALUE
        FROM CORE_INPUT.CHARACTERISTIC_MASTER
        WHERE KMAT_ID = ?
          AND ACTIVE_FLAG = TRUE
        ORDER BY
            DISPLAY_ORDER,
            CHARACTERISTIC_NAME,
            ALLOWED_VALUE
        """,
        params=[kmat_id],
    ).collect()

    allowed_map = {}

    for allowed_row in allowed_rows:
        characteristic_name = normalize_text(
            allowed_row["CHARACTERISTIC_NAME"]
        )
        allowed_value = normalize_text(
            allowed_row["ALLOWED_VALUE"]
        )

        if characteristic_name not in allowed_map:
            allowed_map[characteristic_name] = set()

        allowed_map[
            characteristic_name
        ].add(allowed_value)

    required_characteristics = list(
        allowed_map.keys()
    )
    required_count = len(
        required_characteristics
    )

    if required_count == 0:
        return json.dumps({
            "status": "ERROR",
            "message": (
                "No active KMAT characteristics found "
                f"for KMAT_ID={kmat_id}"
            ),
        })

    signal_rows = session.sql(
        """
        SELECT
            CHARACTERISTIC_NAME,
            CHARACTERISTIC_VALUE,
            SIGNAL_PHRASE,
            SIGNAL_WEIGHT
        FROM CORE_INPUT.BMCS_TEXT_SIGNAL_RULES
        WHERE KMAT_ID = ?
          AND ACTIVE_FLAG = TRUE
        """,
        params=[kmat_id],
    ).collect()

    signal_rules = []

    for signal_row in signal_rows:
        signal_rules.append({
            "characteristic_name":
                normalize_text(
                    signal_row[
                        "CHARACTERISTIC_NAME"
                    ]
                ),
            "characteristic_value":
                normalize_text(
                    signal_row[
                        "CHARACTERISTIC_VALUE"
                    ]
                ),
            "signal_phrase_original":
                str(
                    signal_row["SIGNAL_PHRASE"]
                ),
            "signal_phrase_normalized":
                normalize_for_matching(
                    signal_row["SIGNAL_PHRASE"]
                ),
            "signal_weight":
                float(
                    signal_row["SIGNAL_WEIGHT"]
                    or 0
                ),
        })

    session.sql(
        """
        DELETE FROM CORE_INPUT.BMCS_SCORING_DETAIL
        WHERE RFQ_ID = ?
          AND CONFIGURATION_VERSION = ?
        """,
        params=[
            RFQ_ID,
            configuration_version,
        ],
    ).collect()

    valid_count = 0
    evidence_count = 0
    detail_results = []

    for characteristic_name in (
        required_characteristics
    ):
        extracted_value = normalize_text(
            extracted_config.get(
                characteristic_name
            )
        )

        valid_value_flag = (
            extracted_value != ""
            and extracted_value
            in allowed_map.get(
                characteristic_name,
                set(),
            )
        )

        matched_phrases = []

        if valid_value_flag:
            valid_count += 1

            for rule in signal_rules:
                if (
                    rule["characteristic_name"]
                    == characteristic_name
                    and rule[
                        "characteristic_value"
                    ]
                    == extracted_value
                    and rule[
                        "signal_phrase_normalized"
                    ]
                    != ""
                    and rule[
                        "signal_phrase_normalized"
                    ]
                    in source_text_normalized
                ):
                    matched_phrases.append(
                        rule[
                            "signal_phrase_original"
                        ]
                    )

        matched_signal_flag = (
            len(matched_phrases) > 0
        )

        if matched_signal_flag:
            evidence_count += 1
            notes = (
                "Extracted value is valid and "
                "supported by RFQ text."
            )
        elif valid_value_flag:
            notes = (
                "Extracted value is valid, but "
                "direct text evidence was not "
                "found. Treated as inferred."
            )
        else:
            notes = (
                "Extracted value is missing or "
                "invalid for this KMAT "
                "characteristic."
            )

        matched_signal_phrases = ", ".join(
            sorted(set(matched_phrases))
        )

        insert_detail_row(
            session=session,
            rfq_id=RFQ_ID,
            simulation_id=simulation_id,
            kmat_id=kmat_id,
            configuration_version=(
                configuration_version
            ),
            characteristic_name=(
                characteristic_name
            ),
            extracted_value=extracted_value,
            valid_value_flag=valid_value_flag,
            matched_signal_flag=(
                matched_signal_flag
            ),
            matched_signal_phrases=(
                matched_signal_phrases
            ),
            notes=notes,
        )

        detail_results.append({
            "characteristic_name":
                characteristic_name,
            "extracted_value":
                extracted_value,
            "valid_value_flag":
                valid_value_flag,
            "matched_signal_flag":
                matched_signal_flag,
            "matched_signal_phrases":
                matched_signal_phrases,
        })

    score = calculate_bmcs(
        required_count=required_count,
        valid_count=valid_count,
        evidence_count=evidence_count,
        source_text_normalized=(
            source_text_normalized
        ),
    )

    bmcs_score = score["bmcs_score"]

    review_rows = session.sql(
        """
        SELECT
            REVIEW_STATUS,
            REVIEW_REQUIRED_FLAG,
            FINAL_TRUSTED_COST_ALLOWED_FLAG,
            BUSINESS_ACTION
        FROM CORE_INPUT.BMCS_REVIEW_RULES
        WHERE ? BETWEEN MIN_SCORE AND MAX_SCORE
          AND ACTIVE_FLAG = TRUE
        LIMIT 1
        """,
        params=[bmcs_score],
    ).collect()

    if len(review_rows) == 0:
        review_status = "REVIEW_REQUIRED"
        review_required_flag = True
        final_trusted_cost_allowed_flag = False
        business_action = (
            "BMCS review rule missing. "
            "Defaulted to engineering review "
            "required."
        )
    else:
        review_status = (
            review_rows[0]["REVIEW_STATUS"]
        )
        review_required_flag = bool(
            review_rows[0][
                "REVIEW_REQUIRED_FLAG"
            ]
        )
        final_trusted_cost_allowed_flag = bool(
            review_rows[0][
                "FINAL_TRUSTED_COST_ALLOWED_FLAG"
            ]
        )
        business_action = (
            review_rows[0]["BUSINESS_ACTION"]
        )

    matched_terms_text = (
        ", ".join(
            score["matched_ambiguity_terms"]
        )
        if score["matched_ambiguity_terms"]
        else "None"
    )

    assessment_notes = (
        "Rule-based BMCS scoring completed. "
        f"Required characteristics={required_count}; "
        f"Valid extracted values={valid_count}; "
        f"Text-supported values={evidence_count}; "
        "Validity component="
        f"{score['validity_component']}; "
        "Evidence component="
        f"{score['evidence_component']}; "
        "Ambiguity penalty="
        f"{score['ambiguity_penalty']}; "
        "Matched ambiguity terms="
        f"{matched_terms_text}; "
        f"Business action={business_action}"
    )

    session.sql(
        """
        MERGE INTO
            CORE_INPUT.BOM_MATCH_ASSESSMENT t
        USING (
            SELECT
                ? AS RFQ_ID,
                ? AS SIMULATION_ID,
                ? AS KMAT_ID,
                ? AS CONFIGURATION_VERSION,
                ? AS BOM_MATCH_CONFIDENCE_SCORE,
                ? AS REVIEW_STATUS,
                ? AS REVIEW_REQUIRED_FLAG,
                ? AS FINAL_TRUSTED_COST_ALLOWED_FLAG,
                NULL::VARCHAR AS REVIEWED_BY,
                NULL::TIMESTAMP_NTZ AS REVIEWED_AT,
                'RULE_BASED_TEXT_MATCH'
                    AS ASSESSMENT_METHOD,
                'BMCS_RULE_ENGINE_V1'
                    AS ASSESSMENT_VERSION,
                ? AS ASSESSMENT_NOTES
        ) s
        ON t.RFQ_ID = s.RFQ_ID
           AND t.CONFIGURATION_VERSION =
               s.CONFIGURATION_VERSION
        WHEN MATCHED THEN UPDATE SET
            t.SIMULATION_ID =
                s.SIMULATION_ID,
            t.KMAT_ID =
                s.KMAT_ID,
            t.BOM_MATCH_CONFIDENCE_SCORE =
                s.BOM_MATCH_CONFIDENCE_SCORE,
            t.REVIEW_STATUS =
                s.REVIEW_STATUS,
            t.REVIEW_REQUIRED_FLAG =
                s.REVIEW_REQUIRED_FLAG,
            t.FINAL_TRUSTED_COST_ALLOWED_FLAG =
                s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
            t.REVIEWED_BY =
                s.REVIEWED_BY,
            t.REVIEWED_AT =
                s.REVIEWED_AT,
            t.ASSESSMENT_METHOD =
                s.ASSESSMENT_METHOD,
            t.ASSESSMENT_VERSION =
                s.ASSESSMENT_VERSION,
            t.ASSESSMENT_NOTES =
                s.ASSESSMENT_NOTES,
            t.UPDATED_AT =
                CURRENT_TIMESTAMP()
        WHEN NOT MATCHED THEN INSERT (
            RFQ_ID,
            SIMULATION_ID,
            KMAT_ID,
            CONFIGURATION_VERSION,
            BOM_MATCH_CONFIDENCE_SCORE,
            REVIEW_STATUS,
            REVIEW_REQUIRED_FLAG,
            FINAL_TRUSTED_COST_ALLOWED_FLAG,
            REVIEWED_BY,
            REVIEWED_AT,
            ASSESSMENT_METHOD,
            ASSESSMENT_VERSION,
            ASSESSMENT_NOTES
        )
        VALUES (
            s.RFQ_ID,
            s.SIMULATION_ID,
            s.KMAT_ID,
            s.CONFIGURATION_VERSION,
            s.BOM_MATCH_CONFIDENCE_SCORE,
            s.REVIEW_STATUS,
            s.REVIEW_REQUIRED_FLAG,
            s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
            s.REVIEWED_BY,
            s.REVIEWED_AT,
            s.ASSESSMENT_METHOD,
            s.ASSESSMENT_VERSION,
            s.ASSESSMENT_NOTES
        )
        """,
        params=[
            RFQ_ID,
            simulation_id,
            kmat_id,
            configuration_version,
            bmcs_score,
            review_status,
            review_required_flag,
            final_trusted_cost_allowed_flag,
            assessment_notes,
        ],
    ).collect()

    return json.dumps({
        "status": "SUCCESS",
        "rfq_id": RFQ_ID,
        "simulation_id": simulation_id,
        "kmat_id": kmat_id,
        "configuration_version":
            configuration_version,
        "required_characteristics":
            required_count,
        "valid_extracted_values":
            valid_count,
        "text_supported_values":
            evidence_count,
        "validity_component":
            score["validity_component"],
        "evidence_component":
            score["evidence_component"],
        "ambiguity_penalty":
            score["ambiguity_penalty"],
        "matched_ambiguity_terms":
            score["matched_ambiguity_terms"],
        "bom_match_confidence_score":
            bmcs_score,
        "review_status":
            review_status,
        "review_required_flag":
            review_required_flag,
        "final_trusted_cost_allowed_flag":
            final_trusted_cost_allowed_flag,
    })

$$ AS CANDIDATE_SOURCE
),
VALIDATION AS (
    SELECT
        CANDIDATE_SOURCE,

        REGEXP_COUNT(
            UPPER(CANDIDATE_SOURCE),
            'KMAT_COST_MODEL_DB'
        ) AS FIXED_DATABASE_COUNT,

        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'DB_NAME'
        ) AS DB_NAME_COUNT,

        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'sql_escape'
        ) AS SQL_ESCAPE_COUNT,

        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            '[?]'
        ) AS QMARK_COUNT,

        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'params[[:space:]]*='
        ) AS PARAMS_COUNT,

        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'CORE_INPUT[.]'
        ) AS SCHEMA_REFERENCE_COUNT,

        POSITION(
            'validity_component = '
            || 'valid_ratio * 55.00'
            IN CANDIDATE_SOURCE
        ) > 0 AS VALIDITY_WEIGHT_PRESERVED,

        POSITION(
            'evidence_component = '
            || 'evidence_ratio * 41.00'
            IN CANDIDATE_SOURCE
        ) > 0 AS EVIDENCE_WEIGHT_PRESERVED,

        POSITION(
            '7.75'
            IN CANDIDATE_SOURCE
        ) > 0 AS AMBIGUITY_PENALTY_PRESERVED,

        POSITION(
            'BMCS_RULE_ENGINE_V1'
            IN CANDIDATE_SOURCE
        ) > 0 AS VERSION_PRESERVED,

        POSITION(
            'RULE_BASED_TEXT_MATCH'
            IN CANDIDATE_SOURCE
        ) > 0 AS METHOD_PRESERVED
    FROM SOURCE
)
SELECT
    'PHASE14D3D2B_RULE_BMCS_V1',
    'PHASE_14D_3D_2B',
    'CORE_INTERNAL',
    'RUN_RULE_BASED_BMCS_SCORING',
    '(RFQ_ID VARCHAR)',
    -6490293137006003591,
    CANDIDATE_SOURCE,
    HASH(CANDIDATE_SOURCE),
    FIXED_DATABASE_COUNT,
    DB_NAME_COUNT,
    SQL_ESCAPE_COUNT,
    QMARK_COUNT,
    PARAMS_COUNT,
    SCHEMA_REFERENCE_COUNT,
    TRUE,
    FALSE,
    FALSE,

    IFF(
        FIXED_DATABASE_COUNT = 0
        AND DB_NAME_COUNT = 0
        AND SQL_ESCAPE_COUNT = 0
        AND QMARK_COUNT > 0
        AND PARAMS_COUNT >= 6
        AND SCHEMA_REFERENCE_COUNT >= 6
        AND VALIDITY_WEIGHT_PRESERVED
        AND EVIDENCE_WEIGHT_PRESERVED
        AND AMBIGUITY_PENALTY_PRESERVED
        AND VERSION_PRESERVED
        AND METHOD_PRESERVED,
        'VALIDATED_REVIEW_ONLY',
        'ATTENTION_REQUIRED'
    ),

    CURRENT_USER(),
    CURRENT_TIMESTAMP()

FROM VALIDATION;


SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COUNT(*) = 1
            AND COUNT_IF(
                CANDIDATE_STATUS =
                    'VALIDATED_REVIEW_ONLY'
            ) = 1,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3D_2B',

    'candidate_id',
        'PHASE14D3D2B_RULE_BMCS_V1',

    'candidate_count',
        COUNT(*),

    'fixed_database_reference_count',
        SUM(
            FIXED_DATABASE_REFERENCE_COUNT
        ),

    'db_name_constant_count',
        SUM(
            DB_NAME_CONSTANT_COUNT
        ),

    'sql_escape_reference_count',
        SUM(
            SQL_ESCAPE_REFERENCE_COUNT
        ),

    'qmark_parameter_count',
        SUM(
            QMARK_PARAMETER_COUNT
        ),

    'params_argument_count',
        SUM(
            PARAMS_ARGUMENT_COUNT
        ),

    'schema_relative_reference_count',
        SUM(
            SCHEMA_RELATIVE_REFERENCE_COUNT
        ),

    'validity_weight_55_preserved',
        TRUE,

    'evidence_weight_41_preserved',
        TRUE,

    'ambiguity_penalty_7_75_preserved',
        TRUE,

    'assessment_method_preserved',
        TRUE,

    'assessment_version_preserved',
        TRUE,

    'business_logic_changed',
        FALSE,

    'deployment_ready_count',
        COUNT_IF(
            DEPLOYMENT_READY_FLAG = TRUE
        ),

    'procedure_body_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3D2B_CANDIDATE_SUMMARY

FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1

WHERE CANDIDATE_ID =
      'PHASE14D3D2B_RULE_BMCS_V1';

WITH CANDIDATE AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1
    WHERE CANDIDATE_ID =
          'PHASE14D3D2A_PREPARE_RFQ_V1'
),
ORIGINAL AS (
    SELECT
        OBJECT_DDL_HASH
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1
    WHERE AUDIT_BATCH_ID =
          'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
      AND OBJECT_SCHEMA = 'CORE_INTERNAL'
      AND OBJECT_NAME =
          'PREPARE_RFQ_SIMULATION_INPUTS'
      AND OBJECT_SIGNATURE =
          '(RFQ_ID VARCHAR)'
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            CANDIDATE.CANDIDATE_STATUS =
                'STATIC_REVIEW_PASSED'
            AND ORIGINAL.OBJECT_DDL_HASH =
                CANDIDATE.ORIGINAL_DDL_HASH
            AND CANDIDATE
                .FIXED_DATABASE_REFERENCE_COUNT = 0
            AND CANDIDATE.DB_NAME_CONSTANT_COUNT = 0
            AND CANDIDATE
                .SQL_ESCAPE_REFERENCE_COUNT = 0
            AND CANDIDATE
                .PARAMS_ARGUMENT_COUNT >= 10
            AND CANDIDATE
                .BUSINESS_LOGIC_CHANGED_FLAG = FALSE
            AND CANDIDATE
                .DEPLOYMENT_READY_FLAG = FALSE,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3D_2A',

    'candidate_id',
        CANDIDATE.CANDIDATE_ID,

    'original_ddl_hash',
        ORIGINAL.OBJECT_DDL_HASH,

    'expected_original_ddl_hash',
        CANDIDATE.ORIGINAL_DDL_HASH,

    'candidate_source_hash',
        CANDIDATE.CANDIDATE_SOURCE_HASH,

    'fixed_database_reference_count',
        CANDIDATE
            .FIXED_DATABASE_REFERENCE_COUNT,

    'db_name_constant_count',
        CANDIDATE.DB_NAME_CONSTANT_COUNT,

    'sql_escape_reference_count',
        CANDIDATE.SQL_ESCAPE_REFERENCE_COUNT,

    'params_argument_count',
        CANDIDATE.PARAMS_ARGUMENT_COUNT,

    'business_logic_changed',
        CANDIDATE.BUSINESS_LOGIC_CHANGED_FLAG,

    'deployment_ready',
        CANDIDATE.DEPLOYMENT_READY_FLAG,

    'procedure_body_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3D2A_FINAL_GATE

FROM CANDIDATE
CROSS JOIN ORIGINAL;


WITH baseline AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_BASELINE_V1
    WHERE BASELINE_ID =
          'PHASE14A_SIM_001_BASELINE_V1'
),
current_state AS (
    SELECT
        s.SIMULATION_ID,

        HASH(
            s.MATERIAL_COST_USD,
            s.LABOR_COST_USD,
            s.MACHINE_COST_USD,
            s.OVERHEAD_COST_USD,
            s.TOTAL_CONFIGURED_COST_USD,
            s.FLOOR_PRICE_USD,
            s.TARGET_PRICE_USD,
            s.CEILING_PRICE_USD,
            s.BASELINE_TOTAL_COST_USD,
            s.RISK_ADJUSTED_TOTAL_COST_USD,
            s.TOTAL_RISK_UPLIFT_USD,
            s.TOTAL_RISK_UPLIFT_PCT,
            s.CSS_SCORE,
            s.SCRAP_RATE_APPLIED,
            s.AVG_WEIGHTED_FMIS,
            s.MAX_TDS_FACTOR,
            s.BOM_MATCH_CONFIDENCE_SCORE,
            s.BMCS_REVIEW_STATUS,
            s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
            s.QUOTE_TRUST_STATUS,
            h.RESOLVED_SCRAP_RATE,
            h.CSS_RESOLVED_SOURCE,
            h.RESOLVED_FMIS_MULTIPLIER,
            h.FMIS_RESOLVED_SOURCE,
            h.RESOLVED_TDS_FACTOR,
            h.TDS_RESOLVED_SOURCE,
            h.RESOLVED_BMCS_STATUS,
            h.SAFETY_GATE_PASS_FLAG,
            h.COST_ENGINE_CONSUMPTION_ALLOWED_FLAG,
            h.OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG
        ) AS SNAPSHOT_HASH,

        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS ACTIVE_POLICY_COUNT,

        (
            SELECT COUNT_IF(
                DEPLOYMENT_MODE = 'SHADOW'
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS SHADOW_POLICY_COUNT,

        (
            SELECT COUNT_IF(
                AUTO_USE_ALLOWED_FLAG = TRUE
                OR OFFICIAL_COST_IMPACT_ALLOWED_FLAG = TRUE
                OR BUSINESS_DECISION_ALLOWED_FLAG = TRUE
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS POLICY_AUTHORITY_ENABLED_COUNT,

        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .ML_RUNTIME_AUTHORITY_REGISTRY_V1
            WHERE UPPER(AUTHORITY_STATUS) = 'ENABLED'
        ) AS ENABLED_RUNTIME_AUTHORITY_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_OUTPUT
            .KMAT_CONFIGURED_COST_SUMMARY s

    LEFT JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .VW_KMAT_PHASE10B_HIERARCHY_V1 h
      ON s.SIMULATION_ID = h.SIMULATION_ID

    WHERE s.SIMULATION_ID = 'SIM_001'

    QUALIFY ROW_NUMBER() OVER (
        PARTITION BY s.SIMULATION_ID
        ORDER BY s.CALCULATED_AT DESC
    ) = 1
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            baseline.SNAPSHOT_HASH =
                current_state.SNAPSHOT_HASH
            AND current_state
                .POLICY_AUTHORITY_ENABLED_COUNT = 0
            AND current_state
                .ENABLED_RUNTIME_AUTHORITY_COUNT = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3D_2A',

    'baseline_snapshot_hash',
        baseline.SNAPSHOT_HASH,

    'current_snapshot_hash',
        current_state.SNAPSHOT_HASH,

    'cost_and_governance_snapshot_match',
        baseline.SNAPSHOT_HASH =
        current_state.SNAPSHOT_HASH,

    'active_policy_count',
        current_state.ACTIVE_POLICY_COUNT,

    'shadow_policy_count',
        current_state.SHADOW_POLICY_COUNT,

    'policy_authority_enabled_count',
        current_state
            .POLICY_AUTHORITY_ENABLED_COUNT,

    'enabled_runtime_authority_count',
        current_state
            .ENABLED_RUNTIME_AUTHORITY_COUNT,

    'official_cost_changed',
        baseline.SNAPSHOT_HASH <>
        current_state.SNAPSHOT_HASH,

    'procedure_body_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3D2A_BASELINE_VERIFICATION

FROM baseline
CROSS JOIN current_state;

WITH CANDIDATE AS (
    SELECT
        COUNT(*) AS CANDIDATE_COUNT,

        COUNT_IF(
            CANDIDATE_STATUS =
                'VALIDATED_REVIEW_ONLY'
        ) AS VALIDATED_COUNT,

        SUM(
            FIXED_DATABASE_REFERENCE_COUNT
        ) AS FIXED_DATABASE_COUNT,

        SUM(
            DB_NAME_CONSTANT_COUNT
        ) AS DB_NAME_COUNT,

        SUM(
            SQL_ESCAPE_REFERENCE_COUNT
        ) AS SQL_ESCAPE_COUNT,

        SUM(
            QMARK_PARAMETER_COUNT
        ) AS QMARK_COUNT,

        SUM(
            PARAMS_ARGUMENT_COUNT
        ) AS PARAMS_COUNT,

        COUNT_IF(
            BUSINESS_LOGIC_CHANGED_FLAG = TRUE
        ) AS BUSINESS_LOGIC_CHANGE_COUNT,

        COUNT_IF(
            DEPLOYMENT_READY_FLAG = TRUE
        ) AS DEPLOYMENT_READY_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1

    WHERE CANDIDATE_ID =
          'PHASE14D3D2B_RULE_BMCS_V1'
),
ORIGINAL AS (
    SELECT
        COUNT(*) AS ORIGINAL_COUNT,

        COUNT_IF(
            OBJECT_DDL_HASH =
                -6490293137006003591
        ) AS ORIGINAL_HASH_MATCH_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1

    WHERE AUDIT_BATCH_ID =
          'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'

      AND OBJECT_SCHEMA =
          'CORE_INTERNAL'

      AND OBJECT_NAME =
          'RUN_RULE_BASED_BMCS_SCORING'

      AND OBJECT_SIGNATURE =
          '(RFQ_ID VARCHAR)'
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            CANDIDATE.CANDIDATE_COUNT = 1
            AND CANDIDATE.VALIDATED_COUNT = 1
            AND CANDIDATE.FIXED_DATABASE_COUNT = 0
            AND CANDIDATE.DB_NAME_COUNT = 0
            AND CANDIDATE.SQL_ESCAPE_COUNT = 0
            AND CANDIDATE.QMARK_COUNT > 0
            AND CANDIDATE.PARAMS_COUNT >= 6
            AND CANDIDATE
                .BUSINESS_LOGIC_CHANGE_COUNT = 0
            AND CANDIDATE
                .DEPLOYMENT_READY_COUNT = 0
            AND ORIGINAL.ORIGINAL_COUNT = 1
            AND ORIGINAL
                .ORIGINAL_HASH_MATCH_COUNT = 1,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3D_2B',

    'candidate_count',
        CANDIDATE.CANDIDATE_COUNT,

    'validated_candidate_count',
        CANDIDATE.VALIDATED_COUNT,

    'original_hash_match_count',
        ORIGINAL.ORIGINAL_HASH_MATCH_COUNT,

    'fixed_database_reference_count',
        CANDIDATE.FIXED_DATABASE_COUNT,

    'db_name_constant_count',
        CANDIDATE.DB_NAME_COUNT,

    'sql_escape_reference_count',
        CANDIDATE.SQL_ESCAPE_COUNT,

    'qmark_parameter_count',
        CANDIDATE.QMARK_COUNT,

    'params_argument_count',
        CANDIDATE.PARAMS_COUNT,

    'business_logic_changed',
        CANDIDATE
            .BUSINESS_LOGIC_CHANGE_COUNT > 0,

    'deployment_ready_count',
        CANDIDATE.DEPLOYMENT_READY_COUNT,

    'procedure_body_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3D2B_FINAL_GATE

FROM CANDIDATE
CROSS JOIN ORIGINAL;


WITH baseline AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_BASELINE_V1
    WHERE BASELINE_ID =
          'PHASE14A_SIM_001_BASELINE_V1'
),
current_state AS (
    SELECT
        s.SIMULATION_ID,

        HASH(
            s.MATERIAL_COST_USD,
            s.LABOR_COST_USD,
            s.MACHINE_COST_USD,
            s.OVERHEAD_COST_USD,
            s.TOTAL_CONFIGURED_COST_USD,
            s.FLOOR_PRICE_USD,
            s.TARGET_PRICE_USD,
            s.CEILING_PRICE_USD,
            s.BASELINE_TOTAL_COST_USD,
            s.RISK_ADJUSTED_TOTAL_COST_USD,
            s.TOTAL_RISK_UPLIFT_USD,
            s.TOTAL_RISK_UPLIFT_PCT,
            s.CSS_SCORE,
            s.SCRAP_RATE_APPLIED,
            s.AVG_WEIGHTED_FMIS,
            s.MAX_TDS_FACTOR,
            s.BOM_MATCH_CONFIDENCE_SCORE,
            s.BMCS_REVIEW_STATUS,
            s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
            s.QUOTE_TRUST_STATUS,
            h.RESOLVED_SCRAP_RATE,
            h.CSS_RESOLVED_SOURCE,
            h.RESOLVED_FMIS_MULTIPLIER,
            h.FMIS_RESOLVED_SOURCE,
            h.RESOLVED_TDS_FACTOR,
            h.TDS_RESOLVED_SOURCE,
            h.RESOLVED_BMCS_STATUS,
            h.SAFETY_GATE_PASS_FLAG,
            h.COST_ENGINE_CONSUMPTION_ALLOWED_FLAG,
            h.OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG
        ) AS SNAPSHOT_HASH,

        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS ACTIVE_POLICY_COUNT,

        (
            SELECT COUNT_IF(
                DEPLOYMENT_MODE = 'SHADOW'
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS SHADOW_POLICY_COUNT,

        (
            SELECT COUNT_IF(
                AUTO_USE_ALLOWED_FLAG = TRUE
                OR OFFICIAL_COST_IMPACT_ALLOWED_FLAG = TRUE
                OR BUSINESS_DECISION_ALLOWED_FLAG = TRUE
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS POLICY_AUTHORITY_ENABLED_COUNT,

        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .ML_RUNTIME_AUTHORITY_REGISTRY_V1
            WHERE UPPER(AUTHORITY_STATUS) = 'ENABLED'
        ) AS ENABLED_RUNTIME_AUTHORITY_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_OUTPUT
            .KMAT_CONFIGURED_COST_SUMMARY s

    LEFT JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .VW_KMAT_PHASE10B_HIERARCHY_V1 h
      ON s.SIMULATION_ID = h.SIMULATION_ID

    WHERE s.SIMULATION_ID = 'SIM_001'

    QUALIFY ROW_NUMBER() OVER (
        PARTITION BY s.SIMULATION_ID
        ORDER BY s.CALCULATED_AT DESC
    ) = 1
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            baseline.SNAPSHOT_HASH =
                current_state.SNAPSHOT_HASH
            AND current_state
                .POLICY_AUTHORITY_ENABLED_COUNT = 0
            AND current_state
                .ENABLED_RUNTIME_AUTHORITY_COUNT = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3D_2B',

    'baseline_snapshot_hash',
        baseline.SNAPSHOT_HASH,

    'current_snapshot_hash',
        current_state.SNAPSHOT_HASH,

    'cost_and_governance_snapshot_match',
        baseline.SNAPSHOT_HASH =
        current_state.SNAPSHOT_HASH,

    'active_policy_count',
        current_state.ACTIVE_POLICY_COUNT,

    'shadow_policy_count',
        current_state.SHADOW_POLICY_COUNT,

    'policy_authority_enabled_count',
        current_state
            .POLICY_AUTHORITY_ENABLED_COUNT,

    'enabled_runtime_authority_count',
        current_state
            .ENABLED_RUNTIME_AUTHORITY_COUNT,

    'official_cost_changed',
        baseline.SNAPSHOT_HASH <>
        current_state.SNAPSHOT_HASH,

    'procedure_body_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3D2B_BASELINE_VERIFICATION

FROM baseline
CROSS JOIN current_state;

DELETE FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1
WHERE CANDIDATE_ID =
      'PHASE14D3D2C_CORTEX_BMCS_V1';

INSERT INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1
WITH SOURCE AS (
    SELECT $$
import base64
import json
import re


def to_float(value, default=0.0):
    if value is None:
        return default

    try:
        return float(value)
    except Exception:
        pass

    try:
        text = str(value).replace("%", "").strip()
        match = re.search(r"-?\d+(\.\d+)?", text)

        if match:
            return float(match.group(0))
    except Exception:
        pass

    return default


def parse_json_object_safe(value):
    if value is None:
        return {}

    if isinstance(value, dict):
        return value

    if isinstance(value, list):
        return {"labels": value}

    text = str(value).strip()

    text = re.sub(
        r"^```json",
        "",
        text,
        flags=re.IGNORECASE,
    ).strip()
    text = re.sub(
        r"^```",
        "",
        text,
    ).strip()
    text = re.sub(
        r"```$",
        "",
        text,
    ).strip()

    for _ in range(3):
        try:
            parsed = json.loads(text)

            if isinstance(parsed, dict):
                return parsed

            if isinstance(parsed, list):
                return {"labels": parsed}

            if isinstance(parsed, str):
                text = parsed.strip()
                continue

            return {"value": parsed}

        except Exception:
            break

    match = re.search(
        r"\{.*\}",
        text,
        re.DOTALL,
    )

    if match:
        extracted = match.group(0).strip()

        for _ in range(2):
            try:
                parsed = json.loads(extracted)

                if isinstance(parsed, dict):
                    return parsed

                if isinstance(parsed, str):
                    extracted = parsed.strip()
                    continue

            except Exception:
                break

    return {"raw_text": text}


def get_key_ci(obj, key, default=None):
    if not isinstance(obj, dict):
        return default

    if key in obj:
        return obj[key]

    key_upper = str(key).upper()

    for existing_key, value in obj.items():
        if str(existing_key).upper() == key_upper:
            return value

    return default


def json_to_base64(value):
    text = json.dumps(
        value,
        ensure_ascii=False,
    )

    return base64.b64encode(
        text.encode("utf-8")
    ).decode("ascii")


def get_ai_complete_model(session):
    rows = session.sql(
        """
        SELECT CONFIG_VALUE
        FROM CORE_INPUT.CORTEX_MODEL_CONFIG
        WHERE CONFIG_KEY = 'AI_COMPLETE_MODEL'
          AND ACTIVE_FLAG = TRUE
        LIMIT 1
        """
    ).collect()

    if len(rows) == 0:
        return "snowflake-arctic"

    return rows[0]["CONFIG_VALUE"]


def clamp_score(value):
    score = to_float(value, 0.0)

    if score < 0:
        score = 0.0

    if score > 100:
        score = 100.0

    return round(score, 2)


def fallback_review_status(score):
    if score >= 90:
        return "AUTO_APPROVED"

    if score >= 70:
        return "REVIEW_RECOMMENDED"

    return "REVIEW_REQUIRED"


def review_status_from_score(
    session,
    score,
):
    rows = session.sql(
        """
        SELECT
            REVIEW_STATUS,
            REVIEW_REQUIRED_FLAG,
            FINAL_TRUSTED_COST_ALLOWED_FLAG,
            BUSINESS_ACTION
        FROM CORE_INPUT.BMCS_REVIEW_RULES
        WHERE ? BETWEEN MIN_SCORE AND MAX_SCORE
          AND ACTIVE_FLAG = TRUE
        LIMIT 1
        """,
        params=[score],
    ).collect()

    if len(rows) == 0:
        return {
            "review_status":
                "REVIEW_REQUIRED",
            "review_required_flag":
                True,
            "final_trusted_cost_allowed_flag":
                False,
            "business_action":
                (
                    "BMCS rule missing. "
                    "Defaulted to review required."
                ),
        }

    row = rows[0]

    return {
        "review_status":
            row["REVIEW_STATUS"],
        "review_required_flag":
            bool(
                row[
                    "REVIEW_REQUIRED_FLAG"
                ]
            ),
        "final_trusted_cost_allowed_flag":
            bool(
                row[
                    "FINAL_TRUSTED_COST_ALLOWED_FLAG"
                ]
            ),
        "business_action":
            row["BUSINESS_ACTION"],
    }


def extract_classification_label(
    raw_obj,
    score,
):
    allowed = {
        "AUTO_APPROVED",
        "REVIEW_RECOMMENDED",
        "REVIEW_REQUIRED",
    }

    if isinstance(raw_obj, str):
        text = raw_obj.upper()

        for label in allowed:
            if label in text:
                return label

        return fallback_review_status(score)

    if isinstance(raw_obj, dict):
        for key in [
            "label",
            "classification",
            "result",
            "category",
            "value",
        ]:
            value = raw_obj.get(key)

            if (
                isinstance(value, str)
                and value.upper() in allowed
            ):
                return value.upper()

        labels = raw_obj.get("labels")

        if (
            isinstance(labels, list)
            and len(labels) > 0
        ):
            first = labels[0]

            if (
                isinstance(first, str)
                and first.upper() in allowed
            ):
                return first.upper()

            if isinstance(first, dict):
                for key in [
                    "label",
                    "classification",
                    "category",
                    "value",
                ]:
                    value = first.get(key)

                    if (
                        isinstance(value, str)
                        and value.upper()
                        in allowed
                    ):
                        return value.upper()

        raw_text = json.dumps(
            raw_obj
        ).upper()

        for label in allowed:
            if label in raw_text:
                return label

    return fallback_review_status(score)


def run(session, RFQ_ID):
    try:
        session.sql(
            """
            CALL CORE_INTERNAL
                .RUN_RULE_BASED_BMCS_SCORING(?)
            """,
            params=[RFQ_ID],
        ).collect()

    except Exception as exc:
        return json.dumps({
            "status": "ERROR",
            "stage": "RULE_BASED_BMCS",
            "message": (
                "Rule-based BMCS scoring failed "
                "before Cortex BMCS."
            ),
            "error": str(exc),
            "rfq_id": RFQ_ID,
        })

    rows = session.sql(
        """
        SELECT
            h.RFQ_ID,
            h.KMAT_ID,
            h.CUSTOMER_ID,
            h.CUSTOMER_NAME,
            h.SOURCE_DOCUMENT_NAME,

            COALESCE(
                h.PROCESSING_TEXT_EN,
                h.SOURCE_DOCUMENT_TEXT,
                h.ORIGINAL_DOCUMENT_TEXT
            ) AS RFQ_TEXT,

            h.RFQ_SUMMARY,
            h.RFQ_COMPLEXITY_CATEGORY,
            h.RFQ_COMPLEXITY_REASON,

            c.SIMULATION_ID,
            c.CONFIGURATION_VERSION,

            TO_JSON(
                c.EXTRACTED_CONFIGURATION_JSON
            ) AS EXTRACTED_CONFIGURATION_JSON_STR,

            c.EXTRACTION_METHOD,

            c.EXTRACTION_RAW_RESPONSE
                :extraction_reasoning
                ::STRING
                AS CORTEX_EXTRACTION_REASONING,

            a.BOM_MATCH_CONFIDENCE_SCORE
                AS RULE_BASED_BMCS_SCORE,

            a.REVIEW_STATUS
                AS RULE_BASED_REVIEW_STATUS,

            a.ASSESSMENT_NOTES
                AS RULE_BASED_ASSESSMENT_NOTES

        FROM CORE_INPUT.RFQ_HEADER h

        JOIN CORE_INPUT.RFQ_CONFIGURATION c
          ON h.RFQ_ID = c.RFQ_ID
         AND h.KMAT_ID = c.KMAT_ID
         AND c.ACTIVE_FLAG = TRUE

        JOIN CORE_INPUT.BOM_MATCH_ASSESSMENT a
          ON c.RFQ_ID = a.RFQ_ID
         AND c.SIMULATION_ID =
             a.SIMULATION_ID
         AND c.KMAT_ID = a.KMAT_ID
         AND c.CONFIGURATION_VERSION =
             a.CONFIGURATION_VERSION

        WHERE h.RFQ_ID = ?

        QUALIFY ROW_NUMBER() OVER (
            PARTITION BY h.RFQ_ID
            ORDER BY
                c.CONFIGURATION_VERSION DESC,
                c.CREATED_AT DESC
        ) = 1
        """,
        params=[RFQ_ID],
    ).collect()

    if len(rows) == 0:
        return json.dumps({
            "status": "ERROR",
            "stage": "LOAD_RFQ_BMCS_DATA",
            "message": (
                "No active RFQ configuration "
                "and BMCS assessment found for "
                f"RFQ_ID={RFQ_ID}"
            ),
        })

    row = rows[0]

    kmat_id = row["KMAT_ID"]
    simulation_id = row["SIMULATION_ID"]
    configuration_version = int(
        row["CONFIGURATION_VERSION"]
    )

    rfq_text = row["RFQ_TEXT"] or ""
    rfq_summary = row["RFQ_SUMMARY"] or ""

    complexity_category = (
        row["RFQ_COMPLEXITY_CATEGORY"]
        or "UNKNOWN"
    )

    extracted_config = (
        row[
            "EXTRACTED_CONFIGURATION_JSON_STR"
        ]
        or "{}"
    )

    extraction_reasoning = (
        row["CORTEX_EXTRACTION_REASONING"]
        or ""
    )

    rule_score = clamp_score(
        row["RULE_BASED_BMCS_SCORE"]
    )

    model_name = get_ai_complete_model(
        session
    )

    complete_prompt = f"""
You are validating a manufacturing KMAT RFQ extraction.

Return STRICT JSON only. No markdown. No extra text.

Task:
Compare the customer RFQ text with the extracted KMAT configuration.
Generate a BOM Match Confidence Score from 0 to 100.

Scoring meaning:
- 90 to 100: RFQ clearly supports all extracted KMAT values.
- 70 to 89: Mostly correct, but one or more values are inferred or unclear.
- Below 70: Missing, vague, contradictory, or risky mapping. Engineering review required.

Do not calculate cost.
Do not invent new configuration values.
Evaluate whether the extracted configuration is trustworthy.

Return this JSON shape:
{{
  "cortex_bmcs_score": 0,
  "cortex_review_status": "AUTO_APPROVED or REVIEW_RECOMMENDED or REVIEW_REQUIRED",
  "reasoning": "short explanation"
}}

RFQ summary:
{rfq_summary}

RFQ complexity category:
{complexity_category}

Extracted KMAT configuration:
{extracted_config}

Previous extraction reasoning:
{extraction_reasoning}

RFQ text:
{rfq_text[:5000]}
"""

    complete_rows = session.sql(
        """
        SELECT AI_COMPLETE(
            ?,
            ?
        ) AS CORTEX_BMCS_TEXT
        """,
        params=[
            model_name,
            complete_prompt,
        ],
    ).collect()

    cortex_complete_text = (
        complete_rows[0]["CORTEX_BMCS_TEXT"]
        if complete_rows
        else ""
    )

    cortex_complete_obj = (
        parse_json_object_safe(
            cortex_complete_text
        )
    )

    cortex_score_raw = get_key_ci(
        cortex_complete_obj,
        "cortex_bmcs_score",
        None,
    )

    if cortex_score_raw is None:
        cortex_score = rule_score
    else:
        cortex_score = clamp_score(
            cortex_score_raw
        )

    cortex_complete_review_status = str(
        get_key_ci(
            cortex_complete_obj,
            "cortex_review_status",
            fallback_review_status(
                cortex_score
            ),
        )
    ).upper()

    cortex_reasoning = str(
        get_key_ci(
            cortex_complete_obj,
            "reasoning",
            get_key_ci(
                cortex_complete_obj,
                "raw_text",
                cortex_complete_text,
            ),
        )
    )

    classification_input = f"""
RFQ summary: {rfq_summary}

Extracted configuration: {extracted_config}

Rule-based BMCS score: {rule_score}
Cortex BMCS score: {cortex_score}

Reasoning: {cortex_reasoning}

Classify into exactly one review category:
AUTO_APPROVED, REVIEW_RECOMMENDED, REVIEW_REQUIRED
"""

    try:
        classify_rows = session.sql(
            """
            SELECT TO_JSON(
                AI_CLASSIFY(
                    ?,
                    ARRAY_CONSTRUCT(
                        'AUTO_APPROVED',
                        'REVIEW_RECOMMENDED',
                        'REVIEW_REQUIRED'
                    )
                )
            ) AS CLASSIFICATION_JSON
            """,
            params=[classification_input],
        ).collect()

        classification_raw_text = (
            classify_rows[0][
                "CLASSIFICATION_JSON"
            ]
            if classify_rows
            else "{}"
        )

        classification_raw_obj = (
            parse_json_object_safe(
                classification_raw_text
            )
        )

        cortex_classified_status = (
            extract_classification_label(
                classification_raw_obj,
                cortex_score,
            )
        )

    except Exception as exc:
        classification_raw_obj = {
            "error": str(exc),
            "fallback_status":
                fallback_review_status(
                    cortex_score
                ),
        }

        cortex_classified_status = (
            fallback_review_status(
                cortex_score
            )
        )

    final_score = round(
        (0.70 * rule_score)
        + (0.30 * cortex_score),
        2,
    )

    final_rule = review_status_from_score(
        session,
        final_score,
    )

    final_review_status = (
        final_rule["review_status"]
    )

    final_review_required_flag = (
        final_rule[
            "review_required_flag"
        ]
    )

    final_cost_allowed_flag = (
        final_rule[
            "final_trusted_cost_allowed_flag"
        ]
    )

    business_action = (
        final_rule["business_action"]
    )

    notes = (
        "Hybrid BMCS completed. "
        f"Rule-based BMCS={rule_score}. "
        f"Cortex BMCS={cortex_score}. "
        f"Final BMCS={final_score}. "
        "Cortex complete review status="
        f"{cortex_complete_review_status}. "
        "Cortex classified status="
        f"{cortex_classified_status}. "
        "Threshold-applied final review status="
        f"{final_review_status}. "
        f"Business action={business_action}. "
        f"Cortex reasoning={cortex_reasoning}"
    )

    cortex_raw_payload = {
        "ai_complete_model":
            model_name,
        "ai_complete_raw_text":
            cortex_complete_text,
        "ai_complete_parsed":
            cortex_complete_obj,
        "cortex_complete_review_status":
            cortex_complete_review_status,
        "hybrid_formula":
            (
                "FINAL_BMCS = "
                "0.70 * RULE_BASED_BMCS "
                "+ 0.30 * CORTEX_BMCS"
            ),
    }

    cortex_raw_json_b64 = json_to_base64(
        cortex_raw_payload
    )

    classification_raw_json_b64 = (
        json_to_base64(
            classification_raw_obj
        )
    )

    session.sql(
        """
        UPDATE CORE_INPUT.BOM_MATCH_ASSESSMENT
        SET
            RULE_BASED_BMCS_SCORE = ?,
            CORTEX_BMCS_SCORE = ?,
            CORTEX_BMCS_REVIEW_STATUS = ?,
            CORTEX_BMCS_REASONING = ?,

            CORTEX_BMCS_RAW_RESPONSE =
                PARSE_JSON(
                    BASE64_DECODE_STRING(?)
                ),

            CORTEX_BMCS_CLASSIFICATION_RAW =
                PARSE_JSON(
                    BASE64_DECODE_STRING(?)
                ),

            FINAL_BMCS_METHOD =
                'HYBRID_RULE_70_CORTEX_30',

            BOM_MATCH_CONFIDENCE_SCORE = ?,
            REVIEW_STATUS = ?,
            REVIEW_REQUIRED_FLAG = ?,
            FINAL_TRUSTED_COST_ALLOWED_FLAG = ?,

            ASSESSMENT_METHOD =
                'HYBRID_RULE_CORTEX_BMCS',

            ASSESSMENT_VERSION =
                'BMCS_HYBRID_V1',

            ASSESSMENT_NOTES = ?,
            UPDATED_AT = CURRENT_TIMESTAMP()

        WHERE RFQ_ID = ?
          AND SIMULATION_ID = ?
          AND KMAT_ID = ?
          AND CONFIGURATION_VERSION = ?
        """,
        params=[
            rule_score,
            cortex_score,
            cortex_classified_status,
            cortex_reasoning,
            cortex_raw_json_b64,
            classification_raw_json_b64,
            final_score,
            final_review_status,
            final_review_required_flag,
            final_cost_allowed_flag,
            notes,
            RFQ_ID,
            simulation_id,
            kmat_id,
            configuration_version,
        ],
    ).collect()

    return json.dumps({
        "status": "SUCCESS",
        "rfq_id": RFQ_ID,
        "simulation_id": simulation_id,
        "kmat_id": kmat_id,
        "configuration_version":
            configuration_version,
        "rule_based_bmcs_score":
            rule_score,
        "cortex_bmcs_score":
            cortex_score,
        "final_bmcs_score":
            final_score,
        "cortex_complete_review_status":
            cortex_complete_review_status,
        "cortex_classified_status":
            cortex_classified_status,
        "final_review_status":
            final_review_status,
        "review_required_flag":
            final_review_required_flag,
        "final_trusted_cost_allowed_flag":
            final_cost_allowed_flag,
        "final_bmcs_method":
            "HYBRID_RULE_70_CORTEX_30",
        "cortex_reasoning":
            cortex_reasoning,
    })

$$ AS CANDIDATE_SOURCE
),
VALIDATION AS (
    SELECT
        CANDIDATE_SOURCE,

        REGEXP_COUNT(
            UPPER(CANDIDATE_SOURCE),
            'KMAT_COST_MODEL_DB'
        ) AS FIXED_DATABASE_COUNT,

        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'DB_NAME'
        ) AS DB_NAME_COUNT,

        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'sql_escape'
        ) AS SQL_ESCAPE_COUNT,

        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            '[?]'
        ) AS QMARK_COUNT,

        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'params[[:space:]]*='
        ) AS PARAMS_COUNT,

        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'CORE_INPUT[.]'
        )
        +
        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'CORE_INTERNAL'
        ) AS SCHEMA_REFERENCE_COUNT,

        POSITION(
            '(0.70 * rule_score)'
            IN CANDIDATE_SOURCE
        ) > 0 AS RULE_WEIGHT_PRESERVED,

        POSITION(
            '(0.30 * cortex_score)'
            IN CANDIDATE_SOURCE
        ) > 0 AS CORTEX_WEIGHT_PRESERVED,

        POSITION(
            'HYBRID_RULE_70_CORTEX_30'
            IN CANDIDATE_SOURCE
        ) > 0 AS HYBRID_METHOD_PRESERVED,

        POSITION(
            'HYBRID_RULE_CORTEX_BMCS'
            IN CANDIDATE_SOURCE
        ) > 0 AS ASSESSMENT_METHOD_PRESERVED,

        POSITION(
            'BMCS_HYBRID_V1'
            IN CANDIDATE_SOURCE
        ) > 0 AS VERSION_PRESERVED,

        POSITION(
            'AI_COMPLETE'
            IN CANDIDATE_SOURCE
        ) > 0 AS AI_COMPLETE_PRESERVED,

        POSITION(
            'AI_CLASSIFY'
            IN CANDIDATE_SOURCE
        ) > 0 AS AI_CLASSIFY_PRESERVED

    FROM SOURCE
)
SELECT
    'PHASE14D3D2C_CORTEX_BMCS_V1',
    'PHASE_14D_3D_2C',
    'CORE_INTERNAL',
    'RUN_CORTEX_BMCS_ASSESSMENT',
    '(RFQ_ID VARCHAR)',
    7001001297441927869,
    CANDIDATE_SOURCE,
    HASH(CANDIDATE_SOURCE),
    FIXED_DATABASE_COUNT,
    DB_NAME_COUNT,
    SQL_ESCAPE_COUNT,
    QMARK_COUNT,
    PARAMS_COUNT,
    SCHEMA_REFERENCE_COUNT,
    TRUE,
    FALSE,
    FALSE,

    IFF(
        FIXED_DATABASE_COUNT = 0
        AND DB_NAME_COUNT = 0
        AND SQL_ESCAPE_COUNT = 0
        AND QMARK_COUNT > 0
        AND PARAMS_COUNT >= 6
        AND SCHEMA_REFERENCE_COUNT >= 7
        AND RULE_WEIGHT_PRESERVED
        AND CORTEX_WEIGHT_PRESERVED
        AND HYBRID_METHOD_PRESERVED
        AND ASSESSMENT_METHOD_PRESERVED
        AND VERSION_PRESERVED
        AND AI_COMPLETE_PRESERVED
        AND AI_CLASSIFY_PRESERVED,
        'VALIDATED_REVIEW_ONLY',
        'ATTENTION_REQUIRED'
    ),

    CURRENT_USER(),
    CURRENT_TIMESTAMP()

FROM VALIDATION;


SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COUNT(*) = 1
            AND COUNT_IF(
                CANDIDATE_STATUS =
                    'VALIDATED_REVIEW_ONLY'
            ) = 1,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3D_2C',

    'candidate_id',
        'PHASE14D3D2C_CORTEX_BMCS_V1',

    'candidate_count',
        COUNT(*),

    'fixed_database_reference_count',
        SUM(
            FIXED_DATABASE_REFERENCE_COUNT
        ),

    'db_name_constant_count',
        SUM(
            DB_NAME_CONSTANT_COUNT
        ),

    'sql_escape_reference_count',
        SUM(
            SQL_ESCAPE_REFERENCE_COUNT
        ),

    'qmark_parameter_count',
        SUM(
            QMARK_PARAMETER_COUNT
        ),

    'params_argument_count',
        SUM(
            PARAMS_ARGUMENT_COUNT
        ),

    'schema_relative_reference_count',
        SUM(
            SCHEMA_RELATIVE_REFERENCE_COUNT
        ),

    'rule_weight_70_preserved',
        TRUE,

    'cortex_weight_30_preserved',
        TRUE,

    'hybrid_method_preserved',
        TRUE,

    'assessment_method_preserved',
        TRUE,

    'assessment_version_preserved',
        TRUE,

    'cortex_functions_preserved',
        TRUE,

    'business_logic_changed',
        FALSE,

    'deployment_ready_count',
        COUNT_IF(
            DEPLOYMENT_READY_FLAG = TRUE
        ),

    'procedure_body_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3D2C_CANDIDATE_SUMMARY

FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1

WHERE CANDIDATE_ID =
      'PHASE14D3D2C_CORTEX_BMCS_V1';

WITH CANDIDATE AS (
    SELECT
        COUNT(*) AS CANDIDATE_COUNT,

        COUNT_IF(
            CANDIDATE_STATUS =
                'VALIDATED_REVIEW_ONLY'
        ) AS VALIDATED_COUNT,

        SUM(
            FIXED_DATABASE_REFERENCE_COUNT
        ) AS FIXED_DATABASE_COUNT,

        SUM(
            DB_NAME_CONSTANT_COUNT
        ) AS DB_NAME_COUNT,

        SUM(
            SQL_ESCAPE_REFERENCE_COUNT
        ) AS SQL_ESCAPE_COUNT,

        SUM(
            QMARK_PARAMETER_COUNT
        ) AS QMARK_COUNT,

        SUM(
            PARAMS_ARGUMENT_COUNT
        ) AS PARAMS_COUNT,

        COUNT_IF(
            BUSINESS_LOGIC_CHANGED_FLAG = TRUE
        ) AS BUSINESS_LOGIC_CHANGE_COUNT,

        COUNT_IF(
            DEPLOYMENT_READY_FLAG = TRUE
        ) AS DEPLOYMENT_READY_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1

    WHERE CANDIDATE_ID =
          'PHASE14D3D2C_CORTEX_BMCS_V1'
),
ORIGINAL AS (
    SELECT
        COUNT(*) AS ORIGINAL_COUNT,

        COUNT_IF(
            OBJECT_DDL_HASH =
                7001001297441927869
        ) AS ORIGINAL_HASH_MATCH_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1

    WHERE AUDIT_BATCH_ID =
          'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'

      AND OBJECT_SCHEMA =
          'CORE_INTERNAL'

      AND OBJECT_NAME =
          'RUN_CORTEX_BMCS_ASSESSMENT'

      AND OBJECT_SIGNATURE =
          '(RFQ_ID VARCHAR)'
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            CANDIDATE.CANDIDATE_COUNT = 1
            AND CANDIDATE.VALIDATED_COUNT = 1
            AND CANDIDATE.FIXED_DATABASE_COUNT = 0
            AND CANDIDATE.DB_NAME_COUNT = 0
            AND CANDIDATE.SQL_ESCAPE_COUNT = 0
            AND CANDIDATE.QMARK_COUNT > 0
            AND CANDIDATE.PARAMS_COUNT >= 6
            AND CANDIDATE
                .BUSINESS_LOGIC_CHANGE_COUNT = 0
            AND CANDIDATE
                .DEPLOYMENT_READY_COUNT = 0
            AND ORIGINAL.ORIGINAL_COUNT = 1
            AND ORIGINAL
                .ORIGINAL_HASH_MATCH_COUNT = 1,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3D_2C',

    'candidate_count',
        CANDIDATE.CANDIDATE_COUNT,

    'validated_candidate_count',
        CANDIDATE.VALIDATED_COUNT,

    'original_hash_match_count',
        ORIGINAL.ORIGINAL_HASH_MATCH_COUNT,

    'fixed_database_reference_count',
        CANDIDATE.FIXED_DATABASE_COUNT,

    'db_name_constant_count',
        CANDIDATE.DB_NAME_COUNT,

    'sql_escape_reference_count',
        CANDIDATE.SQL_ESCAPE_COUNT,

    'qmark_parameter_count',
        CANDIDATE.QMARK_COUNT,

    'params_argument_count',
        CANDIDATE.PARAMS_COUNT,

    'business_logic_changed',
        CANDIDATE
            .BUSINESS_LOGIC_CHANGE_COUNT > 0,

    'deployment_ready_count',
        CANDIDATE.DEPLOYMENT_READY_COUNT,

    'procedure_body_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3D2C_FINAL_GATE

FROM CANDIDATE
CROSS JOIN ORIGINAL;


WITH baseline AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_BASELINE_V1
    WHERE BASELINE_ID =
          'PHASE14A_SIM_001_BASELINE_V1'
),
current_state AS (
    SELECT
        s.SIMULATION_ID,

        HASH(
            s.MATERIAL_COST_USD,
            s.LABOR_COST_USD,
            s.MACHINE_COST_USD,
            s.OVERHEAD_COST_USD,
            s.TOTAL_CONFIGURED_COST_USD,
            s.FLOOR_PRICE_USD,
            s.TARGET_PRICE_USD,
            s.CEILING_PRICE_USD,
            s.BASELINE_TOTAL_COST_USD,
            s.RISK_ADJUSTED_TOTAL_COST_USD,
            s.TOTAL_RISK_UPLIFT_USD,
            s.TOTAL_RISK_UPLIFT_PCT,
            s.CSS_SCORE,
            s.SCRAP_RATE_APPLIED,
            s.AVG_WEIGHTED_FMIS,
            s.MAX_TDS_FACTOR,
            s.BOM_MATCH_CONFIDENCE_SCORE,
            s.BMCS_REVIEW_STATUS,
            s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
            s.QUOTE_TRUST_STATUS,
            h.RESOLVED_SCRAP_RATE,
            h.CSS_RESOLVED_SOURCE,
            h.RESOLVED_FMIS_MULTIPLIER,
            h.FMIS_RESOLVED_SOURCE,
            h.RESOLVED_TDS_FACTOR,
            h.TDS_RESOLVED_SOURCE,
            h.RESOLVED_BMCS_STATUS,
            h.SAFETY_GATE_PASS_FLAG,
            h.COST_ENGINE_CONSUMPTION_ALLOWED_FLAG,
            h.OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG
        ) AS SNAPSHOT_HASH,

        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS ACTIVE_POLICY_COUNT,

        (
            SELECT COUNT_IF(
                DEPLOYMENT_MODE = 'SHADOW'
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS SHADOW_POLICY_COUNT,

        (
            SELECT COUNT_IF(
                AUTO_USE_ALLOWED_FLAG = TRUE
                OR OFFICIAL_COST_IMPACT_ALLOWED_FLAG = TRUE
                OR BUSINESS_DECISION_ALLOWED_FLAG = TRUE
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS POLICY_AUTHORITY_ENABLED_COUNT,

        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .ML_RUNTIME_AUTHORITY_REGISTRY_V1
            WHERE UPPER(AUTHORITY_STATUS) = 'ENABLED'
        ) AS ENABLED_RUNTIME_AUTHORITY_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_OUTPUT
            .KMAT_CONFIGURED_COST_SUMMARY s

    LEFT JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .VW_KMAT_PHASE10B_HIERARCHY_V1 h
      ON s.SIMULATION_ID = h.SIMULATION_ID

    WHERE s.SIMULATION_ID = 'SIM_001'

    QUALIFY ROW_NUMBER() OVER (
        PARTITION BY s.SIMULATION_ID
        ORDER BY s.CALCULATED_AT DESC
    ) = 1
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            baseline.SNAPSHOT_HASH =
                current_state.SNAPSHOT_HASH
            AND current_state
                .POLICY_AUTHORITY_ENABLED_COUNT = 0
            AND current_state
                .ENABLED_RUNTIME_AUTHORITY_COUNT = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3D_2C',

    'baseline_snapshot_hash',
        baseline.SNAPSHOT_HASH,

    'current_snapshot_hash',
        current_state.SNAPSHOT_HASH,

    'cost_and_governance_snapshot_match',
        baseline.SNAPSHOT_HASH =
        current_state.SNAPSHOT_HASH,

    'active_policy_count',
        current_state.ACTIVE_POLICY_COUNT,

    'shadow_policy_count',
        current_state.SHADOW_POLICY_COUNT,

    'policy_authority_enabled_count',
        current_state
            .POLICY_AUTHORITY_ENABLED_COUNT,

    'enabled_runtime_authority_count',
        current_state
            .ENABLED_RUNTIME_AUTHORITY_COUNT,

    'official_cost_changed',
        baseline.SNAPSHOT_HASH <>
        current_state.SNAPSHOT_HASH,

    'procedure_body_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3D2C_BASELINE_VERIFICATION

FROM baseline
CROSS JOIN current_state;

CREATE TABLE IF NOT EXISTS
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1 (
            CANDIDATE_ID VARCHAR NOT NULL,
            PHASE VARCHAR NOT NULL,
            OBJECT_SCHEMA VARCHAR NOT NULL,
            OBJECT_NAME VARCHAR NOT NULL,
            OBJECT_SIGNATURE VARCHAR NOT NULL,
            EXPECTED_ORIGINAL_DDL_HASH NUMBER NOT NULL,
            CANDIDATE_SOURCE VARCHAR NOT NULL,
            CANDIDATE_SOURCE_HASH NUMBER NOT NULL,
            FIXED_DATABASE_REFERENCE_COUNT NUMBER NOT NULL,
            DB_NAME_CONSTANT_COUNT NUMBER NOT NULL,
            SQL_ESCAPE_REFERENCE_COUNT NUMBER NOT NULL,
            QMARK_PARAMETER_COUNT NUMBER NOT NULL,
            PARAMS_ARGUMENT_COUNT NUMBER NOT NULL,
            SCHEMA_RELATIVE_REFERENCE_COUNT NUMBER NOT NULL,
            BUSINESS_LOGIC_CHANGED_FLAG BOOLEAN NOT NULL,
            DEPLOYMENT_READY_FLAG BOOLEAN NOT NULL,
            CANDIDATE_SOURCE_EXECUTED_FLAG BOOLEAN NOT NULL,
            CANDIDATE_STATUS VARCHAR NOT NULL,
            GENERATED_BY VARCHAR NOT NULL,
            GENERATED_AT TIMESTAMP_NTZ NOT NULL
        );

DELETE FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1
WHERE CANDIDATE_ID =
      'PHASE14D3D2D_QUOTE_PIPELINE_V1';

INSERT INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1
WITH SOURCE AS (
    SELECT $$
import json


def parse_json_safe(value):
    if value is None:
        return {}

    if isinstance(value, dict):
        return value

    if isinstance(value, str):
        try:
            return json.loads(value)
        except Exception:
            return {"raw_result": value}

    return {"raw_result": str(value)}


def quote_trust_status(
    review_status,
    review_required,
    final_allowed,
):
    if (
        review_status == "AUTO_APPROVED"
        and final_allowed
    ):
        return "TRUSTED_AUTO_APPROVED"

    if (
        review_status == "REVIEW_RECOMMENDED"
        and final_allowed
    ):
        return (
            "TRUSTED_WITH_REVIEW_RECOMMENDED"
        )

    if review_required or not final_allowed:
        return (
            "PRELIMINARY_ENGINEERING_"
            "REVIEW_REQUIRED"
        )

    return "BMCS_STATUS_CHECK_REQUIRED"


def run(session, RFQ_ID):
    bmcs_rows = session.sql(
        """
        CALL CORE_INTERNAL
            .RUN_CORTEX_BMCS_ASSESSMENT(?)
        """,
        params=[RFQ_ID],
    ).collect()

    bmcs_result = parse_json_safe(
        bmcs_rows[0][0]
        if bmcs_rows
        else "{}"
    )

    if bmcs_result.get("status") != "SUCCESS":
        return json.dumps({
            "status": "ERROR",
            "stage": "CORTEX_BMCS_ASSESSMENT",
            "result": bmcs_result,
        })

    prep_rows = session.sql(
        """
        CALL CORE_INTERNAL
            .PREPARE_RFQ_SIMULATION_INPUTS(?)
        """,
        params=[RFQ_ID],
    ).collect()

    prep_result = parse_json_safe(
        prep_rows[0][0]
        if prep_rows
        else "{}"
    )

    if prep_result.get("status") != "SUCCESS":
        return json.dumps({
            "status": "ERROR",
            "stage":
                "PREPARE_RFQ_SIMULATION_INPUTS",
            "result": prep_result,
        })

    simulation_id = prep_result.get(
        "simulation_id"
    )

    if not simulation_id:
        return json.dumps({
            "status": "ERROR",
            "stage":
                "PREPARE_RFQ_SIMULATION_INPUTS",
            "message": (
                "Simulation ID missing from "
                "prepare result."
            ),
            "result": prep_result,
        })

    cost_rows = session.sql(
        """
        CALL CORE_INTERNAL
            .RUN_KMAT_COST_SIMULATION(?)
        """,
        params=[simulation_id],
    ).collect()

    cost_result = parse_json_safe(
        cost_rows[0][0]
        if cost_rows
        else "{}"
    )

    if cost_result.get("status") != "SUCCESS":
        return json.dumps({
            "status": "ERROR",
            "stage":
                "RUN_KMAT_COST_SIMULATION",
            "result": cost_result,
        })

    bmcs_rows_2 = session.sql(
        """
        CALL CORE_INTERNAL
            .RUN_CORTEX_BMCS_ASSESSMENT(?)
        """,
        params=[RFQ_ID],
    ).collect()

    bmcs_result_2 = parse_json_safe(
        bmcs_rows_2[0][0]
        if bmcs_rows_2
        else "{}"
    )

    status_rows = session.sql(
        """
        SELECT
            RFQ_ID,
            SOURCE_DOCUMENT_NAME,
            CONFIGURATION_VERSION,
            BOM_MATCH_CONFIDENCE_SCORE,
            REVIEW_STATUS,
            REVIEW_REQUIRED_FLAG,
            FINAL_TRUSTED_COST_ALLOWED_FLAG,
            ASSESSMENT_METHOD,
            ASSESSMENT_VERSION,
            ASSESSMENT_NOTES
        FROM CORE_INPUT.VW_RFQ_BMCS_STATUS
        WHERE RFQ_ID = ?
        LIMIT 1
        """,
        params=[RFQ_ID],
    ).collect()

    if len(status_rows) == 0:
        return json.dumps({
            "status": "ERROR",
            "stage": "READ_FINAL_BMCS_STATUS",
            "message": (
                "No BMCS status found after "
                "hybrid scoring."
            ),
        })

    status = status_rows[0]

    trust_status = quote_trust_status(
        status["REVIEW_STATUS"],
        bool(
            status["REVIEW_REQUIRED_FLAG"]
        ),
        bool(
            status[
                "FINAL_TRUSTED_COST_ALLOWED_FLAG"
            ]
        ),
    )

    session.sql(
        """
        UPDATE
            CORE_OUTPUT.KMAT_CONFIGURED_COST_SUMMARY
        SET
            RFQ_ID = ?,
            SOURCE_DOCUMENT_NAME = ?,
            BMCS_CONFIGURATION_VERSION = ?,
            BOM_MATCH_CONFIDENCE_SCORE = ?,
            BMCS_REVIEW_STATUS = ?,
            BMCS_REVIEW_REQUIRED_FLAG = ?,
            FINAL_TRUSTED_COST_ALLOWED_FLAG = ?,
            QUOTE_TRUST_STATUS = ?,
            BMCS_ASSESSMENT_METHOD = ?,
            BMCS_ASSESSMENT_VERSION = ?,
            BMCS_ASSESSMENT_NOTES = ?
        WHERE SIMULATION_ID = ?
        """,
        params=[
            status["RFQ_ID"],
            status["SOURCE_DOCUMENT_NAME"],
            int(
                status[
                    "CONFIGURATION_VERSION"
                ]
            ),
            float(
                status[
                    "BOM_MATCH_CONFIDENCE_SCORE"
                ]
            ),
            status["REVIEW_STATUS"],
            bool(
                status[
                    "REVIEW_REQUIRED_FLAG"
                ]
            ),
            bool(
                status[
                    "FINAL_TRUSTED_COST_ALLOWED_FLAG"
                ]
            ),
            trust_status,
            status["ASSESSMENT_METHOD"],
            status["ASSESSMENT_VERSION"],
            status["ASSESSMENT_NOTES"],
            simulation_id,
        ],
    ).collect()

    return json.dumps({
        "status": "SUCCESS",
        "rfq_id": RFQ_ID,
        "simulation_id": simulation_id,
        "bmcs_result": bmcs_result_2,
        "cost_result": cost_result,
        "quote_trust_status": trust_status,
    })

$$ AS CANDIDATE_SOURCE
),
VALIDATION AS (
    SELECT
        CANDIDATE_SOURCE,

        REGEXP_COUNT(
            UPPER(CANDIDATE_SOURCE),
            'KMAT_COST_MODEL_DB'
        ) AS FIXED_DATABASE_COUNT,

        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'DB_NAME'
        ) AS DB_NAME_COUNT,

        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'sql_escape'
        ) AS SQL_ESCAPE_COUNT,

        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            '[?]'
        ) AS QMARK_COUNT,

        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'params[[:space:]]*='
        ) AS PARAMS_COUNT,

        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'CORE_INTERNAL'
        )
        +
        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'CORE_INPUT[.]'
        )
        +
        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'CORE_OUTPUT[.]'
        ) AS SCHEMA_REFERENCE_COUNT,

        POSITION(
            'RUN_CORTEX_BMCS_ASSESSMENT'
            IN CANDIDATE_SOURCE
        ) > 0
            AS CORTEX_BMCS_CALL_PRESERVED,

        POSITION(
            'PREPARE_RFQ_SIMULATION_INPUTS'
            IN CANDIDATE_SOURCE
        ) > 0
            AS PREPARE_CALL_PRESERVED,

        POSITION(
            'RUN_KMAT_COST_SIMULATION'
            IN CANDIDATE_SOURCE
        ) > 0
            AS COST_CALL_PRESERVED,

        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'RUN_CORTEX_BMCS_ASSESSMENT'
        ) = 2
            AS BMCS_REFRESH_PRESERVED,

        POSITION(
            'VW_RFQ_BMCS_STATUS'
            IN CANDIDATE_SOURCE
        ) > 0
            AS FINAL_STATUS_READ_PRESERVED,

        POSITION(
            'KMAT_CONFIGURED_COST_SUMMARY'
            IN CANDIDATE_SOURCE
        ) > 0
            AS COST_SUMMARY_UPDATE_PRESERVED,

        POSITION(
            'TRUSTED_AUTO_APPROVED'
            IN CANDIDATE_SOURCE
        ) > 0
        AND POSITION(
            'TRUSTED_WITH_REVIEW_RECOMMENDED'
            IN CANDIDATE_SOURCE
        ) > 0
        AND POSITION(
            'PRELIMINARY_ENGINEERING_'
            IN CANDIDATE_SOURCE
        ) > 0
        AND POSITION(
            'BMCS_STATUS_CHECK_REQUIRED'
            IN CANDIDATE_SOURCE
        ) > 0
            AS TRUST_MAPPING_PRESERVED

    FROM SOURCE
)
SELECT
    'PHASE14D3D2D_QUOTE_PIPELINE_V1',
    'PHASE_14D_3D_2D',
    'CORE_INTERNAL',
    'RUN_CORTEX_RFQ_QUOTE_PIPELINE',
    '(RFQ_ID VARCHAR)',
    -3637676842551177783,
    CANDIDATE_SOURCE,
    HASH(CANDIDATE_SOURCE),
    FIXED_DATABASE_COUNT,
    DB_NAME_COUNT,
    SQL_ESCAPE_COUNT,
    QMARK_COUNT,
    PARAMS_COUNT,
    SCHEMA_REFERENCE_COUNT,
    TRUE,
    FALSE,
    FALSE,

    IFF(
        FIXED_DATABASE_COUNT = 0
        AND DB_NAME_COUNT = 0
        AND SQL_ESCAPE_COUNT = 0
        AND QMARK_COUNT > 0
        AND PARAMS_COUNT = 6
        AND SCHEMA_REFERENCE_COUNT >= 6
        AND CORTEX_BMCS_CALL_PRESERVED
        AND PREPARE_CALL_PRESERVED
        AND COST_CALL_PRESERVED
        AND BMCS_REFRESH_PRESERVED
        AND FINAL_STATUS_READ_PRESERVED
        AND COST_SUMMARY_UPDATE_PRESERVED
        AND TRUST_MAPPING_PRESERVED,
        'VALIDATED_REVIEW_ONLY',
        'ATTENTION_REQUIRED'
    ),

    CURRENT_USER(),
    CURRENT_TIMESTAMP()

FROM VALIDATION;


SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COUNT(*) = 1
            AND COUNT_IF(
                CANDIDATE_STATUS =
                    'VALIDATED_REVIEW_ONLY'
            ) = 1,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3D_2D',

    'candidate_id',
        'PHASE14D3D2D_QUOTE_PIPELINE_V1',

    'candidate_count',
        COUNT(*),

    'fixed_database_reference_count',
        SUM(
            FIXED_DATABASE_REFERENCE_COUNT
        ),

    'db_name_constant_count',
        SUM(
            DB_NAME_CONSTANT_COUNT
        ),

    'sql_escape_reference_count',
        SUM(
            SQL_ESCAPE_REFERENCE_COUNT
        ),

    'qmark_parameter_count',
        SUM(
            QMARK_PARAMETER_COUNT
        ),

    'params_argument_count',
        SUM(
            PARAMS_ARGUMENT_COUNT
        ),

    'schema_relative_reference_count',
        SUM(
            SCHEMA_RELATIVE_REFERENCE_COUNT
        ),

    'bmcs_before_cost_preserved',
        TRUE,

    'prepare_input_call_preserved',
        TRUE,

    'deterministic_cost_call_preserved',
        TRUE,

    'bmcs_refresh_after_cost_preserved',
        TRUE,

    'quote_trust_mapping_preserved',
        TRUE,

    'cost_summary_update_preserved',
        TRUE,

    'business_logic_changed',
        FALSE,

    'deployment_ready_count',
        COUNT_IF(
            DEPLOYMENT_READY_FLAG = TRUE
        ),

    'procedure_body_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3D2D_CANDIDATE_SUMMARY

FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1

WHERE CANDIDATE_ID =
      'PHASE14D3D2D_QUOTE_PIPELINE_V1';

WITH CANDIDATE AS (
    SELECT
        COUNT(*) AS CANDIDATE_COUNT,

        COUNT_IF(
            CANDIDATE_STATUS =
                'VALIDATED_REVIEW_ONLY'
        ) AS VALIDATED_COUNT,

        SUM(
            FIXED_DATABASE_REFERENCE_COUNT
        ) AS FIXED_DATABASE_COUNT,

        SUM(
            DB_NAME_CONSTANT_COUNT
        ) AS DB_NAME_COUNT,

        SUM(
            SQL_ESCAPE_REFERENCE_COUNT
        ) AS SQL_ESCAPE_COUNT,

        SUM(
            QMARK_PARAMETER_COUNT
        ) AS QMARK_COUNT,

        SUM(
            PARAMS_ARGUMENT_COUNT
        ) AS PARAMS_COUNT,

        COUNT_IF(
            BUSINESS_LOGIC_CHANGED_FLAG = TRUE
        ) AS BUSINESS_LOGIC_CHANGE_COUNT,

        COUNT_IF(
            DEPLOYMENT_READY_FLAG = TRUE
        ) AS DEPLOYMENT_READY_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1

    WHERE CANDIDATE_ID =
          'PHASE14D3D2D_QUOTE_PIPELINE_V1'
),
ORIGINAL AS (
    SELECT
        COUNT(*) AS ORIGINAL_COUNT,

        COUNT_IF(
            OBJECT_DDL_HASH =
                -3637676842551177783
        ) AS ORIGINAL_HASH_MATCH_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1

    WHERE AUDIT_BATCH_ID =
          'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'

      AND OBJECT_SCHEMA =
          'CORE_INTERNAL'

      AND OBJECT_NAME =
          'RUN_CORTEX_RFQ_QUOTE_PIPELINE'

      AND OBJECT_SIGNATURE =
          '(RFQ_ID VARCHAR)'
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            CANDIDATE.CANDIDATE_COUNT = 1
            AND CANDIDATE.VALIDATED_COUNT = 1
            AND CANDIDATE.FIXED_DATABASE_COUNT = 0
            AND CANDIDATE.DB_NAME_COUNT = 0
            AND CANDIDATE.SQL_ESCAPE_COUNT = 0
            AND CANDIDATE.QMARK_COUNT > 0
            AND CANDIDATE.PARAMS_COUNT = 6
            AND CANDIDATE
                .BUSINESS_LOGIC_CHANGE_COUNT = 0
            AND CANDIDATE
                .DEPLOYMENT_READY_COUNT = 0
            AND ORIGINAL.ORIGINAL_COUNT = 1
            AND ORIGINAL
                .ORIGINAL_HASH_MATCH_COUNT = 1,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3D_2D',

    'candidate_count',
        CANDIDATE.CANDIDATE_COUNT,

    'validated_candidate_count',
        CANDIDATE.VALIDATED_COUNT,

    'original_hash_match_count',
        ORIGINAL.ORIGINAL_HASH_MATCH_COUNT,

    'fixed_database_reference_count',
        CANDIDATE.FIXED_DATABASE_COUNT,

    'db_name_constant_count',
        CANDIDATE.DB_NAME_COUNT,

    'sql_escape_reference_count',
        CANDIDATE.SQL_ESCAPE_COUNT,

    'qmark_parameter_count',
        CANDIDATE.QMARK_COUNT,

    'params_argument_count',
        CANDIDATE.PARAMS_COUNT,

    'business_logic_changed',
        CANDIDATE
            .BUSINESS_LOGIC_CHANGE_COUNT > 0,

    'deployment_ready_count',
        CANDIDATE.DEPLOYMENT_READY_COUNT,

    'procedure_body_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3D2D_FINAL_GATE

FROM CANDIDATE
CROSS JOIN ORIGINAL;


WITH baseline AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_BASELINE_V1
    WHERE BASELINE_ID =
          'PHASE14A_SIM_001_BASELINE_V1'
),
current_state AS (
    SELECT
        s.SIMULATION_ID,

        HASH(
            s.MATERIAL_COST_USD,
            s.LABOR_COST_USD,
            s.MACHINE_COST_USD,
            s.OVERHEAD_COST_USD,
            s.TOTAL_CONFIGURED_COST_USD,
            s.FLOOR_PRICE_USD,
            s.TARGET_PRICE_USD,
            s.CEILING_PRICE_USD,
            s.BASELINE_TOTAL_COST_USD,
            s.RISK_ADJUSTED_TOTAL_COST_USD,
            s.TOTAL_RISK_UPLIFT_USD,
            s.TOTAL_RISK_UPLIFT_PCT,
            s.CSS_SCORE,
            s.SCRAP_RATE_APPLIED,
            s.AVG_WEIGHTED_FMIS,
            s.MAX_TDS_FACTOR,
            s.BOM_MATCH_CONFIDENCE_SCORE,
            s.BMCS_REVIEW_STATUS,
            s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
            s.QUOTE_TRUST_STATUS,
            h.RESOLVED_SCRAP_RATE,
            h.CSS_RESOLVED_SOURCE,
            h.RESOLVED_FMIS_MULTIPLIER,
            h.FMIS_RESOLVED_SOURCE,
            h.RESOLVED_TDS_FACTOR,
            h.TDS_RESOLVED_SOURCE,
            h.RESOLVED_BMCS_STATUS,
            h.SAFETY_GATE_PASS_FLAG,
            h.COST_ENGINE_CONSUMPTION_ALLOWED_FLAG,
            h.OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG
        ) AS SNAPSHOT_HASH,

        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS ACTIVE_POLICY_COUNT,

        (
            SELECT COUNT_IF(
                DEPLOYMENT_MODE = 'SHADOW'
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS SHADOW_POLICY_COUNT,

        (
            SELECT COUNT_IF(
                AUTO_USE_ALLOWED_FLAG = TRUE
                OR OFFICIAL_COST_IMPACT_ALLOWED_FLAG = TRUE
                OR BUSINESS_DECISION_ALLOWED_FLAG = TRUE
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS POLICY_AUTHORITY_ENABLED_COUNT,

        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .ML_RUNTIME_AUTHORITY_REGISTRY_V1
            WHERE UPPER(AUTHORITY_STATUS) = 'ENABLED'
        ) AS ENABLED_RUNTIME_AUTHORITY_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_OUTPUT
            .KMAT_CONFIGURED_COST_SUMMARY s

    LEFT JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .VW_KMAT_PHASE10B_HIERARCHY_V1 h
      ON s.SIMULATION_ID = h.SIMULATION_ID

    WHERE s.SIMULATION_ID = 'SIM_001'

    QUALIFY ROW_NUMBER() OVER (
        PARTITION BY s.SIMULATION_ID
        ORDER BY s.CALCULATED_AT DESC
    ) = 1
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            baseline.SNAPSHOT_HASH =
                current_state.SNAPSHOT_HASH
            AND current_state
                .POLICY_AUTHORITY_ENABLED_COUNT = 0
            AND current_state
                .ENABLED_RUNTIME_AUTHORITY_COUNT = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_3D_2D',

    'baseline_snapshot_hash',
        baseline.SNAPSHOT_HASH,

    'current_snapshot_hash',
        current_state.SNAPSHOT_HASH,

    'cost_and_governance_snapshot_match',
        baseline.SNAPSHOT_HASH =
        current_state.SNAPSHOT_HASH,

    'active_policy_count',
        current_state.ACTIVE_POLICY_COUNT,

    'shadow_policy_count',
        current_state.SHADOW_POLICY_COUNT,

    'policy_authority_enabled_count',
        current_state
            .POLICY_AUTHORITY_ENABLED_COUNT,

    'enabled_runtime_authority_count',
        current_state
            .ENABLED_RUNTIME_AUTHORITY_COUNT,

    'official_cost_changed',
        baseline.SNAPSHOT_HASH <>
        current_state.SNAPSHOT_HASH,

    'procedure_body_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D3D2D_BASELINE_VERIFICATION

FROM baseline
CROSS JOIN current_state;

CREATE TABLE IF NOT EXISTS
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_COST_ENGINE_CONTRACT_V1 (
            CONTRACT_ID VARCHAR NOT NULL,
            PHASE VARCHAR NOT NULL,
            OBJECT_SCHEMA VARCHAR NOT NULL,
            OBJECT_NAME VARCHAR NOT NULL,
            OBJECT_SIGNATURE VARCHAR NOT NULL,
            EXPECTED_DDL_HASH NUMBER NOT NULL,
            CURRENT_DDL_HASH NUMBER,
            OBJECT_OWNER VARCHAR,
            OBJECT_LANGUAGE VARCHAR,
            OWNER_RIGHTS_FLAG BOOLEAN,
            DYNAMIC_SQL_COUNT NUMBER,
            FIXED_DATABASE_REFERENCE_COUNT NUMBER,
            FIXED_WAREHOUSE_REFERENCE_COUNT NUMBER,
            TEMP_OBJECT_REFERENCE_COUNT NUMBER,
            SUPER_BOM_CONTRACT_FLAG BOOLEAN,
            SUPER_ROUTING_CONTRACT_FLAG BOOLEAN,
            DEPENDENCY_RULE_CONTRACT_FLAG BOOLEAN,
            CSS_CONTRACT_FLAG BOOLEAN,
            FMIS_CONTRACT_FLAG BOOLEAN,
            TDS_CONTRACT_FLAG BOOLEAN,
            OVERHEAD_CONTRACT_FLAG BOOLEAN,
            BASELINE_COST_FORMULA_FLAG BOOLEAN,
            RISK_COST_FORMULA_FLAG BOOLEAN,
            PRICE_FORMULA_FLAG BOOLEAN,
            OUTPUT_COMPONENT_TABLE_FLAG BOOLEAN,
            OUTPUT_OPERATION_TABLE_FLAG BOOLEAN,
            OUTPUT_OVERHEAD_TABLE_FLAG BOOLEAN,
            OUTPUT_SUMMARY_TABLE_FLAG BOOLEAN,
            RISK_MODEL_VERSION_FLAG BOOLEAN,
            RETURN_CONTRACT_FLAG BOOLEAN,
            CONTRACT_STATUS VARCHAR NOT NULL,
            CAPTURED_BY VARCHAR NOT NULL,
            CAPTURED_AT TIMESTAMP_NTZ NOT NULL
        );

DELETE FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_COST_ENGINE_CONTRACT_V1
WHERE CONTRACT_ID =
      'PHASE14D3D3A_COST_ENGINE_V1';

INSERT INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_COST_ENGINE_CONTRACT_V1
WITH SOURCE AS (
    SELECT
        OBJECT_DDL,
        OBJECT_DDL_HASH,
        OBJECT_OWNER,
        OBJECT_LANGUAGE,
        DYNAMIC_SQL_INDICATOR_COUNT,
        FIXED_DATABASE_REFERENCE_COUNT,
        FIXED_WAREHOUSE_REFERENCE_COUNT,
        TEMP_OBJECT_REFERENCE_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1
    WHERE AUDIT_BATCH_ID =
          'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
      AND OBJECT_TYPE = 'PROCEDURE'
      AND OBJECT_SCHEMA = 'CORE_INTERNAL'
      AND OBJECT_NAME =
          'RUN_KMAT_COST_SIMULATION'
      AND OBJECT_SIGNATURE =
          '(SIMULATION_ID VARCHAR)'
),
FLAGS AS (
    SELECT
        *,

        REGEXP_COUNT(
            UPPER(OBJECT_DDL),
            'EXECUTE[[:space:]]+AS[[:space:]]+OWNER'
        ) > 0 AS OWNER_RIGHTS_FLAG,

        POSITION(
            'CORE_INPUT.KMAT_SUPER_BOM'
            IN OBJECT_DDL
        ) > 0 AS SUPER_BOM_CONTRACT_FLAG,

        POSITION(
            'CORE_INPUT.KMAT_SUPER_ROUTING'
            IN OBJECT_DDL
        ) > 0 AS SUPER_ROUTING_CONTRACT_FLAG,

        POSITION(
            'CORE_INPUT.DEPENDENCY_RULES'
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            'def evaluate_rule'
            IN OBJECT_DDL
        ) > 0 AS DEPENDENCY_RULE_CONTRACT_FLAG,

        POSITION(
            'CORE_INPUT.SCRAP_SCORE_RULES'
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            'CORE_INPUT.SCRAP_SCORE_BANDS'
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            'def calculate_css'
            IN OBJECT_DDL
        ) > 0 AS CSS_CONTRACT_FLAG,

        POSITION(
            'CORE_INPUT.MATERIAL_INDEX_FORECASTS'
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            'CORE_INPUT.COMPONENT_COMMODITY_EXPOSURE'
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            'def get_weighted_fmis'
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            'weighted_fmis += '
            || 'exposure_percent * fmis'
            IN OBJECT_DDL
        ) > 0 AS FMIS_CONTRACT_FLAG,

        POSITION(
            'CORE_INPUT.OPERATION_TDS_RULES'
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            'adjusted_machine_rate = '
            || 'operating_rate + '
            || '(maintenance_rate * tds_factor)'
            IN OBJECT_DDL
        ) > 0 AS TDS_CONTRACT_FLAG,

        POSITION(
            'CORE_INPUT.OVERHEAD_RATES'
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            'MATERIAL_PERCENT'
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            'LABOR_PERCENT'
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            'MACHINE_PERCENT'
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            'TOTAL_COST_PERCENT'
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            'FIXED'
            IN OBJECT_DDL
        ) > 0 AS OVERHEAD_CONTRACT_FLAG,

        POSITION(
            'baseline_total_cost = ('
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            'baseline_material_total'
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            'baseline_labor_total'
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            'baseline_machine_total'
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            'baseline_overhead_total'
            IN OBJECT_DDL
        ) > 0 AS BASELINE_COST_FORMULA_FLAG,

        POSITION(
            'risk_adjusted_total_cost = ('
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            'risk_adjusted_material_total'
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            'risk_adjusted_machine_total'
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            'risk_adjusted_overhead_total'
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            'total_risk_uplift = '
            || 'risk_adjusted_total_cost '
            || '- baseline_total_cost'
            IN OBJECT_DDL
        ) > 0 AS RISK_COST_FORMULA_FLAG,

        POSITION(
            'floor_price = '
            || 'baseline_total_cost * '
            || '(1.0 + floor_markup_pct)'
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            'target_price = '
            || 'baseline_total_cost * '
            || '(1.0 + target_margin_pct)'
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            'ceiling_price = '
            || 'baseline_total_cost * '
            || '(1.0 + ceiling_markup_pct)'
            IN OBJECT_DDL
        ) > 0 AS PRICE_FORMULA_FLAG,

        POSITION(
            'CORE_OUTPUT.KMAT_CONFIGURED_COMPONENT_COSTS'
            IN OBJECT_DDL
        ) > 0 AS OUTPUT_COMPONENT_TABLE_FLAG,

        POSITION(
            'CORE_OUTPUT.KMAT_CONFIGURED_OPERATION_COSTS'
            IN OBJECT_DDL
        ) > 0 AS OUTPUT_OPERATION_TABLE_FLAG,

        POSITION(
            'CORE_OUTPUT.KMAT_CONFIGURED_OVERHEAD_COSTS'
            IN OBJECT_DDL
        ) > 0 AS OUTPUT_OVERHEAD_TABLE_FLAG,

        POSITION(
            'CORE_OUTPUT.KMAT_CONFIGURED_COST_SUMMARY'
            IN OBJECT_DDL
        ) > 0 AS OUTPUT_SUMMARY_TABLE_FLAG,

        POSITION(
            'CSS_FMIS_TDS_RULE_BASED_V1'
            IN OBJECT_DDL
        ) > 0 AS RISK_MODEL_VERSION_FLAG,

        POSITION(
            '"baseline_total_cost_usd"'
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            '"risk_adjusted_total_cost_usd"'
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            '"total_risk_uplift_usd"'
            IN OBJECT_DDL
        ) > 0
        AND POSITION(
            '"total_risk_uplift_pct"'
            IN OBJECT_DDL
        ) > 0 AS RETURN_CONTRACT_FLAG

    FROM SOURCE
)
SELECT
    'PHASE14D3D3A_COST_ENGINE_V1',
    'PHASE_14D_3D_3A',
    'CORE_INTERNAL',
    'RUN_KMAT_COST_SIMULATION',
    '(SIMULATION_ID VARCHAR)',
    -4107916750694060430,
    OBJECT_DDL_HASH,
    OBJECT_OWNER,
    OBJECT_LANGUAGE,
    OWNER_RIGHTS_FLAG,
    DYNAMIC_SQL_INDICATOR_COUNT,
    FIXED_DATABASE_REFERENCE_COUNT,
    FIXED_WAREHOUSE_REFERENCE_COUNT,
    TEMP_OBJECT_REFERENCE_COUNT,
    SUPER_BOM_CONTRACT_FLAG,
    SUPER_ROUTING_CONTRACT_FLAG,
    DEPENDENCY_RULE_CONTRACT_FLAG,
    CSS_CONTRACT_FLAG,
    FMIS_CONTRACT_FLAG,
    TDS_CONTRACT_FLAG,
    OVERHEAD_CONTRACT_FLAG,
    BASELINE_COST_FORMULA_FLAG,
    RISK_COST_FORMULA_FLAG,
    PRICE_FORMULA_FLAG,
    OUTPUT_COMPONENT_TABLE_FLAG,
    OUTPUT_OPERATION_TABLE_FLAG,
    OUTPUT_OVERHEAD_TABLE_FLAG,
    OUTPUT_SUMMARY_TABLE_FLAG,
    RISK_MODEL_VERSION_FLAG,
    RETURN_CONTRACT_FLAG,

    IFF(
        OBJECT_DDL_HASH =
            -4107916750694060430
        AND OBJECT_OWNER = 'SYSADMIN'
        AND OBJECT_LANGUAGE = 'PYTHON'
        AND OWNER_RIGHTS_FLAG
        AND DYNAMIC_SQL_INDICATOR_COUNT = 18
        AND FIXED_DATABASE_REFERENCE_COUNT = 1
        AND FIXED_WAREHOUSE_REFERENCE_COUNT = 0
        AND TEMP_OBJECT_REFERENCE_COUNT = 0
        AND SUPER_BOM_CONTRACT_FLAG
        AND SUPER_ROUTING_CONTRACT_FLAG
        AND DEPENDENCY_RULE_CONTRACT_FLAG
        AND CSS_CONTRACT_FLAG
        AND FMIS_CONTRACT_FLAG
        AND TDS_CONTRACT_FLAG
        AND OVERHEAD_CONTRACT_FLAG
        AND BASELINE_COST_FORMULA_FLAG
        AND RISK_COST_FORMULA_FLAG
        AND PRICE_FORMULA_FLAG
        AND OUTPUT_COMPONENT_TABLE_FLAG
        AND OUTPUT_OPERATION_TABLE_FLAG
        AND OUTPUT_OVERHEAD_TABLE_FLAG
        AND OUTPUT_SUMMARY_TABLE_FLAG
        AND RISK_MODEL_VERSION_FLAG
        AND RETURN_CONTRACT_FLAG,
        'CONTRACT_FROZEN',
        'ATTENTION_REQUIRED'
    ),

    CURRENT_USER(),
    CURRENT_TIMESTAMP()

FROM FLAGS;


SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COUNT(*) = 1
            AND COUNT_IF(
                CONTRACT_STATUS =
                    'CONTRACT_FROZEN'
            ) = 1,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),
    'phase',
        'PHASE_14D_3D_3A',
    'contract_id',
        'PHASE14D3D3A_COST_ENGINE_V1',
    'target_procedure_count',
        COUNT(*),
    'contract_frozen_count',
        COUNT_IF(
            CONTRACT_STATUS =
                'CONTRACT_FROZEN'
        ),
    'owner_rights_count',
        COUNT_IF(
            OWNER_RIGHTS_FLAG = TRUE
        ),
    'dynamic_sql_count',
        MAX(DYNAMIC_SQL_COUNT),
    'fixed_database_reference_count',
        MAX(
            FIXED_DATABASE_REFERENCE_COUNT
        ),
    'fixed_warehouse_reference_count',
        MAX(
            FIXED_WAREHOUSE_REFERENCE_COUNT
        ),
    'temporary_object_reference_count',
        MAX(
            TEMP_OBJECT_REFERENCE_COUNT
        ),
    'super_bom_preserved',
        BOOLOR_AGG(
            SUPER_BOM_CONTRACT_FLAG
        ),
    'super_routing_preserved',
        BOOLOR_AGG(
            SUPER_ROUTING_CONTRACT_FLAG
        ),
    'css_preserved',
        BOOLOR_AGG(
            CSS_CONTRACT_FLAG
        ),
    'fmis_preserved',
        BOOLOR_AGG(
            FMIS_CONTRACT_FLAG
        ),
    'tds_preserved',
        BOOLOR_AGG(
            TDS_CONTRACT_FLAG
        ),
    'overhead_preserved',
        BOOLOR_AGG(
            OVERHEAD_CONTRACT_FLAG
        ),
    'baseline_cost_formula_preserved',
        BOOLOR_AGG(
            BASELINE_COST_FORMULA_FLAG
        ),
    'risk_cost_formula_preserved',
        BOOLOR_AGG(
            RISK_COST_FORMULA_FLAG
        ),
    'price_formula_preserved',
        BOOLOR_AGG(
            PRICE_FORMULA_FLAG
        ),
    'output_table_contract_count',
        COUNT_IF(
            OUTPUT_COMPONENT_TABLE_FLAG
            AND OUTPUT_OPERATION_TABLE_FLAG
            AND OUTPUT_OVERHEAD_TABLE_FLAG
            AND OUTPUT_SUMMARY_TABLE_FLAG
        ) * 4,
    'procedure_body_changed',
        FALSE,
    'candidate_source_created',
        FALSE,
    'candidate_source_executed',
        FALSE,
    'official_cost_changed',
        FALSE,
    'native_app_package_created',
        FALSE
) AS PHASE14D3D3A_CONTRACT_SUMMARY
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_COST_ENGINE_CONTRACT_V1
WHERE CONTRACT_ID =
      'PHASE14D3D3A_COST_ENGINE_V1';


SELECT
    OBJECT_SCHEMA,
    OBJECT_NAME,
    OBJECT_SIGNATURE,
    EXPECTED_DDL_HASH,
    CURRENT_DDL_HASH,
    OBJECT_OWNER,
    OBJECT_LANGUAGE,
    OWNER_RIGHTS_FLAG,
    DYNAMIC_SQL_COUNT,
    SUPER_BOM_CONTRACT_FLAG,
    SUPER_ROUTING_CONTRACT_FLAG,
    DEPENDENCY_RULE_CONTRACT_FLAG,
    CSS_CONTRACT_FLAG,
    FMIS_CONTRACT_FLAG,
    TDS_CONTRACT_FLAG,
    OVERHEAD_CONTRACT_FLAG,
    BASELINE_COST_FORMULA_FLAG,
    RISK_COST_FORMULA_FLAG,
    PRICE_FORMULA_FLAG,
    OUTPUT_COMPONENT_TABLE_FLAG,
    OUTPUT_OPERATION_TABLE_FLAG,
    OUTPUT_OVERHEAD_TABLE_FLAG,
    OUTPUT_SUMMARY_TABLE_FLAG,
    RISK_MODEL_VERSION_FLAG,
    RETURN_CONTRACT_FLAG,
    CONTRACT_STATUS
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_COST_ENGINE_CONTRACT_V1
WHERE CONTRACT_ID =
      'PHASE14D3D3A_COST_ENGINE_V1';

WITH CONTRACT AS (
    SELECT
        COUNT(*) AS CONTRACT_COUNT,
        COUNT_IF(
            CONTRACT_STATUS =
                'CONTRACT_FROZEN'
        ) AS FROZEN_COUNT,
        COUNT_IF(
            CURRENT_DDL_HASH =
                EXPECTED_DDL_HASH
        ) AS HASH_MATCH_COUNT,
        COUNT_IF(
            OWNER_RIGHTS_FLAG = TRUE
        ) AS OWNER_RIGHTS_COUNT,
        COUNT_IF(
            SUPER_BOM_CONTRACT_FLAG
            AND SUPER_ROUTING_CONTRACT_FLAG
            AND DEPENDENCY_RULE_CONTRACT_FLAG
            AND CSS_CONTRACT_FLAG
            AND FMIS_CONTRACT_FLAG
            AND TDS_CONTRACT_FLAG
            AND OVERHEAD_CONTRACT_FLAG
            AND BASELINE_COST_FORMULA_FLAG
            AND RISK_COST_FORMULA_FLAG
            AND PRICE_FORMULA_FLAG
            AND OUTPUT_COMPONENT_TABLE_FLAG
            AND OUTPUT_OPERATION_TABLE_FLAG
            AND OUTPUT_OVERHEAD_TABLE_FLAG
            AND OUTPUT_SUMMARY_TABLE_FLAG
            AND RISK_MODEL_VERSION_FLAG
            AND RETURN_CONTRACT_FLAG
        ) AS COMPLETE_EQUIVALENCE_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_COST_ENGINE_CONTRACT_V1
    WHERE CONTRACT_ID =
          'PHASE14D3D3A_COST_ENGINE_V1'
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            CONTRACT_COUNT = 1
            AND FROZEN_COUNT = 1
            AND HASH_MATCH_COUNT = 1
            AND OWNER_RIGHTS_COUNT = 1
            AND COMPLETE_EQUIVALENCE_COUNT = 1,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),
    'phase',
        'PHASE_14D_3D_3A',
    'contract_count',
        CONTRACT_COUNT,
    'contract_frozen_count',
        FROZEN_COUNT,
    'original_hash_match_count',
        HASH_MATCH_COUNT,
    'owner_rights_count',
        OWNER_RIGHTS_COUNT,
    'complete_equivalence_contract_count',
        COMPLETE_EQUIVALENCE_COUNT,
    'procedure_body_changed',
        FALSE,
    'candidate_source_created',
        FALSE,
    'candidate_source_executed',
        FALSE,
    'official_cost_changed',
        FALSE,
    'ml_authority_changed',
        FALSE,
    'native_app_package_created',
        FALSE
) AS PHASE14D3D3A_FINAL_GATE
FROM CONTRACT;


WITH baseline AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_BASELINE_V1
    WHERE BASELINE_ID =
          'PHASE14A_SIM_001_BASELINE_V1'
),
current_state AS (
    SELECT
        s.SIMULATION_ID,
        HASH(
            s.MATERIAL_COST_USD,
            s.LABOR_COST_USD,
            s.MACHINE_COST_USD,
            s.OVERHEAD_COST_USD,
            s.TOTAL_CONFIGURED_COST_USD,
            s.FLOOR_PRICE_USD,
            s.TARGET_PRICE_USD,
            s.CEILING_PRICE_USD,
            s.BASELINE_TOTAL_COST_USD,
            s.RISK_ADJUSTED_TOTAL_COST_USD,
            s.TOTAL_RISK_UPLIFT_USD,
            s.TOTAL_RISK_UPLIFT_PCT,
            s.CSS_SCORE,
            s.SCRAP_RATE_APPLIED,
            s.AVG_WEIGHTED_FMIS,
            s.MAX_TDS_FACTOR,
            s.BOM_MATCH_CONFIDENCE_SCORE,
            s.BMCS_REVIEW_STATUS,
            s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
            s.QUOTE_TRUST_STATUS,
            h.RESOLVED_SCRAP_RATE,
            h.CSS_RESOLVED_SOURCE,
            h.RESOLVED_FMIS_MULTIPLIER,
            h.FMIS_RESOLVED_SOURCE,
            h.RESOLVED_TDS_FACTOR,
            h.TDS_RESOLVED_SOURCE,
            h.RESOLVED_BMCS_STATUS,
            h.SAFETY_GATE_PASS_FLAG,
            h.COST_ENGINE_CONSUMPTION_ALLOWED_FLAG,
            h.OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG
        ) AS SNAPSHOT_HASH,
        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS ACTIVE_POLICY_COUNT,
        (
            SELECT COUNT_IF(
                DEPLOYMENT_MODE = 'SHADOW'
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS SHADOW_POLICY_COUNT,
        (
            SELECT COUNT_IF(
                AUTO_USE_ALLOWED_FLAG = TRUE
                OR OFFICIAL_COST_IMPACT_ALLOWED_FLAG = TRUE
                OR BUSINESS_DECISION_ALLOWED_FLAG = TRUE
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS POLICY_AUTHORITY_ENABLED_COUNT,
        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .ML_RUNTIME_AUTHORITY_REGISTRY_V1
            WHERE UPPER(AUTHORITY_STATUS) = 'ENABLED'
        ) AS ENABLED_RUNTIME_AUTHORITY_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_OUTPUT
            .KMAT_CONFIGURED_COST_SUMMARY s
    LEFT JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .VW_KMAT_PHASE10B_HIERARCHY_V1 h
      ON s.SIMULATION_ID = h.SIMULATION_ID
    WHERE s.SIMULATION_ID = 'SIM_001'
    QUALIFY ROW_NUMBER() OVER (
        PARTITION BY s.SIMULATION_ID
        ORDER BY s.CALCULATED_AT DESC
    ) = 1
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            baseline.SNAPSHOT_HASH =
                current_state.SNAPSHOT_HASH
            AND current_state
                .POLICY_AUTHORITY_ENABLED_COUNT = 0
            AND current_state
                .ENABLED_RUNTIME_AUTHORITY_COUNT = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),
    'phase',
        'PHASE_14D_3D_3A',
    'baseline_id',
        baseline.BASELINE_ID,
    'simulation_id',
        baseline.SIMULATION_ID,
    'baseline_snapshot_hash',
        baseline.SNAPSHOT_HASH,
    'current_snapshot_hash',
        current_state.SNAPSHOT_HASH,
    'cost_and_governance_snapshot_match',
        baseline.SNAPSHOT_HASH =
        current_state.SNAPSHOT_HASH,
    'active_policy_count',
        current_state.ACTIVE_POLICY_COUNT,
    'shadow_policy_count',
        current_state.SHADOW_POLICY_COUNT,
    'policy_authority_enabled_count',
        current_state
            .POLICY_AUTHORITY_ENABLED_COUNT,
    'enabled_runtime_authority_count',
        current_state
            .ENABLED_RUNTIME_AUTHORITY_COUNT,
    'official_cost_changed',
        baseline.SNAPSHOT_HASH <>
        current_state.SNAPSHOT_HASH,
    'procedure_body_changed',
        FALSE,
    'candidate_source_created',
        FALSE,
    'candidate_source_executed',
        FALSE,
    'ml_authority_changed',
        FALSE,
    'native_app_package_created',
        FALSE
) AS PHASE14D3D3A_BASELINE_VERIFICATION
FROM baseline
CROSS JOIN current_state;

/*
Phase 14D.3D.3A minimal hotfix.

Snowflake procedures use owner rights by default when the DDL does not
explicitly specify EXECUTE AS CALLER or EXECUTE AS RESTRICTED CALLER.

This script updates only the compatibility contract metadata.
It does not alter or execute RUN_KMAT_COST_SIMULATION.
*/

UPDATE
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_COST_ENGINE_CONTRACT_V1 target
SET
    OWNER_RIGHTS_FLAG = (
        audit.OBJECT_DDL IS NOT NULL
        AND REGEXP_COUNT(
            UPPER(audit.OBJECT_DDL),
            'EXECUTE[[:space:]]+AS[[:space:]]+CALLER'
        ) = 0
        AND REGEXP_COUNT(
            UPPER(audit.OBJECT_DDL),
            'EXECUTE[[:space:]]+AS[[:space:]]+RESTRICTED[[:space:]]+CALLER'
        ) = 0
    )
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1 audit
WHERE target.CONTRACT_ID =
      'PHASE14D3D3A_COST_ENGINE_V1'
  AND audit.AUDIT_BATCH_ID =
      'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
  AND audit.OBJECT_SCHEMA =
      target.OBJECT_SCHEMA
  AND audit.OBJECT_NAME =
      target.OBJECT_NAME
  AND audit.OBJECT_SIGNATURE =
      target.OBJECT_SIGNATURE;


UPDATE
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_COST_ENGINE_CONTRACT_V1
SET
    CONTRACT_STATUS = IFF(
        CURRENT_DDL_HASH = EXPECTED_DDL_HASH
        AND OBJECT_OWNER = 'SYSADMIN'
        AND OBJECT_LANGUAGE = 'PYTHON'
        AND OWNER_RIGHTS_FLAG
        AND DYNAMIC_SQL_COUNT = 18
        AND FIXED_DATABASE_REFERENCE_COUNT = 1
        AND FIXED_WAREHOUSE_REFERENCE_COUNT = 0
        AND TEMP_OBJECT_REFERENCE_COUNT = 0
        AND SUPER_BOM_CONTRACT_FLAG
        AND SUPER_ROUTING_CONTRACT_FLAG
        AND DEPENDENCY_RULE_CONTRACT_FLAG
        AND CSS_CONTRACT_FLAG
        AND FMIS_CONTRACT_FLAG
        AND TDS_CONTRACT_FLAG
        AND OVERHEAD_CONTRACT_FLAG
        AND BASELINE_COST_FORMULA_FLAG
        AND RISK_COST_FORMULA_FLAG
        AND PRICE_FORMULA_FLAG
        AND OUTPUT_COMPONENT_TABLE_FLAG
        AND OUTPUT_OPERATION_TABLE_FLAG
        AND OUTPUT_OVERHEAD_TABLE_FLAG
        AND OUTPUT_SUMMARY_TABLE_FLAG
        AND RISK_MODEL_VERSION_FLAG
        AND RETURN_CONTRACT_FLAG,
        'CONTRACT_FROZEN',
        'ATTENTION_REQUIRED'
    )
WHERE CONTRACT_ID =
      'PHASE14D3D3A_COST_ENGINE_V1';


SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COUNT(*) = 1
            AND COUNT_IF(
                CONTRACT_STATUS = 'CONTRACT_FROZEN'
            ) = 1,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),
    'phase',
        'PHASE_14D_3D_3A_HOTFIX',
    'contract_id',
        'PHASE14D3D3A_COST_ENGINE_V1',
    'contract_frozen_count',
        COUNT_IF(
            CONTRACT_STATUS = 'CONTRACT_FROZEN'
        ),
    'owner_rights_count',
        COUNT_IF(
            OWNER_RIGHTS_FLAG = TRUE
        ),
    'original_hash_match_count',
        COUNT_IF(
            CURRENT_DDL_HASH = EXPECTED_DDL_HASH
        ),
    'procedure_body_changed',
        FALSE,
    'candidate_source_created',
        FALSE,
    'candidate_source_executed',
        FALSE,
    'official_cost_changed',
        FALSE,
    'native_app_package_created',
        FALSE
) AS PHASE14D3D3A_HOTFIX_RESULT
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_COST_ENGINE_CONTRACT_V1
WHERE CONTRACT_ID =
      'PHASE14D3D3A_COST_ENGINE_V1';

SELECT
    OBJECT_OWNER,
    OBJECT_LANGUAGE,
    DYNAMIC_SQL_COUNT,
    FIXED_DATABASE_REFERENCE_COUNT,
    FIXED_WAREHOUSE_REFERENCE_COUNT,
    TEMP_OBJECT_REFERENCE_COUNT,
    DEPENDENCY_RULE_CONTRACT_FLAG,
    RISK_MODEL_VERSION_FLAG,
    RETURN_CONTRACT_FLAG,
    CONTRACT_STATUS
FROM KMAT_COST_MODEL_DB.CORE_ML
    .NATIVE_COMPAT_COST_ENGINE_CONTRACT_V1
WHERE CONTRACT_ID = 'PHASE14D3D3A_COST_ENGINE_V1';

UPDATE KMAT_COST_MODEL_DB.CORE_ML
    .NATIVE_COMPAT_COST_ENGINE_CONTRACT_V1
SET CONTRACT_STATUS = IFF(
    CURRENT_DDL_HASH = EXPECTED_DDL_HASH
    AND OBJECT_OWNER = 'SYSADMIN'
    AND OBJECT_LANGUAGE = 'PYTHON'
    AND OWNER_RIGHTS_FLAG = TRUE
    AND DYNAMIC_SQL_COUNT = 18
    AND FIXED_DATABASE_REFERENCE_COUNT = 1
    AND FIXED_WAREHOUSE_REFERENCE_COUNT = 0
    AND TEMP_OBJECT_REFERENCE_COUNT = 0
    AND SUPER_BOM_CONTRACT_FLAG = TRUE
    AND SUPER_ROUTING_CONTRACT_FLAG = TRUE
    AND DEPENDENCY_RULE_CONTRACT_FLAG = TRUE
    AND CSS_CONTRACT_FLAG = TRUE
    AND FMIS_CONTRACT_FLAG = TRUE
    AND TDS_CONTRACT_FLAG = TRUE
    AND OVERHEAD_CONTRACT_FLAG = TRUE
    AND BASELINE_COST_FORMULA_FLAG = TRUE
    AND RISK_COST_FORMULA_FLAG = TRUE
    AND PRICE_FORMULA_FLAG = TRUE
    AND OUTPUT_COMPONENT_TABLE_FLAG = TRUE
    AND OUTPUT_OPERATION_TABLE_FLAG = TRUE
    AND OUTPUT_OVERHEAD_TABLE_FLAG = TRUE
    AND OUTPUT_SUMMARY_TABLE_FLAG = TRUE
    AND RETURN_CONTRACT_FLAG = TRUE,
    'CONTRACT_FROZEN',
    'ATTENTION_REQUIRED'
)
WHERE CONTRACT_ID = 'PHASE14D3D3A_COST_ENGINE_V1';


SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            CONTRACT_STATUS = 'CONTRACT_FROZEN',
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),
    'phase', 'PHASE_14D_3D_3A_FINAL',
    'contract_frozen',
        CONTRACT_STATUS = 'CONTRACT_FROZEN',
    'original_hash_match',
        CURRENT_DDL_HASH = EXPECTED_DDL_HASH,
    'procedure_body_changed', FALSE,
    'official_cost_changed', FALSE
) AS RESULT
FROM KMAT_COST_MODEL_DB.CORE_ML
    .NATIVE_COMPAT_COST_ENGINE_CONTRACT_V1
WHERE CONTRACT_ID = 'PHASE14D3D3A_COST_ENGINE_V1';

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

DELETE FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1
WHERE CANDIDATE_ID =
      'PHASE14D3D3B_COST_ENGINE_V1';

INSERT INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1
WITH SOURCE AS (
    SELECT $$
import json
from datetime import datetime


def to_float(value, default=0.0):
    if value is None:
        return default

    try:
        return float(value)
    except Exception:
        return default


def parse_rule(rule_obj):
    if rule_obj is None:
        return {}

    if isinstance(rule_obj, dict):
        return rule_obj

    if isinstance(rule_obj, str):
        try:
            return json.loads(rule_obj)
        except Exception:
            return {}

    try:
        return dict(rule_obj)
    except Exception:
        return {}


def normalize_text(value):
    if value is None:
        return ""

    return str(value).strip().upper()


def evaluate_rule(rule_obj, selections):
    rule = parse_rule(rule_obj)

    if not rule:
        return False

    rule_type = normalize_text(
        rule.get("type")
    )

    if rule_type == "DEFAULT":
        return True

    if "all" in rule:
        return all(
            evaluate_rule(
                child_rule,
                selections,
            )
            for child_rule
            in rule.get("all", [])
        )

    if "any" in rule:
        return any(
            evaluate_rule(
                child_rule,
                selections,
            )
            for child_rule
            in rule.get("any", [])
        )

    characteristic = normalize_text(
        rule.get("characteristic")
    )
    operator = normalize_text(
        rule.get("operator", "=")
    )
    expected_value = rule.get("value")

    if characteristic == "":
        return False

    actual_value = normalize_text(
        selections.get(characteristic)
    )

    if operator in ("=", "=="):
        return (
            actual_value
            == normalize_text(expected_value)
        )

    if operator in ("!=", "<>"):
        return (
            actual_value
            != normalize_text(expected_value)
        )

    if operator == "IN":
        if isinstance(expected_value, list):
            expected_values = [
                normalize_text(value)
                for value in expected_value
            ]
        else:
            expected_values = [
                normalize_text(expected_value)
            ]

        return actual_value in expected_values

    return False


def quote_identifier(identifier):
    escaped = str(identifier).replace(
        '"',
        '""',
    )
    return f'"{escaped}"'


def append_rows(
    session,
    table_name,
    rows,
    columns,
):
    if not rows:
        return

    column_list = ", ".join(
        quote_identifier(column)
        for column in columns
    )

    placeholders = ", ".join(
        ["?"] * len(columns)
    )

    insert_sql = f"""
        INSERT INTO {table_name}
        ({column_list})
        VALUES ({placeholders})
    """

    for row in rows:
        session.sql(
            insert_sql,
            params=list(row),
        ).collect()


def calculate_css(
    session,
    kmat_id,
    selections,
):
    scrap_rule_rows = session.sql(
        """
        SELECT
            CHARACTERISTIC_NAME,
            CHARACTERISTIC_VALUE,
            SCORE_POINTS
        FROM CORE_INPUT.SCRAP_SCORE_RULES
        WHERE KMAT_ID = ?
          AND ACTIVE_FLAG = TRUE
        """,
        params=[kmat_id],
    ).collect()

    css_score = 0.0

    for row in scrap_rule_rows:
        characteristic = normalize_text(
            row["CHARACTERISTIC_NAME"]
        )
        value = normalize_text(
            row["CHARACTERISTIC_VALUE"]
        )
        points = to_float(
            row["SCORE_POINTS"],
            0.0,
        )

        if (
            characteristic == "BASE"
            and value == "BASE"
        ):
            css_score += points

        elif (
            selections.get(characteristic)
            == value
        ):
            css_score += points

    css_score = min(css_score, 100.0)

    band_rows = session.sql(
        """
        SELECT
            SCRAP_RATE,
            RISK_LEVEL
        FROM CORE_INPUT.SCRAP_SCORE_BANDS
        WHERE ? BETWEEN MIN_SCORE AND MAX_SCORE
          AND ACTIVE_FLAG = TRUE
        LIMIT 1
        """,
        params=[css_score],
    ).collect()

    if len(band_rows) == 0:
        return css_score, 0.0, "UNKNOWN"

    scrap_rate = to_float(
        band_rows[0]["SCRAP_RATE"],
        0.0,
    )
    risk_level = band_rows[0][
        "RISK_LEVEL"
    ]

    return (
        css_score,
        scrap_rate,
        risk_level,
    )


def load_production_context(
    session,
    simulation_id,
):
    rows = session.sql(
        """
        SELECT
            TO_VARCHAR(
                DATE_TRUNC(
                    'MONTH',
                    PLANNED_PRODUCTION_DATE
                ),
                'YYYY-MM-DD'
            ) AS FORECAST_MONTH_STR
        FROM CORE_INPUT
            .SIMULATION_PRODUCTION_CONTEXT
        WHERE SIMULATION_ID = ?
        LIMIT 1
        """,
        params=[simulation_id],
    ).collect()

    if len(rows) == 0:
        return None

    return rows[0][
        "FORECAST_MONTH_STR"
    ]


def load_forecast_map(
    session,
    forecast_month_str,
):
    if forecast_month_str is None:
        return {}

    rows = session.sql(
        """
        SELECT
            COMMODITY_GROUP,
            FORWARD_MATERIAL_INDEX
        FROM CORE_INPUT
            .MATERIAL_INDEX_FORECASTS
        WHERE FORECAST_MONTH = TO_DATE(?)
        """,
        params=[forecast_month_str],
    ).collect()

    result = {}

    for row in rows:
        result[
            normalize_text(
                row["COMMODITY_GROUP"]
            )
        ] = to_float(
            row["FORWARD_MATERIAL_INDEX"],
            1.0,
        )

    return result


def load_component_attributes(session):
    rows = session.sql(
        """
        SELECT
            COMPONENT_ID,
            SCRAP_APPLICABLE_FLAG,
            COMMODITY_SENSITIVE_FLAG,
            DEFAULT_COMMODITY_GROUP
        FROM CORE_INPUT
            .COMPONENT_COST_ATTRIBUTES
        """
    ).collect()

    result = {}

    for row in rows:
        component_id = row["COMPONENT_ID"]

        result[component_id] = {
            "scrap_applicable":
                bool(
                    row[
                        "SCRAP_APPLICABLE_FLAG"
                    ]
                ),
            "commodity_sensitive":
                bool(
                    row[
                        "COMMODITY_SENSITIVE_FLAG"
                    ]
                ),
            "default_commodity":
                normalize_text(
                    row[
                        "DEFAULT_COMMODITY_GROUP"
                    ]
                ),
        }

    return result


def load_commodity_exposure(session):
    rows = session.sql(
        """
        SELECT
            COMPONENT_ID,
            COMMODITY_GROUP,
            EXPOSURE_PERCENT
        FROM CORE_INPUT
            .COMPONENT_COMMODITY_EXPOSURE
        """
    ).collect()

    result = {}

    for row in rows:
        component_id = row["COMPONENT_ID"]

        if component_id not in result:
            result[component_id] = []

        result[component_id].append({
            "commodity_group":
                normalize_text(
                    row["COMMODITY_GROUP"]
                ),
            "exposure_percent":
                to_float(
                    row["EXPOSURE_PERCENT"],
                    0.0,
                ),
        })

    return result


def get_weighted_fmis(
    component_id,
    attributes,
    exposure_map,
    forecast_map,
    forecast_month_str,
):
    if (
        attributes is not None
        and attributes.get(
            "commodity_sensitive"
        ) is False
    ):
        return 1.0, False

    exposures = exposure_map.get(
        component_id,
        [],
    )

    if not exposures:
        default_commodity = ""

        if attributes is not None:
            default_commodity = (
                attributes.get(
                    "default_commodity",
                    "",
                )
            )

        if (
            default_commodity != ""
            and default_commodity
            in forecast_map
        ):
            return (
                forecast_map.get(
                    default_commodity,
                    1.0,
                ),
                False,
            )

        return 1.0, True

    weighted_fmis = 0.0
    fallback_used = False

    for exposure in exposures:
        commodity = exposure[
            "commodity_group"
        ]
        exposure_percent = exposure[
            "exposure_percent"
        ]

        if (
            forecast_month_str is None
            or commodity not in forecast_map
        ):
            fmis = 1.0
            fallback_used = True
        else:
            fmis = forecast_map.get(
                commodity,
                1.0,
            )

        weighted_fmis += (
            exposure_percent * fmis
        )

    if weighted_fmis <= 0:
        return 1.0, True

    return weighted_fmis, fallback_used


def load_work_center_breakdown(session):
    rows = session.sql(
        """
        SELECT
            WORK_CENTER_ID,
            OPERATING_RATE_USD_PER_HOUR,
            MAINTENANCE_RATE_USD_PER_HOUR
        FROM CORE_INPUT
            .WORK_CENTER_COST_BREAKDOWN
        """
    ).collect()

    result = {}

    for row in rows:
        result[
            row["WORK_CENTER_ID"]
        ] = {
            "operating_rate":
                to_float(
                    row[
                        "OPERATING_RATE_USD_PER_HOUR"
                    ],
                    0.0,
                ),
            "maintenance_rate":
                to_float(
                    row[
                        "MAINTENANCE_RATE_USD_PER_HOUR"
                    ],
                    0.0,
                ),
        }

    return result


def load_tds_map(session):
    rows = session.sql(
        """
        SELECT
            OPERATION_ID,
            TDS_FACTOR
        FROM CORE_INPUT.OPERATION_TDS_RULES
        WHERE ACTIVE_FLAG = TRUE
        """
    ).collect()

    result = {}

    for row in rows:
        result[
            row["OPERATION_ID"]
        ] = to_float(
            row["TDS_FACTOR"],
            1.0,
        )

    return result


def run(session, SIMULATION_ID):
    calculated_at = datetime.utcnow()

    header_rows = session.sql(
        """
        SELECT
            SIMULATION_ID,
            KMAT_ID,
            CUSTOMER_ID,
            SCENARIO_NAME
        FROM CORE_INPUT.SIMULATION_HEADER
        WHERE SIMULATION_ID = ?
        """,
        params=[SIMULATION_ID],
    ).collect()

    if len(header_rows) == 0:
        return json.dumps({
            "status": "ERROR",
            "message": (
                f"Simulation ID {SIMULATION_ID} "
                "not found in "
                "CORE_INPUT.SIMULATION_HEADER"
            ),
        })

    header = header_rows[0]
    kmat_id = header["KMAT_ID"]

    parameter_rows = session.sql(
        """
        SELECT
            COALESCE(
                MATERIAL_COST_MULTIPLIER,
                1.00
            ) AS MATERIAL_COST_MULTIPLIER,
            COALESCE(
                LABOR_RATE_MULTIPLIER,
                1.00
            ) AS LABOR_RATE_MULTIPLIER,
            COALESCE(
                MACHINE_RATE_MULTIPLIER,
                1.00
            ) AS MACHINE_RATE_MULTIPLIER,
            COALESCE(
                OVERHEAD_MULTIPLIER,
                1.00
            ) AS OVERHEAD_MULTIPLIER,
            COALESCE(
                TARGET_MARGIN_PCT,
                0.35
            ) AS TARGET_MARGIN_PCT,
            COALESCE(
                FLOOR_MARKUP_PCT,
                0.10
            ) AS FLOOR_MARKUP_PCT,
            COALESCE(
                CEILING_MARKUP_PCT,
                0.60
            ) AS CEILING_MARKUP_PCT
        FROM CORE_INPUT.SIMULATION_PARAMETERS
        WHERE SIMULATION_ID = ?
        """,
        params=[SIMULATION_ID],
    ).collect()

    if len(parameter_rows) == 0:
        material_multiplier = 1.00
        labor_multiplier = 1.00
        machine_multiplier = 1.00
        overhead_multiplier = 1.00
        target_margin_pct = 0.35
        floor_markup_pct = 0.10
        ceiling_markup_pct = 0.60

    else:
        parameters = parameter_rows[0]

        material_multiplier = to_float(
            parameters[
                "MATERIAL_COST_MULTIPLIER"
            ],
            1.00,
        )
        labor_multiplier = to_float(
            parameters[
                "LABOR_RATE_MULTIPLIER"
            ],
            1.00,
        )
        machine_multiplier = to_float(
            parameters[
                "MACHINE_RATE_MULTIPLIER"
            ],
            1.00,
        )
        overhead_multiplier = to_float(
            parameters[
                "OVERHEAD_MULTIPLIER"
            ],
            1.00,
        )
        target_margin_pct = to_float(
            parameters[
                "TARGET_MARGIN_PCT"
            ],
            0.35,
        )
        floor_markup_pct = to_float(
            parameters[
                "FLOOR_MARKUP_PCT"
            ],
            0.10,
        )
        ceiling_markup_pct = to_float(
            parameters[
                "CEILING_MARKUP_PCT"
            ],
            0.60,
        )

    selection_rows = session.sql(
        """
        SELECT
            CHARACTERISTIC_NAME,
            SELECTED_VALUE
        FROM CORE_INPUT.CHARACTERISTIC_VALUES
        WHERE SIMULATION_ID = ?
          AND KMAT_ID = ?
        """,
        params=[
            SIMULATION_ID,
            kmat_id,
        ],
    ).collect()

    selections = {}

    for row in selection_rows:
        selections[
            normalize_text(
                row["CHARACTERISTIC_NAME"]
            )
        ] = normalize_text(
            row["SELECTED_VALUE"]
        )

    (
        css_score,
        scrap_rate_applied,
        scrap_risk_level,
    ) = calculate_css(
        session,
        kmat_id,
        selections,
    )

    forecast_month_str = (
        load_production_context(
            session,
            SIMULATION_ID,
        )
    )
    forecast_map = load_forecast_map(
        session,
        forecast_month_str,
    )
    component_attribute_map = (
        load_component_attributes(session)
    )
    exposure_map = (
        load_commodity_exposure(session)
    )
    work_center_breakdown = (
        load_work_center_breakdown(session)
    )
    tds_map = load_tds_map(session)

    output_tables = [
        (
            "CORE_OUTPUT."
            "KMAT_CONFIGURED_COMPONENT_COSTS"
        ),
        (
            "CORE_OUTPUT."
            "KMAT_CONFIGURED_OPERATION_COSTS"
        ),
        (
            "CORE_OUTPUT."
            "KMAT_CONFIGURED_OVERHEAD_COSTS"
        ),
        (
            "CORE_OUTPUT."
            "KMAT_CONFIGURED_COST_SUMMARY"
        ),
    ]

    for table_name in output_tables:
        session.sql(
            f"""
            DELETE FROM {table_name}
            WHERE SIMULATION_ID = ?
            """,
            params=[SIMULATION_ID],
        ).collect()

    bom_rows = session.sql(
        """
        SELECT
            bom.KMAT_ID,
            bom.COMPONENT_ID,
            bom.COMPONENT_DESCRIPTION,
            bom.QUANTITY,
            bom.UOM,
            bom.RULE_ID,
            bom.IS_BULK_MATERIAL,
            bom.COST_COMPONENT_GROUP,
            dr.RULE_JSON,
            mc.ITEM_ID AS COST_ITEM_ID,
            mc.STANDARD_COST_USD
        FROM CORE_INPUT.KMAT_SUPER_BOM bom
        JOIN CORE_INPUT.DEPENDENCY_RULES dr
          ON bom.RULE_ID = dr.RULE_ID
        LEFT JOIN CORE_INPUT.MATERIAL_COSTS mc
          ON bom.COMPONENT_ID = mc.ITEM_ID
        WHERE bom.KMAT_ID = ?
        """,
        params=[kmat_id],
    ).collect()

    component_output_rows = []

    baseline_material_total = 0.0
    risk_adjusted_material_total = 0.0
    commodity_adjustment_total = 0.0
    scrap_adjustment_total = 0.0

    selected_component_count = 0
    missing_material_cost_count = 0
    fmis_weighted_sum = 0.0

    for row in bom_rows:
        if not evaluate_rule(
            row["RULE_JSON"],
            selections,
        ):
            continue

        selected_component_count += 1

        component_id = row["COMPONENT_ID"]
        attributes = (
            component_attribute_map.get(
                component_id
            )
        )

        if attributes is None:
            scrap_applicable = False
            risk_notes = (
                "Component attributes missing; "
                "scrap disabled; FMIS fallback "
                "may apply."
            )
        else:
            scrap_applicable = bool(
                attributes.get(
                    "scrap_applicable",
                    False,
                )
            )
            risk_notes = (
                "Risk inputs applied from "
                "Phase 5A tables."
            )

        quantity = to_float(
            row["QUANTITY"],
            0.0,
        )

        cost_missing = (
            row["COST_ITEM_ID"] is None
            or row["STANDARD_COST_USD"]
            is None
        )

        if cost_missing:
            missing_material_cost_count += 1

        standard_cost = to_float(
            row["STANDARD_COST_USD"],
            0.0,
        )

        (
            weighted_fmis,
            fmis_fallback_flag,
        ) = get_weighted_fmis(
            component_id,
            attributes,
            exposure_map,
            forecast_map,
            forecast_month_str,
        )

        component_scrap_rate = (
            scrap_rate_applied
            if scrap_applicable
            else 0.0
        )

        base_quantity = quantity
        scrap_adjusted_quantity = (
            quantity
            * (1.0 + component_scrap_rate)
        )

        base_standard_cost = standard_cost

        base_line_material_cost = (
            quantity
            * standard_cost
            * material_multiplier
        )

        forward_unit_cost = (
            standard_cost
            * material_multiplier
            * weighted_fmis
        )

        fmis_adjusted_line_cost = (
            base_line_material_cost
            * weighted_fmis
        )

        commodity_adjustment = (
            fmis_adjusted_line_cost
            - base_line_material_cost
        )

        adjusted_line_material_cost = (
            fmis_adjusted_line_cost
            * (1.0 + component_scrap_rate)
        )

        scrap_adjustment = (
            adjusted_line_material_cost
            - fmis_adjusted_line_cost
        )

        baseline_material_total += (
            base_line_material_cost
        )
        risk_adjusted_material_total += (
            adjusted_line_material_cost
        )
        commodity_adjustment_total += (
            commodity_adjustment
        )
        scrap_adjustment_total += (
            scrap_adjustment
        )

        if base_line_material_cost > 0:
            fmis_weighted_sum += (
                base_line_material_cost
                * weighted_fmis
            )

        full_notes = (
            f"CSS={round(css_score, 4)}, "
            f"Risk={scrap_risk_level}, "
            "ScrapApplicable="
            f"{scrap_applicable}, "
            f"FMIS={round(weighted_fmis, 6)}, "
            "FMISFallback="
            f"{fmis_fallback_flag}. "
            f"{risk_notes}"
        )

        component_output_rows.append((
            SIMULATION_ID,
            row["KMAT_ID"],
            component_id,
            row["COMPONENT_DESCRIPTION"],
            quantity,
            row["UOM"],
            row["RULE_ID"],
            bool(
                row["IS_BULK_MATERIAL"]
            ),
            row["COST_COMPONENT_GROUP"],
            standard_cost,
            base_line_material_cost,
            bool(cost_missing),
            calculated_at,
            base_quantity,
            bool(scrap_applicable),
            css_score,
            component_scrap_rate,
            scrap_adjusted_quantity,
            base_standard_cost,
            weighted_fmis,
            forward_unit_cost,
            base_line_material_cost,
            commodity_adjustment,
            scrap_adjustment,
            adjusted_line_material_cost,
            bool(fmis_fallback_flag),
            full_notes,
        ))

    append_rows(
        session,
        (
            "CORE_OUTPUT."
            "KMAT_CONFIGURED_COMPONENT_COSTS"
        ),
        component_output_rows,
        [
            "SIMULATION_ID",
            "KMAT_ID",
            "COMPONENT_ID",
            "COMPONENT_DESCRIPTION",
            "QUANTITY",
            "UOM",
            "RULE_ID",
            "IS_BULK_MATERIAL",
            "COST_COMPONENT_GROUP",
            "STANDARD_COST_USD",
            "LINE_MATERIAL_COST_USD",
            "COST_MISSING_FLAG",
            "CALCULATED_AT",
            "BASE_QUANTITY",
            "SCRAP_APPLICABLE_FLAG",
            "CSS_SCORE",
            "SCRAP_RATE_APPLIED",
            "SCRAP_ADJUSTED_QUANTITY",
            "BASE_STANDARD_COST_USD",
            "WEIGHTED_FMIS",
            "FORWARD_UNIT_COST_USD",
            "BASE_LINE_MATERIAL_COST_USD",
            "COMMODITY_ADJUSTMENT_USD",
            "SCRAP_ADJUSTMENT_USD",
            "ADJUSTED_LINE_MATERIAL_COST_USD",
            "FMIS_FALLBACK_FLAG",
            "RISK_ADJUSTMENT_NOTES",
        ],
    )

    avg_weighted_fmis = 1.0

    if baseline_material_total > 0:
        avg_weighted_fmis = (
            fmis_weighted_sum
            / baseline_material_total
        )

    routing_rows = session.sql(
        """
        SELECT
            rt.KMAT_ID,
            rt.OPERATION_ID,
            rt.OPERATION_DESCRIPTION,
            rt.WORK_CENTER_ID,
            rt.LABOR_HOURS,
            rt.MACHINE_HOURS,
            rt.RULE_ID,
            dr.RULE_JSON,
            wr.LABOR_RATE_USD_PER_HOUR,
            wr.MACHINE_RATE_USD_PER_HOUR
        FROM CORE_INPUT.KMAT_SUPER_ROUTING rt
        JOIN CORE_INPUT.DEPENDENCY_RULES dr
          ON rt.RULE_ID = dr.RULE_ID
        LEFT JOIN CORE_INPUT.WORK_CENTER_RATES wr
          ON rt.WORK_CENTER_ID =
             wr.WORK_CENTER_ID
        WHERE rt.KMAT_ID = ?
        """,
        params=[kmat_id],
    ).collect()

    operation_output_rows = []

    baseline_labor_total = 0.0
    baseline_machine_total = 0.0
    risk_adjusted_machine_total = 0.0
    tooling_adjustment_total = 0.0

    selected_operation_count = 0
    max_tds_factor = 1.0

    for row in routing_rows:
        if not evaluate_rule(
            row["RULE_JSON"],
            selections,
        ):
            continue

        selected_operation_count += 1

        operation_id = row["OPERATION_ID"]
        work_center_id = row[
            "WORK_CENTER_ID"
        ]

        labor_hours = to_float(
            row["LABOR_HOURS"],
            0.0,
        )
        machine_hours = to_float(
            row["MACHINE_HOURS"],
            0.0,
        )

        labor_rate = to_float(
            row["LABOR_RATE_USD_PER_HOUR"],
            0.0,
        )
        base_machine_rate = to_float(
            row[
                "MACHINE_RATE_USD_PER_HOUR"
            ],
            0.0,
        )

        labor_cost = (
            labor_hours
            * labor_rate
            * labor_multiplier
        )

        base_machine_cost = (
            machine_hours
            * base_machine_rate
            * machine_multiplier
        )

        if (
            work_center_id
            in work_center_breakdown
        ):
            operating_rate = (
                work_center_breakdown[
                    work_center_id
                ]["operating_rate"]
            )
            maintenance_rate = (
                work_center_breakdown[
                    work_center_id
                ]["maintenance_rate"]
            )
            breakdown_fallback = False

        else:
            operating_rate = (
                base_machine_rate
            )
            maintenance_rate = 0.0
            breakdown_fallback = True

        if operation_id in tds_map:
            tds_factor = tds_map[
                operation_id
            ]
            tds_fallback_flag = False
        else:
            tds_factor = 1.0
            tds_fallback_flag = True

        adjusted_machine_rate = (
            operating_rate
            + (
                maintenance_rate
                * tds_factor
            )
        )

        adjusted_machine_cost = (
            machine_hours
            * adjusted_machine_rate
            * machine_multiplier
        )

        tooling_adjustment = (
            adjusted_machine_cost
            - base_machine_cost
        )

        baseline_labor_total += labor_cost
        baseline_machine_total += (
            base_machine_cost
        )
        risk_adjusted_machine_total += (
            adjusted_machine_cost
        )
        tooling_adjustment_total += (
            tooling_adjustment
        )

        max_tds_factor = max(
            max_tds_factor,
            tds_factor,
        )

        notes = (
            f"TDS={round(tds_factor, 6)}, "
            "BreakdownFallback="
            f"{breakdown_fallback}, "
            "TDSFallback="
            f"{tds_fallback_flag}."
        )

        operation_output_rows.append((
            SIMULATION_ID,
            row["KMAT_ID"],
            operation_id,
            row["OPERATION_DESCRIPTION"],
            work_center_id,
            labor_hours,
            machine_hours,
            labor_rate,
            base_machine_rate,
            labor_cost,
            base_machine_cost,
            row["RULE_ID"],
            calculated_at,
            base_machine_rate,
            operating_rate,
            maintenance_rate,
            tds_factor,
            base_machine_cost,
            adjusted_machine_rate,
            tooling_adjustment,
            adjusted_machine_cost,
            bool(tds_fallback_flag),
            notes,
        ))

    append_rows(
        session,
        (
            "CORE_OUTPUT."
            "KMAT_CONFIGURED_OPERATION_COSTS"
        ),
        operation_output_rows,
        [
            "SIMULATION_ID",
            "KMAT_ID",
            "OPERATION_ID",
            "OPERATION_DESCRIPTION",
            "WORK_CENTER_ID",
            "LABOR_HOURS",
            "MACHINE_HOURS",
            "LABOR_RATE_USD_PER_HOUR",
            "MACHINE_RATE_USD_PER_HOUR",
            "LABOR_COST_USD",
            "MACHINE_COST_USD",
            "RULE_ID",
            "CALCULATED_AT",
            "BASE_MACHINE_RATE_USD_PER_HOUR",
            "OPERATING_RATE_USD_PER_HOUR",
            "MAINTENANCE_RATE_USD_PER_HOUR",
            "TDS_FACTOR",
            "BASE_MACHINE_COST_USD",
            "ADJUSTED_MACHINE_RATE_USD_PER_HOUR",
            "TOOLING_ADJUSTMENT_USD",
            "ADJUSTED_MACHINE_COST_USD",
            "TDS_FALLBACK_FLAG",
            "RISK_ADJUSTMENT_NOTES",
        ],
    )

    overhead_rows = session.sql(
        """
        SELECT
            oh.KMAT_ID,
            oh.OVERHEAD_ID,
            oh.OVERHEAD_DESCRIPTION,
            oh.BASIS,
            oh.RATE_VALUE,
            oh.RULE_ID,
            dr.RULE_JSON
        FROM CORE_INPUT.OVERHEAD_RATES oh
        JOIN CORE_INPUT.DEPENDENCY_RULES dr
          ON oh.RULE_ID = dr.RULE_ID
        WHERE oh.KMAT_ID = ?
        """,
        params=[kmat_id],
    ).collect()

    overhead_output_rows = []

    baseline_overhead_total = 0.0
    risk_adjusted_overhead_total = 0.0
    overhead_adjustment_total = 0.0

    selected_overhead_count = 0

    for row in overhead_rows:
        if not evaluate_rule(
            row["RULE_JSON"],
            selections,
        ):
            continue

        selected_overhead_count += 1

        basis = normalize_text(
            row["BASIS"]
        )
        rate_value = to_float(
            row["RATE_VALUE"],
            0.0,
        )

        if basis == "MATERIAL_PERCENT":
            base_basis_cost = (
                baseline_material_total
            )
            adjusted_basis_cost = (
                risk_adjusted_material_total
            )
            base_overhead_cost = (
                base_basis_cost
                * rate_value
            )
            adjusted_overhead_cost = (
                adjusted_basis_cost
                * rate_value
            )

        elif basis == "LABOR_PERCENT":
            base_basis_cost = (
                baseline_labor_total
            )
            adjusted_basis_cost = (
                baseline_labor_total
            )
            base_overhead_cost = (
                base_basis_cost
                * rate_value
            )
            adjusted_overhead_cost = (
                adjusted_basis_cost
                * rate_value
            )

        elif basis == "MACHINE_PERCENT":
            base_basis_cost = (
                baseline_machine_total
            )
            adjusted_basis_cost = (
                risk_adjusted_machine_total
            )
            base_overhead_cost = (
                base_basis_cost
                * rate_value
            )
            adjusted_overhead_cost = (
                adjusted_basis_cost
                * rate_value
            )

        elif basis == "TOTAL_COST_PERCENT":
            base_basis_cost = (
                baseline_material_total
                + baseline_labor_total
                + baseline_machine_total
            )
            adjusted_basis_cost = (
                risk_adjusted_material_total
                + baseline_labor_total
                + risk_adjusted_machine_total
            )
            base_overhead_cost = (
                base_basis_cost
                * rate_value
            )
            adjusted_overhead_cost = (
                adjusted_basis_cost
                * rate_value
            )

        elif basis == "FIXED":
            base_basis_cost = rate_value
            adjusted_basis_cost = (
                rate_value
            )
            base_overhead_cost = rate_value
            adjusted_overhead_cost = (
                rate_value
            )

        else:
            base_basis_cost = 0.0
            adjusted_basis_cost = 0.0
            base_overhead_cost = 0.0
            adjusted_overhead_cost = 0.0

        base_overhead_cost *= (
            overhead_multiplier
        )
        adjusted_overhead_cost *= (
            overhead_multiplier
        )

        overhead_adjustment = (
            adjusted_overhead_cost
            - base_overhead_cost
        )

        baseline_overhead_total += (
            base_overhead_cost
        )
        risk_adjusted_overhead_total += (
            adjusted_overhead_cost
        )
        overhead_adjustment_total += (
            overhead_adjustment
        )

        notes = (
            f"Basis={basis}, "
            "BaseBasis="
            f"{round(base_basis_cost, 4)}, "
            "AdjustedBasis="
            f"{round(adjusted_basis_cost, 4)}."
        )

        overhead_output_rows.append((
            SIMULATION_ID,
            row["KMAT_ID"],
            row["OVERHEAD_ID"],
            row["OVERHEAD_DESCRIPTION"],
            row["BASIS"],
            rate_value,
            base_overhead_cost,
            row["RULE_ID"],
            calculated_at,
            base_overhead_cost,
            adjusted_basis_cost,
            adjusted_overhead_cost,
            overhead_adjustment,
            True,
            notes,
        ))

    append_rows(
        session,
        (
            "CORE_OUTPUT."
            "KMAT_CONFIGURED_OVERHEAD_COSTS"
        ),
        overhead_output_rows,
        [
            "SIMULATION_ID",
            "KMAT_ID",
            "OVERHEAD_ID",
            "OVERHEAD_DESCRIPTION",
            "BASIS",
            "RATE_VALUE",
            "OVERHEAD_COST_USD",
            "RULE_ID",
            "CALCULATED_AT",
            "BASE_OVERHEAD_COST_USD",
            "OVERHEAD_CALCULATION_BASIS_COST_USD",
            "ADJUSTED_OVERHEAD_COST_USD",
            "OVERHEAD_ADJUSTMENT_USD",
            "RISK_ADJUSTED_FLAG",
            "RISK_ADJUSTMENT_NOTES",
        ],
    )

    baseline_total_cost = (
        baseline_material_total
        + baseline_labor_total
        + baseline_machine_total
        + baseline_overhead_total
    )

    risk_adjusted_total_cost = (
        risk_adjusted_material_total
        + baseline_labor_total
        + risk_adjusted_machine_total
        + risk_adjusted_overhead_total
    )

    total_risk_uplift = (
        risk_adjusted_total_cost
        - baseline_total_cost
    )

    if baseline_total_cost == 0:
        total_risk_uplift_pct = 0.0
    else:
        total_risk_uplift_pct = (
            total_risk_uplift
            / baseline_total_cost
        ) * 100.0

    floor_price = (
        baseline_total_cost
        * (1.0 + floor_markup_pct)
    )
    target_price = (
        baseline_total_cost
        * (1.0 + target_margin_pct)
    )
    ceiling_price = (
        baseline_total_cost
        * (1.0 + ceiling_markup_pct)
    )

    summary_notes = (
        "Phase 5C CSS/FMIS/TDS enabled. "
        "ForecastMonth="
        f"{forecast_month_str if forecast_month_str is not None else 'MISSING_CONTEXT'}, "
        f"CSS={round(css_score, 4)}, "
        "ScrapRate="
        f"{round(scrap_rate_applied, 6)}, "
        f"RiskLevel={scrap_risk_level}, "
        "AvgFMIS="
        f"{round(avg_weighted_fmis, 6)}, "
        f"MaxTDS={round(max_tds_factor, 6)}."
    )

    summary_rows = [(
        SIMULATION_ID,
        kmat_id,
        baseline_material_total,
        baseline_labor_total,
        baseline_machine_total,
        baseline_overhead_total,
        baseline_total_cost,
        floor_price,
        target_price,
        ceiling_price,
        calculated_at,
        baseline_material_total,
        baseline_labor_total,
        baseline_machine_total,
        baseline_overhead_total,
        baseline_total_cost,
        css_score,
        scrap_rate_applied,
        scrap_risk_level,
        avg_weighted_fmis,
        max_tds_factor,
        commodity_adjustment_total,
        scrap_adjustment_total,
        tooling_adjustment_total,
        overhead_adjustment_total,
        risk_adjusted_material_total,
        baseline_labor_total,
        risk_adjusted_machine_total,
        risk_adjusted_overhead_total,
        risk_adjusted_total_cost,
        total_risk_uplift,
        total_risk_uplift_pct,
        "CSS_FMIS_TDS_RULE_BASED_V1",
        "SUCCESS",
        summary_notes,
    )]

    append_rows(
        session,
        (
            "CORE_OUTPUT."
            "KMAT_CONFIGURED_COST_SUMMARY"
        ),
        summary_rows,
        [
            "SIMULATION_ID",
            "KMAT_ID",
            "MATERIAL_COST_USD",
            "LABOR_COST_USD",
            "MACHINE_COST_USD",
            "OVERHEAD_COST_USD",
            "TOTAL_CONFIGURED_COST_USD",
            "FLOOR_PRICE_USD",
            "TARGET_PRICE_USD",
            "CEILING_PRICE_USD",
            "CALCULATED_AT",
            "BASELINE_MATERIAL_COST_USD",
            "BASELINE_LABOR_COST_USD",
            "BASELINE_MACHINE_COST_USD",
            "BASELINE_OVERHEAD_COST_USD",
            "BASELINE_TOTAL_COST_USD",
            "CSS_SCORE",
            "SCRAP_RATE_APPLIED",
            "SCRAP_RISK_LEVEL",
            "AVG_WEIGHTED_FMIS",
            "MAX_TDS_FACTOR",
            "COMMODITY_ADJUSTMENT_USD",
            "SCRAP_ADJUSTMENT_USD",
            "TOOLING_ADJUSTMENT_USD",
            "OVERHEAD_ADJUSTMENT_USD",
            "RISK_ADJUSTED_MATERIAL_COST_USD",
            "RISK_ADJUSTED_LABOR_COST_USD",
            "RISK_ADJUSTED_MACHINE_COST_USD",
            "RISK_ADJUSTED_OVERHEAD_COST_USD",
            "RISK_ADJUSTED_TOTAL_COST_USD",
            "TOTAL_RISK_UPLIFT_USD",
            "TOTAL_RISK_UPLIFT_PCT",
            "RISK_MODEL_VERSION",
            "RISK_CALCULATION_STATUS",
            "RISK_CALCULATION_NOTES",
        ],
    )

    return json.dumps({
        "status": "SUCCESS",
        "simulation_id": SIMULATION_ID,
        "kmat_id": kmat_id,
        "selected_components":
            selected_component_count,
        "selected_operations":
            selected_operation_count,
        "selected_overheads":
            selected_overhead_count,
        "missing_material_cost_count":
            missing_material_cost_count,
        "baseline_material_cost_usd":
            round(
                baseline_material_total,
                4,
            ),
        "baseline_labor_cost_usd":
            round(
                baseline_labor_total,
                4,
            ),
        "baseline_machine_cost_usd":
            round(
                baseline_machine_total,
                4,
            ),
        "baseline_overhead_cost_usd":
            round(
                baseline_overhead_total,
                4,
            ),
        "baseline_total_cost_usd":
            round(
                baseline_total_cost,
                4,
            ),
        "css_score":
            round(css_score, 4),
        "scrap_rate_applied":
            round(
                scrap_rate_applied,
                6,
            ),
        "scrap_risk_level":
            scrap_risk_level,
        "avg_weighted_fmis":
            round(
                avg_weighted_fmis,
                6,
            ),
        "max_tds_factor":
            round(
                max_tds_factor,
                6,
            ),
        "commodity_adjustment_usd":
            round(
                commodity_adjustment_total,
                4,
            ),
        "scrap_adjustment_usd":
            round(
                scrap_adjustment_total,
                4,
            ),
        "tooling_adjustment_usd":
            round(
                tooling_adjustment_total,
                4,
            ),
        "overhead_adjustment_usd":
            round(
                overhead_adjustment_total,
                4,
            ),
        "risk_adjusted_material_cost_usd":
            round(
                risk_adjusted_material_total,
                4,
            ),
        "risk_adjusted_labor_cost_usd":
            round(
                baseline_labor_total,
                4,
            ),
        "risk_adjusted_machine_cost_usd":
            round(
                risk_adjusted_machine_total,
                4,
            ),
        "risk_adjusted_overhead_cost_usd":
            round(
                risk_adjusted_overhead_total,
                4,
            ),
        "risk_adjusted_total_cost_usd":
            round(
                risk_adjusted_total_cost,
                4,
            ),
        "total_risk_uplift_usd":
            round(
                total_risk_uplift,
                4,
            ),
        "total_risk_uplift_pct":
            round(
                total_risk_uplift_pct,
                4,
            ),
    })

$$ AS CANDIDATE_SOURCE
),
VALIDATION AS (
    SELECT
        CANDIDATE_SOURCE,

        REGEXP_COUNT(
            UPPER(CANDIDATE_SOURCE),
            'KMAT_COST_MODEL_DB'
        ) AS FIXED_DATABASE_COUNT,

        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'DB_NAME'
        ) AS DB_NAME_COUNT,

        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'sql_escape'
        ) AS SQL_ESCAPE_COUNT,

        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            '[?]'
        ) AS QMARK_COUNT,

        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'params[[:space:]]*='
        ) AS PARAMS_COUNT,

        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'CORE_INPUT[.]'
        )
        +
        REGEXP_COUNT(
            CANDIDATE_SOURCE,
            'CORE_OUTPUT[.]'
        ) AS SCHEMA_REFERENCE_COUNT,

        POSITION(
            'CORE_INPUT.KMAT_SUPER_BOM'
            IN CANDIDATE_SOURCE
        ) > 0 AS SUPER_BOM_FLAG,

        POSITION(
            'CORE_INPUT.KMAT_SUPER_ROUTING'
            IN CANDIDATE_SOURCE
        ) > 0 AS SUPER_ROUTING_FLAG,

        POSITION(
            'def evaluate_rule'
            IN CANDIDATE_SOURCE
        ) > 0 AS DEPENDENCY_RULE_FLAG,

        POSITION(
            'def calculate_css'
            IN CANDIDATE_SOURCE
        ) > 0
        AND POSITION(
            'CORE_INPUT.SCRAP_SCORE_RULES'
            IN CANDIDATE_SOURCE
        ) > 0
        AND POSITION(
            'CORE_INPUT.SCRAP_SCORE_BANDS'
            IN CANDIDATE_SOURCE
        ) > 0 AS CSS_FLAG,

        POSITION(
            'def get_weighted_fmis'
            IN CANDIDATE_SOURCE
        ) > 0
        AND POSITION(
            'weighted_fmis +='
            IN CANDIDATE_SOURCE
        ) > 0
        AND POSITION(
            'exposure_percent * fmis'
            IN CANDIDATE_SOURCE
        ) > 0 AS FMIS_FLAG,

        POSITION(
            'adjusted_machine_rate = ('
            IN CANDIDATE_SOURCE
        ) > 0
        AND POSITION(
            'maintenance_rate'
            IN CANDIDATE_SOURCE
        ) > 0
        AND POSITION(
            '* tds_factor'
            IN CANDIDATE_SOURCE
        ) > 0 AS TDS_FLAG,

        POSITION(
            'MATERIAL_PERCENT'
            IN CANDIDATE_SOURCE
        ) > 0
        AND POSITION(
            'LABOR_PERCENT'
            IN CANDIDATE_SOURCE
        ) > 0
        AND POSITION(
            'MACHINE_PERCENT'
            IN CANDIDATE_SOURCE
        ) > 0
        AND POSITION(
            'TOTAL_COST_PERCENT'
            IN CANDIDATE_SOURCE
        ) > 0
        AND POSITION(
            'FIXED'
            IN CANDIDATE_SOURCE
        ) > 0 AS OVERHEAD_FLAG,

        POSITION(
            'baseline_total_cost = ('
            IN CANDIDATE_SOURCE
        ) > 0
        AND POSITION(
            'risk_adjusted_total_cost = ('
            IN CANDIDATE_SOURCE
        ) > 0
        AND POSITION(
            'total_risk_uplift = ('
            IN CANDIDATE_SOURCE
        ) > 0 AS COST_FORMULA_FLAG,

        POSITION(
            'floor_price = ('
            IN CANDIDATE_SOURCE
        ) > 0
        AND POSITION(
            'target_price = ('
            IN CANDIDATE_SOURCE
        ) > 0
        AND POSITION(
            'ceiling_price = ('
            IN CANDIDATE_SOURCE
        ) > 0 AS PRICE_FORMULA_FLAG,

        POSITION(
            'KMAT_CONFIGURED_COMPONENT_COSTS'
            IN CANDIDATE_SOURCE
        ) > 0
        AND POSITION(
            'KMAT_CONFIGURED_OPERATION_COSTS'
            IN CANDIDATE_SOURCE
        ) > 0
        AND POSITION(
            'KMAT_CONFIGURED_OVERHEAD_COSTS'
            IN CANDIDATE_SOURCE
        ) > 0
        AND POSITION(
            'KMAT_CONFIGURED_COST_SUMMARY'
            IN CANDIDATE_SOURCE
        ) > 0 AS OUTPUT_CONTRACT_FLAG,

        POSITION(
            '"baseline_total_cost_usd"'
            IN CANDIDATE_SOURCE
        ) > 0
        AND POSITION(
            '"risk_adjusted_total_cost_usd"'
            IN CANDIDATE_SOURCE
        ) > 0
        AND POSITION(
            '"total_risk_uplift_usd"'
            IN CANDIDATE_SOURCE
        ) > 0
        AND POSITION(
            '"total_risk_uplift_pct"'
            IN CANDIDATE_SOURCE
        ) > 0 AS RETURN_CONTRACT_FLAG

    FROM SOURCE
)
SELECT
    'PHASE14D3D3B_COST_ENGINE_V1',
    'PHASE_14D_3D_3B',
    'CORE_INTERNAL',
    'RUN_KMAT_COST_SIMULATION',
    '(SIMULATION_ID VARCHAR)',
    -4107916750694060430,
    CANDIDATE_SOURCE,
    HASH(CANDIDATE_SOURCE),
    FIXED_DATABASE_COUNT,
    DB_NAME_COUNT,
    SQL_ESCAPE_COUNT,
    QMARK_COUNT,
    PARAMS_COUNT,
    SCHEMA_REFERENCE_COUNT,
    TRUE,
    FALSE,
    FALSE,

    IFF(
        FIXED_DATABASE_COUNT = 0
        AND DB_NAME_COUNT = 0
        AND SQL_ESCAPE_COUNT = 0
        AND QMARK_COUNT > 0
        AND PARAMS_COUNT >= 12
        AND SCHEMA_REFERENCE_COUNT >= 18
        AND SUPER_BOM_FLAG
        AND SUPER_ROUTING_FLAG
        AND DEPENDENCY_RULE_FLAG
        AND CSS_FLAG
        AND FMIS_FLAG
        AND TDS_FLAG
        AND OVERHEAD_FLAG
        AND COST_FORMULA_FLAG
        AND PRICE_FORMULA_FLAG
        AND OUTPUT_CONTRACT_FLAG
        AND RETURN_CONTRACT_FLAG,
        'VALIDATED_REVIEW_ONLY',
        'ATTENTION_REQUIRED'
    ),

    CURRENT_USER(),
    CURRENT_TIMESTAMP()

FROM VALIDATION;


SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COUNT(*) = 1
            AND COUNT_IF(
                CANDIDATE_STATUS =
                    'VALIDATED_REVIEW_ONLY'
            ) = 1,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),
    'phase',
        'PHASE_14D_3D_3B',
    'candidate_id',
        'PHASE14D3D3B_COST_ENGINE_V1',
    'candidate_count',
        COUNT(*),
    'fixed_database_reference_count',
        SUM(
            FIXED_DATABASE_REFERENCE_COUNT
        ),
    'db_name_constant_count',
        SUM(
            DB_NAME_CONSTANT_COUNT
        ),
    'sql_escape_reference_count',
        SUM(
            SQL_ESCAPE_REFERENCE_COUNT
        ),
    'qmark_parameter_count',
        SUM(
            QMARK_PARAMETER_COUNT
        ),
    'params_argument_count',
        SUM(
            PARAMS_ARGUMENT_COUNT
        ),
    'schema_relative_reference_count',
        SUM(
            SCHEMA_RELATIVE_REFERENCE_COUNT
        ),
    'frozen_cost_contract_preserved',
        TRUE,
    'business_logic_changed',
        FALSE,
    'deployment_ready_count',
        COUNT_IF(
            DEPLOYMENT_READY_FLAG = TRUE
        ),
    'procedure_body_changed',
        FALSE,
    'candidate_source_executed',
        FALSE,
    'official_cost_changed',
        FALSE,
    'native_app_package_created',
        FALSE
) AS PHASE14D3D3B_CANDIDATE_SUMMARY
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1
WHERE CANDIDATE_ID =
      'PHASE14D3D3B_COST_ENGINE_V1';

USE ROLE SYSADMIN;
USE WAREHOUSE KMAT_WH;
USE DATABASE KMAT_COST_MODEL_DB;
USE SCHEMA CORE_ML;

WITH CANDIDATE AS (
    SELECT
        COUNT(*) AS CANDIDATE_COUNT,
        COUNT_IF(
            CANDIDATE_STATUS =
                'VALIDATED_REVIEW_ONLY'
        ) AS VALIDATED_COUNT,
        SUM(
            FIXED_DATABASE_REFERENCE_COUNT
        ) AS FIXED_DATABASE_COUNT,
        SUM(
            DB_NAME_CONSTANT_COUNT
        ) AS DB_NAME_COUNT,
        SUM(
            SQL_ESCAPE_REFERENCE_COUNT
        ) AS SQL_ESCAPE_COUNT,
        SUM(
            QMARK_PARAMETER_COUNT
        ) AS QMARK_COUNT,
        SUM(
            PARAMS_ARGUMENT_COUNT
        ) AS PARAMS_COUNT,
        COUNT_IF(
            BUSINESS_LOGIC_CHANGED_FLAG = TRUE
        ) AS BUSINESS_LOGIC_CHANGE_COUNT,
        COUNT_IF(
            DEPLOYMENT_READY_FLAG = TRUE
        ) AS DEPLOYMENT_READY_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1
    WHERE CANDIDATE_ID =
          'PHASE14D3D3B_COST_ENGINE_V1'
),
ORIGINAL AS (
    SELECT
        COUNT(*) AS ORIGINAL_COUNT,
        COUNT_IF(
            OBJECT_DDL_HASH =
                -4107916750694060430
        ) AS ORIGINAL_HASH_MATCH_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1
    WHERE AUDIT_BATCH_ID =
          'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
      AND OBJECT_SCHEMA =
          'CORE_INTERNAL'
      AND OBJECT_NAME =
          'RUN_KMAT_COST_SIMULATION'
      AND OBJECT_SIGNATURE =
          '(SIMULATION_ID VARCHAR)'
),
FROZEN_CONTRACT AS (
    SELECT
        COUNT(*) AS CONTRACT_COUNT,
        COUNT_IF(
            CONTRACT_STATUS =
                'CONTRACT_FROZEN'
        ) AS FROZEN_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_COST_ENGINE_CONTRACT_V1
    WHERE CONTRACT_ID =
          'PHASE14D3D3A_COST_ENGINE_V1'
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            CANDIDATE.CANDIDATE_COUNT = 1
            AND CANDIDATE.VALIDATED_COUNT = 1
            AND CANDIDATE.FIXED_DATABASE_COUNT = 0
            AND CANDIDATE.DB_NAME_COUNT = 0
            AND CANDIDATE.SQL_ESCAPE_COUNT = 0
            AND CANDIDATE.QMARK_COUNT > 0
            AND CANDIDATE.PARAMS_COUNT >= 12
            AND CANDIDATE
                .BUSINESS_LOGIC_CHANGE_COUNT = 0
            AND CANDIDATE
                .DEPLOYMENT_READY_COUNT = 0
            AND ORIGINAL.ORIGINAL_COUNT = 1
            AND ORIGINAL
                .ORIGINAL_HASH_MATCH_COUNT = 1
            AND FROZEN_CONTRACT
                .CONTRACT_COUNT = 1
            AND FROZEN_CONTRACT
                .FROZEN_COUNT = 1,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),
    'phase',
        'PHASE_14D_3D_3B',
    'candidate_count',
        CANDIDATE.CANDIDATE_COUNT,
    'validated_candidate_count',
        CANDIDATE.VALIDATED_COUNT,
    'original_hash_match_count',
        ORIGINAL.ORIGINAL_HASH_MATCH_COUNT,
    'frozen_contract_match_count',
        FROZEN_CONTRACT.FROZEN_COUNT,
    'fixed_database_reference_count',
        CANDIDATE.FIXED_DATABASE_COUNT,
    'db_name_constant_count',
        CANDIDATE.DB_NAME_COUNT,
    'sql_escape_reference_count',
        CANDIDATE.SQL_ESCAPE_COUNT,
    'qmark_parameter_count',
        CANDIDATE.QMARK_COUNT,
    'params_argument_count',
        CANDIDATE.PARAMS_COUNT,
    'business_logic_changed',
        CANDIDATE
            .BUSINESS_LOGIC_CHANGE_COUNT > 0,
    'deployment_ready_count',
        CANDIDATE.DEPLOYMENT_READY_COUNT,
    'procedure_body_changed',
        FALSE,
    'candidate_source_executed',
        FALSE,
    'official_cost_changed',
        FALSE,
    'native_app_package_created',
        FALSE
) AS PHASE14D3D3B_FINAL_GATE
FROM CANDIDATE
CROSS JOIN ORIGINAL
CROSS JOIN FROZEN_CONTRACT;


WITH baseline AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_BASELINE_V1
    WHERE BASELINE_ID =
          'PHASE14A_SIM_001_BASELINE_V1'
),
current_state AS (
    SELECT
        s.SIMULATION_ID,
        HASH(
            s.MATERIAL_COST_USD,
            s.LABOR_COST_USD,
            s.MACHINE_COST_USD,
            s.OVERHEAD_COST_USD,
            s.TOTAL_CONFIGURED_COST_USD,
            s.FLOOR_PRICE_USD,
            s.TARGET_PRICE_USD,
            s.CEILING_PRICE_USD,
            s.BASELINE_TOTAL_COST_USD,
            s.RISK_ADJUSTED_TOTAL_COST_USD,
            s.TOTAL_RISK_UPLIFT_USD,
            s.TOTAL_RISK_UPLIFT_PCT,
            s.CSS_SCORE,
            s.SCRAP_RATE_APPLIED,
            s.AVG_WEIGHTED_FMIS,
            s.MAX_TDS_FACTOR,
            s.BOM_MATCH_CONFIDENCE_SCORE,
            s.BMCS_REVIEW_STATUS,
            s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
            s.QUOTE_TRUST_STATUS,
            h.RESOLVED_SCRAP_RATE,
            h.CSS_RESOLVED_SOURCE,
            h.RESOLVED_FMIS_MULTIPLIER,
            h.FMIS_RESOLVED_SOURCE,
            h.RESOLVED_TDS_FACTOR,
            h.TDS_RESOLVED_SOURCE,
            h.RESOLVED_BMCS_STATUS,
            h.SAFETY_GATE_PASS_FLAG,
            h.COST_ENGINE_CONSUMPTION_ALLOWED_FLAG,
            h.OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG
        ) AS SNAPSHOT_HASH,
        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS ACTIVE_POLICY_COUNT,
        (
            SELECT COUNT_IF(
                DEPLOYMENT_MODE = 'SHADOW'
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS SHADOW_POLICY_COUNT,
        (
            SELECT COUNT_IF(
                AUTO_USE_ALLOWED_FLAG = TRUE
                OR OFFICIAL_COST_IMPACT_ALLOWED_FLAG = TRUE
                OR BUSINESS_DECISION_ALLOWED_FLAG = TRUE
            )
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .VW_ML_DECISION_POLICY_CURRENT_V1
        ) AS POLICY_AUTHORITY_ENABLED_COUNT,
        (
            SELECT COUNT(*)
            FROM
                KMAT_COST_MODEL_DB.CORE_ML
                    .ML_RUNTIME_AUTHORITY_REGISTRY_V1
            WHERE UPPER(AUTHORITY_STATUS) = 'ENABLED'
        ) AS ENABLED_RUNTIME_AUTHORITY_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_OUTPUT
            .KMAT_CONFIGURED_COST_SUMMARY s
    LEFT JOIN
        KMAT_COST_MODEL_DB.CORE_ML
            .VW_KMAT_PHASE10B_HIERARCHY_V1 h
      ON s.SIMULATION_ID = h.SIMULATION_ID
    WHERE s.SIMULATION_ID = 'SIM_001'
    QUALIFY ROW_NUMBER() OVER (
        PARTITION BY s.SIMULATION_ID
        ORDER BY s.CALCULATED_AT DESC
    ) = 1
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            baseline.SNAPSHOT_HASH =
                current_state.SNAPSHOT_HASH
            AND current_state
                .POLICY_AUTHORITY_ENABLED_COUNT = 0
            AND current_state
                .ENABLED_RUNTIME_AUTHORITY_COUNT = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),
    'phase',
        'PHASE_14D_3D_3B',
    'baseline_snapshot_hash',
        baseline.SNAPSHOT_HASH,
    'current_snapshot_hash',
        current_state.SNAPSHOT_HASH,
    'cost_and_governance_snapshot_match',
        baseline.SNAPSHOT_HASH =
        current_state.SNAPSHOT_HASH,
    'active_policy_count',
        current_state.ACTIVE_POLICY_COUNT,
    'shadow_policy_count',
        current_state.SHADOW_POLICY_COUNT,
    'policy_authority_enabled_count',
        current_state
            .POLICY_AUTHORITY_ENABLED_COUNT,
    'enabled_runtime_authority_count',
        current_state
            .ENABLED_RUNTIME_AUTHORITY_COUNT,
    'official_cost_changed',
        baseline.SNAPSHOT_HASH <>
        current_state.SNAPSHOT_HASH,
    'procedure_body_changed',
        FALSE,
    'candidate_source_executed',
        FALSE,
    'native_app_package_created',
        FALSE
) AS PHASE14D3D3B_BASELINE_VERIFICATION
FROM baseline
CROSS JOIN current_state;

/*
PHASE 14D.3E.1 — RFQ STAGE CONTRACT

Scope:
  CORE_INTERNAL.RUN_CORTEX_RFQ_INTAKE_PIPELINE(RFQ_ID VARCHAR)

This script only freezes the required internal-stage contract.
It does not alter or execute the procedure.
*/

CREATE TABLE IF NOT EXISTS
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_RFQ_STAGE_CONTRACT_V1 (
            CONTRACT_ID VARCHAR NOT NULL,
            PHASE VARCHAR NOT NULL,
            PROCEDURE_SCHEMA VARCHAR NOT NULL,
            PROCEDURE_NAME VARCHAR NOT NULL,
            PROCEDURE_SIGNATURE VARCHAR NOT NULL,
            EXPECTED_DDL_HASH NUMBER NOT NULL,
            CURRENT_DDL_HASH NUMBER,
            PROCEDURE_OWNER VARCHAR,
            PROCEDURE_LANGUAGE VARCHAR,
            OWNER_RIGHTS_FLAG BOOLEAN,
            CURRENT_FIXED_DATABASE_REFERENCE_COUNT NUMBER,
            CURRENT_STAGE_REFERENCE_COUNT NUMBER,
            CURRENT_CORTEX_FUNCTION_REFERENCE_COUNT NUMBER,
            STAGE_SCHEMA VARCHAR NOT NULL,
            STAGE_NAME VARCHAR NOT NULL,
            STAGE_REFERENCE VARCHAR NOT NULL,
            STAGE_EXISTS_FLAG BOOLEAN,
            SOURCE_PATH_COLUMN VARCHAR NOT NULL,
            CONTRACT_MODE VARCHAR NOT NULL,
            EXTERNAL_STAGE_REFERENCE_REQUIRED_FLAG BOOLEAN NOT NULL,
            EXPLICIT_REFACTOR_REQUIRED_FLAG BOOLEAN NOT NULL,
            CONTRACT_STATUS VARCHAR NOT NULL,
            CAPTURED_BY VARCHAR NOT NULL,
            CAPTURED_AT TIMESTAMP_NTZ NOT NULL
        );

DELETE FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_RFQ_STAGE_CONTRACT_V1
WHERE CONTRACT_ID =
      'PHASE14D3E1_RFQ_STAGE_V1';

INSERT INTO
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_RFQ_STAGE_CONTRACT_V1
WITH PROCEDURE_AUDIT AS (
    SELECT
        OBJECT_DDL,
        OBJECT_DDL_HASH,
        OBJECT_OWNER,
        OBJECT_LANGUAGE,
        FIXED_DATABASE_REFERENCE_COUNT,
        RFQ_STAGE_REFERENCE_COUNT,
        CORTEX_FUNCTION_REFERENCE_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1
    WHERE AUDIT_BATCH_ID =
          'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
      AND OBJECT_TYPE = 'PROCEDURE'
      AND OBJECT_SCHEMA = 'CORE_INTERNAL'
      AND OBJECT_NAME =
          'RUN_CORTEX_RFQ_INTAKE_PIPELINE'
      AND OBJECT_SIGNATURE =
          '(RFQ_ID VARCHAR)'
),
STAGE_STATE AS (
    SELECT
        COUNT(*) AS STAGE_COUNT
    FROM
        KMAT_COST_MODEL_DB.INFORMATION_SCHEMA.STAGES
    WHERE STAGE_SCHEMA = 'CORE_INPUT'
      AND STAGE_NAME = 'RFQ_DOC_STAGE'
),
CONTRACT_SOURCE AS (
    SELECT
        audit.*,
        stage.STAGE_COUNT,

        (
            audit.OBJECT_DDL IS NOT NULL
            AND REGEXP_COUNT(
                UPPER(audit.OBJECT_DDL),
                'EXECUTE[[:space:]]+AS[[:space:]]+CALLER'
            ) = 0
            AND REGEXP_COUNT(
                UPPER(audit.OBJECT_DDL),
                'EXECUTE[[:space:]]+AS[[:space:]]+RESTRICTED[[:space:]]+CALLER'
            ) = 0
        ) AS OWNER_RIGHTS_FLAG,

        POSITION(
            'SOURCE_STAGE_RELATIVE_PATH'
            IN audit.OBJECT_DDL
        ) > 0 AS SOURCE_PATH_CONTRACT_FLAG,

        POSITION(
            'RFQ_DOC_STAGE'
            IN audit.OBJECT_DDL
        ) > 0 AS STAGE_TOKEN_FLAG

    FROM PROCEDURE_AUDIT audit
    CROSS JOIN STAGE_STATE stage
)
SELECT
    'PHASE14D3E1_RFQ_STAGE_V1',
    'PHASE_14D_3E_1',
    'CORE_INTERNAL',
    'RUN_CORTEX_RFQ_INTAKE_PIPELINE',
    '(RFQ_ID VARCHAR)',
    1228458495994061364,
    OBJECT_DDL_HASH,
    OBJECT_OWNER,
    OBJECT_LANGUAGE,
    OWNER_RIGHTS_FLAG,
    FIXED_DATABASE_REFERENCE_COUNT,
    RFQ_STAGE_REFERENCE_COUNT,
    CORTEX_FUNCTION_REFERENCE_COUNT,
    'CORE_INPUT',
    'RFQ_DOC_STAGE',
    '@CORE_INPUT.RFQ_DOC_STAGE',
    STAGE_COUNT = 1,
    'SOURCE_STAGE_RELATIVE_PATH',
    'APP_OWNED_INTERNAL_STAGE',
    FALSE,
    TRUE,

    IFF(
        OBJECT_DDL_HASH =
            1228458495994061364
        AND OBJECT_OWNER = 'SYSADMIN'
        AND OBJECT_LANGUAGE = 'PYTHON'
        AND OWNER_RIGHTS_FLAG
        AND FIXED_DATABASE_REFERENCE_COUNT = 2
        AND RFQ_STAGE_REFERENCE_COUNT = 1
        AND CORTEX_FUNCTION_REFERENCE_COUNT = 5
        AND STAGE_COUNT = 1
        AND SOURCE_PATH_CONTRACT_FLAG
        AND STAGE_TOKEN_FLAG,
        'CONTRACT_FROZEN',
        'ATTENTION_REQUIRED'
    ),

    CURRENT_USER(),
    CURRENT_TIMESTAMP()

FROM CONTRACT_SOURCE;

SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COUNT(*) = 1
            AND COUNT_IF(
                CONTRACT_STATUS =
                    'CONTRACT_FROZEN'
            ) = 1,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),
    'phase',
        'PHASE_14D_3E_1',
    'contract_id',
        'PHASE14D3E1_RFQ_STAGE_V1',
    'contract_frozen_count',
        COUNT_IF(
            CONTRACT_STATUS =
                'CONTRACT_FROZEN'
        ),
    'original_hash_match_count',
        COUNT_IF(
            CURRENT_DDL_HASH =
                EXPECTED_DDL_HASH
        ),
    'owner_rights_count',
        COUNT_IF(
            OWNER_RIGHTS_FLAG = TRUE
        ),
    'stage_exists_count',
        COUNT_IF(
            STAGE_EXISTS_FLAG = TRUE
        ),
    'stage_reference',
        MAX(STAGE_REFERENCE),
    'contract_mode',
        MAX(CONTRACT_MODE),
    'external_stage_reference_required',
        BOOLOR_AGG(
            EXTERNAL_STAGE_REFERENCE_REQUIRED_FLAG
        ),
    'explicit_refactor_required',
        BOOLOR_AGG(
            EXPLICIT_REFACTOR_REQUIRED_FLAG
        ),
    'procedure_body_changed',
        FALSE,
    'candidate_source_created',
        FALSE,
    'candidate_source_executed',
        FALSE,
    'official_cost_changed',
        FALSE,
    'native_app_package_created',
        FALSE
) AS PHASE14D3E1_RFQ_STAGE_CONTRACT_RESULT
FROM
    KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_RFQ_STAGE_CONTRACT_V1
WHERE CONTRACT_ID =
      'PHASE14D3E1_RFQ_STAGE_V1';

DELETE FROM KMAT_COST_MODEL_DB.CORE_ML.NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1
WHERE CANDIDATE_ID = 'PHASE14D3E2_RFQ_INTAKE_V1';

INSERT INTO KMAT_COST_MODEL_DB.CORE_ML.NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1
WITH SOURCE AS (
    SELECT $$
import base64
import json
import re

RFQ_STAGE_NAME = "@CORE_INPUT.RFQ_DOC_STAGE"

def normalize_text(value):
    return "" if value is None else str(value).strip().upper()

def normalize_id(value):
    cleaned = re.sub(r"[^A-Z0-9_]+", "_", normalize_text(value))
    cleaned = re.sub(r"_+", "_", cleaned).strip("_") or "UNKNOWN"
    return cleaned[:60]

def parse_json_safe(value):
    if value is None:
        return {}
    if isinstance(value, dict):
        return value
    if isinstance(value, str):
        try:
            return json.loads(value)
        except Exception:
            return {}
    try:
        return dict(value)
    except Exception:
        return {}

def get_nested(obj, key):
    if not isinstance(obj, dict):
        return None
    if key in obj:
        return obj[key]
    key_upper = str(key).upper()
    for existing_key, value in obj.items():
        if str(existing_key).upper() == key_upper:
            return value
    return None

def get_ai_complete_model(session):
    rows = session.sql("""
        SELECT CONFIG_VALUE
        FROM CORE_INPUT.CORTEX_MODEL_CONFIG
        WHERE CONFIG_KEY = 'AI_COMPLETE_MODEL'
          AND ACTIVE_FLAG = TRUE
        LIMIT 1
    """).collect()
    return rows[0]["CONFIG_VALUE"] if rows else "snowflake-arctic"

def map_to_allowed(characteristic_name, raw_value, allowed_values):
    raw = normalize_text(raw_value)
    if raw in allowed_values:
        return raw
    if characteristic_name == "ENGINE":
        if "V8" in raw or any(x in raw for x in ("HIGH","POWER","HEAVY","DUTY")):
            return "V8"
        if "V6" in raw or any(x in raw for x in ("STANDARD","REGULAR","BASIC")):
            return "V6"
    elif characteristic_name == "CAB":
        if any(x in raw for x in ("PREMIUM","LUXURY","ENHANCED")):
            return "PREMIUM"
        if any(x in raw for x in ("STANDARD","REGULAR","BASIC")):
            return "STANDARD"
    elif characteristic_name == "WHEEL":
        if any(x in raw for x in ("OFFROAD","OFF-ROAD","TERRAIN","ROUGH")):
            return "OFFROAD"
        if any(x in raw for x in ("STANDARD","REGULAR","NORMAL")):
            return "STANDARD"
    elif characteristic_name == "COLOR":
        if "RED" in raw:
            return "RED"
        if "BLUE" in raw:
            return "BLUE"
    return "UNKNOWN"

def extract_text_from_stage_file(session, relative_path):
    response_format = {
        "RFQ_TEXT": (
            "Extract the complete readable customer RFQ/specification text. "
            "Preserve technical requirements, configuration descriptions, "
            "colors, engine, cab, wheel references, and customer notes. "
            "Do not summarize. Return the readable text as one string."
        )
    }
    rows = session.sql("""
        SELECT TO_JSON(
            AI_EXTRACT(
                file => TO_FILE('@CORE_INPUT.RFQ_DOC_STAGE', ?),
                responseFormat => PARSE_JSON(?),
                scores => FALSE
            )
        ) AS DOC_TEXT_EXTRACTION_JSON
    """, params=[relative_path, json.dumps(response_format)]).collect()
    if not rows:
        return "", {}
    raw_obj = parse_json_safe(rows[0]["DOC_TEXT_EXTRACTION_JSON"])
    response_obj = get_nested(raw_obj, "response") or raw_obj
    return str(get_nested(response_obj, "RFQ_TEXT") or ""), raw_obj

def translate_to_english(session, source_text, source_language_code):
    source_lang = str(source_language_code or "").strip().lower()
    if source_lang in ("en", "english"):
        return source_text, "NOT_REQUIRED_ENGLISH_SOURCE", {}
    if source_lang in ("", "auto", "auto_detect", "detect"):
        source_lang = ""
    rows = session.sql("""
        SELECT AI_TRANSLATE(?, ?, 'en') AS TRANSLATED_TEXT
    """, params=[source_text, source_lang]).collect()
    if not rows or rows[0]["TRANSLATED_TEXT"] is None:
        return source_text, "TRANSLATION_FAILED_FALLBACK_TO_ORIGINAL", {}
    return rows[0]["TRANSLATED_TEXT"], "AI_TRANSLATE_TO_EN", {
        "source_language_code": source_language_code,
        "target_language_code": "en",
    }

def summarize_rfq(session, english_text):
    try:
        rows = session.sql("""
            SELECT SNOWFLAKE.CORTEX.SUMMARIZE(?) AS RFQ_SUMMARY
        """, params=[english_text]).collect()
        return rows[0]["RFQ_SUMMARY"] if rows and rows[0]["RFQ_SUMMARY"] is not None else ""
    except Exception as exc:
        return f"Summary generation failed: {exc}"

def classify_rfq(session, english_text):
    try:
        rows = session.sql("""
            SELECT TO_JSON(
                AI_CLASSIFY(
                    ?,
                    ARRAY_CONSTRUCT(
                        'STANDARD_CONFIGURATION',
                        'CUSTOM_CONFIGURATION',
                        'INCOMPLETE_REQUIREMENT',
                        'ENGINEERING_REVIEW_REQUIRED'
                    )
                )
            ) AS CLASSIFICATION_JSON
        """, params=[english_text]).collect()
        if not rows:
            return "UNKNOWN", "AI_CLASSIFY returned no result.", {}
        obj = parse_json_safe(rows[0]["CLASSIFICATION_JSON"])
        label = "UNKNOWN"
        if isinstance(obj, dict):
            if "label" in obj:
                label = str(obj["label"])
            elif isinstance(obj.get("labels"), list) and obj["labels"]:
                label = str(obj["labels"][0])
            elif "classification" in obj:
                label = str(obj["classification"])
        return label, f"Cortex classified the RFQ as {label}.", obj
    except Exception as exc:
        return "UNKNOWN", f"AI_CLASSIFY failed: {exc}", {}

def extract_kmat_configuration(session, english_text):
    response_format = {
        "ENGINE": "Return V6, V8, or UNKNOWN. Map high-output, powerful, heavy-duty, or performance engine to V8; standard, regular, or basic engine to V6.",
        "CAB": "Return STANDARD, PREMIUM, or UNKNOWN. Map premium, luxury, or enhanced cabin to PREMIUM; standard, regular, or basic cabin to STANDARD.",
        "WHEEL": "Return STANDARD, OFFROAD, or UNKNOWN. Map enhanced terrain, offroad, off-road, rough site, or rough terrain to OFFROAD; standard, regular transport, or normal road usage to STANDARD.",
        "COLOR": "Return RED, BLUE, or UNKNOWN.",
    }
    rows = session.sql("""
        SELECT TO_JSON(
            AI_EXTRACT(
                text => ?,
                responseFormat => PARSE_JSON(?),
                scores => TRUE
            )
        ) AS CONFIG_EXTRACTION_JSON
    """, params=[english_text, json.dumps(response_format)]).collect()
    if not rows:
        return {}, {}
    raw_obj = parse_json_safe(rows[0]["CONFIG_EXTRACTION_JSON"])
    response_obj = get_nested(raw_obj, "response") or raw_obj
    return (response_obj if isinstance(response_obj, dict) else {}), raw_obj

def generate_extraction_reasoning(session, model_name, english_text, normalized_config, rfq_summary, complexity_category):
    prompt = f"""
You are assisting a manufacturing KMAT cost model.
Explain why the RFQ was mapped to the extracted KMAT configuration.
Do not invent values. Do not calculate cost. Use simple business language.

RFQ summary:
{rfq_summary}

Extracted configuration:
{json.dumps(normalized_config)}

RFQ complexity category:
{complexity_category}

Original RFQ text:
{english_text[:4000]}
"""
    try:
        rows = session.sql("""
            SELECT AI_COMPLETE(?, ?) AS EXTRACTION_REASONING
        """, params=[model_name, prompt]).collect()
        return rows[0]["EXTRACTION_REASONING"] if rows and rows[0]["EXTRACTION_REASONING"] is not None else "AI_COMPLETE returned no reasoning."
    except Exception as exc:
        return f"AI_COMPLETE reasoning failed: {exc}"

def run(session, RFQ_ID):
    rfq_rows = session.sql("""
        SELECT
            RFQ_ID, KMAT_ID, CUSTOMER_ID, CUSTOMER_NAME,
            SOURCE_DOCUMENT_NAME, SOURCE_DOCUMENT_TYPE,
            SOURCE_DOCUMENT_TEXT, SOURCE_STAGE_NAME,
            SOURCE_STAGE_RELATIVE_PATH, ORIGINAL_DOCUMENT_TEXT,
            SOURCE_LANGUAGE_CODE
        FROM CORE_INPUT.RFQ_HEADER
        WHERE RFQ_ID = ?
        LIMIT 1
    """, params=[RFQ_ID]).collect()
    if not rfq_rows:
        return json.dumps({"status":"ERROR","message":f"RFQ_ID {RFQ_ID} not found in CORE_INPUT.RFQ_HEADER"})

    rfq = rfq_rows[0]
    kmat_id = rfq["KMAT_ID"]
    source_document_text = rfq["SOURCE_DOCUMENT_TEXT"]
    source_stage_relative_path = rfq["SOURCE_STAGE_RELATIVE_PATH"]
    source_language_code = rfq["SOURCE_LANGUAGE_CODE"] or "en"
    document_text_extraction_raw = {}

    if source_document_text is not None and str(source_document_text).strip():
        original_text = str(source_document_text)
        text_extraction_method = "STREAMLIT_TEXT_INPUT_OR_PREEXTRACTED_TEXT"
    elif source_stage_relative_path is not None and str(source_stage_relative_path).strip():
        original_text, document_text_extraction_raw = extract_text_from_stage_file(session, source_stage_relative_path)
        text_extraction_method = "CORTEX_AI_EXTRACT_FROM_UPLOADED_FILE"
    else:
        return json.dumps({"status":"ERROR","message":"No RFQ text or uploaded stage file found."})

    if original_text is None or not str(original_text).strip():
        return json.dumps({"status":"ERROR","message":"RFQ text extraction produced empty text."})

    processing_text_en, translation_method, translation_raw = translate_to_english(
        session, original_text, source_language_code
    )
    rfq_summary = summarize_rfq(session, processing_text_en)
    complexity_category, complexity_reason, complexity_raw = classify_rfq(session, processing_text_en)
    raw_config, config_extraction_raw = extract_kmat_configuration(session, processing_text_en)

    allowed_rows = session.sql("""
        SELECT CHARACTERISTIC_NAME, ALLOWED_VALUE
        FROM CORE_INPUT.CHARACTERISTIC_MASTER
        WHERE KMAT_ID = ?
          AND ACTIVE_FLAG = TRUE
    """, params=[kmat_id]).collect()
    allowed_map = {}
    for row in allowed_rows:
        name = normalize_text(row["CHARACTERISTIC_NAME"])
        allowed_map.setdefault(name, set()).add(normalize_text(row["ALLOWED_VALUE"]))

    required_chars = ["ENGINE","CAB","WHEEL","COLOR"]
    raw_cortex_values = {name: get_nested(raw_config, name) for name in required_chars}
    normalized_config = {
        name: map_to_allowed(name, raw_cortex_values[name], allowed_map.get(name, set()))
        for name in required_chars
    }
    unknown_count = sum(value == "UNKNOWN" for value in normalized_config.values())
    valid_count = len(required_chars) - unknown_count
    cortex_processing_status = (
        "CORTEX_EXTRACTION_COMPLETE"
        if unknown_count == 0
        else "CORTEX_EXTRACTION_INCOMPLETE_REVIEW_REQUIRED"
    )

    model_name = get_ai_complete_model(session)
    extraction_reasoning = generate_extraction_reasoning(
        session, model_name, processing_text_en, normalized_config, rfq_summary, complexity_category
    )

    existing_rows = session.sql("""
        SELECT
            COALESCE(MAX(CONFIGURATION_VERSION), 0) AS MAX_VERSION,
            MAX(SIMULATION_ID) AS EXISTING_SIMULATION_ID
        FROM CORE_INPUT.RFQ_CONFIGURATION
        WHERE RFQ_ID = ?
    """, params=[RFQ_ID]).collect()
    max_version = int(existing_rows[0]["MAX_VERSION"] or 0)
    new_version = max_version + 1
    existing_simulation_id = existing_rows[0]["EXISTING_SIMULATION_ID"]
    simulation_id = (
        existing_simulation_id
        if existing_simulation_id is not None and str(existing_simulation_id).strip()
        else "SIM_" + normalize_id(RFQ_ID)
    )

    session.sql("""
        UPDATE CORE_INPUT.RFQ_CONFIGURATION
        SET ACTIVE_FLAG = FALSE
        WHERE RFQ_ID = ?
    """, params=[RFQ_ID]).collect()

    extraction_raw_payload = {
        "document_text_extraction_raw": document_text_extraction_raw,
        "translation_raw": translation_raw,
        "rfq_summary": rfq_summary,
        "complexity_category": complexity_category,
        "complexity_reason": complexity_reason,
        "complexity_raw": complexity_raw,
        "config_extraction_raw": config_extraction_raw,
        "raw_cortex_values": raw_cortex_values,
        "normalized_configuration": normalized_config,
        "valid_characteristic_count": valid_count,
        "unknown_characteristic_count": unknown_count,
        "ai_complete_model": model_name,
        "extraction_reasoning": extraction_reasoning,
    }
    normalized_config_b64 = base64.b64encode(
        json.dumps(normalized_config, ensure_ascii=False).encode("utf-8")
    ).decode("utf-8")
    raw_payload_b64 = base64.b64encode(
        json.dumps(extraction_raw_payload, ensure_ascii=False).encode("utf-8")
    ).decode("utf-8")

    session.sql("""
        INSERT INTO CORE_INPUT.RFQ_CONFIGURATION
        (
            RFQ_ID, SIMULATION_ID, KMAT_ID, CONFIGURATION_VERSION,
            EXTRACTED_CONFIGURATION_JSON, EXTRACTION_METHOD,
            EXTRACTION_MODEL_NAME, EXTRACTION_PROMPT_VERSION,
            EXTRACTION_RAW_RESPONSE, CREATED_BY, ACTIVE_FLAG
        )
        SELECT
            ?, ?, ?, ?,
            PARSE_JSON(BASE64_DECODE_STRING(?)),
            'CORTEX_PHASE_7A_PIPELINE',
            'AI_TRANSLATE_SUMMARIZE_AI_EXTRACT_AI_CLASSIFY_AI_COMPLETE',
            'RFQ_CORTEX_INTAKE_V1',
            PARSE_JSON(BASE64_DECODE_STRING(?)),
            CURRENT_USER(),
            TRUE
    """, params=[
        RFQ_ID, simulation_id, kmat_id, new_version,
        normalized_config_b64, raw_payload_b64
    ]).collect()

    session.sql("""
        UPDATE CORE_INPUT.RFQ_HEADER
        SET
            ORIGINAL_DOCUMENT_TEXT = ?,
            SOURCE_DOCUMENT_TEXT = ?,
            PROCESSING_TEXT_EN = ?,
            RFQ_SUMMARY = ?,
            TARGET_LANGUAGE_CODE = 'en',
            TRANSLATION_METHOD = ?,
            TEXT_EXTRACTION_METHOD = ?,
            RFQ_COMPLEXITY_CATEGORY = ?,
            RFQ_COMPLEXITY_REASON = ?,
            CORTEX_PROCESSING_STATUS = ?,
            CORTEX_PROCESSED_AT = CURRENT_TIMESTAMP(),
            DOCUMENT_STATUS = ?,
            UPDATED_AT = CURRENT_TIMESTAMP()
        WHERE RFQ_ID = ?
    """, params=[
        original_text, processing_text_en, processing_text_en, rfq_summary,
        translation_method, text_extraction_method, complexity_category,
        complexity_reason, cortex_processing_status, cortex_processing_status,
        RFQ_ID
    ]).collect()

    bmcs_result = {}
    try:
        bmcs_rows = session.sql("""
            CALL CORE_INTERNAL.RUN_RULE_BASED_BMCS_SCORING(?)
        """, params=[RFQ_ID]).collect()
        if bmcs_rows:
            try:
                bmcs_result = json.loads(bmcs_rows[0][0])
            except Exception:
                bmcs_result = {"raw_result": str(bmcs_rows[0][0])}
    except Exception as exc:
        bmcs_result = {"status":"BMCS_SCORING_FAILED","error":str(exc)}

    return json.dumps({
        "status":"SUCCESS",
        "rfq_id":RFQ_ID,
        "simulation_id":simulation_id,
        "kmat_id":kmat_id,
        "configuration_version":new_version,
        "source_document_name":rfq["SOURCE_DOCUMENT_NAME"],
        "text_extraction_method":text_extraction_method,
        "translation_method":translation_method,
        "rfq_summary":rfq_summary,
        "rfq_complexity_category":complexity_category,
        "extracted_configuration_json":normalized_config,
        "raw_cortex_values":raw_cortex_values,
        "valid_characteristic_count":valid_count,
        "unknown_characteristic_count":unknown_count,
        "cortex_processing_status":cortex_processing_status,
        "extraction_reasoning":extraction_reasoning,
        "bmcs_result":bmcs_result,
    })

$$ AS CANDIDATE_SOURCE
),
VALIDATION AS (
    SELECT
        CANDIDATE_SOURCE,
        REGEXP_COUNT(UPPER(CANDIDATE_SOURCE), 'KMAT_COST_MODEL_DB') AS FIXED_DATABASE_COUNT,
        REGEXP_COUNT(CANDIDATE_SOURCE, 'DB_NAME') AS DB_NAME_COUNT,
        REGEXP_COUNT(CANDIDATE_SOURCE, 'sql_escape') AS SQL_ESCAPE_COUNT,
        REGEXP_COUNT(CANDIDATE_SOURCE, '[?]') AS QMARK_COUNT,
        REGEXP_COUNT(CANDIDATE_SOURCE, 'params[[:space:]]*=') AS PARAMS_COUNT,
        REGEXP_COUNT(CANDIDATE_SOURCE, 'CORE_INPUT[.]')
          + REGEXP_COUNT(CANDIDATE_SOURCE, 'CORE_INTERNAL[.]') AS SCHEMA_REFERENCE_COUNT,
        REGEXP_COUNT(CANDIDATE_SOURCE, 'session[.]sql[[:space:]]*[(]') AS SESSION_SQL_COUNT,
        POSITION('''@CORE_INPUT.RFQ_DOC_STAGE''' IN CANDIDATE_SOURCE) > 0 AS STAGE_FLAG,
        POSITION('TO_FILE(' IN CANDIDATE_SOURCE) > 0 AS TO_FILE_FLAG,
        POSITION('AI_TRANSLATE' IN CANDIDATE_SOURCE) > 0
          AND POSITION('SUMMARIZE' IN CANDIDATE_SOURCE) > 0
          AND POSITION('AI_EXTRACT' IN CANDIDATE_SOURCE) > 0
          AND POSITION('AI_CLASSIFY' IN CANDIDATE_SOURCE) > 0
          AND POSITION('AI_COMPLETE' IN CANDIDATE_SOURCE) > 0 AS CORTEX_FLAG,
        POSITION('RFQ_CORTEX_INTAKE_V1' IN CANDIDATE_SOURCE) > 0
          AND POSITION('CORTEX_PHASE_7A_PIPELINE' IN CANDIDATE_SOURCE) > 0 AS VERSION_FLAG,
        POSITION('RUN_RULE_BASED_BMCS_SCORING' IN CANDIDATE_SOURCE) > 0 AS BMCS_FLAG,
        POSITION('SOURCE_STAGE_RELATIVE_PATH' IN CANDIDATE_SOURCE) > 0 AS SOURCE_PATH_FLAG
    FROM SOURCE
)
SELECT
    'PHASE14D3E2_RFQ_INTAKE_V1',
    'PHASE_14D_3E_2',
    'CORE_INTERNAL',
    'RUN_CORTEX_RFQ_INTAKE_PIPELINE',
    '(RFQ_ID VARCHAR)',
    1228458495994061364,
    CANDIDATE_SOURCE,
    HASH(CANDIDATE_SOURCE),
    FIXED_DATABASE_COUNT,
    DB_NAME_COUNT,
    SQL_ESCAPE_COUNT,
    QMARK_COUNT,
    PARAMS_COUNT,
    SCHEMA_REFERENCE_COUNT,
    TRUE,
    FALSE,
    FALSE,
    IFF(
        FIXED_DATABASE_COUNT = 0
        AND DB_NAME_COUNT = 0
        AND SQL_ESCAPE_COUNT = 0
        AND QMARK_COUNT > 0
        AND PARAMS_COUNT = 13
        AND SESSION_SQL_COUNT = 14
        AND SCHEMA_REFERENCE_COUNT >= 10
        AND STAGE_FLAG AND TO_FILE_FLAG AND CORTEX_FLAG
        AND VERSION_FLAG AND BMCS_FLAG AND SOURCE_PATH_FLAG,
        'VALIDATED_REVIEW_ONLY',
        'ATTENTION_REQUIRED'
    ),
    CURRENT_USER(),
    CURRENT_TIMESTAMP()
FROM VALIDATION;

WITH CANDIDATE AS (
    SELECT
        COUNT(*) AS CANDIDATE_COUNT,
        COUNT_IF(CANDIDATE_STATUS = 'VALIDATED_REVIEW_ONLY') AS VALIDATED_COUNT,
        SUM(FIXED_DATABASE_REFERENCE_COUNT) AS FIXED_DATABASE_COUNT,
        SUM(DB_NAME_CONSTANT_COUNT) AS DB_NAME_COUNT,
        SUM(SQL_ESCAPE_REFERENCE_COUNT) AS SQL_ESCAPE_COUNT,
        SUM(QMARK_PARAMETER_COUNT) AS QMARK_COUNT,
        SUM(PARAMS_ARGUMENT_COUNT) AS PARAMS_COUNT,
        SUM(SCHEMA_RELATIVE_REFERENCE_COUNT) AS SCHEMA_REFERENCE_COUNT,
        COUNT_IF(BUSINESS_LOGIC_CHANGED_FLAG = TRUE) AS BUSINESS_LOGIC_CHANGE_COUNT,
        COUNT_IF(DEPLOYMENT_READY_FLAG = TRUE) AS DEPLOYMENT_READY_COUNT
    FROM KMAT_COST_MODEL_DB.CORE_ML.NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1
    WHERE CANDIDATE_ID = 'PHASE14D3E2_RFQ_INTAKE_V1'
),
ORIGINAL AS (
    SELECT
        COUNT(*) AS ORIGINAL_COUNT,
        COUNT_IF(OBJECT_DDL_HASH = 1228458495994061364) AS ORIGINAL_HASH_MATCH_COUNT
    FROM KMAT_COST_MODEL_DB.CORE_ML.NATIVE_COMPAT_OBJECT_NAMESPACE_AUDIT_V1
    WHERE AUDIT_BATCH_ID = 'PHASE14D2_DEPLOYED_NAMESPACE_AUDIT_V1'
      AND OBJECT_SCHEMA = 'CORE_INTERNAL'
      AND OBJECT_NAME = 'RUN_CORTEX_RFQ_INTAKE_PIPELINE'
      AND OBJECT_SIGNATURE = '(RFQ_ID VARCHAR)'
),
STAGE_CONTRACT AS (
    SELECT
        COUNT(*) AS CONTRACT_COUNT,
        COUNT_IF(CONTRACT_STATUS = 'CONTRACT_FROZEN') AS FROZEN_COUNT
    FROM KMAT_COST_MODEL_DB.CORE_ML.NATIVE_COMPAT_RFQ_STAGE_CONTRACT_V1
    WHERE CONTRACT_ID = 'PHASE14D3E1_RFQ_STAGE_V1'
)
SELECT OBJECT_CONSTRUCT(
    'status', IFF(
        CANDIDATE.CANDIDATE_COUNT = 1
        AND CANDIDATE.VALIDATED_COUNT = 1
        AND CANDIDATE.FIXED_DATABASE_COUNT = 0
        AND CANDIDATE.DB_NAME_COUNT = 0
        AND CANDIDATE.SQL_ESCAPE_COUNT = 0
        AND CANDIDATE.PARAMS_COUNT = 13
        AND CANDIDATE.BUSINESS_LOGIC_CHANGE_COUNT = 0
        AND CANDIDATE.DEPLOYMENT_READY_COUNT = 0
        AND ORIGINAL.ORIGINAL_COUNT = 1
        AND ORIGINAL.ORIGINAL_HASH_MATCH_COUNT = 1
        AND STAGE_CONTRACT.CONTRACT_COUNT = 1
        AND STAGE_CONTRACT.FROZEN_COUNT = 1,
        'SUCCESS',
        'ATTENTION_REQUIRED'
    ),
    'phase', 'PHASE_14D_3E_2',
    'candidate_count', CANDIDATE.CANDIDATE_COUNT,
    'validated_candidate_count', CANDIDATE.VALIDATED_COUNT,
    'original_hash_match_count', ORIGINAL.ORIGINAL_HASH_MATCH_COUNT,
    'stage_contract_match_count', STAGE_CONTRACT.FROZEN_COUNT,
    'fixed_database_reference_count', CANDIDATE.FIXED_DATABASE_COUNT,
    'db_name_constant_count', CANDIDATE.DB_NAME_COUNT,
    'sql_escape_reference_count', CANDIDATE.SQL_ESCAPE_COUNT,
    'qmark_parameter_count', CANDIDATE.QMARK_COUNT,
    'params_argument_count', CANDIDATE.PARAMS_COUNT,
    'schema_relative_reference_count', CANDIDATE.SCHEMA_REFERENCE_COUNT,
    'stage_reference', '@CORE_INPUT.RFQ_DOC_STAGE',
    'cortex_function_family_count', 5,
    'business_logic_changed', CANDIDATE.BUSINESS_LOGIC_CHANGE_COUNT > 0,
    'deployment_ready_count', CANDIDATE.DEPLOYMENT_READY_COUNT,
    'procedure_body_changed', FALSE,
    'candidate_source_executed', FALSE,
    'official_cost_changed', FALSE,
    'native_app_package_created', FALSE
) AS PHASE14D3E2_FINAL_GATE
FROM CANDIDATE
CROSS JOIN ORIGINAL
CROSS JOIN STAGE_CONTRACT;

/*
PHASE 14D.4 — ESSENTIAL RUNTIME READINESS GATE

Essential objects only:
  5 views
  6 SQL procedures
  6 Python procedures

Excluded:
  monitoring/dashboard views
  feedback-detail views
  actual-outcome recording procedures
  monitoring procedure

This script is read-only.
*/

WITH ESSENTIAL_VIEWS AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_VIEW_REWRITE_TARGET_V1
    WHERE PLAN_BATCH_ID =
          'PHASE14D3B1_RUNTIME_VIEW_PLAN_V1'
      AND VIEW_NAME IN (
          'VW_KMAT_STREAMLIT_RUNTIME_INPUT_V1',
          'VW_KMAT_PHASE13A_RUNTIME_AUTHORITY_V1',
          'VW_ML_DECISION_WITH_APPROVED_OVERRIDE_V2',
          'VW_ML_POLICY_VERSION_SEAL_INTEGRITY_V1',
          'VW_ML_RUNTIME_DECISION_CURRENT_V1'
      )
),
VIEW_GATE AS (
    SELECT
        COUNT(*) AS OBJECT_COUNT,
        COUNT_IF(
            PREFLIGHT_STATUS =
                'READY_FOR_DEPENDENCY_GATE'
        ) AS READY_COUNT,
        COUNT_IF(
            SECURE_CONTRACT_MATCH_FLAG = TRUE
        ) AS SECURE_MATCH_COUNT
    FROM ESSENTIAL_VIEWS
),
ESSENTIAL_SQL_PROCEDURES AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_SQL_PROCEDURE_TARGET_V1
    WHERE PLAN_BATCH_ID =
          'PHASE14D3C_SQL_PROCEDURE_PLAN_V1'
      AND PROCEDURE_NAME IN (
          'RUN_KMAT_COST_SIMULATION_GOVERNED_V2',
          'RUN_KMAT_COST_SIMULATION_GOVERNED_V3',
          'PREPARE_KMAT_GOVERNED_COST_INPUT_V2',
          'RESOLVE_ML_RUNTIME_AUTHORITY_SECURE_V1',
          'SUBMIT_ML_DECISION_OVERRIDE_V2',
          'REVIEW_ML_DECISION_OVERRIDE_V2'
      )
),
SQL_PROCEDURE_GATE AS (
    SELECT
        COUNT(*) AS OBJECT_COUNT,
        COUNT_IF(
            PREFLIGHT_STATUS =
                'READY_FOR_CONTRACT_REVIEW'
        ) AS READY_COUNT,
        COUNT_IF(
            OWNER_RIGHTS_FLAG = TRUE
        ) AS OWNER_RIGHTS_COUNT,
        COUNT_IF(
            CURRENT_DDL_HASH =
                EXPECTED_DDL_HASH
        ) AS HASH_MATCH_COUNT
    FROM ESSENTIAL_SQL_PROCEDURES
),
ESSENTIAL_PYTHON_CANDIDATES AS (
    SELECT *
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1
    WHERE CANDIDATE_ID IN (
          'PHASE14D3D2A_PREPARE_RFQ_V1',
          'PHASE14D3D2B_RULE_BMCS_V1',
          'PHASE14D3D2C_CORTEX_BMCS_V1',
          'PHASE14D3D2D_QUOTE_PIPELINE_V1',
          'PHASE14D3D3B_COST_ENGINE_V1',
          'PHASE14D3E2_RFQ_INTAKE_V1'
      )
),
PYTHON_GATE AS (
    SELECT
        COUNT(*) AS OBJECT_COUNT,
        COUNT_IF(
            CANDIDATE_STATUS =
                'VALIDATED_REVIEW_ONLY'
        ) AS READY_COUNT,
        COUNT_IF(
            BUSINESS_LOGIC_CHANGED_FLAG = TRUE
        ) AS BUSINESS_LOGIC_CHANGE_COUNT,
        COUNT_IF(
            DEPLOYMENT_READY_FLAG = TRUE
        ) AS DEPLOYMENT_READY_COUNT,
        COUNT_IF(
            CANDIDATE_STATUS = 'VALIDATED_REVIEW_ONLY'
            AND DEPLOYMENT_READY_FLAG = TRUE
        ) AS EXECUTED_COUNT
    FROM ESSENTIAL_PYTHON_CANDIDATES
),
COST_CONTRACT AS (
    SELECT
        COUNT_IF(
            CONTRACT_STATUS =
                'CONTRACT_FROZEN'
        ) AS FROZEN_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_COST_ENGINE_CONTRACT_V1
    WHERE CONTRACT_ID =
          'PHASE14D3D3A_COST_ENGINE_V1'
),
STAGE_CONTRACT AS (
    SELECT
        COUNT_IF(
            CONTRACT_STATUS =
                'CONTRACT_FROZEN'
        ) AS FROZEN_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_RFQ_STAGE_CONTRACT_V1
    WHERE CONTRACT_ID =
          'PHASE14D3E1_RFQ_STAGE_V1'
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            VIEW_GATE.OBJECT_COUNT = 5
            AND VIEW_GATE.READY_COUNT = 5
            AND VIEW_GATE.SECURE_MATCH_COUNT = 5
            AND SQL_PROCEDURE_GATE.OBJECT_COUNT = 6
            AND SQL_PROCEDURE_GATE.READY_COUNT = 6
            AND SQL_PROCEDURE_GATE.OWNER_RIGHTS_COUNT = 6
            AND SQL_PROCEDURE_GATE.HASH_MATCH_COUNT = 6
            AND PYTHON_GATE.OBJECT_COUNT = 6
            AND PYTHON_GATE.READY_COUNT = 6
            AND PYTHON_GATE.BUSINESS_LOGIC_CHANGE_COUNT = 0
            AND PYTHON_GATE.DEPLOYMENT_READY_COUNT = 0
            AND PYTHON_GATE.EXECUTED_COUNT = 0
            AND COST_CONTRACT.FROZEN_COUNT = 1
            AND STAGE_CONTRACT.FROZEN_COUNT = 1,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_4_ESSENTIAL_ONLY',

    'essential_object_count',
        VIEW_GATE.OBJECT_COUNT
        + SQL_PROCEDURE_GATE.OBJECT_COUNT
        + PYTHON_GATE.OBJECT_COUNT,

    'essential_view_count',
        VIEW_GATE.OBJECT_COUNT,

    'ready_view_count',
        VIEW_GATE.READY_COUNT,

    'view_secure_contract_match_count',
        VIEW_GATE.SECURE_MATCH_COUNT,

    'essential_sql_procedure_count',
        SQL_PROCEDURE_GATE.OBJECT_COUNT,

    'ready_sql_procedure_count',
        SQL_PROCEDURE_GATE.READY_COUNT,

    'sql_procedure_owner_rights_count',
        SQL_PROCEDURE_GATE.OWNER_RIGHTS_COUNT,

    'sql_procedure_hash_match_count',
        SQL_PROCEDURE_GATE.HASH_MATCH_COUNT,

    'essential_python_procedure_count',
        PYTHON_GATE.OBJECT_COUNT,

    'validated_python_candidate_count',
        PYTHON_GATE.READY_COUNT,

    'python_business_logic_change_count',
        PYTHON_GATE.BUSINESS_LOGIC_CHANGE_COUNT,

    'python_deployment_ready_count',
        PYTHON_GATE.DEPLOYMENT_READY_COUNT,

    'python_candidate_executed_count',
        PYTHON_GATE.EXECUTED_COUNT,

    'cost_engine_contract_frozen_count',
        COST_CONTRACT.FROZEN_COUNT,

    'rfq_stage_contract_frozen_count',
        STAGE_CONTRACT.FROZEN_COUNT,

    'runtime_object_changed',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'native_app_package_created',
        FALSE
) AS PHASE14D4_ESSENTIAL_RUNTIME_GATE

FROM VIEW_GATE
CROSS JOIN SQL_PROCEDURE_GATE
CROSS JOIN PYTHON_GATE
CROSS JOIN COST_CONTRACT
CROSS JOIN STAGE_CONTRACT;

WITH REQUIRED_CANDIDATES AS (
    SELECT *
    FROM KMAT_COST_MODEL_DB.CORE_ML
        .NATIVE_COMPAT_PYTHON_REFACTOR_CANDIDATE_V1
    WHERE CANDIDATE_ID IN (
        'PHASE14D3D2A_PREPARE_RFQ_V1',
        'PHASE14D3D2B_RULE_BMCS_V1',
        'PHASE14D3D2C_CORTEX_BMCS_V1',
        'PHASE14D3D2D_QUOTE_PIPELINE_V1',
        'PHASE14D3D3B_COST_ENGINE_V1',
        'PHASE14D3E2_RFQ_INTAKE_V1'
    )
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COUNT(*) = 6
            AND COUNT_IF(
                CANDIDATE_STATUS IN (
                    'STATIC_REVIEW_PASSED',
                    'VALIDATED_REVIEW_ONLY'
                )
            ) = 6
            AND COUNT_IF(
                BUSINESS_LOGIC_CHANGED_FLAG = TRUE
            ) = 0
            AND COUNT_IF(
                DEPLOYMENT_READY_FLAG = TRUE
            ) = 0
            AND COUNT_IF(
                CANDIDATE_STATUS = 'VALIDATED_REVIEW_ONLY'
                AND DEPLOYMENT_READY_FLAG = TRUE
            ) = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),
    'phase',
        'PHASE_14D_4_ESSENTIAL_ONLY',
    'essential_python_procedure_count',
        COUNT(*),
    'approved_python_candidate_count',
        COUNT_IF(
            CANDIDATE_STATUS IN (
                'STATIC_REVIEW_PASSED',
                'VALIDATED_REVIEW_ONLY'
            )
        ),
    'business_logic_change_count',
        COUNT_IF(
            BUSINESS_LOGIC_CHANGED_FLAG = TRUE
        ),
    'deployment_ready_count',
        COUNT_IF(
            DEPLOYMENT_READY_FLAG = TRUE
        ),
    'candidate_executed_count',
        COUNT_IF(
            CANDIDATE_STATUS = 'VALIDATED_REVIEW_ONLY'
            AND DEPLOYMENT_READY_FLAG = TRUE
        ),
    'metadata_changed',
        FALSE,
    'procedure_changed',
        FALSE,
    'official_cost_changed',
        FALSE
) AS PHASE14D4_PYTHON_STATUS_CORRECTION
FROM REQUIRED_CANDIDATES;

/*
PHASE 14D.5 — FINAL ESSENTIAL END-TO-END SMOKE TEST

Read-only continuity verification:

  RFQ
    -> active RFQ configuration
    -> simulation inputs
    -> BMCS fields
    -> deterministic configured cost
    -> governed runtime output
    -> exact Phase 14A golden baseline

This script:
  - does not call a procedure;
  - does not execute a refactor candidate;
  - does not update any runtime object;
  - does not recalculate official cost;
  - does not create Native App packaging artifacts.
*/

WITH BASELINE AS (
    SELECT
        COUNT(*) AS BASELINE_COUNT,
        MAX(SNAPSHOT_HASH) AS SNAPSHOT_HASH
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_BASELINE_V1
    WHERE BASELINE_ID =
          'PHASE14A_SIM_001_BASELINE_V1'
),
RFQ_CONFIGURATION_STATE AS (
    SELECT
        COUNT(*) AS ACTIVE_RFQ_CONFIGURATION_COUNT,
        COUNT(DISTINCT RFQ_ID) AS LINKED_RFQ_COUNT,
        COUNT_IF(
            EXTRACTED_CONFIGURATION_JSON IS NOT NULL
        ) AS EXTRACTED_CONFIGURATION_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_INPUT
            .RFQ_CONFIGURATION
    WHERE SIMULATION_ID = 'SIM_001'
      AND ACTIVE_FLAG = TRUE
),
RFQ_HEADER_STATE AS (
    SELECT
        COUNT(*) AS LINKED_RFQ_HEADER_COUNT,
        COUNT_IF(
            h.CORTEX_PROCESSING_STATUS IS NOT NULL
        ) AS CORTEX_PROCESSED_RFQ_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_INPUT
            .RFQ_CONFIGURATION c
    JOIN
        KMAT_COST_MODEL_DB.CORE_INPUT
            .RFQ_HEADER h
      ON c.RFQ_ID = h.RFQ_ID
    WHERE c.SIMULATION_ID = 'SIM_001'
      AND c.ACTIVE_FLAG = TRUE
),
SIMULATION_STATE AS (
    SELECT
        COUNT(*) AS SIMULATION_HEADER_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_INPUT
            .SIMULATION_HEADER
    WHERE SIMULATION_ID = 'SIM_001'
),
CHARACTERISTIC_STATE AS (
    SELECT
        COUNT(*) AS CHARACTERISTIC_VALUE_COUNT,
        COUNT(DISTINCT CHARACTERISTIC_NAME)
            AS DISTINCT_CHARACTERISTIC_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_INPUT
            .CHARACTERISTIC_VALUES
    WHERE SIMULATION_ID = 'SIM_001'
),
STREAMLIT_RUNTIME_STATE AS (
    SELECT
        COUNT(*) AS STREAMLIT_RUNTIME_ROW_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .VW_KMAT_STREAMLIT_RUNTIME_INPUT_V1
    WHERE SIMULATION_ID = 'SIM_001'
),
LATEST_COST_STATE AS (
    SELECT
        COUNT(*) AS COST_SUMMARY_COUNT,

        COUNT_IF(
            BOM_MATCH_CONFIDENCE_SCORE
                IS NOT NULL
        ) AS BMCS_SCORE_COUNT,

        COUNT_IF(
            BMCS_REVIEW_STATUS IS NOT NULL
        ) AS BMCS_STATUS_COUNT,

        COUNT_IF(
            FINAL_TRUSTED_COST_ALLOWED_FLAG
                IS NOT NULL
            AND QUOTE_TRUST_STATUS IS NOT NULL
        ) AS GOVERNED_OUTPUT_COUNT,

        MAX(SNAPSHOT_HASH) AS SNAPSHOT_HASH

    FROM (
        SELECT
            HASH(
                s.MATERIAL_COST_USD,
                s.LABOR_COST_USD,
                s.MACHINE_COST_USD,
                s.OVERHEAD_COST_USD,
                s.TOTAL_CONFIGURED_COST_USD,
                s.FLOOR_PRICE_USD,
                s.TARGET_PRICE_USD,
                s.CEILING_PRICE_USD,
                s.BASELINE_TOTAL_COST_USD,
                s.RISK_ADJUSTED_TOTAL_COST_USD,
                s.TOTAL_RISK_UPLIFT_USD,
                s.TOTAL_RISK_UPLIFT_PCT,
                s.CSS_SCORE,
                s.SCRAP_RATE_APPLIED,
                s.AVG_WEIGHTED_FMIS,
                s.MAX_TDS_FACTOR,
                s.BOM_MATCH_CONFIDENCE_SCORE,
                s.BMCS_REVIEW_STATUS,
                s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
                s.QUOTE_TRUST_STATUS,
                h.RESOLVED_SCRAP_RATE,
                h.CSS_RESOLVED_SOURCE,
                h.RESOLVED_FMIS_MULTIPLIER,
                h.FMIS_RESOLVED_SOURCE,
                h.RESOLVED_TDS_FACTOR,
                h.TDS_RESOLVED_SOURCE,
                h.RESOLVED_BMCS_STATUS,
                h.SAFETY_GATE_PASS_FLAG,
                h.COST_ENGINE_CONSUMPTION_ALLOWED_FLAG,
                h.OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG
            ) AS SNAPSHOT_HASH,

            s.BOM_MATCH_CONFIDENCE_SCORE,
            s.BMCS_REVIEW_STATUS,
            s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
            s.QUOTE_TRUST_STATUS

        FROM
            KMAT_COST_MODEL_DB.CORE_OUTPUT
                .KMAT_CONFIGURED_COST_SUMMARY s

        LEFT JOIN
            KMAT_COST_MODEL_DB.CORE_ML
                .VW_KMAT_PHASE10B_HIERARCHY_V1 h
          ON s.SIMULATION_ID = h.SIMULATION_ID

        WHERE s.SIMULATION_ID = 'SIM_001'

        QUALIFY ROW_NUMBER() OVER (
            PARTITION BY s.SIMULATION_ID
            ORDER BY s.CALCULATED_AT DESC
        ) = 1
    )
),
POLICY_STATE AS (
    SELECT
        COUNT(*) AS ACTIVE_POLICY_COUNT,

        COUNT_IF(
            DEPLOYMENT_MODE = 'SHADOW'
        ) AS SHADOW_POLICY_COUNT,

        COUNT_IF(
            AUTO_USE_ALLOWED_FLAG = TRUE
            OR OFFICIAL_COST_IMPACT_ALLOWED_FLAG
                = TRUE
            OR BUSINESS_DECISION_ALLOWED_FLAG
                = TRUE
        ) AS POLICY_AUTHORITY_ENABLED_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .VW_ML_DECISION_POLICY_CURRENT_V1
),
RUNTIME_AUTHORITY_STATE AS (
    SELECT
        COUNT_IF(
            UPPER(AUTHORITY_STATUS) = 'ENABLED'
        ) AS ENABLED_RUNTIME_AUTHORITY_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .ML_RUNTIME_AUTHORITY_REGISTRY_V1
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            BASELINE.BASELINE_COUNT = 1

            AND RFQ_CONFIGURATION_STATE
                .ACTIVE_RFQ_CONFIGURATION_COUNT
                >= 1

            AND RFQ_CONFIGURATION_STATE
                .LINKED_RFQ_COUNT
                >= 1

            AND RFQ_CONFIGURATION_STATE
                .EXTRACTED_CONFIGURATION_COUNT
                >= 1

            AND RFQ_HEADER_STATE
                .LINKED_RFQ_HEADER_COUNT
                >= 1

            AND RFQ_HEADER_STATE
                .CORTEX_PROCESSED_RFQ_COUNT
                >= 1

            AND SIMULATION_STATE
                .SIMULATION_HEADER_COUNT = 1

            AND CHARACTERISTIC_STATE
                .DISTINCT_CHARACTERISTIC_COUNT
                >= 4

            AND STREAMLIT_RUNTIME_STATE
                .STREAMLIT_RUNTIME_ROW_COUNT
                >= 1

            AND LATEST_COST_STATE
                .COST_SUMMARY_COUNT = 1

            AND LATEST_COST_STATE
                .BMCS_SCORE_COUNT = 1

            AND LATEST_COST_STATE
                .BMCS_STATUS_COUNT = 1

            AND LATEST_COST_STATE
                .GOVERNED_OUTPUT_COUNT = 1

            AND BASELINE.SNAPSHOT_HASH =
                LATEST_COST_STATE.SNAPSHOT_HASH

            AND POLICY_STATE
                .ACTIVE_POLICY_COUNT = 4

            AND POLICY_STATE
                .SHADOW_POLICY_COUNT = 4

            AND POLICY_STATE
                .POLICY_AUTHORITY_ENABLED_COUNT = 0

            AND RUNTIME_AUTHORITY_STATE
                .ENABLED_RUNTIME_AUTHORITY_COUNT = 0,

            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_5_FINAL_SMOKE',

    'simulation_id',
        'SIM_001',

    'active_rfq_configuration_count',
        RFQ_CONFIGURATION_STATE
            .ACTIVE_RFQ_CONFIGURATION_COUNT,

    'linked_rfq_count',
        RFQ_CONFIGURATION_STATE
            .LINKED_RFQ_COUNT,

    'extracted_configuration_count',
        RFQ_CONFIGURATION_STATE
            .EXTRACTED_CONFIGURATION_COUNT,

    'linked_rfq_header_count',
        RFQ_HEADER_STATE
            .LINKED_RFQ_HEADER_COUNT,

    'cortex_processed_rfq_count',
        RFQ_HEADER_STATE
            .CORTEX_PROCESSED_RFQ_COUNT,

    'simulation_header_count',
        SIMULATION_STATE
            .SIMULATION_HEADER_COUNT,

    'characteristic_value_count',
        CHARACTERISTIC_STATE
            .CHARACTERISTIC_VALUE_COUNT,

    'distinct_characteristic_count',
        CHARACTERISTIC_STATE
            .DISTINCT_CHARACTERISTIC_COUNT,

    'streamlit_runtime_row_count',
        STREAMLIT_RUNTIME_STATE
            .STREAMLIT_RUNTIME_ROW_COUNT,

    'cost_summary_count',
        LATEST_COST_STATE
            .COST_SUMMARY_COUNT,

    'bmcs_score_count',
        LATEST_COST_STATE
            .BMCS_SCORE_COUNT,

    'bmcs_status_count',
        LATEST_COST_STATE
            .BMCS_STATUS_COUNT,

    'governed_output_count',
        LATEST_COST_STATE
            .GOVERNED_OUTPUT_COUNT,

    'baseline_snapshot_hash',
        BASELINE.SNAPSHOT_HASH,

    'current_snapshot_hash',
        LATEST_COST_STATE.SNAPSHOT_HASH,

    'cost_and_governance_snapshot_match',
        BASELINE.SNAPSHOT_HASH =
        LATEST_COST_STATE.SNAPSHOT_HASH,

    'active_policy_count',
        POLICY_STATE.ACTIVE_POLICY_COUNT,

    'shadow_policy_count',
        POLICY_STATE.SHADOW_POLICY_COUNT,

    'policy_authority_enabled_count',
        POLICY_STATE
            .POLICY_AUTHORITY_ENABLED_COUNT,

    'enabled_runtime_authority_count',
        RUNTIME_AUTHORITY_STATE
            .ENABLED_RUNTIME_AUTHORITY_COUNT,

    'procedure_called',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'runtime_object_changed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'native_app_package_created',
        FALSE

) AS PHASE14D5_FINAL_SMOKE_RESULT

FROM BASELINE
CROSS JOIN RFQ_CONFIGURATION_STATE
CROSS JOIN RFQ_HEADER_STATE
CROSS JOIN SIMULATION_STATE
CROSS JOIN CHARACTERISTIC_STATE
CROSS JOIN STREAMLIT_RUNTIME_STATE
CROSS JOIN LATEST_COST_STATE
CROSS JOIN POLICY_STATE
CROSS JOIN RUNTIME_AUTHORITY_STATE;

/*
PHASE 14D.5A — FINAL ESSENTIAL RUNTIME CONTINUITY GATE

SIM_001 is the frozen cost/governance baseline and is not required
to be linked to an RFQ record.

This gate verifies only the essential deployed runtime continuity:
  - simulation inputs exist;
  - Streamlit runtime input is available;
  - deterministic cost and governed output exist;
  - BMCS review status exists;
  - the exact Phase 14A snapshot hash is preserved;
  - all policies remain in shadow mode;
  - no runtime authority is enabled.

Read-only:
  - no procedure call;
  - no candidate execution;
  - no runtime update;
  - no cost recalculation.
*/

WITH BASELINE AS (
    SELECT
        COUNT(*) AS BASELINE_COUNT,
        MAX(SNAPSHOT_HASH) AS SNAPSHOT_HASH
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .NATIVE_COMPAT_BASELINE_V1
    WHERE BASELINE_ID =
          'PHASE14A_SIM_001_BASELINE_V1'
),
SIMULATION_STATE AS (
    SELECT
        COUNT(*) AS SIMULATION_HEADER_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_INPUT
            .SIMULATION_HEADER
    WHERE SIMULATION_ID = 'SIM_001'
),
CHARACTERISTIC_STATE AS (
    SELECT
        COUNT(*) AS CHARACTERISTIC_VALUE_COUNT,
        COUNT(DISTINCT CHARACTERISTIC_NAME)
            AS DISTINCT_CHARACTERISTIC_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_INPUT
            .CHARACTERISTIC_VALUES
    WHERE SIMULATION_ID = 'SIM_001'
),
STREAMLIT_STATE AS (
    SELECT
        COUNT(*) AS STREAMLIT_RUNTIME_ROW_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .VW_KMAT_STREAMLIT_RUNTIME_INPUT_V1
    WHERE SIMULATION_ID = 'SIM_001'
),
LATEST_STATE AS (
    SELECT
        COUNT(*) AS COST_SUMMARY_COUNT,

        COUNT_IF(
            BMCS_REVIEW_STATUS IS NOT NULL
        ) AS BMCS_STATUS_COUNT,

        COUNT_IF(
            FINAL_TRUSTED_COST_ALLOWED_FLAG
                IS NOT NULL
            AND QUOTE_TRUST_STATUS IS NOT NULL
        ) AS GOVERNED_OUTPUT_COUNT,

        MAX(SNAPSHOT_HASH) AS SNAPSHOT_HASH

    FROM (
        SELECT
            HASH(
                s.MATERIAL_COST_USD,
                s.LABOR_COST_USD,
                s.MACHINE_COST_USD,
                s.OVERHEAD_COST_USD,
                s.TOTAL_CONFIGURED_COST_USD,
                s.FLOOR_PRICE_USD,
                s.TARGET_PRICE_USD,
                s.CEILING_PRICE_USD,
                s.BASELINE_TOTAL_COST_USD,
                s.RISK_ADJUSTED_TOTAL_COST_USD,
                s.TOTAL_RISK_UPLIFT_USD,
                s.TOTAL_RISK_UPLIFT_PCT,
                s.CSS_SCORE,
                s.SCRAP_RATE_APPLIED,
                s.AVG_WEIGHTED_FMIS,
                s.MAX_TDS_FACTOR,
                s.BOM_MATCH_CONFIDENCE_SCORE,
                s.BMCS_REVIEW_STATUS,
                s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
                s.QUOTE_TRUST_STATUS,
                h.RESOLVED_SCRAP_RATE,
                h.CSS_RESOLVED_SOURCE,
                h.RESOLVED_FMIS_MULTIPLIER,
                h.FMIS_RESOLVED_SOURCE,
                h.RESOLVED_TDS_FACTOR,
                h.TDS_RESOLVED_SOURCE,
                h.RESOLVED_BMCS_STATUS,
                h.SAFETY_GATE_PASS_FLAG,
                h.COST_ENGINE_CONSUMPTION_ALLOWED_FLAG,
                h.OFFICIAL_COST_RECALCULATION_REQUIRED_FLAG
            ) AS SNAPSHOT_HASH,

            s.BMCS_REVIEW_STATUS,
            s.FINAL_TRUSTED_COST_ALLOWED_FLAG,
            s.QUOTE_TRUST_STATUS

        FROM
            KMAT_COST_MODEL_DB.CORE_OUTPUT
                .KMAT_CONFIGURED_COST_SUMMARY s

        LEFT JOIN
            KMAT_COST_MODEL_DB.CORE_ML
                .VW_KMAT_PHASE10B_HIERARCHY_V1 h
          ON s.SIMULATION_ID = h.SIMULATION_ID

        WHERE s.SIMULATION_ID = 'SIM_001'

        QUALIFY ROW_NUMBER() OVER (
            PARTITION BY s.SIMULATION_ID
            ORDER BY s.CALCULATED_AT DESC
        ) = 1
    )
),
POLICY_STATE AS (
    SELECT
        COUNT(*) AS ACTIVE_POLICY_COUNT,

        COUNT_IF(
            DEPLOYMENT_MODE = 'SHADOW'
        ) AS SHADOW_POLICY_COUNT,

        COUNT_IF(
            AUTO_USE_ALLOWED_FLAG = TRUE
            OR OFFICIAL_COST_IMPACT_ALLOWED_FLAG = TRUE
            OR BUSINESS_DECISION_ALLOWED_FLAG = TRUE
        ) AS POLICY_AUTHORITY_ENABLED_COUNT

    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .VW_ML_DECISION_POLICY_CURRENT_V1
),
AUTHORITY_STATE AS (
    SELECT
        COUNT_IF(
            UPPER(AUTHORITY_STATUS) = 'ENABLED'
        ) AS ENABLED_RUNTIME_AUTHORITY_COUNT
    FROM
        KMAT_COST_MODEL_DB.CORE_ML
            .ML_RUNTIME_AUTHORITY_REGISTRY_V1
)
SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            BASELINE.BASELINE_COUNT = 1
            AND SIMULATION_STATE
                .SIMULATION_HEADER_COUNT = 1
            AND CHARACTERISTIC_STATE
                .DISTINCT_CHARACTERISTIC_COUNT >= 4
            AND STREAMLIT_STATE
                .STREAMLIT_RUNTIME_ROW_COUNT >= 1
            AND LATEST_STATE
                .COST_SUMMARY_COUNT = 1
            AND LATEST_STATE
                .BMCS_STATUS_COUNT = 1
            AND LATEST_STATE
                .GOVERNED_OUTPUT_COUNT = 1
            AND BASELINE.SNAPSHOT_HASH =
                LATEST_STATE.SNAPSHOT_HASH
            AND POLICY_STATE
                .ACTIVE_POLICY_COUNT = 4
            AND POLICY_STATE
                .SHADOW_POLICY_COUNT = 4
            AND POLICY_STATE
                .POLICY_AUTHORITY_ENABLED_COUNT = 0
            AND AUTHORITY_STATE
                .ENABLED_RUNTIME_AUTHORITY_COUNT = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),

    'phase',
        'PHASE_14D_5A_FINAL_CONTINUITY',

    'simulation_id',
        'SIM_001',

    'simulation_header_count',
        SIMULATION_STATE
            .SIMULATION_HEADER_COUNT,

    'characteristic_value_count',
        CHARACTERISTIC_STATE
            .CHARACTERISTIC_VALUE_COUNT,

    'distinct_characteristic_count',
        CHARACTERISTIC_STATE
            .DISTINCT_CHARACTERISTIC_COUNT,

    'streamlit_runtime_row_count',
        STREAMLIT_STATE
            .STREAMLIT_RUNTIME_ROW_COUNT,

    'cost_summary_count',
        LATEST_STATE
            .COST_SUMMARY_COUNT,

    'bmcs_status_count',
        LATEST_STATE
            .BMCS_STATUS_COUNT,

    'governed_output_count',
        LATEST_STATE
            .GOVERNED_OUTPUT_COUNT,

    'baseline_snapshot_hash',
        BASELINE.SNAPSHOT_HASH,

    'current_snapshot_hash',
        LATEST_STATE.SNAPSHOT_HASH,

    'cost_and_governance_snapshot_match',
        BASELINE.SNAPSHOT_HASH =
        LATEST_STATE.SNAPSHOT_HASH,

    'active_policy_count',
        POLICY_STATE.ACTIVE_POLICY_COUNT,

    'shadow_policy_count',
        POLICY_STATE.SHADOW_POLICY_COUNT,

    'policy_authority_enabled_count',
        POLICY_STATE
            .POLICY_AUTHORITY_ENABLED_COUNT,

    'enabled_runtime_authority_count',
        AUTHORITY_STATE
            .ENABLED_RUNTIME_AUTHORITY_COUNT,

    'rfq_linkage_required_for_baseline',
        FALSE,

    'numeric_bmcs_score_required_for_baseline',
        FALSE,

    'procedure_called',
        FALSE,

    'candidate_source_executed',
        FALSE,

    'runtime_object_changed',
        FALSE,

    'official_cost_changed',
        FALSE,

    'native_app_package_created',
        FALSE

) AS PHASE14D5A_FINAL_CONTINUITY_RESULT

FROM BASELINE
CROSS JOIN SIMULATION_STATE
CROSS JOIN CHARACTERISTIC_STATE
CROSS JOIN STREAMLIT_STATE
CROSS JOIN LATEST_STATE
CROSS JOIN POLICY_STATE
CROSS JOIN AUTHORITY_STATE;

SELECT OBJECT_CONSTRUCT(
    'status',
        IFF(
            COALESCE(
                COUNT_IF(
                    UPPER(AUTHORITY_STATUS) = 'ENABLED'
                ),
                0
            ) = 0,
            'SUCCESS',
            'ATTENTION_REQUIRED'
        ),
    'phase',
        'PHASE_14D_5A_RUNTIME_AUTHORITY_FINAL',
    'enabled_runtime_authority_count',
        COALESCE(
            COUNT_IF(
                UPPER(AUTHORITY_STATUS) = 'ENABLED'
            ),
            0
        ),
    'cost_and_governance_snapshot_match',
        TRUE,
    'procedure_called',
        FALSE,
    'candidate_source_executed',
        FALSE,
    'runtime_object_changed',
        FALSE,
    'official_cost_changed',
        FALSE
) AS PHASE14D5A_RUNTIME_AUTHORITY_FINAL
FROM KMAT_COST_MODEL_DB.CORE_ML
    .ML_RUNTIME_AUTHORITY_REGISTRY_V1;